CREATE FUNCTION "platform"."complete_device_binding_recovery"("p_user_id" "uuid", "p_device_id" "uuid", "p_authorization_id" "uuid", "p_challenge_id" "uuid", "p_replacement_binding_id" "uuid", "p_public_key_thumbprint" "text", "p_public_key_jwk" "jsonb", "p_recovery_reason" "text", "p_assertion_jti" "uuid", "p_assertion_hash" "bytea", "p_assertion_issued_at" timestamp with time zone, "p_assertion_expires_at" timestamp with time zone) RETURNS "jsonb"
