    or challenge.expires_at<=v_now or p_assertion_expires_at<=v_now
    or p_assertion_expires_at>p_assertion_issued_at+interval '2 minutes'
    or challenge.user_id<>p_user_id or challenge.device_id<>p_device_id
    or challenge.device_authorization_id<>p_authorization_id
    or challenge.replacement_binding_id<>p_replacement_binding_id
    or challenge.public_key_thumbprint<>p_public_key_thumbprint
    or challenge.purpose<>'PLATFORM_DEVICE_OWNERSHIP_HANDOFF'
    or challenge.handoff_mode<>'binding_recovery' or challenge.recovery_reason<>p_recovery_reason
    or p_recovery_reason<>'lost_private_key'
    or pg_catalog.octet_length(p_assertion_hash)<>32 then
    raise exception 'DEVICE_BINDING_RECOVERY_FINALIZATION_DENIED' using errcode='42501';
  end if;
  if not exists(select 1 from platform.user_device_authorizations device_authorization
      join platform.devices device on device.id=device_authorization.device_id
      join platform.profiles profile on profile.user_id=device_authorization.user_id
      where device_authorization.id=p_authorization_id and device_authorization.user_id=p_user_id
        and device_authorization.device_id=p_device_id and device_authorization.status='approved'
        and device_authorization.revoked_at is null and device.lifecycle_status='active'
        and profile.account_status='approved') then
    raise exception 'DEVICE_HANDOFF_AUTHORIZATION_INVALID' using errcode='42501';
  end if;
  select * into previous_binding from platform.device_key_bindings binding
    where binding.id=p_replacement_binding_id and binding.user_id=p_user_id
      and binding.device_id=p_device_id and binding.device_authorization_id=p_authorization_id
      and binding.lifecycle_status='active' and binding.rotated_at is null
      and binding.revoked_at is null and binding.retired_at is null
    for update;
  if not found then raise exception 'DEVICE_HANDOFF_REPLACEMENT_STALE' using errcode='55000'; end if;
  update platform.device_key_bindings
    set lifecycle_status='rotated',rotated_at=v_now
    where id=previous_binding.id;
  insert into platform.device_key_bindings(user_id,device_id,device_authorization_id,public_key_jwk,
    public_key_thumbprint,algorithm,lifecycle_status,migration_source,created_at,activated_at)
  values(p_user_id,p_device_id,p_authorization_id,p_public_key_jwk,p_public_key_thumbprint,
    'ECDSA_P256_SHA256','active','bound_key_rotation',v_now,v_now) returning id into v_binding;
  update platform.device_key_bindings set replaced_by_binding_id=v_binding where id=previous_binding.id;
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,subject_user_id,domain,module,action,
    entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source)
  values(p_user_id,p_authorization_id,p_user_id,'platform','devices','device_key_binding.rotated',
    'device_key_binding',previous_binding.id,'platform',jsonb_build_object('lifecycleStatus','active'),
    jsonb_build_object('lifecycleStatus','rotated','rotatedAt',v_now,'replacedByBindingId',v_binding),
    jsonb_build_object('deviceId',p_device_id,'authorizationId',p_authorization_id,
      'previousBindingId',previous_binding.id,'newBindingId',v_binding,
      'previousPublicKeyThumbprint',previous_binding.public_key_thumbprint,
      'newPublicKeyThumbprint',p_public_key_thumbprint,'recoveryReason',p_recovery_reason,
      'challengeId',p_challenge_id,'assertionJti',p_assertion_jti),p_assertion_jti,'system')
    returning id into v_rotation_audit;
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,subject_user_id,domain,module,action,
    entity_type,entity_id,scope_type,new_values,metadata,operation_id,source)
  values(p_user_id,p_authorization_id,p_user_id,'platform','devices','device_key_binding.recovery_activated',
    'device_key_binding',v_binding,'platform',jsonb_build_object('lifecycleStatus','active'),
    jsonb_build_object('deviceId',p_device_id,'authorizationId',p_authorization_id,
      'previousBindingId',previous_binding.id,'newBindingId',v_binding,
      'previousPublicKeyThumbprint',previous_binding.public_key_thumbprint,
      'newPublicKeyThumbprint',p_public_key_thumbprint,'recoveryReason',p_recovery_reason,
      'challengeId',p_challenge_id,'assertionJti',p_assertion_jti),p_assertion_jti,'system')
    returning id into v_activation_audit;
  insert into platform_private.device_ownership_handoff_audit(user_id,device_id,device_authorization_id,binding_id,
    public_key_thumbprint,purpose,migration_source,challenge_id,assertion_jti,handoff_mode,
    previous_binding_id,previous_public_key_thumbprint,recovery_reason)
  values(p_user_id,p_device_id,p_authorization_id,v_binding,p_public_key_thumbprint,'PLATFORM_DEVICE_OWNERSHIP_HANDOFF',
    'bound_key_rotation',p_challenge_id,p_assertion_jti,'binding_recovery',previous_binding.id,
    previous_binding.public_key_thumbprint,p_recovery_reason) returning id into v_handoff_audit;
  update platform_private.device_ownership_handoff_challenges
    set consumed_at=v_now,assertion_jti=p_assertion_jti,assertion_hash=p_assertion_hash,binding_id=v_binding
    where id=p_challenge_id;
  update platform.device_key_bindings set audit_event_id=v_activation_audit where id=v_binding;
  return jsonb_build_object('status','active','bindingId',v_binding,'previousBindingId',previous_binding.id,
    'deviceId',p_device_id,'authorizationId',p_authorization_id,'publicKeyThumbprint',p_public_key_thumbprint,
    'handoffAuditId',v_handoff_audit,'rotationAuditId',v_rotation_audit,'activationAuditId',v_activation_audit);
end;
$$;


--
-- Name: complete_device_ownership_handoff("uuid", "uuid", "uuid", "uuid", "text", "jsonb", "uuid", "bytea", timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."complete_device_ownership_handoff"("p_user_id" "uuid", "p_device_id" "uuid", "p_authorization_id" "uuid", "p_challenge_id" "uuid", "p_public_key_thumbprint" "text", "p_public_key_jwk" "jsonb", "p_assertion_jti" "uuid", "p_assertion_hash" "bytea", "p_assertion_issued_at" timestamp with time zone, "p_assertion_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform', 'platform_private'
    AS $$
declare challenge platform_private.device_ownership_handoff_challenges%rowtype; v_binding uuid; v_audit uuid; v_platform_audit uuid;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'DEVICE_HANDOFF_BACKEND_REQUIRED' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('device-handoff:'||p_challenge_id::text,0));
  select * into challenge from platform_private.device_ownership_handoff_challenges item where item.id=p_challenge_id for update;
  if not found or challenge.consumed_at is not null or challenge.failed_at is not null
    or challenge.expires_at<=statement_timestamp() or p_assertion_expires_at<=statement_timestamp()
    or p_assertion_expires_at>p_assertion_issued_at+interval '2 minutes'
    or challenge.user_id<>p_user_id or challenge.device_id<>p_device_id
    or challenge.device_authorization_id<>p_authorization_id or challenge.public_key_thumbprint<>p_public_key_thumbprint
    or challenge.purpose<>'PLATFORM_DEVICE_OWNERSHIP_HANDOFF'
    or pg_catalog.octet_length(p_assertion_hash)<>32 then
    raise exception 'DEVICE_HANDOFF_FINALIZATION_DENIED' using errcode='42501';
  end if;
  if not exists(select 1 from platform.user_device_authorizations device_authorization
      join platform.devices device on device.id=device_authorization.device_id
      join platform.profiles profile on profile.user_id=device_authorization.user_id
      where device_authorization.id=p_authorization_id and device_authorization.user_id=p_user_id and device_authorization.device_id=p_device_id
        and device_authorization.status='approved' and device_authorization.revoked_at is null and device.lifecycle_status='active'
        and profile.account_status='approved') then
    raise exception 'DEVICE_HANDOFF_AUTHORIZATION_INVALID' using errcode='42501';
  end if;
  insert into platform.device_key_bindings(user_id,device_id,device_authorization_id,public_key_jwk,
    public_key_thumbprint,algorithm,lifecycle_status,migration_source)
  values(p_user_id,p_device_id,p_authorization_id,p_public_key_jwk,p_public_key_thumbprint,
    'ECDSA_P256_SHA256','active','current_http_only_device_secret') returning id into v_binding;
  insert into platform_private.device_ownership_handoff_audit(user_id,device_id,device_authorization_id,binding_id,
    public_key_thumbprint,purpose,migration_source,challenge_id,assertion_jti)
  values(p_user_id,p_device_id,p_authorization_id,v_binding,p_public_key_thumbprint,'PLATFORM_DEVICE_OWNERSHIP_HANDOFF',
    'current_http_only_device_secret',p_challenge_id,p_assertion_jti) returning id into v_audit;
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,subject_user_id,domain,module,action,
    entity_type,entity_id,scope_type,new_values,metadata,operation_id,source)
  values(p_user_id,p_authorization_id,p_user_id,'platform','devices','device_key_binding.activated',
    'device_key_binding',v_binding,'platform',jsonb_build_object('lifecycleStatus','active'),
    jsonb_build_object('deviceId',p_device_id,'authorizationId',p_authorization_id,'bindingId',v_binding,
      'publicKeyThumbprint',p_public_key_thumbprint,'purpose','PLATFORM_DEVICE_OWNERSHIP_HANDOFF',
      'migrationSource','current_http_only_device_secret','challengeId',p_challenge_id,'assertionJti',p_assertion_jti),
    p_assertion_jti,'system') returning id into v_platform_audit;
  update platform_private.device_ownership_handoff_challenges set consumed_at=statement_timestamp(),assertion_jti=p_assertion_jti,
    assertion_hash=p_assertion_hash,binding_id=v_binding where id=p_challenge_id;
  update platform.device_key_bindings set audit_event_id=v_platform_audit where id=v_binding;
  return jsonb_build_object('status','active','bindingId',v_binding,'deviceId',p_device_id,
    'authorizationId',p_authorization_id,'publicKeyThumbprint',p_public_key_thumbprint,'auditId',v_audit);
end;
$$;


--
-- Name: complete_device_session("uuid", "uuid", "uuid", "uuid", "uuid", "text", "uuid", "bytea"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."complete_device_session"("p_challenge_id" "uuid", "p_user_id" "uuid", "p_device_id" "uuid", "p_authorization_id" "uuid", "p_binding_id" "uuid", "p_public_key_thumbprint" "text", "p_session_id" "uuid", "p_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform', 'platform_private'
    AS $$
declare v_challenge platform_private.device_session_challenges%rowtype; v_now timestamptz:=statement_timestamp();
begin
  if auth.role() is distinct from 'service_role' then raise exception 'DEVICE_SESSION_BACKEND_REQUIRED' using errcode='42501'; end if;
  if p_session_id is null or octet_length(p_token_hash)<>32 then raise exception 'DEVICE_SESSION_ARGUMENT_INVALID' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('device-session:'||p_challenge_id::text,0));
  select * into v_challenge from platform_private.device_session_challenges where id=p_challenge_id for update;
  if not found or v_challenge.consumed_at is not null or v_challenge.failed_at is not null or v_challenge.expires_at<=v_now
    or v_challenge.user_id<>p_user_id or v_challenge.device_id<>p_device_id
    or v_challenge.device_authorization_id<>p_authorization_id or v_challenge.binding_id<>p_binding_id
    or v_challenge.public_key_thumbprint<>p_public_key_thumbprint
    or v_challenge.purpose<>'PLATFORM_DEVICE_SESSION_ESTABLISH'
    or v_challenge.origin<>'https://ramyawny37.github.io' then raise exception 'DEVICE_SESSION_CHALLENGE_INVALID' using errcode='42501'; end if;
  if not exists(select 1 from platform.device_key_bindings binding
    join platform.user_device_authorizations uda on uda.id=binding.device_authorization_id
    join platform.devices device on device.id=binding.device_id join platform.profiles profile on profile.user_id=binding.user_id
    where binding.id=p_binding_id and binding.user_id=p_user_id and binding.device_id=p_device_id
      and binding.device_authorization_id=p_authorization_id and binding.public_key_thumbprint=p_public_key_thumbprint
      and binding.algorithm='ECDSA_P256_SHA256' and binding.lifecycle_status='active' and binding.revoked_at is null and binding.retired_at is null
      and uda.user_id=p_user_id and uda.device_id=p_device_id and uda.status='approved' and uda.revoked_at is null
      and device.lifecycle_status='active' and device.retired_at is null and device.compromised_at is null and profile.account_status='approved')
    then raise exception 'DEVICE_SESSION_AUTHORITY_INVALID' using errcode='42501'; end if;
  insert into platform_private.device_sessions(id,user_id,device_id,device_authorization_id,binding_id,public_key_thumbprint,token_hash,purpose,created_at,expires_at,challenge_id)
  values(p_session_id,p_user_id,p_device_id,p_authorization_id,p_binding_id,p_public_key_thumbprint,p_token_hash,'PLATFORM_DEVICE_SESSION',v_now,v_now+interval '5 minutes',p_challenge_id);
  update platform_private.device_session_challenges set consumed_at=v_now,session_id=p_session_id where id=p_challenge_id;
  insert into platform_private.device_session_audit(event,session_id,challenge_id,user_id,device_id,device_authorization_id,binding_id,public_key_thumbprint,purpose)
  values('established',p_session_id,p_challenge_id,p_user_id,p_device_id,p_authorization_id,p_binding_id,p_public_key_thumbprint,'PLATFORM_DEVICE_SESSION');
  return jsonb_build_object('sessionId',p_session_id,'userId',p_user_id,'deviceId',p_device_id,'authorizationId',p_authorization_id,'bindingId',p_binding_id,'purpose','PLATFORM_DEVICE_SESSION','issuedAt',v_now,'expiresAt',v_now+interval '5 minutes');
end; $$;


--
-- Name: enroll_new_device_key("uuid", "uuid", "text", "text", "jsonb", "text", "text", "text", "text"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."enroll_new_device_key"("p_user_id" "uuid", "p_device_id" "uuid", "p_device_secret_hash" "text", "p_public_key_thumbprint" "text", "p_public_key_jwk" "jsonb", "p_nonce" "text", "p_display_name" "text", "p_platform" "text", "p_browser" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform', 'platform_private'
    AS $_$
declare v_authorization uuid; v_binding uuid;
begin
  if coalesce(auth.jwt()->>'role','') <> 'service_role' then raise exception 'DEVICE_ENROLLMENT_BACKEND_REQUIRED' using errcode='42501'; end if;
  if p_user_id is null or p_device_id is null or p_device_secret_hash !~ '^[0-9a-f]{64}$'
    or p_public_key_thumbprint !~ '^[0-9a-f]{64}$' or p_nonce !~ '^[A-Za-z0-9_-]{43}$'
    or p_public_key_jwk->>'kty'<>'EC' or p_public_key_jwk->>'crv'<>'P-256'
    or not (p_public_key_jwk ? 'x') or not (p_public_key_jwk ? 'y') or p_public_key_jwk ? 'd' then
    raise exception 'DEVICE_ENROLLMENT_ARGUMENT_INVALID' using errcode='22023';
  end if;
  if not exists(select 1 from platform.profiles where user_id=p_user_id) then
    raise exception 'DEVICE_ENROLLMENT_PROFILE_REQUIRED' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('device-enrollment:'||p_user_id::text||':'||p_nonce,0));
  if exists(select 1 from platform_private.device_enrollment_nonces where nonce=p_nonce) then
    raise exception 'DEVICE_ENROLLMENT_REPLAY_DENIED' using errcode='42501';
  end if;
  insert into platform.devices(id,secret_hash,display_name,platform,browser)
  values(p_device_id,p_device_secret_hash,nullif(btrim(p_display_name),''),nullif(btrim(p_platform),''),nullif(btrim(p_browser),''));
  insert into platform.user_device_authorizations(user_id,device_id,status)
  values(p_user_id,p_device_id,'pending') returning id into v_authorization;
  insert into platform.device_key_bindings(user_id,device_id,device_authorization_id,public_key_jwk,
    public_key_thumbprint,algorithm,lifecycle_status,migration_source)
  values(p_user_id,p_device_id,v_authorization,p_public_key_jwk,p_public_key_thumbprint,
    'ECDSA_P256_SHA256','active','native_device_enrollment') returning id into v_binding;
  insert into platform_private.device_enrollment_nonces(nonce,user_id,device_id,binding_id)
  values(p_nonce,p_user_id,p_device_id,v_binding);
  insert into platform.audit_events(actor_user_id,subject_user_id,domain,module,action,entity_type,entity_id,
    scope_type,new_values,metadata,source)
  values(p_user_id,p_user_id,'platform','devices','device.enrolled','user_device_authorization',v_authorization,
    'platform',jsonb_build_object('status','pending'),jsonb_build_object('deviceId',p_device_id,'bindingId',v_binding,
    'publicKeyThumbprint',p_public_key_thumbprint,'enrollment','native_key_possession'),'system');
  return jsonb_build_object('deviceId',p_device_id,'authorizationId',v_authorization,'bindingId',v_binding,
    'publicKeyThumbprint',p_public_key_thumbprint,'status','pending');
end; $_$;


--
-- Name: execute_conference_device_operation("uuid", "uuid", "bytea", "text", "jsonb"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."execute_conference_device_operation"("p_user_id" "uuid", "p_session_id" "uuid", "p_token_hash" "bytea", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_session platform_private.device_sessions%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'CONFERENCE_OPERATION_BACKEND_REQUIRED' using errcode='42501';
  end if;
  if p_user_id is null or p_session_id is null
     or pg_catalog.octet_length(p_token_hash)<>32 then
    raise exception 'DEVICE_SESSION_ARGUMENT_INVALID' using errcode='22023';
  end if;
  select session.* into v_session
  from platform_private.device_sessions session
  join platform.device_key_bindings binding on binding.id=session.binding_id
  join platform.user_device_authorizations device_authorization
    on device_authorization.id=session.device_authorization_id
  join platform.devices device on device.id=session.device_id
  join platform.profiles profile on profile.user_id=session.user_id
  where session.id=p_session_id and session.user_id=p_user_id
    and session.token_hash=p_token_hash
    and session.purpose='PLATFORM_DEVICE_SESSION'
    and session.revoked_at is null
    and session.expires_at>pg_catalog.statement_timestamp()
    and binding.user_id=session.user_id and binding.device_id=session.device_id
    and binding.device_authorization_id=session.device_authorization_id
    and binding.public_key_thumbprint=session.public_key_thumbprint
    and binding.algorithm='ECDSA_P256_SHA256'
    and binding.lifecycle_status='active'
    and binding.revoked_at is null and binding.retired_at is null
    and device_authorization.user_id=session.user_id
    and device_authorization.device_id=session.device_id
    and device_authorization.status='approved'
    and device_authorization.revoked_at is null
    and device.lifecycle_status='active' and device.retired_at is null
    and device.compromised_at is null and profile.account_status='approved';
  if not found then
    raise exception 'DEVICE_SESSION_INVALID' using errcode='42501';
  end if;
  if p_args ? 'p_actor_device_id'
     or (p_args ? 'p_device_id'
         and p_operation<>'approve_pending_device_authorization') then
    raise exception 'ACTOR_DEVICE_OVERRIDE_DENIED' using errcode='22023';
  end if;
  perform pg_catalog.set_config(
    'platform.phase1c_context',pg_catalog.jsonb_build_object(
      'purpose','PLATFORM_DEVICE_SESSION_DISPATCH','session_id',v_session.id,
      'user_id',v_session.user_id,'device_id',v_session.device_id,
      'authorization_id',v_session.device_authorization_id,
      'binding_id',v_session.binding_id,
      'token_hash',pg_catalog.encode(p_token_hash,'hex')
    )::text,true
  );
  perform pg_catalog.set_config(
    'request.jwt.claims',pg_catalog.jsonb_build_object(
      'sub',p_user_id,'role','authenticated'
    )::text,true
  );
  return platform_private.route_canonical_conference_operation(
    p_user_id,p_session_id,p_token_hash,v_session.device_id,p_operation,p_args
  );
end $$;


--
-- Name: execute_conference_device_operation_phase1c_core("uuid", "uuid", "bytea", "text", "jsonb"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."execute_conference_device_operation_phase1c_core"("p_user_id" "uuid", "p_session_id" "uuid", "p_token_hash" "bytea", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'platform', 'platform_private'
    AS $$
declare v_session platform_private.device_sessions%rowtype; v_result jsonb;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'CONFERENCE_OPERATION_BACKEND_REQUIRED' using errcode='42501';
  end if;
  if p_user_id is null or p_session_id is null or octet_length(p_token_hash)<>32 then
    raise exception 'DEVICE_SESSION_ARGUMENT_INVALID' using errcode='22023';
  end if;
  select session.* into v_session from platform_private.device_sessions session
  join platform.device_key_bindings binding on binding.id=session.binding_id
  join platform.user_device_authorizations device_authorization
    on device_authorization.id=session.device_authorization_id
  join platform.devices device on device.id=session.device_id
  join platform.profiles profile on profile.user_id=session.user_id
  where session.id=p_session_id and session.user_id=p_user_id
    and session.token_hash=p_token_hash
    and session.revoked_at is null and session.expires_at>statement_timestamp()
    and binding.user_id=session.user_id and binding.device_id=session.device_id
    and binding.device_authorization_id=session.device_authorization_id
    and binding.public_key_thumbprint=session.public_key_thumbprint
    and binding.lifecycle_status='active' and binding.revoked_at is null
    and binding.retired_at is null
    and device_authorization.user_id=session.user_id
    and device_authorization.device_id=session.device_id
    and device_authorization.status='approved'
    and device_authorization.revoked_at is null
    and device.lifecycle_status='active' and device.retired_at is null
    and device.compromised_at is null and profile.account_status='approved';
  if not found then raise exception 'DEVICE_SESSION_INVALID' using errcode='42501'; end if;
  if p_args ? 'p_actor_device_id'
     or (p_args ? 'p_device_id' and p_operation<>'approve_pending_device_authorization') then
    raise exception 'ACTOR_DEVICE_OVERRIDE_DENIED' using errcode='22023';
  end if;
  perform set_config('platform.phase1c_context',jsonb_build_object(
    'purpose','PLATFORM_DEVICE_SESSION_DISPATCH','session_id',v_session.id,
    'user_id',v_session.user_id,'device_id',v_session.device_id,
    'authorization_id',v_session.device_authorization_id,
    'binding_id',v_session.binding_id,'token_hash',encode(p_token_hash,'hex'))::text,true);
  perform set_config('request.jwt.claims',jsonb_build_object(
    'sub',p_user_id,'role','authenticated')::text,true);

  case p_operation

  when 'get_user_management_actor_capabilities' then
    perform platform_private.require_exact_jsonb_keys(p_args,'{}');
    v_result:=public.get_user_management_actor_capabilities(v_session.device_id);
  when 'search_user_management_users' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_query','p_account_status','p_limit']);
    v_result:=public.search_user_management_users(v_session.device_id,p_args->>'p_query',p_args->>'p_account_status',(p_args->>'p_limit')::integer);
  when 'get_user_management_overview' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_target_user_id']);
    v_result:=public.get_user_management_overview(v_session.device_id,(p_args->>'p_target_user_id')::uuid);
  when 'get_user_management_devices' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_target_user_id']);
    v_result:=public.get_user_management_devices(v_session.device_id,(p_args->>'p_target_user_id')::uuid);
  when 'get_user_management_account' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_target_user_id']);
    v_result:=public.get_user_management_account(v_session.device_id,(p_args->>'p_target_user_id')::uuid);
  when 'device_guarded_manage_system_user' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_target_user_id','p_operation_id','p_action'],array['p_requested_value']);
    v_result:=public.device_guarded_manage_system_user(v_session.device_id,(p_args->>'p_target_user_id')::uuid,(p_args->>'p_operation_id')::uuid,p_args->>'p_action',case when p_args ? 'p_requested_value' then (p_args->>'p_requested_value')::boolean else null end);

  when 'list_pending_device_authorizations' then
    perform platform_private.require_exact_jsonb_keys(p_args,'{}');
    v_result:=platform.list_pending_device_authorizations();
  when 'approve_pending_device_authorization' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_authorization_id','p_device_id','p_reason']);
    v_result:=platform.approve_pending_device_authorization((p_args->>'p_authorization_id')::uuid,(p_args->>'p_device_id')::uuid,p_args->>'p_reason');

  when 'apply_library_template_content_operation' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_template_type','p_template_id','p_action','p_base_revision','p_payload']);
    v_result:=public.apply_library_template_content_operation(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_template_type',p_args->>'p_template_id',p_args->>'p_action',(p_args->>'p_base_revision')::bigint,p_args->'p_payload');

  when 'list_module_permission_grants' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_module_key','p_target_user_id']);
    v_result:=public.list_module_permission_grants(v_session.device_id,p_args->>'p_module_key',(p_args->>'p_target_user_id')::uuid);
  when 'manage_foundation_module_grant' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_action','p_target_user_id','p_module_key','p_permission_key','p_grant_id','p_revocation_reason']);
    v_result:=public.manage_foundation_module_grant(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_action',(p_args->>'p_target_user_id')::uuid,p_args->>'p_module_key',p_args->>'p_permission_key',(p_args->>'p_grant_id')::uuid,p_args->>'p_revocation_reason');
  when 'recover_revoke_final_module_manager' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_module_key','p_target_user_id','p_target_grant_id','p_recovery_reason']);
    v_result:=public.recover_revoke_final_module_manager(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_module_key',(p_args->>'p_target_user_id')::uuid,(p_args->>'p_target_grant_id')::uuid,p_args->>'p_recovery_reason');
  when 'acquire_conference_lock','renew_conference_lock' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_lock_token','p_ttl_seconds']);
    if p_operation='acquire_conference_lock' then v_result:=public.device_guarded_acquire_conference_lock(v_session.device_id,(p_args->>'p_conference_id')::uuid,(p_args->>'p_lock_token')::uuid,(p_args->>'p_ttl_seconds')::integer);
    else v_result:=public.device_guarded_renew_conference_lock(v_session.device_id,(p_args->>'p_conference_id')::uuid,(p_args->>'p_lock_token')::uuid,(p_args->>'p_ttl_seconds')::integer); end if;
  when 'release_conference_lock' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_lock_token']);
    v_result:=public.device_guarded_release_conference_lock(v_session.device_id,(p_args->>'p_conference_id')::uuid,(p_args->>'p_lock_token')::uuid);
  when 'get_conference_lock' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    v_result:=public.device_guarded_get_conference_lock(v_session.device_id,(p_args->>'p_conference_id')::uuid);
  when 'acquire_conference_section_lock','renew_conference_section_lock' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_section','p_lock_token','p_ttl_seconds']);
    if p_operation='acquire_conference_section_lock' then v_result:=public.acquire_conference_section_lock((p_args->>'p_conference_id')::uuid,p_args->>'p_section',v_session.device_id,(p_args->>'p_lock_token')::uuid,(p_args->>'p_ttl_seconds')::integer);
    else v_result:=public.renew_conference_section_lock((p_args->>'p_conference_id')::uuid,p_args->>'p_section',v_session.device_id,(p_args->>'p_lock_token')::uuid,(p_args->>'p_ttl_seconds')::integer); end if;
  when 'release_conference_section_lock' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_section','p_lock_token']);
    v_result:=public.release_conference_section_lock((p_args->>'p_conference_id')::uuid,p_args->>'p_section',v_session.device_id,(p_args->>'p_lock_token')::uuid);
  when 'get_conference_section_lock' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_section']);
    v_result:=public.get_conference_section_lock((p_args->>'p_conference_id')::uuid,p_args->>'p_section',v_session.device_id);
  when 'mutate_conference_core' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_expected_revision','p_name','p_start_date','p_end_date','p_status']); v_result:=public.mutate_conference_core(v_session.device_id,(p_args->>'p_conference_id')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->>'p_name',(p_args->>'p_start_date')::date,(p_args->>'p_end_date')::date,p_args->>'p_status'); else raise exception 'CONFERENCE_OPERATION_NOT_ALLOWED' using errcode='42501';
  end case;
  return v_result;
end $$;


--
-- Name: execute_device_operation("uuid", "uuid", "bytea", "text", "text", "jsonb"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."execute_device_operation"("p_user_id" "uuid", "p_session_id" "uuid", "p_token_hash" "bytea", "p_module" "text", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'platform', 'platform_private', 'reservations', 'reservations_private', 'warehouse', 'warehouse_private'
    AS $$
declare v_session platform_private.device_sessions%rowtype; v_result jsonb;
begin
  if coalesce(auth.jwt()->>'role','')<>'service_role' then
    raise exception 'PLATFORM_OPERATION_BACKEND_REQUIRED' using errcode='42501';
  end if;
  if p_user_id is null or p_session_id is null or octet_length(p_token_hash)<>32
     or p_module not in('platform','conference','reservations','warehouse')
     or p_args is null or jsonb_typeof(p_args)<>'object' then
    raise exception 'PLATFORM_OPERATION_ARGUMENT_INVALID' using errcode='22023';
  end if;
  if p_args ? 'p_actor_device_id' or p_args ? 'p_actor_user_id'
     or p_args ? 'actor_device_id' or p_args ? 'actor_user_id'
     or p_args ? 'device_id'
     or p_args ? 'scope_partition_id' or p_args ? 'p_scope_partition_id'
     or p_args ? 'p_conference_person_id' or p_args ? 'conference_person_id'
     or (p_args ? 'p_device_id' and not(
       p_module='platform' and p_operation='approve_pending_device_authorization'
     )) then
    raise exception 'ACTOR_DEVICE_OVERRIDE_DENIED' using errcode='22023';
  end if;

  select session.* into v_session
  from platform_private.device_sessions session
  join platform.device_key_bindings binding on binding.id=session.binding_id
  join platform.user_device_authorizations device_auth on device_auth.id=session.device_authorization_id
  join platform.devices device on device.id=session.device_id
  join platform.profiles profile on profile.user_id=session.user_id
  where session.id=p_session_id and session.user_id=p_user_id
    and session.token_hash=p_token_hash and session.purpose='PLATFORM_DEVICE_SESSION'
    and session.revoked_at is null and session.expires_at>statement_timestamp()
    and binding.user_id=session.user_id and binding.device_id=session.device_id
    and binding.device_authorization_id=session.device_authorization_id
    and binding.public_key_thumbprint=session.public_key_thumbprint
    and binding.algorithm='ECDSA_P256_SHA256' and binding.lifecycle_status='active'
    and binding.revoked_at is null and binding.retired_at is null
    and device_auth.user_id=session.user_id and device_auth.device_id=session.device_id
    and device_auth.status='approved' and device_auth.revoked_at is null
    and device.lifecycle_status='active' and device.retired_at is null
    and device.compromised_at is null and profile.account_status='approved';
  if not found then raise exception 'DEVICE_SESSION_INVALID' using errcode='42501'; end if;

  perform set_config('request.jwt.claims',jsonb_build_object(
    'sub',p_user_id,'role','service_role')::text,true);
  perform set_config('platform.phase1c_context',jsonb_build_object(
    'purpose','PLATFORM_DEVICE_SESSION_DISPATCH','session_id',v_session.id,
    'user_id',v_session.user_id,'device_id',v_session.device_id,
    'authorization_id',v_session.device_authorization_id,'binding_id',v_session.binding_id,
    'token_hash',encode(p_token_hash,'hex'))::text,true);

  if p_operation='check_module_access' then
    if p_module not in('conference','reservations','warehouse') then
      raise exception 'PLATFORM_OPERATION_NOT_ALLOWED' using errcode='42501';
    end if;
    perform platform_private.require_exact_jsonb_keys(p_args,array[]::text[]);
    perform public.require_effective_module_permission(v_session.device_id,p_module,p_module||'.module.access',null,null);
    return jsonb_build_object('status','allowed','moduleKey',p_module);
  end if;

  if p_module='conference' then
    return platform.execute_conference_device_operation(
      p_user_id,p_session_id,p_token_hash,p_operation,p_args
    );
  end if;

  if p_module='platform' then
    case p_operation
    when 'list_system_owner_pending_device_authorizations' then
      perform platform_private.require_exact_jsonb_keys(p_args,array[]::text[]);
      return public.list_system_owner_pending_device_authorizations_for_session(v_session.device_id);
    when 'get_user_management_actor_capabilities' then
      perform platform_private.require_exact_jsonb_keys(p_args,array[]::text[]);
      return public.get_user_management_actor_capabilities(v_session.device_id);
    when 'search_user_management_users' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_query','p_account_status','p_limit']);
      return public.search_user_management_users(v_session.device_id,p_args->>'p_query',p_args->>'p_account_status',(p_args->>'p_limit')::integer);
    when 'get_user_management_overview' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_target_user_id']);
      return public.get_user_management_overview(v_session.device_id,(p_args->>'p_target_user_id')::uuid);
    when 'get_user_management_devices' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_target_user_id']);
      return public.get_user_management_devices(v_session.device_id,(p_args->>'p_target_user_id')::uuid);
    when 'get_user_management_account' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_target_user_id']);
      return public.get_user_management_account(v_session.device_id,(p_args->>'p_target_user_id')::uuid);
    when 'device_guarded_manage_system_user' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_target_user_id','p_operation_id','p_action'],array['p_requested_value']);
      return public.device_guarded_manage_system_user(v_session.device_id,(p_args->>'p_target_user_id')::uuid,(p_args->>'p_operation_id')::uuid,p_args->>'p_action',case when p_args ? 'p_requested_value' then (p_args->>'p_requested_value')::boolean end);
    when 'list_pending_device_authorizations' then
      perform platform_private.require_exact_jsonb_keys(p_args,array[]::text[]);
      return platform.list_pending_device_authorizations();
    when 'approve_pending_device_authorization' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_authorization_id','p_device_id','p_reason']);
      return platform.approve_pending_device_authorization((p_args->>'p_authorization_id')::uuid,(p_args->>'p_device_id')::uuid,p_args->>'p_reason');
    when 'list_library_templates' then
      perform platform_private.require_exact_jsonb_keys(p_args,array[]::text[]);
      return public.list_library_templates(v_session.device_id);
    when 'apply_library_template_content_operation' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_template_type','p_template_id','p_action','p_base_revision','p_payload']);
      return public.apply_library_template_content_operation(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_template_type',p_args->>'p_template_id',p_args->>'p_action',(p_args->>'p_base_revision')::bigint,p_args->'p_payload');
    when 'list_module_permission_grants' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_module_key','p_target_user_id']);
    when 'search_module_permission_candidates' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_module_key','p_query','p_limit']);
    when 'list_module_permission_catalog_for_administration' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_module_key']);
    when 'list_module_permission_resources_for_administration' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_module_key','p_resource_type']);
    when 'manage_catalog_module_grant' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_action','p_target_user_id','p_module_key','p_permission_key','p_resource_type','p_resource_id','p_grant_id','p_revocation_reason']);
    when 'recover_revoke_final_module_manager' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_module_key','p_target_user_id','p_target_grant_id','p_recovery_reason']);
      return public.recover_revoke_final_module_manager(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_module_key',(p_args->>'p_target_user_id')::uuid,(p_args->>'p_target_grant_id')::uuid,p_args->>'p_recovery_reason');
    else raise exception 'PLATFORM_OPERATION_NOT_ALLOWED' using errcode='42501';
    end case;
    return platform_private.route_permission_administration(p_user_id,p_operation,p_args);
  end if;

  if p_module='reservations' then
    case p_operation
    when 'search_people' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_query','p_limit']);
      return reservations.read(v_session.device_id,p_operation,p_args);
    when 'get_effective_capabilities' then
      if p_args ? 'p_conference_id' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
      else perform platform_private.require_exact_jsonb_keys(p_args,array['p_scope_type']); end if;
      return reservations.read(v_session.device_id,p_operation,p_args);
    when 'list_conference_options' then
      perform platform_private.require_exact_jsonb_keys(p_args,array[]::text[]);
    when 'get_booking_creation_context' then
      if p_args ? 'p_scope_type' then
        perform platform_private.require_exact_jsonb_keys(p_args,array['p_scope_type']);
        if p_args->>'p_scope_type' <> 'standalone' then
          raise exception 'RESERVATIONS_SCOPE_TYPE_INVALID' using errcode='22023';
        end if;
      else
        perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
        if nullif(p_args->>'p_conference_id','') is null then
          raise exception 'RESERVATIONS_CONFERENCE_REQUIRED' using errcode='22023';
        end if;
      end if;
    when 'list_events' then
      if p_args ? 'p_scope_type' then
        perform platform_private.require_exact_jsonb_keys(p_args,array['p_scope_type','p_status','p_limit']);
        if p_args->>'p_scope_type'<>'standalone' then raise exception 'PLATFORM_OPERATION_ARGUMENT_INVALID' using errcode='22023'; end if;
      else perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_status','p_limit']); end if;
    when 'get_event','list_event_periods','list_booking_types' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_event_id']);
    when 'get_dashboard_summary' then
      if p_args ? 'p_scope_type' then
        perform platform_private.require_exact_jsonb_keys(p_args,array['p_scope_type']);
        if p_args->>'p_scope_type'<>'platform' then raise exception 'PLATFORM_OPERATION_ARGUMENT_INVALID' using errcode='22023'; end if;
      elsif p_args ? 'p_event_id' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_event_id']);
      else perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']); end if;
    when 'list_bookings' then
      perform platform_private.require_exact_jsonb_keys(p_args,case when nullif(p_args->>'p_event_id','') is null then array['p_conference_id','p_event_id','p_limit'] else array['p_event_id','p_limit'] end);
    when 'get_booking_detail','list_booking_payments','get_operational_state','get_booking_accommodation','get_booking_settlement' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_booking_id']);
    when 'search_participants_bookings' then
      perform platform_private.require_exact_jsonb_keys(p_args,case when nullif(p_args->>'p_event_id','') is null then array['p_conference_id','p_query','p_event_id','p_limit'] else array['p_query','p_event_id','p_limit'] end);
    when 'list_attendance','get_report_source_data' then
      perform platform_private.require_exact_jsonb_keys(p_args,case when nullif(p_args->>'p_event_id','') is null then array['p_conference_id','p_event_id','p_limit'] else array['p_event_id','p_limit'] end);
    when 'get_report_booking_page' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_event_id','p_limit','p_after_created_at','p_after_booking_id']);
    when 'create_event' then
      if p_args ? 'p_scope_type' then
        perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_scope_type','p_name','p_start_date','p_end_date','p_location','p_capacity','p_status','p_notes']);
        if p_args->>'p_scope_type'<>'standalone' then raise exception 'PLATFORM_OPERATION_ARGUMENT_INVALID' using errcode='22023'; end if;
      else perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_name','p_start_date','p_end_date','p_location','p_capacity','p_status','p_notes']); end if;
    when 'update_event' then
      if p_args ? 'p_conference_id' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_expected_revision','p_conference_id','p_name','p_start_date','p_end_date','p_location','p_capacity','p_status','p_notes']);
      else perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_expected_revision','p_name','p_start_date','p_end_date','p_location','p_capacity','p_status','p_notes']); end if;
    when 'delete_event' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_expected_revision']);
    when 'create_event_period' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_kind','p_label','p_starts_on','p_ends_on','p_display_order']);
    when 'update_event_period' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_period_id','p_expected_revision','p_kind','p_label','p_starts_on','p_ends_on','p_display_order']);
    when 'delete_event_period' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_period_id','p_expected_revision']);
    when 'reorder_event_periods' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_period_ids']);
    when 'create_booking_type' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_name','p_code','p_price','p_active','p_display_order','p_eligible_attendance_segments']);
    when 'update_booking_type' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_booking_type_id','p_expected_revision','p_name','p_code','p_price','p_active','p_display_order','p_eligible_attendance_segments']);
    when 'create_booking' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_booking_type_id','p_full_name','p_phone','p_age','p_church','p_governorate','p_city_or_village','p_service_sector','p_service_sector_other','p_notes'],array['p_person_id','p_person_update_revision','p_gender','p_date_of_birth','p_identity_resolution_token','p_identity_resolution_decision']);
    when 'update_participant_booking' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_booking_id','p_expected_revision','p_booking_type_id','p_full_name','p_phone','p_age','p_church','p_governorate','p_city_or_village','p_service_sector','p_service_sector_other','p_notes'],array['p_gender','p_date_of_birth','p_person_update_revision']);
    when 'cancel_booking' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_booking_id','p_expected_revision','p_reason','p_non_refundable_amount','p_refunded_amount','p_credit_amount','p_pending_refund_amount']);
    when 'disburse_refund' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_booking_id','p_amount','p_disbursed_on','p_payment_method','p_payment_method_other','p_reference','p_reason']);
    when 'redeem_person_credit' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_person_id','p_settlement_id','p_expected_revision','p_amount','p_reason']);
    when 'get_cancellation_financial_summary' then perform platform_private.require_exact_jsonb_keys(p_args,case when p_args ? 'p_event_id' then array['p_event_id'] else array[]::text[] end);
    when 'delete_booking' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_booking_id','p_expected_revision']);
    when 'record_payment' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_booking_id','p_amount','p_payment_date','p_payment_method','p_payment_method_other','p_reference','p_notes']);
    when 'void_payment' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_payment_id','p_void_reason']);
    when 'update_attendance' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_booking_id','p_segment','p_attended','p_attendance_date','p_notes']);
    when 'update_operational_review' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_booking_id','p_expected_revision','p_review_status']);
    when 'link_standalone_event_to_conference' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_expected_revision','p_conference_id']);
      return reservations_private.link_standalone_event_to_conference(v_session.device_id,p_args);
    else raise exception 'RESERVATIONS_OPERATION_NOT_ALLOWED' using errcode='42501';
    end case;
    if p_operation in('list_conference_options','get_booking_creation_context','get_booking_accommodation','get_dashboard_summary','list_events','get_event','list_event_periods','list_booking_types','list_bookings','get_booking_detail','search_participants_bookings','list_booking_payments','list_attendance','get_operational_state','get_report_source_data','get_report_booking_page','get_booking_settlement','get_cancellation_financial_summary') then
      return reservations.read(v_session.device_id,p_operation,p_args);
    end if;
    return reservations.mutate(v_session.device_id,p_operation,p_args);
  end if;

  case p_operation
  when 'discover_parties' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_role','p_include_inactive']); v_result:=warehouse.discover_parties(v_session.device_id,p_args->>'p_role',(p_args->>'p_include_inactive')::boolean);
  when 'list_permission_administration_stores' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_include_inactive']); v_result:=warehouse.list_permission_administration_stores(v_session.device_id,(p_args->>'p_include_inactive')::boolean);
  when 'get_beneficiary_balance' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_party_id']); v_result:=warehouse.get_beneficiary_balance(v_session.device_id,(p_args->>'p_party_id')::uuid);
  when 'create_party' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_payload']); v_result:=warehouse.create_party(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->'p_payload');
  when 'update_party' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_party_id','p_expected_revision','p_payload']); v_result:=warehouse.update_party(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_party_id')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->'p_payload');
  when 'list_stores' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_store_id']); select coalesce(jsonb_agg(to_jsonb(x)),'[]') into v_result from warehouse.list_stores(v_session.device_id,(p_args->>'p_store_id')::uuid) x;
  when 'list_item_master' then perform platform_private.require_exact_jsonb_keys(p_args,array[]::text[]); v_result:=warehouse.list_item_master(v_session.device_id);
  when 'view_stock' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_store_id']); v_result:=warehouse.view_stock(v_session.device_id,(p_args->>'p_store_id')::uuid);
  when 'discover_stores' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_include_inactive']); v_result:=warehouse.discover_stores(v_session.device_id,(p_args->>'p_include_inactive')::boolean);
  when 'list_documents' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_document_kind','p_store_id','p_status','p_before_created_at','p_before_id','p_limit']); v_result:=warehouse.list_documents(v_session.device_id,p_args->>'p_document_kind',(p_args->>'p_store_id')::uuid,p_args->>'p_status',(p_args->>'p_before_created_at')::timestamptz,(p_args->>'p_before_id')::uuid,(p_args->>'p_limit')::integer);
  when 'get_document' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_document_id']); v_result:=warehouse.get_document(v_session.device_id,(p_args->>'p_document_id')::uuid);
  when 'list_approval_queue' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_before_created_at','p_before_id','p_limit']); v_result:=warehouse.list_approval_queue(v_session.device_id,(p_args->>'p_before_created_at')::timestamptz,(p_args->>'p_before_id')::uuid,(p_args->>'p_limit')::integer);
  when 'list_reversal_requests' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_status','p_before_created_at','p_before_id','p_limit']); v_result:=warehouse.list_reversal_requests(v_session.device_id,p_args->>'p_status',(p_args->>'p_before_created_at')::timestamptz,(p_args->>'p_before_id')::uuid,(p_args->>'p_limit')::integer);
  when 'list_history' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_store_id','p_document_id','p_item_id','p_document_kind','p_from','p_to','p_before_sequence','p_limit']); v_result:=warehouse.list_history(v_session.device_id,(p_args->>'p_store_id')::uuid,(p_args->>'p_document_id')::uuid,(p_args->>'p_item_id')::uuid,p_args->>'p_document_kind',(p_args->>'p_from')::timestamptz,(p_args->>'p_to')::timestamptz,(p_args->>'p_before_sequence')::bigint,(p_args->>'p_limit')::integer);
  when 'list_balances' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_store_id','p_before_item_id','p_limit']); v_result:=warehouse.list_balances(v_session.device_id,(p_args->>'p_store_id')::uuid,(p_args->>'p_before_item_id')::uuid,(p_args->>'p_limit')::integer);
  when 'create_store' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_name','p_type','p_address','p_notes']); v_result:=warehouse.create_store(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_name',p_args->>'p_type',p_args->>'p_address',p_args->>'p_notes');
  when 'update_store' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_store_id','p_expected_revision','p_name','p_type','p_address','p_status','p_notes']); v_result:=warehouse.update_store(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_store_id')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->>'p_name',p_args->>'p_type',p_args->>'p_address',p_args->>'p_status',p_args->>'p_notes');
  when 'upsert_item_master' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_entity_kind','p_entity_id','p_expected_revision','p_payload']); v_result:=warehouse.upsert_item_master(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_entity_kind',(p_args->>'p_entity_id')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->'p_payload');
  when 'upsert_item_units' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_item_id','p_expected_revision','p_units']); v_result:=warehouse.upsert_item_units(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_item_id')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->'p_units');
  when 'create_receipt_draft','create_issue_draft','create_transfer_draft' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_payload']);
    if p_operation='create_receipt_draft' then v_result:=warehouse.create_receipt_draft(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->'p_payload');
    elsif p_operation='create_issue_draft' then v_result:=warehouse.create_issue_draft(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->'p_payload');
    else v_result:=warehouse.create_transfer_draft(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->'p_payload'); end if;
  when 'create_adjustment_draft' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_adjustment_kind','p_payload']); v_result:=warehouse.create_adjustment_draft(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_adjustment_kind',p_args->'p_payload');
  when 'update_document_draft' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_document_kind','p_document_id','p_expected_revision','p_payload']); v_result:=warehouse.update_document_draft(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_document_kind',(p_args->>'p_document_id')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->'p_payload');
  when 'cancel_document_draft' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_document_kind','p_document_id','p_expected_revision','p_reason']); v_result:=warehouse.cancel_document_draft(v_session.device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_document_kind',(p_args->>'p_document_id')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->>'p_reason');
  when 'submit_adjustment_for_approval','post_receipt','post_issue','post_transfer','post_adjustment' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_document_id','p_expected_revision']);
    if p_operation='submit_adjustment_for_approval' then v_result:=warehouse.submit_adjustment_for_approval(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_document_id')::uuid,(p_args->>'p_expected_revision')::bigint);
    elsif p_operation='post_receipt' then v_result:=warehouse.post_receipt(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_document_id')::uuid,(p_args->>'p_expected_revision')::bigint);
    elsif p_operation='post_issue' then v_result:=warehouse.post_issue(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_document_id')::uuid,(p_args->>'p_expected_revision')::bigint);
    elsif p_operation='post_transfer' then v_result:=warehouse.post_transfer(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_document_id')::uuid,(p_args->>'p_expected_revision')::bigint);
    else v_result:=warehouse.post_adjustment(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_document_id')::uuid,(p_args->>'p_expected_revision')::bigint); end if;
  when 'decide_adjustment_approval' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_document_id','p_expected_revision','p_decision','p_reason']); v_result:=warehouse.decide_adjustment_approval(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_document_id')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->>'p_decision',p_args->>'p_reason');
  when 'create_reversal_request' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_original_document_id','p_reason']); v_result:=warehouse.create_reversal_request(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_original_document_id')::uuid,p_args->>'p_reason');
  when 'submit_reversal_request' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_request_id','p_expected_revision','p_reason']); v_result:=warehouse.submit_reversal_request(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_request_id')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->>'p_reason');
  when 'decide_reversal_approval' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_request_id','p_expected_revision','p_decision','p_reason']); v_result:=warehouse.decide_reversal_approval(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_request_id')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->>'p_decision',p_args->>'p_reason');
  when 'post_reversal' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_request_id','p_expected_revision']); v_result:=warehouse.post_reversal(v_session.device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_request_id')::uuid,(p_args->>'p_expected_revision')::bigint);
  when 'authorize_report_export' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_store_id']); v_result:=warehouse.authorize_report_export(v_session.device_id,(p_args->>'p_store_id')::uuid);
  else raise exception 'WAREHOUSE_OPERATION_NOT_ALLOWED' using errcode='42501';
  end case;
  return v_result;
end $$;


--
-- Name: get_current_device_handoff_assertion_claims("uuid", "text"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."get_current_device_handoff_assertion_claims"("p_challenge_id" "uuid", "p_public_key_thumbprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform', 'platform_private'
    AS $$
declare v_user uuid:=auth.uid(); v_authorization uuid; challenge platform_private.device_ownership_handoff_challenges%rowtype;
begin
  v_authorization:=platform_private.current_device_authorization_id(v_user);
  select * into challenge from platform_private.device_ownership_handoff_challenges item where item.id=p_challenge_id;
  if not found or challenge.user_id<>v_user or challenge.device_authorization_id<>v_authorization OR challenge.device_id IS DISTINCT FROM platform_private.request_device_id()
    or challenge.public_key_thumbprint<>p_public_key_thumbprint or challenge.purpose<>'PLATFORM_DEVICE_OWNERSHIP_HANDOFF'
    or challenge.consumed_at is not null or challenge.failed_at is not null or challenge.expires_at<=statement_timestamp() then
    raise exception 'DEVICE_HANDOFF_ASSERTION_CLAIMS_DENIED' using errcode='42501';
  end if;
  if challenge.handoff_mode='binding_recovery' and not exists(
    select 1 from platform.device_key_bindings binding
    where binding.id=challenge.replacement_binding_id and binding.user_id=challenge.user_id
      and binding.device_id=challenge.device_id
      and binding.device_authorization_id=challenge.device_authorization_id
      and binding.lifecycle_status='active' and binding.rotated_at is null
      and binding.revoked_at is null and binding.retired_at is null
  ) then
    raise exception 'DEVICE_HANDOFF_REPLACEMENT_STALE' using errcode='55000';
  end if;
  return jsonb_build_object('userId',challenge.user_id,'deviceId',challenge.device_id,
    'authorizationId',challenge.device_authorization_id,'challengeId',challenge.id,
    'publicKeyThumbprint',challenge.public_key_thumbprint,'purpose',challenge.purpose,
    'signingPayload',challenge.signing_payload,'challengeExpiresAt',challenge.expires_at,
    'handoffMode',challenge.handoff_mode,'replacementBindingId',challenge.replacement_binding_id,
    'recoveryReason',challenge.recovery_reason);
end;
$$;


--
-- Name: get_device_enrollment_device_status("uuid", "uuid"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."get_device_enrollment_device_status"("p_user_id" "uuid", "p_device_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform'
    AS $$ select coalesce((select jsonb_build_object('known',true,'status',uda.status,'revoked',uda.revoked_at is not null) from platform.user_device_authorizations uda where uda.user_id=p_user_id and uda.device_id=p_device_id order by uda.created_at desc limit 1),jsonb_build_object('known',false,'status','missing','revoked',false)) $$;


--
-- Name: get_device_key_enrollment_status("uuid", "uuid"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."get_device_key_enrollment_status"("p_user_id" "uuid", "p_binding_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform'
    AS $$
  select coalesce((select jsonb_build_object('deviceId',binding.device_id,'authorizationId',binding.device_authorization_id,
    'bindingId',binding.id,'publicKeyThumbprint',binding.public_key_thumbprint,'status',uda.status,
    'deviceLifecycle',device.lifecycle_status,'bindingLifecycle',binding.lifecycle_status)
    from platform.device_key_bindings binding
    join platform.user_device_authorizations uda on uda.id=binding.device_authorization_id
    join platform.devices device on device.id=binding.device_id
    where binding.id=p_binding_id and binding.user_id=p_user_id and uda.user_id=p_user_id
      and uda.device_id=binding.device_id),jsonb_build_object('status','missing'));
$$;


--
-- Name: get_device_session_challenge_context("uuid", "uuid"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."get_device_session_challenge_context"("p_challenge_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform', 'platform_private'
    AS $$
declare v_challenge platform_private.device_session_challenges%rowtype; v_jwk jsonb;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'DEVICE_SESSION_BACKEND_REQUIRED' using errcode='42501';
  end if;
  select challenge.* into v_challenge
  from platform_private.device_session_challenges challenge
  join platform.device_key_bindings binding on binding.id=challenge.binding_id
  join platform.user_device_authorizations device_authorization on device_authorization.id=challenge.device_authorization_id
  join platform.devices device on device.id=challenge.device_id
  join platform.profiles profile on profile.user_id=challenge.user_id
  where challenge.id=p_challenge_id and challenge.user_id=p_user_id
    and challenge.purpose='PLATFORM_DEVICE_SESSION_ESTABLISH'
    and challenge.origin='https://ramyawny37.github.io'
    and challenge.consumed_at is null and challenge.failed_at is null and challenge.expires_at>statement_timestamp()
    and binding.user_id=challenge.user_id and binding.device_id=challenge.device_id
    and binding.device_authorization_id=challenge.device_authorization_id
    and binding.public_key_thumbprint=challenge.public_key_thumbprint
    and binding.lifecycle_status='active' and binding.revoked_at is null and binding.retired_at is null
    and binding.algorithm='ECDSA_P256_SHA256'
    and device_authorization.user_id=challenge.user_id and device_authorization.device_id=challenge.device_id
    and device_authorization.status='approved' and device_authorization.revoked_at is null
    and device.lifecycle_status='active' and device.retired_at is null and device.compromised_at is null
    and profile.account_status='approved';
  if not found then raise exception 'DEVICE_SESSION_CHALLENGE_INVALID' using errcode='42501'; end if;
  select binding.public_key_jwk into strict v_jwk
    from platform.device_key_bindings binding where binding.id=v_challenge.binding_id;
  return jsonb_build_object('challengeId',v_challenge.id,'userId',v_challenge.user_id,'deviceId',v_challenge.device_id,
    'authorizationId',v_challenge.device_authorization_id,'bindingId',v_challenge.binding_id,
    'publicKeyThumbprint',v_challenge.public_key_thumbprint,'purpose',v_challenge.purpose,'origin',v_challenge.origin,
    'issuedAt',v_challenge.issued_at,'expiresAt',v_challenge.expires_at,'signingPayload',v_challenge.signing_payload,
    'publicKeyJwk',v_jwk);
end;
$$;


--
-- Name: get_my_access_context("text", "text", "uuid"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."get_my_access_context"("p_domain" "text" DEFAULT 'platform'::"text", "p_scope_type" "text" DEFAULT 'platform'::"text", "p_scope_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when auth.uid() is null then null else pg_catalog.jsonb_build_object(
    'userId',auth.uid(),'displayName',profile.display_name,'avatarUrl',profile.avatar_url,
    'accountStatus',coalesce(profile.account_status,'pending'),
    'deviceStatus',coalesce((select device_authorization.status from platform.user_device_authorizations device_authorization
      join platform.devices device on device.id=device_authorization.device_id
      where device_authorization.user_id=auth.uid()
        and device.id=platform_private.request_device_id()
        and device.secret_hash=platform_private.hash_device_secret(platform_private.request_header('x-platform-device-secret'))),'missing'),
    'deviceLifecycle',coalesce((select device.lifecycle_status from platform.devices device
      where device.id=platform_private.request_device_id()
        and device.secret_hash=platform_private.hash_device_secret(platform_private.request_header('x-platform-device-secret'))),'unknown'),
    'roles',coalesce((select pg_catalog.jsonb_agg(role.code order by role.code) from platform.user_roles assignment
      join platform.roles role on role.id=assignment.role_id where assignment.user_id=auth.uid()
      and p_domain='platform' and p_scope_type='platform' and p_scope_id is null
      and role.domain='platform' and role.scope_type='platform'
      and assignment.scope_type='platform' and assignment.scope_id is null
      and assignment.revoked_at is null and (assignment.expires_at is null or assignment.expires_at>pg_catalog.now())),'[]'::jsonb),
    'permissions',coalesce((select pg_catalog.jsonb_agg(distinct permission.code order by permission.code)
      from platform.user_roles assignment join platform.roles role on role.id=assignment.role_id
      join platform.role_permissions role_permission on role_permission.role_id=role.id
      join platform.permissions permission on permission.id=role_permission.permission_id
      where assignment.user_id=auth.uid() and p_domain='platform' and p_scope_type='platform' and p_scope_id is null
        and assignment.scope_type='platform' and assignment.scope_id is null
        and role.domain='platform' and role.scope_type='platform' and permission.domain='platform'
        and assignment.revoked_at is null and (assignment.expires_at is null or assignment.expires_at>pg_catalog.now())
        and coalesce(platform_private.validated_phase1c_device_authorization(
          auth.uid(),platform_private.phase1c_context_device_id()
        ),platform_private.current_device_authorization_id(auth.uid())) is not null),'[]'::jsonb)
  ) end from (select 1) singleton left join platform.profiles profile on profile.user_id=auth.uid();
$$;


--
-- Name: get_my_device_authorization(); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."get_my_device_authorization"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when auth.uid() is null then null else pg_catalog.jsonb_build_object(
    'status',coalesce((select device_authorization.status from platform.user_device_authorizations device_authorization join platform.devices device on device.id=device_authorization.device_id
      where device_authorization.user_id=auth.uid() and device.id=platform_private.request_device_id()
      and device.secret_hash=platform_private.hash_device_secret(platform_private.request_header('x-platform-device-secret'))),'missing'),
    'lifecycle',coalesce((select device.lifecycle_status from platform.devices device where device.id=platform_private.request_device_id()
      and device.secret_hash=platform_private.hash_device_secret(platform_private.request_header('x-platform-device-secret'))),'unknown')) end;
$$;


--
-- Name: get_my_device_key_binding_status(); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."get_my_device_key_binding_status"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform'
    AS $$
  select coalesce((select jsonb_build_object('status',binding.lifecycle_status,'bindingId',binding.id,
    'deviceId',binding.device_id,'authorizationId',binding.device_authorization_id,
    'publicKeyThumbprint',binding.public_key_thumbprint,'algorithm',binding.algorithm)
    from platform.device_key_bindings binding join platform.user_device_authorizations device_authorization
      on device_authorization.id=binding.device_authorization_id and device_authorization.user_id=binding.user_id and device_authorization.device_id=binding.device_id
    join platform.devices device on device.id=binding.device_id join platform.profiles profile on profile.user_id=binding.user_id
    where binding.user_id=auth.uid() and binding.lifecycle_status='active' and device_authorization.status='approved'
      and device_authorization.revoked_at is null and device.lifecycle_status='active' and profile.account_status='approved'
    order by binding.activated_at desc limit 1),jsonb_build_object('status','missing'));
$$;


--
-- Name: grant_role_permission("text", "text", "text"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."grant_role_permission"("p_role_domain" "text", "p_role_code" "text", "p_permission_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin perform platform_private.change_role_permission(p_role_domain,p_role_code,p_permission_code,true); end; $$;


--
-- Name: grant_user_role("uuid", "text", "text", "text", "uuid"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."grant_user_role"("p_user_id" "uuid", "p_role_domain" "text", "p_role_code" "text", "p_scope_type" "text", "p_scope_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_role platform.roles%rowtype;v_id uuid;
begin
  if not platform_private.has_permission_for(auth.uid(),'platform.roles.manage','platform',null) then
    raise exception 'PERMISSION_DENIED' using errcode='42501';
  end if;
  if p_role_domain = 'inventory' or p_scope_type = 'inventory' then
    raise exception 'INVENTORY_AUTHORITY_RETIRED' using errcode='42501';
  end if;
  if p_scope_type <> 'platform' or p_scope_id is not null then
    raise exception 'UNSUPPORTED_ROLE_SCOPE' using errcode='22023';
  end if;
  select * into v_role from platform.roles where domain=p_role_domain and code=p_role_code;
  if not found or v_role.scope_type<>p_scope_type then raise exception 'ROLE_NOT_FOUND_OR_SCOPE_INVALID' using errcode='P0002'; end if;
  if not v_role.is_assignable then raise exception 'ROLE_NOT_ASSIGNABLE' using errcode='42501'; end if;
  if not exists(select 1 from platform.profiles where user_id=p_user_id) then raise exception 'PROFILE_NOT_FOUND' using errcode='P0002'; end if;
  select id into v_id from platform.user_roles where user_id=p_user_id and role_id=v_role.id and scope_type=p_scope_type and revoked_at is null;
  if v_id is null then
    insert into platform.user_roles(user_id,role_id,scope_type,scope_id,granted_by)
    values(p_user_id,v_role.id,p_scope_type,null,auth.uid()) returning id into v_id;
    perform platform_private.write_audit_event(auth.uid(),p_user_id,'platform','roles','role.granted','user_role',v_id,p_scope_type,null,
      pg_catalog.jsonb_build_object('domain',p_role_domain,'role',p_role_code),pg_catalog.jsonb_build_object());
  end if;
  return v_id;
end; $$;


--
-- Name: has_permission("text", "text", "uuid"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."has_permission"("p_permission_code" "text", "p_scope_type" "text" DEFAULT 'platform'::"text", "p_scope_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null
    and p_scope_type = 'platform'
    and platform_private.has_permission_for(auth.uid(),p_permission_code,p_scope_type,p_scope_id);
$$;


--
-- Name: list_pending_device_authorizations(); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."list_pending_device_authorizations"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not platform_private.has_permission_for(
    auth.uid(), 'platform.devices.view', 'platform', null
  ) then
    raise exception 'PERMISSION_DENIED' using errcode = '42501';
  end if;

  return pg_catalog.jsonb_build_object(
    'status', 'success',
    'devices', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'authorizationId', device_authorization.id,
          'deviceId', device_authorization.device_id,
          'deviceName', device.display_name,
          'platform', device.platform,
          'browser', device.browser,
          'authorizationStatus', device_authorization.status,
          'requestedAt', device_authorization.requested_at
        ) order by device_authorization.requested_at, device_authorization.id
      )
      from platform.user_device_authorizations device_authorization
      join platform.devices device on device.id = device_authorization.device_id
      join platform.profiles profile on profile.user_id = device_authorization.user_id
      where device_authorization.status = 'pending'
        and device.lifecycle_status = 'active'
        and profile.account_status = 'approved'
    ), '[]'::jsonb)
  );
end;
$$;


--
-- Name: recover_zero_approved_owner_device("uuid", "uuid", "uuid", "uuid", "uuid", "text"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."recover_zero_approved_owner_device"("p_target_user_id" "uuid", "p_target_device_id" "uuid", "p_target_authorization_id" "uuid", "p_target_binding_id" "uuid", "p_operation_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_action constant text:='zero_approved_platform_owner_device_recovery';
  v_reason text:=nullif(pg_catalog.btrim(p_reason),'');
  v_prior platform_private.zero_approved_owner_device_recovery_operations%rowtype;
  v_approved_active_count integer;
  v_changed integer;
  v_audit_id uuid;
  v_result jsonb;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'ZERO_APPROVED_OWNER_RECOVERY_BACKEND_REQUIRED' using errcode='42501';
  end if;
  if p_target_user_id is null or p_target_device_id is null
     or p_target_authorization_id is null or p_target_binding_id is null
     or p_operation_id is null or v_reason is null or length(v_reason)>1000 then
    raise exception 'ZERO_APPROVED_OWNER_RECOVERY_ARGUMENT_INVALID' using errcode='22023';
  end if;

  -- Serialize operation replay/retargeting before taking the owner lock.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('platform-zero-owner-recovery-operation:'||p_operation_id::text,0)
  );
  select * into v_prior
  from platform_private.zero_approved_owner_device_recovery_operations operation
  where operation.operation_id=p_operation_id;
  if found then
    if v_prior.target_user_id is distinct from p_target_user_id
       or v_prior.target_device_id is distinct from p_target_device_id
       or v_prior.target_authorization_id is distinct from p_target_authorization_id
       or v_prior.target_binding_id is distinct from p_target_binding_id
       or v_prior.action is distinct from v_action
       or v_prior.reason is distinct from v_reason then
      raise exception 'ZERO_APPROVED_OWNER_RECOVERY_OPERATION_RETARGET_DENIED' using errcode='22023';
    end if;
    return v_prior.result;
  end if;

  -- Only one zero-device recovery may evaluate an owner at a time.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('platform-zero-owner-recovery-user:'||p_target_user_id::text,0)
  );

  perform 1 from platform.profiles profile
  where profile.user_id=p_target_user_id and profile.account_status='approved'
  for update;
  if not found then
    raise exception 'ZERO_APPROVED_OWNER_RECOVERY_APPROVED_ACCOUNT_REQUIRED' using errcode='42501';
  end if;

  perform 1
  from platform.user_roles assignment
  join platform.roles role on role.id=assignment.role_id
  where assignment.user_id=p_target_user_id
    and assignment.scope_type='platform' and assignment.scope_id is null
    and assignment.revoked_at is null
    and (assignment.expires_at is null or assignment.expires_at>pg_catalog.statement_timestamp())
    and role.domain='platform' and role.scope_type='platform' and role.code='platform_owner'
  for update of assignment,role;
  if not found then
    raise exception 'ZERO_APPROVED_OWNER_RECOVERY_PLATFORM_OWNER_REQUIRED' using errcode='42501';
  end if;

  -- Lock every authorization owned by the target before evaluating the zero-device invariant.
  perform 1 from platform.user_device_authorizations owned
  where owned.user_id=p_target_user_id
  order by owned.id
  for update;

  select count(*)::integer into v_approved_active_count
  from platform.user_device_authorizations approved
  join platform.devices approved_device on approved_device.id=approved.device_id
  where approved.user_id=p_target_user_id
    and approved.status='approved'
    and approved_device.lifecycle_status='active';
  if v_approved_active_count<>0 then
    raise exception 'ZERO_APPROVED_OWNER_RECOVERY_APPROVED_DEVICE_EXISTS' using errcode='55000';
  end if;

  perform 1
  from platform.user_device_authorizations target_authorization
  join platform.devices device on device.id=target_authorization.device_id
  join platform.device_key_bindings binding
    on binding.id=p_target_binding_id
   and binding.user_id=target_authorization.user_id
   and binding.device_id=target_authorization.device_id
   and binding.device_authorization_id=target_authorization.id
  where target_authorization.id=p_target_authorization_id
    and target_authorization.user_id=p_target_user_id
    and target_authorization.device_id=p_target_device_id
    and target_authorization.status='pending'
    and device.id=p_target_device_id
    and device.lifecycle_status='active'
    and binding.lifecycle_status='active'
  for update of target_authorization,device,binding;
  if not found then
    raise exception 'ZERO_APPROVED_OWNER_RECOVERY_TARGET_INVALID' using errcode='42501';
  end if;

  update platform.user_device_authorizations as target_row set
    status='approved',
    status_reason=v_reason,
    approved_by=null,
    approved_at=pg_catalog.statement_timestamp()
  where target_row.id=p_target_authorization_id
    and target_row.user_id=p_target_user_id
    and target_row.device_id=p_target_device_id
    and target_row.status='pending';
  get diagnostics v_changed=row_count;
  if v_changed<>1 then
    raise exception 'ZERO_APPROVED_OWNER_RECOVERY_EXACT_MUTATION_FAILED' using errcode='55000';
  end if;

  v_audit_id:=platform_private.write_audit_event(
    null,p_target_user_id,'platform','devices','device_authorization.zero_approved_owner_recovery',
    'user_device_authorization',p_target_authorization_id,'platform',
    pg_catalog.jsonb_build_object('status','pending'),
    pg_catalog.jsonb_build_object('status','approved','approvedBy',null),
    pg_catalog.jsonb_build_object(
      'action',v_action,'recoveryMode','zero_approved_platform_owner_device',
      'backendContext','service_role_system_recovery','deviceId',p_target_device_id,
      'authorizationId',p_target_authorization_id,'bindingId',p_target_binding_id,
      'operationId',p_operation_id,'reason',v_reason,
      'approvedActiveDeviceCountBefore',v_approved_active_count
    ),null,p_operation_id,'system'
  );

  v_result:=pg_catalog.jsonb_build_object(
    'status','applied','recoveryMode','zero_approved_platform_owner_device',
    'userId',p_target_user_id,'deviceId',p_target_device_id,
    'authorizationId',p_target_authorization_id,'bindingId',p_target_binding_id,
    'operationId',p_operation_id,'authorizationStatus','approved','auditEventId',v_audit_id
  );
  insert into platform_private.zero_approved_owner_device_recovery_operations(
    operation_id,target_user_id,target_device_id,target_authorization_id,target_binding_id,
    action,reason,result,audit_event_id
  ) values(
    p_operation_id,p_target_user_id,p_target_device_id,p_target_authorization_id,p_target_binding_id,
    v_action,v_reason,v_result,v_audit_id
  );
  return v_result;
end;
$$;


--
-- Name: register_current_device("text", "text", "text"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."register_current_device"("p_display_name" "text" DEFAULT NULL::"text", "p_platform" "text" DEFAULT NULL::"text", "p_browser" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p_device_id uuid:=platform_private.request_device_id();v_hash text:=platform_private.hash_device_secret(platform_private.request_header('x-platform-device-secret'));
  v_existing_hash text;v_status text;v_inserted integer;
begin
  if auth.uid() is null then raise exception 'AUTHENTICATION_REQUIRED' using errcode='28000'; end if;
  if p_device_id is null or v_hash is null then raise exception 'INVALID_DEVICE_CREDENTIALS' using errcode='22023'; end if;
  select secret_hash into v_existing_hash from platform.devices where id=p_device_id;
  if found and v_existing_hash<>v_hash then raise exception 'DEVICE_CREDENTIAL_MISMATCH' using errcode='42501'; end if;
  insert into platform.devices(id,secret_hash,display_name,platform,browser)
  values(p_device_id,v_hash,nullif(pg_catalog.btrim(p_display_name),''),nullif(pg_catalog.btrim(p_platform),''),nullif(pg_catalog.btrim(p_browser),''))
  on conflict(id) do update set last_seen_at=pg_catalog.now(),display_name=coalesce(excluded.display_name,platform.devices.display_name),
    platform=coalesce(excluded.platform,platform.devices.platform),browser=coalesce(excluded.browser,platform.devices.browser);
  insert into platform.user_device_authorizations(user_id,device_id) values(auth.uid(),p_device_id)
  on conflict(user_id,device_id) do nothing;
  get diagnostics v_inserted=row_count;
  select status into v_status from platform.user_device_authorizations where user_id=auth.uid() and device_id=p_device_id;
  if v_inserted>0 then perform platform_private.write_audit_event(auth.uid(),auth.uid(),'platform','devices','device.registered',
    'user_device_authorization',(select id from platform.user_device_authorizations where user_id=auth.uid() and device_id=p_device_id),
    'platform',null,pg_catalog.jsonb_build_object('status',v_status),pg_catalog.jsonb_build_object('deviceId',p_device_id)); end if;
  return v_status;
end; $$;


--
-- Name: revoke_device_authorization("uuid", "text"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."revoke_device_authorization"("p_authorization_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin perform platform_private.change_device_authorization(p_authorization_id,'revoked','platform.devices.revoke',p_reason); end; $$;


--
-- Name: revoke_role_permission("text", "text", "text"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."revoke_role_permission"("p_role_domain" "text", "p_role_code" "text", "p_permission_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin perform platform_private.change_role_permission(p_role_domain,p_role_code,p_permission_code,false); end; $$;


--
-- Name: revoke_user_role("uuid"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."revoke_user_role"("p_assignment_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_assignment platform.user_roles%rowtype;v_role platform.roles%rowtype;
begin
  if not platform_private.has_permission_for(auth.uid(),'platform.roles.manage','platform',null) then raise exception 'PERMISSION_DENIED' using errcode='42501'; end if;
  select * into v_assignment from platform.user_roles where id=p_assignment_id for update;
  if not found then raise exception 'ROLE_ASSIGNMENT_NOT_FOUND' using errcode='P0002'; end if;
  select * into v_role from platform.roles where id=v_assignment.role_id;
  if v_role.code='platform_owner' then raise exception 'PLATFORM_OWNER_ROLE_CANNOT_BE_REVOKED_BY_RPC' using errcode='42501'; end if;
  if v_assignment.revoked_at is null then update platform.user_roles set revoked_at=pg_catalog.now(),revoked_by=auth.uid() where id=p_assignment_id;
    perform platform_private.write_audit_event(auth.uid(),v_assignment.user_id,'platform','roles','role.revoked','user_role',p_assignment_id,v_assignment.scope_type,
      pg_catalog.jsonb_build_object('domain',v_role.domain,'role',v_role.code),null,pg_catalog.jsonb_build_object()); end if;
end; $$;


--
-- Name: set_account_status("uuid", "text", "text"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."set_account_status"("p_user_id" "uuid", "p_status" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_old text;
begin
  if p_status not in ('pending','approved','blocked') then raise exception 'INVALID_ACCOUNT_STATUS' using errcode='22023'; end if;
  if not platform_private.has_permission_for(auth.uid(),'platform.users.manage','platform',null) then raise exception 'PERMISSION_DENIED' using errcode='42501'; end if;
  if p_user_id=auth.uid() and p_status<>'approved' then raise exception 'SELF_ACCOUNT_RESTRICTION_FORBIDDEN' using errcode='42501'; end if;
  if p_status<>'approved' and exists(select 1 from platform.user_roles assignment join platform.roles role on role.id=assignment.role_id
    where assignment.user_id=p_user_id and assignment.revoked_at is null and role.domain='platform' and role.code='platform_owner') then
    raise exception 'PLATFORM_OWNER_ACCOUNT_RESTRICTION_FORBIDDEN' using errcode='42501';
  end if;
  select account_status into v_old from platform.profiles where user_id=p_user_id for update;
  if not found then raise exception 'PROFILE_NOT_FOUND' using errcode='P0002'; end if;
  update platform.profiles set account_status=p_status,status_reason=nullif(pg_catalog.btrim(p_reason),''),status_changed_at=pg_catalog.now(),status_changed_by=auth.uid(),
    approved_at=case when p_status='approved' then pg_catalog.now() else approved_at end,approved_by=case when p_status='approved' then auth.uid() else approved_by end,
    blocked_at=case when p_status='blocked' then pg_catalog.now() else null end,blocked_by=case when p_status='blocked' then auth.uid() else null end where user_id=p_user_id;
  perform platform_private.write_audit_event(auth.uid(),p_user_id,'platform','users','account.status_changed','profile',p_user_id,'platform',
    pg_catalog.jsonb_build_object('status',v_old),pg_catalog.jsonb_build_object('status',p_status),pg_catalog.jsonb_build_object('reason',p_reason));
end; $$;


--
-- Name: verify_device_session("uuid", "uuid", "bytea"); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION "platform"."verify_device_session"("p_user_id" "uuid", "p_session_id" "uuid", "p_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'platform', 'platform_private'
    AS $$
declare v_result jsonb;
begin
  if auth.role() is distinct from 'service_role' or pg_catalog.octet_length(p_token_hash)<>32 then
    raise exception 'DEVICE_SESSION_BACKEND_REQUIRED' using errcode='42501';
  end if;
  select jsonb_build_object('valid',true,'sessionId',session.id,'userId',session.user_id,
    'deviceId',session.device_id,'authorizationId',session.device_authorization_id,'bindingId',session.binding_id,
    'purpose',session.purpose,'issuedAt',session.created_at,'expiresAt',session.expires_at)
  into v_result
  from platform_private.device_sessions session
  join platform.device_key_bindings binding on binding.id=session.binding_id
  join platform.user_device_authorizations device_authorization on device_authorization.id=session.device_authorization_id
  join platform.devices device on device.id=session.device_id
  join platform.profiles profile on profile.user_id=session.user_id
  where session.id=p_session_id and session.user_id=p_user_id
    and session.token_hash=p_token_hash and session.purpose='PLATFORM_DEVICE_SESSION'
    and session.revoked_at is null and session.expires_at>statement_timestamp()
    and binding.user_id=session.user_id and binding.device_id=session.device_id
    and binding.device_authorization_id=session.device_authorization_id
    and binding.public_key_thumbprint=session.public_key_thumbprint
    and binding.lifecycle_status='active' and binding.revoked_at is null and binding.retired_at is null
    and device_authorization.user_id=session.user_id and device_authorization.device_id=session.device_id
    and device_authorization.status='approved' and device_authorization.revoked_at is null
    and device.lifecycle_status='active' and device.retired_at is null and device.compromised_at is null
    and profile.account_status='approved';
  if v_result is null then raise exception 'DEVICE_SESSION_INVALID' using errcode='42501'; end if;
  return v_result;
end;
$$;


--
-- Name: acquire_resource_lease("uuid", "text", "text", "text", "text", "uuid", integer); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."acquire_resource_lease"("p_actor_device_id" "uuid", "p_module_id" "text", "p_resource_type" "text", "p_resource_id" "text", "p_scope" "text", "p_lease_token" "uuid", "p_ttl_seconds" integer DEFAULT 120) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid; ttl integer:=coalesce(p_ttl_seconds,120); now_at timestamptz:=clock_timestamp(); exp_at timestamptz; current platform.resource_leases%rowtype;
begin
 if p_lease_token is null or ttl<30 or ttl>300 then raise exception 'PLATFORM_RESOURCE_LEASE_ARGUMENT_INVALID' using errcode='22023'; end if;
 actor_id:=platform_private.require_resource_lease_writer(p_actor_device_id,p_module_id,p_resource_type,p_resource_id,p_scope);
 perform pg_advisory_xact_lock(hashtextextended(concat_ws('|',p_module_id,p_resource_type,p_resource_id,p_scope),0));
 select * into current from platform.resource_leases where module_id=p_module_id and resource_type=p_resource_type and resource_id=p_resource_id and scope=p_scope for update;
 exp_at:=now_at+make_interval(secs=>ttl);
 if not found or current.expires_at<=now_at then
   insert into platform.resource_leases(module_id,resource_type,resource_id,scope,holder_user_id,holder_device_id,lease_token,acquired_at,renewed_at,expires_at)
   values(p_module_id,p_resource_type,p_resource_id,p_scope,actor_id,p_actor_device_id,p_lease_token,now_at,now_at,exp_at)
   on conflict(module_id,resource_type,resource_id,scope) do update set holder_user_id=excluded.holder_user_id,holder_device_id=excluded.holder_device_id,lease_token=excluded.lease_token,acquired_at=excluded.acquired_at,renewed_at=excluded.renewed_at,expires_at=excluded.expires_at;
   return jsonb_build_object('status','acquired','owned',true,'moduleId',p_module_id,'resourceType',p_resource_type,'resourceId',p_resource_id,'scope',p_scope,'leaseToken',p_lease_token,'expiresAt',exp_at,'serverNow',now_at);
 end if;
 if current.holder_user_id=actor_id and current.holder_device_id=p_actor_device_id and platform_private.resource_lease_session_owner(p_actor_device_id,current.holder_session_id) then
   return jsonb_build_object('status','already_owned','owned',true,'moduleId',p_module_id,'resourceType',p_resource_type,'resourceId',p_resource_id,'scope',p_scope,'leaseToken',current.lease_token,'expiresAt',current.expires_at,'serverNow',now_at);
 end if;
 return jsonb_build_object('status','locked','owned',false,'errorCode','RESOURCE_LEASE_HELD','moduleId',p_module_id,'resourceType',p_resource_type,'resourceId',p_resource_id,'scope',p_scope,'expiresAt',current.expires_at,'serverNow',now_at);
end $$;


--
-- Name: assert_conference_room_period_available("uuid", "uuid", "date", "date"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."assert_conference_room_period_available"("p_conference" "uuid", "p_room" "uuid", "p_start" "date", "p_end" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if p_start is null or p_end is null or p_end<p_start then raise exception 'CONFERENCE_CORE_ARGUMENT_INVALID' using errcode='22023';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('conference-room-period:'||p_room::text,0));
 if exists(
  select 1 from public.conference_room_assignments a
  join public.conferences c on c.id=a.conference_id
  where a.room_id=p_room and a.conference_id<>p_conference and c.deleted_at is null
    and p_start<=c.end_date and c.start_date<=p_end
 ) then raise exception 'ROOM_CONFERENCE_PERIOD_OVERLAP' using errcode='23P01';end if;
end $$;


SET default_tablespace = '';

SET default_table_access_method = "heap";

--
-- Name: conference_transport_assignments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."conference_transport_assignments" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "conference_id" "uuid" NOT NULL,
    "vehicle_id" "uuid" NOT NULL,
    "participation_id" "uuid" NOT NULL,
    "assignment_mode" "text" NOT NULL,
    "rider_kind" "text" NOT NULL,
    "seat_number" integer,
    "revision" bigint DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "created_by" "uuid" NOT NULL,
    "updated_by" "uuid" NOT NULL,
    CONSTRAINT "conference_transport_assignments_assignment_mode_check" CHECK (("assignment_mode" = ANY (ARRAY['independent'::"text", 'shared'::"text"]))),
    CONSTRAINT "conference_transport_assignments_check" CHECK (((("assignment_mode" = 'independent'::"text") AND ("seat_number" IS NOT NULL)) OR (("assignment_mode" = 'shared'::"text") AND ("seat_number" IS NULL)))),
    CONSTRAINT "conference_transport_assignments_revision_check" CHECK (("revision" >= 1)),
    CONSTRAINT "conference_transport_assignments_rider_kind_check" CHECK (("rider_kind" = ANY (ARRAY['adult'::"text", 'child'::"text", 'infant'::"text"]))),
    CONSTRAINT "conference_transport_assignments_seat_number_check" CHECK ((("seat_number" >= 1) AND ("seat_number" <= 300)))
);

ALTER TABLE ONLY "public"."conference_transport_assignments" FORCE ROW LEVEL SECURITY;


--
-- Name: audit_conference_transport_assignment_removal("uuid", "uuid", "public"."conference_transport_assignments", "uuid", "text", "text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."audit_conference_transport_assignment_removal"("p_actor" "uuid", "p_device_authorization" "uuid", "p_assignment" "public"."conference_transport_assignments", "p_operation_id" "uuid", "p_reason" "text", "p_permission" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,
    entity_id,scope_type,old_values,new_values,metadata,operation_id,source)
  values(p_actor,p_device_authorization,'platform','conference','conference.transport.assignment_removed',
    'conference_transport_assignment',p_assignment.id,'platform',to_jsonb(p_assignment),null,
    jsonb_build_object('conferenceId',p_assignment.conference_id,'vehicleId',p_assignment.vehicle_id,
      'participationId',p_assignment.participation_id,'removalReason',p_reason,'permissionKey',p_permission),
    p_operation_id,'rpc');
end $$;


--
-- Name: canonical_device_count("uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."canonical_device_count"("p_user_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select count(*) from platform.user_device_authorizations device_authorization
  join platform.devices device on device.id=device_authorization.device_id
  where device_authorization.user_id=p_user_id
    and device.lifecycle_status='active' and device.retired_at is null
    and device.compromised_at is null;
$$;


--
-- Name: change_device_authorization("uuid", "text", "text", "text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."change_device_authorization"("p_authorization_id" "uuid", "p_status" "text", "p_permission" "text", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_row platform.user_device_authorizations%rowtype;
begin
  if not platform_private.has_permission_for(auth.uid(),p_permission,'platform',null) then raise exception 'PERMISSION_DENIED' using errcode='42501'; end if;
  select * into v_row from platform.user_device_authorizations where id=p_authorization_id for update;
  if not found then raise exception 'DEVICE_AUTHORIZATION_NOT_FOUND' using errcode='P0002'; end if;
  if v_row.status='revoked' then raise exception 'DEVICE_AUTHORIZATION_REVOKED_TERMINAL' using errcode='55000'; end if;
  if p_status in ('blocked','revoked') and exists(select 1 from platform.user_roles assignment join platform.roles role on role.id=assignment.role_id
      where assignment.user_id=v_row.user_id and assignment.revoked_at is null and role.domain='platform' and role.code='platform_owner')
    and not exists(select 1 from platform.user_device_authorizations other join platform.devices device on device.id=other.device_id
      where other.user_id=v_row.user_id and other.id<>v_row.id and other.status='approved' and device.lifecycle_status='active') then
    raise exception 'LAST_PLATFORM_OWNER_DEVICE_RESTRICTION_FORBIDDEN' using errcode='42501';
  end if;
  update platform.user_device_authorizations set status=p_status,status_reason=nullif(pg_catalog.btrim(p_reason),''),
    approved_by=case when p_status='approved' then auth.uid() else approved_by end,approved_at=case when p_status='approved' then pg_catalog.now() else approved_at end,
    blocked_by=case when p_status='blocked' then auth.uid() else null end,blocked_at=case when p_status='blocked' then pg_catalog.now() else null end,
    revoked_by=case when p_status='revoked' then auth.uid() else null end,revoked_at=case when p_status='revoked' then pg_catalog.now() else null end
  where id=p_authorization_id;
  perform platform_private.write_audit_event(auth.uid(),v_row.user_id,'platform','devices','device_authorization.'||p_status,'user_device_authorization',p_authorization_id,
    'platform',pg_catalog.jsonb_build_object('status',v_row.status),pg_catalog.jsonb_build_object('status',p_status),pg_catalog.jsonb_build_object('reason',p_reason));
end; $$;


--
-- Name: change_role_permission("text", "text", "text", boolean); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."change_role_permission"("p_role_domain" "text", "p_role_code" "text", "p_permission_code" "text", "p_granted" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_role platform.roles%rowtype;v_permission platform.permissions%rowtype;v_changed integer;
begin
  if not platform_private.has_permission_for(auth.uid(),'platform.roles.manage','platform',null) then raise exception 'PERMISSION_DENIED' using errcode='42501'; end if;
  select * into v_role from platform.roles where domain=p_role_domain and code=p_role_code;
  select * into v_permission from platform.permissions where code=p_permission_code;
  if v_role.id is null or v_permission.id is null then raise exception 'ROLE_OR_PERMISSION_NOT_FOUND' using errcode='P0002'; end if;
  if v_role.domain<>v_permission.domain then raise exception 'CROSS_DOMAIN_PERMISSION_FORBIDDEN' using errcode='42501'; end if;
  if v_role.code='platform_owner' then raise exception 'PLATFORM_OWNER_PERMISSIONS_IMMUTABLE' using errcode='42501'; end if;
  if p_granted then insert into platform.role_permissions(role_id,permission_id,created_by) values(v_role.id,v_permission.id,auth.uid()) on conflict do nothing;
  else delete from platform.role_permissions where role_id=v_role.id and permission_id=v_permission.id; end if;
  get diagnostics v_changed=row_count;
  if v_changed>0 then perform platform_private.write_audit_event(auth.uid(),null,'platform','roles',case when p_granted then 'permission.granted' else 'permission.revoked' end,
    'role',v_role.id,v_role.scope_type,null,pg_catalog.jsonb_build_object('permission',p_permission_code,'granted',p_granted),pg_catalog.jsonb_build_object()); end if;
end; $$;


--
-- Name: cleanup_conference_accommodation_for_participation("uuid", "uuid", "uuid", "jsonb", "text", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."cleanup_conference_accommodation_for_participation"("p_participation_id" "uuid", "p_actor_user_id" "uuid", "p_device_authorization_id" "uuid", "p_authority_context" "jsonb", "p_cause" "text", "p_operation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item public.conference_accommodation_occupancies%rowtype;
  first_changed uuid; effective_day integer; conference_start date; conference_days integer;
begin
  if p_cause not in('accommodation_removed','participation_apologized','participation_deleted') then
    raise exception 'PARTICIPATION_ACCOMMODATION_CLEANUP_CAUSE_INVALID' using errcode='22023';
  end if;
  select c.start_date,(c.end_date-c.start_date+1)::integer into conference_start,conference_days
  from public.conference_participations p join public.conferences c on c.id=p.conference_id
  where p.id=p_participation_id;
  if conference_start is null then return null; end if;
  effective_day:=greatest(1,least(conference_days+1,(current_date-conference_start+1)::integer));
  for item in
    select * from public.conference_accommodation_occupancies
    where participation_id=p_participation_id order by room_id,arrival_day,id for update
  loop
    if item.arrival_day>=effective_day then
      delete from public.conference_accommodation_occupancies where id=item.id;
    elsif coalesce(item.leave_day,conference_days+1)>effective_day then
      update public.conference_accommodation_occupancies
      set leave_day=effective_day,revision=revision+1,updated_at=statement_timestamp(),updated_by=p_actor_user_id
      where id=item.id;
    else
      continue;
    end if;
    first_changed:=coalesce(first_changed,item.id);
    insert into platform.audit_events(
      actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,
      scope_type,old_values,new_values,metadata,operation_id,source)
    values(p_actor_user_id,p_device_authorization_id,'platform','conference',
      'conference.accommodation.participation_cleanup','accommodation_occupancy',item.id,'platform',
      to_jsonb(item),null,jsonb_build_object('conferenceId',item.conference_id,
      'participationId',p_participation_id,'occupancyId',item.id,'previousRoomId',item.room_id,
      'effectiveDay',effective_day,'cause',p_cause,'permissionKey',
      case when p_cause='accommodation_removed' then 'conference.accommodation.manage' else 'conference.people.manage' end,
      'authoritySource',p_authority_context->>'authoritySource','grantId',p_authority_context->'grantId'),
      p_operation_id,'rpc');
  end loop;
  return first_changed;
end $$;


--
-- Name: cleanup_conference_transport_for_participation("uuid", "uuid", "uuid", "text", "uuid", "text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."cleanup_conference_transport_for_participation"("p_participation_id" "uuid", "p_actor_user_id" "uuid", "p_device_authorization_id" "uuid", "p_cause" "text", "p_operation_id" "uuid", "p_permission_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_assignment public.conference_transport_assignments%rowtype;
  v_removed_ids jsonb:='[]'::jsonb;
begin
  if p_cause not in('accommodation_removed','participation_apologized','participation_deleted','guardian_participation_deleted') then
    raise exception 'CONFERENCE_TRANSPORT_CLEANUP_CAUSE_INVALID' using errcode='22023';
  end if;
  for v_assignment in
    select assignment.* from public.conference_transport_assignments assignment
    where assignment.participation_id=p_participation_id
    order by assignment.id for update
  loop
    perform platform_private.audit_conference_transport_assignment_removal(
      p_actor_user_id,p_device_authorization_id,v_assignment,p_operation_id,p_cause,p_permission_key);
    v_removed_ids:=v_removed_ids||jsonb_build_array(v_assignment.id);
  end loop;
  delete from public.conference_transport_assignments where participation_id=p_participation_id;
  return v_removed_ids;
end $$;


--
-- Name: clear_conference_room_key_on_stay_delete(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."clear_conference_room_key_on_stay_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 update public.conference_room_assignments ra
 set key_holder_occupancy_id=null,key_delivered_at=null,key_delivered_by=null,
     revision=ra.revision+1,updated_at=statement_timestamp()
 where ra.key_holder_occupancy_id=old.id;
 return old;
end $$;


--
-- Name: clear_conference_room_key_on_stay_move(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."clear_conference_room_key_on_stay_move"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if old.room_id is distinct from new.room_id then
  update public.conference_room_assignments ra
  set key_holder_occupancy_id=null,key_delivered_at=null,key_delivered_by=null,
      revision=ra.revision+1,updated_at=statement_timestamp()
  where ra.key_holder_occupancy_id=old.id and ra.room_id=old.room_id;
 end if;
 return new;
end $$;


--
-- Name: conference_accommodation_duration("uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."conference_accommodation_duration"("p_conference" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare days integer;
begin
  select end_date-start_date+1 into days from public.conferences where id=p_conference and start_date is not null and end_date is not null and end_date>=start_date;
  if days is null then raise exception 'CONFERENCE_DURATION_REQUIRED' using errcode='22023'; end if; return days;
end $$;


--
-- Name: conference_accommodation_pricing_projection("uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."conference_accommodation_pricing_projection"("p_conference" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'enabled',coalesce(s.enabled,true),'pricingMode',coalesce(s.pricing_mode,'per_person_night'),
    'prices',jsonb_build_object('personNight',coalesce(s.person_night,0),'roomNight',coalesce(s.room_night,0),'personDay',coalesce(s.person_day,0),'roomDay',coalesce(s.room_day,0),'packagePrice',coalesce(s.package_price,0),'packageDayPrice',coalesce(s.package_day_price,0)),
    'roomTypePrices',jsonb_build_object('single',coalesce(s.single_price,0),'double',coalesce(s.double_price,0),'triple',coalesce(s.triple_price,0),'quadruple',coalesce(s.quadruple_price,0),'quintuple',coalesce(s.quintuple_price,0),'sextuple',coalesce(s.sextuple_price,0),'sevenPlus',coalesce(s.seven_plus_price,0)),
    'revision',coalesce(s.revision,0),'updatedAt',s.updated_at,'updatedBy',s.updated_by)
  from (select p_conference conference_id) c left join public.conference_accommodation_pricing s using(conference_id)
$$;


--
-- Name: conference_branding_projection("uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."conference_branding_projection"("p_conference" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
select jsonb_build_object('conferenceId',b.conference_id,'banner',b.banner,'serviceLogo',b.service_logo,
  'autoColors',b.auto_colors,'bannerPosition',b.banner_position,'cardTheme',b.card_theme,
  'primaryColor',b.primary_color,'secondaryColor',b.secondary_color,'textColor',b.text_color,
  'revision',b.revision,'updatedAt',b.updated_at,'updatedBy',b.updated_by)
from public.conference_branding b where b.conference_id=p_conference
$$;


--
-- Name: conference_bundle_rows("text", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."conference_bundle_rows"("p_table" "text", "p_conference_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rows jsonb;
begin
 if not p_table=any(platform_private.conference_bundle_tables()) then
  raise exception 'CONFERENCE_BUNDLE_TABLE_NOT_ALLOWED' using errcode='22023';
 end if;
 execute format(
  'select coalesce(jsonb_agg(to_jsonb(t)-array[''created_by'',''updated_by'',''created_at'',''updated_at'',''revision''] order by t.id::text),''[]''::jsonb) from public.%I t where conference_id=$1',p_table
 ) into v_rows using p_conference_id;
 return v_rows;
exception when undefined_column then
 execute format(
  'select coalesce(jsonb_agg(to_jsonb(t)-array[''created_by'',''updated_by'',''created_at'',''updated_at'',''revision'']),''[]''::jsonb) from public.%I t where conference_id=$1',p_table
 ) into v_rows using p_conference_id;
 return v_rows;
end $_$;


--
-- Name: conference_bundle_tables(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."conference_bundle_tables"() RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select array[
  'conference_participations','conference_house_assignments','conference_room_assignments',
  'conference_accommodation_occupancies','conference_accommodation_pricing',
  'conference_accommodation_pricing_room_exclusions','conference_air_conditioning_defaults',
  'conference_air_conditioning_house_overrides','conference_air_conditioning_room_overrides',
  'conference_branding','conference_finance_settings','conference_finance_items',
  'conference_finance_adjustments','conference_restaurant_settings',
  'conference_restaurant_price_overrides','conference_restaurant_count_overrides',
  'conference_restaurant_participation_overrides','conference_transport_vehicles',
  'conference_transport_assignments'
 ]::text[]
$$;


--
-- Name: conference_bundle_uuid("uuid", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."conference_bundle_uuid"("p_operation_id" "uuid", "p_source" "uuid") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
 select (substr(v,1,8)||'-'||substr(v,9,4)||'-4'||substr(v,14,3)||'-a'||substr(v,18,3)||'-'||substr(v,21,12))::uuid
 from (select md5(p_operation_id::text||':'||p_source::text) v) value
$$;


--
-- Name: conference_finance_projection("uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."conference_finance_projection"("p_conference" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s jsonb;i jsonb;a jsonb;begin
 select coalesce(to_jsonb(x)-'conference_id'-'created_at'-'created_by','{}') into s from public.conference_finance_settings x where conference_id=p_conference;
 select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'created_at'-'created_by' order by kind,id),'[]') into i from public.conference_finance_items x where conference_id=p_conference;
 select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'created_at'-'created_by' order by id),'[]') into a from public.conference_finance_adjustments x where conference_id=p_conference;
 return jsonb_build_object('conferenceId',p_conference,'settings',coalesce(s,jsonb_build_object('currency','EGP','rounding_precision',2,'expenses_enabled',true,'income_enabled',true,'settlements_enabled',true,'adjustments_enabled',true,'revision',0)),'items',i,'adjustments',a);
end $$;


--
-- Name: conference_operational_day("uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."conference_operational_day"("p_conference" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select greatest(1,least((end_date-start_date+1)::integer,(current_date-start_date+1)::integer))
 from public.conferences where id=p_conference and start_date is not null and end_date is not null
$$;


--
-- Name: conference_room_has_capacity("uuid", "uuid", "text", integer, integer, "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."conference_room_has_capacity"("p_conference" "uuid", "p_room" "uuid", "p_bed" "text", "p_arrival" integer, "p_leave" integer, "p_exclude_occupancy" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p_bed='shared'
    or (p_bed='extra' and exists(
      select 1 from public.conference_accommodation_occupancies excluded
      where excluded.id=p_exclude_occupancy and excluded.extra_bed_source='automatic'))
    or not exists(
      select 1
      from generate_series(p_arrival,coalesce(p_leave,platform_private.conference_accommodation_duration(p_conference)+1)-1) night(day)
      cross join lateral(
        select count(*)::integer used
        from public.conference_accommodation_occupancies occupancy
        where occupancy.conference_id=p_conference and occupancy.room_id=p_room
          and occupancy.bed_type=p_bed and occupancy.id is distinct from p_exclude_occupancy
          and (p_bed<>'extra' or occupancy.extra_bed_source='manual')
          and occupancy.arrival_day<=night.day
          and coalesce(occupancy.leave_day,platform_private.conference_accommodation_duration(p_conference)+1)>night.day
      ) usage
      join public.conference_accommodation_rooms room on room.id=p_room
      join public.conference_room_assignments assignment
        on assignment.conference_id=p_conference and assignment.room_id=room.id
      where usage.used>=case when p_bed='base' then room.base_capacity else assignment.extra_bed_capacity end)
$$;


--
-- Name: conference_room_is_assigned("uuid", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."conference_room_is_assigned"("p_conference" "uuid", "p_room" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select exists(select 1 from public.conference_room_assignments a where a.conference_id=p_conference and a.room_id=p_room)
$$;


