-- Name: create_conference_branding_default(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."create_conference_branding_default"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin insert into public.conference_branding(conference_id) values(new.id);return new;end $$;


--
-- Name: create_permission_grant("uuid", "uuid", "uuid", "text", "text", "text", "text", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."create_permission_grant"("p_actor" "uuid", "p_actor_device_id" "uuid", "p_target" "uuid", "p_module" "text", "p_permission" "text", "p_resource_type" "text" DEFAULT NULL::"text", "p_resource_id" "text" DEFAULT NULL::"text", "p_operation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_permission_id uuid;v_id uuid;v_device_authorization_id uuid;
begin
 if p_actor is null or p_actor_device_id is null or p_target is null or p_operation_id is null
 or p_module not in('conference','warehouse','reservations')
 or p_permission is null or ((p_resource_type is null)<>(p_resource_id is null)) then
  raise exception 'INVALID_PERMISSION_GRANT' using errcode='22023'; end if;
 v_device_authorization_id:=platform_private.validated_phase1c_device_authorization(p_actor,p_actor_device_id);
 if v_device_authorization_id is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
 if not exists(select 1 from platform.profiles where user_id=p_target and account_status='approved') then
  raise exception 'TARGET_ACCOUNT_APPROVED_REQUIRED' using errcode='42501'; end if;
 select id into v_permission_id from platform.permissions
 where domain=p_module and code=p_permission and status='active'
 and ((p_resource_type is null and allowed_scope_mode in('module','both'))
   or (p_resource_type is not null and allowed_scope_mode in('resource','both') and allowed_resource_type=p_resource_type));
 if v_permission_id is null then raise exception 'ACTIVE_PERMISSION_SCOPE_REQUIRED' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('permission-grant:'||p_target::text||':'||v_permission_id::text||':'||coalesce(p_resource_type,'')||':'||coalesce(p_resource_id,''),0));
 select id into v_id from platform.permission_grants
 where user_id=p_target and permission_id=v_permission_id and revoked_at is null
 and ((p_resource_type is null and scope_type='module')
  or (p_resource_type is not null and scope_type='resource' and resource_type=p_resource_type and resource_id=p_resource_id));
 if v_id is null then
  insert into platform.permission_grants(user_id,permission_id,scope_type,resource_type,resource_id,granted_by,metadata)
  values(p_target,v_permission_id,case when p_resource_type is null then 'module' else 'resource' end,
   p_resource_type,p_resource_id,p_actor,
   jsonb_build_object('actorDeviceId',p_actor_device_id,'operationId',p_operation_id))
  returning id into v_id;
  insert into platform.audit_events(
   actor_user_id,actor_device_authorization_id,subject_user_id,domain,module,action,
   entity_type,entity_id,scope_type,new_values,metadata,operation_id,source
  ) values(
   p_actor,v_device_authorization_id,p_target,'platform',p_module,'permission.granted',
   'permission_grant',v_id,'platform',
   jsonb_build_object('grantId',v_id,'targetUserId',p_target,'moduleKey',p_module,
    'permissionKey',p_permission,'grantScope',case when p_resource_type is null then 'module' else 'resource' end,
    'resourceType',p_resource_type,'resourceId',p_resource_id),
   jsonb_build_object('actorDeviceId',p_actor_device_id),p_operation_id,'rpc'
  );
 end if;
 return v_id;
end $$;


--
-- Name: current_device_authorization_id("uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."current_device_authorization_id"("p_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select device_authorization.id from platform.user_device_authorizations device_authorization
  join platform.devices device on device.id=device_authorization.device_id
  where device_authorization.user_id=p_user_id and device_authorization.status='approved'
    and device.lifecycle_status='active'
    and device.id=platform_private.request_device_id()
    and device.secret_hash=platform_private.hash_device_secret(platform_private.request_header('x-platform-device-secret'));
$$;


--
-- Name: enforce_conference_participation_guardian_one_level(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."enforce_conference_participation_guardian_one_level"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_guardian public.conference_participations%rowtype;
begin
  if tg_op='UPDATE' and new.guardian_participation_id is not distinct from old.guardian_participation_id then return new; end if;
  perform pg_advisory_xact_lock(hashtextextended('conference-guardian:'||new.conference_id::text,0));
  if new.guardian_participation_id is null then return new; end if;
  if new.guardian_participation_id=new.id then
    raise exception 'CONFERENCE_GUARDIAN_SELF_REFERENCE' using errcode='23514';
  end if;
  select * into v_guardian from public.conference_participations
  where id=new.guardian_participation_id and conference_id=new.conference_id for update;
  if not found then raise exception 'CONFERENCE_GUARDIAN_SAME_CONFERENCE_REQUIRED' using errcode='23503'; end if;
  if v_guardian.guardian_participation_id is not null then
    raise exception 'CONFERENCE_GUARDIAN_ONE_LEVEL_REQUIRED' using errcode='23514';
  end if;
  perform 1 from public.conference_participations
  where conference_id=new.conference_id and guardian_participation_id=new.id for update;
  if found then raise exception 'CONFERENCE_GUARDIAN_ONE_LEVEL_REQUIRED' using errcode='23514'; end if;
  return new;
end $$;


--
-- Name: enforce_linked_child_guardian_stay(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."enforce_linked_child_guardian_stay"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  child public.conference_participations%rowtype;
  guardian public.conference_participations%rowtype;
  guardian_stay public.conference_accommodation_occupancies%rowtype;
  conference_days integer;
begin
  select * into child from public.conference_participations
  where id=new.participation_id and conference_id=new.conference_id;
  if not found or child.guardian_participation_id is null then return new; end if;
  select * into guardian from public.conference_participations
  where id=child.guardian_participation_id and conference_id=new.conference_id and status='active';
  if not found then raise exception 'ACCOMMODATION_ACTIVE_GUARDIAN_REQUIRED' using errcode='23514'; end if;
  conference_days:=platform_private.conference_accommodation_duration(new.conference_id);
  if new.bed_type='shared' then
    select * into guardian_stay from public.conference_accommodation_occupancies stay
    where stay.conference_id=new.conference_id and stay.participation_id=guardian.id
      and stay.room_id=new.room_id and stay.arrival_day=new.arrival_day
      and stay.leave_day is not distinct from new.leave_day
    order by stay.id limit 1 for key share;
    if not found then raise exception 'ACCOMMODATION_SHARED_CHILD_GUARDIAN_STAY_REQUIRED' using errcode='23514'; end if;
  else
    select * into guardian_stay from public.conference_accommodation_occupancies stay
    where stay.conference_id=new.conference_id and stay.participation_id=guardian.id
      and stay.arrival_day<=new.arrival_day
      and coalesce(stay.leave_day,conference_days+1)>=coalesce(new.leave_day,conference_days+1)
    order by stay.arrival_day desc,stay.id limit 1 for key share;
    if not found then raise exception 'ACCOMMODATION_CHILD_GUARDIAN_STAY_REQUIRED' using errcode='23514'; end if;
  end if;
  if new.bed_type='extra' and new.extra_bed_person_type is distinct from 'child' then
    raise exception 'ACCOMMODATION_CHILD_BED_TYPE_INVALID' using errcode='23514';
  end if;
  if new.bed_type<>'extra' and new.extra_bed_person_type is not null then
    raise exception 'ACCOMMODATION_CHILD_BED_TYPE_INVALID' using errcode='23514';
  end if;
  if new.bed_type='shared' then
    if tg_op='INSERT' then new.arrived_at:=guardian_stay.arrived_at;new.arrived_by:=guardian_stay.arrived_by;
    elsif new.arrived_at is distinct from guardian_stay.arrived_at or new.arrived_by is distinct from guardian_stay.arrived_by then
      raise exception 'ACCOMMODATION_CHILD_ARRIVAL_INHERITED' using errcode='23514'; end if;
  end if;
  return new;
end $$;


--
-- Name: enforce_resource_lease_session(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."enforce_resource_lease_session"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_session uuid;
begin
  v_session:=platform_private.require_resource_lease_session(
    case when tg_op='DELETE' then old.holder_device_id else new.holder_device_id end
  );
  if tg_op='INSERT' then
    new.holder_session_id:=v_session;
    return new;
  end if;
  if old.holder_session_id is distinct from v_session
     and not (tg_op='UPDATE' and old.expires_at<=pg_catalog.clock_timestamp()) then
    raise exception 'RESOURCE_LEASE_SESSION_NOT_OWNED' using errcode='42501';
  end if;
  if tg_op='DELETE' then return old; end if;
  new.holder_session_id:=v_session;
  return new;
end $$;


--
-- Name: enforce_transport_resident_assignment(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."enforce_transport_resident_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare part public.conference_participations%rowtype;
begin
  select * into part from public.conference_participations where id=new.participation_id and conference_id=new.conference_id and status='active';
  if not found or not exists(select 1 from public.conference_accommodation_occupancies o where o.participation_id=part.id) then
    raise exception 'CONFERENCE_TRANSPORT_RESIDENT_REQUIRED' using errcode='23514';
  end if;
  if new.rider_kind in('child','infant') and part.guardian_participation_id is null then
    raise exception 'CONFERENCE_TRANSPORT_CHILD_GUARDIAN_REQUIRED' using errcode='23514';
  end if;
  return new;
end $$;


--
-- Name: get_resource_lease("uuid", "text", "text", "text", "text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."get_resource_lease"("p_actor_device_id" "uuid", "p_module_id" "text", "p_resource_type" "text", "p_resource_id" "text", "p_scope" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid; current platform.resource_leases%rowtype; now_at timestamptz:=clock_timestamp(); owned boolean;
begin
 actor_id:=platform_private.require_resource_lease_writer(p_actor_device_id,p_module_id,p_resource_type,p_resource_id,p_scope);
 select * into current from platform.resource_leases where module_id=p_module_id and resource_type=p_resource_type and resource_id=p_resource_id and scope=p_scope;
 if not found or current.expires_at<=now_at then return jsonb_build_object('status','available','locked',false,'owned',false,'serverNow',now_at); end if;
 owned:=current.holder_user_id=actor_id and current.holder_device_id=p_actor_device_id and platform_private.resource_lease_session_owner(p_actor_device_id,current.holder_session_id);
 return jsonb_strip_nulls(jsonb_build_object('status','locked','locked',true,'owned',owned,'leaseToken',case when owned then current.lease_token else null end,'expiresAt',current.expires_at,'serverNow',now_at));
end $$;


--
-- Name: grant_deterministic_resource_permission("jsonb", "uuid", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."grant_deterministic_resource_permission"("p_authorization_context" "jsonb", "p_operation_id" "uuid", "p_created_resource_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid;v_device uuid;v_verified jsonb;v_grant_id uuid;
begin
 if p_authorization_context is null or p_operation_id is null or p_created_resource_id is null
 or p_authorization_context->>'moduleKey'<>'reservations'
 or p_authorization_context->>'permissionKey'<>'reservations.event.create'
 then raise exception 'DETERMINISTIC_RESOURCE_GRANT_RULE_INVALID' using errcode='42501'; end if;
 v_actor:=nullif(p_authorization_context->>'actorUserId','')::uuid;
 v_device:=nullif(p_authorization_context->>'actorDeviceId','')::uuid;
 v_verified:=public.require_effective_module_permission(v_device,'reservations','reservations.event.create',null,null);
 if (v_verified->>'actorUserId')::uuid<>v_actor then raise exception 'DETERMINISTIC_RESOURCE_GRANT_CONTEXT_INVALID' using errcode='42501'; end if;
 v_grant_id:=platform_private.create_permission_grant(
   v_actor,v_device,v_actor,'reservations','reservations.event.manage','event',
   p_created_resource_id::text,p_operation_id);
 return jsonb_build_object('status','granted','grantId',v_grant_id,'targetUserId',v_actor,
   'moduleKey','reservations','permissionKey','reservations.event.manage',
   'resourceType','event','resourceId',p_created_resource_id,
   'authoritySource','business_rule','rule','resource_creator_ownership');
end $$;


--
-- Name: guard_canonical_device_credential_state(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."guard_canonical_device_credential_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op='DELETE' then
    if exists(select 1 from public.device_security_credentials credential
      where credential.user_id=old.user_id and credential.device_id=old.device_id
        and credential.lifecycle_status<>'revoked') then
      raise exception 'DEVICE_AUTHORIZATION_HAS_LIVE_SECURITY_CREDENTIAL' using errcode='42501';
    end if;
    return old;
  end if;
  if (new.status in ('blocked','revoked') or new.revoked_at is not null)
    and exists(select 1 from public.device_security_credentials credential
      where credential.user_id=new.user_id and credential.device_id=new.device_id
        and credential.lifecycle_status<>'revoked') then
    raise exception 'LIVE_SECURITY_CREDENTIAL_REVOCATION_REQUIRED' using errcode='42501';
  end if;
  return new;
end; $$;


--
-- Name: guard_conference_room_period_change(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."guard_conference_room_period_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare assigned record;
begin
 if new.start_date is not distinct from old.start_date and new.end_date is not distinct from old.end_date then return new;end if;
 for assigned in select room_id from public.conference_room_assignments where conference_id=new.id order by room_id loop
  perform platform_private.assert_conference_room_period_available(new.id,assigned.room_id,new.start_date,new.end_date);
 end loop;
 return new;
end $$;


--
-- Name: has_permission_for("uuid", "text", "text", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."has_permission_for"("p_user_id" "uuid", "p_permission_code" "text", "p_scope_type" "text", "p_scope_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select platform_private.is_account_approved(p_user_id)
    and coalesce(
      platform_private.validated_phase1c_device_authorization(
        p_user_id,platform_private.phase1c_context_device_id()
      ),
      platform_private.current_device_authorization_id(p_user_id)
    ) is not null
    and p_scope_type = 'platform' and p_scope_id is null
    and exists(select 1 from platform.user_roles assignment
      join platform.roles role on role.id=assignment.role_id
      join platform.role_permissions role_permission on role_permission.role_id=role.id
      join platform.permissions permission on permission.id=role_permission.permission_id
      where assignment.user_id=p_user_id and assignment.scope_type='platform' and assignment.scope_id is null
        and assignment.revoked_at is null and (assignment.expires_at is null or assignment.expires_at>pg_catalog.now())
        and role.scope_type='platform' and role.domain='platform' and permission.domain='platform'
        and permission.code=p_permission_code);
$$;


--
-- Name: hash_device_secret("text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."hash_device_secret"("p_secret" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case when p_secret ~ '^[A-Za-z0-9_-]{43}$'
    then pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_secret,'UTF8'),'sha256'),'hex') else null end;
$_$;


--
-- Name: inherit_conference_accommodation_arrival(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."inherit_conference_accommodation_arrival"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare prior public.conference_accommodation_occupancies%rowtype;
begin
 if new.arrived_at is null then
  select * into prior from public.conference_accommodation_occupancies o
   where o.conference_id=new.conference_id and o.participation_id=new.participation_id
     and o.leave_day=new.arrival_day and o.arrived_at is not null
   order by o.leave_day desc,o.id limit 1;
  if found then new.arrived_at:=prior.arrived_at;new.arrived_by:=prior.arrived_by;end if;
 end if;
 return new;
end $$;


--
-- Name: is_account_approved("uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."is_account_approved"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists(select 1 from platform.profiles profile where profile.user_id=p_user_id and profile.account_status='approved');
$$;


--
-- Name: is_canonical_platform_owner("uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."is_canonical_platform_owner"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists(
    select 1 from platform.profiles profile
    join platform.user_roles assignment on assignment.user_id=profile.user_id
    join platform.roles role on role.id=assignment.role_id
    where profile.user_id=p_user_id and profile.account_status='approved'
      and assignment.scope_type='platform' and assignment.scope_id is null
      and assignment.revoked_at is null
      and (assignment.expires_at is null or assignment.expires_at>pg_catalog.statement_timestamp())
      and role.domain='platform' and role.code='platform_owner'
  );
$$;


--
-- Name: is_prepared_jpeg_data_url("text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."is_prepared_jpeg_data_url"("p_value" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select p_value~'^data:image/jpeg;base64,[A-Za-z0-9+/]+={0,2}$'
    and length(p_value)<=2097180
$_$;


--
-- Name: person_name_key("text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."person_name_key"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  select lower(btrim(regexp_replace(coalesce(p_value,''),'[[:space:]]+',' ','g')));
$$;


--
-- Name: person_phone_key("text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."person_phone_key"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  select regexp_replace(translate(coalesce(p_value,''),'٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹','01234567890123456789'),'[^0-9]','','g');
$$;


--
-- Name: phase1c_context_device_id(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."phase1c_context_device_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_claims jsonb; v_device_id uuid;
begin
  begin
    v_claims:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;
    if v_claims->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' then return null; end if;
    v_device_id:=(v_claims->>'device_id')::uuid;
  exception when others then return null;
  end;
  return v_device_id;
end; $$;


--
-- Name: prevent_active_binding_for_revoked_device(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."prevent_active_binding_for_revoked_device"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
if new.lifecycle_status='active' and exists(
select 1 from platform.user_device_authorizations as authz
where authz.id=new.device_authorization_id
and authz.user_id=new.user_id and authz.device_id=new.device_id
and (authz.status='revoked' or authz.revoked_at is not null)
) then
raise exception 'DEVICE_AUTHORIZATION_REVOKED' using errcode='42501';
end if;
return new;
end;
$$;


