-- Name: provision_auth_user(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."provision_auth_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into platform.profiles(user_id,display_name)
  values(new.id,nullif(pg_catalog.btrim(coalesce(new.raw_user_meta_data->>'display_name',new.raw_user_meta_data->>'name','')),''))
