--
-- Name: release_resource_lease("uuid", "text", "text", "text", "text", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."release_resource_lease"("p_actor_device_id" "uuid", "p_module_id" "text", "p_resource_type" "text", "p_resource_id" "text", "p_scope" "text", "p_lease_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid; current platform.resource_leases%rowtype; now_at timestamptz:=clock_timestamp();
begin
 actor_id:=platform_private.require_resource_lease_writer(p_actor_device_id,p_module_id,p_resource_type,p_resource_id,p_scope);
 select * into current from platform.resource_leases where module_id=p_module_id and resource_type=p_resource_type and resource_id=p_resource_id and scope=p_scope for update;
 if not found then return jsonb_build_object('status','not_found','owned',false,'serverNow',now_at); end if;
 if current.holder_user_id<>actor_id or current.holder_device_id<>p_actor_device_id or not platform_private.resource_lease_session_owner(p_actor_device_id,current.holder_session_id) or current.lease_token<>p_lease_token then
   return jsonb_build_object('status','not_owner','owned',false,'errorCode','RESOURCE_LEASE_NOT_OWNED','serverNow',now_at);
 end if;
 delete from platform.resource_leases where module_id=p_module_id and resource_type=p_resource_type and resource_id=p_resource_id and scope=p_scope;
 return jsonb_build_object('status','released','owned',false,'serverNow',now_at);
end $$;


--
-- Name: renew_resource_lease("uuid", "text", "text", "text", "text", "uuid", integer); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."renew_resource_lease"("p_actor_device_id" "uuid", "p_module_id" "text", "p_resource_type" "text", "p_resource_id" "text", "p_scope" "text", "p_lease_token" "uuid", "p_ttl_seconds" integer DEFAULT 120) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid; ttl integer:=coalesce(p_ttl_seconds,120); now_at timestamptz:=clock_timestamp(); exp_at timestamptz; current platform.resource_leases%rowtype;
begin
 if p_lease_token is null or ttl<30 or ttl>300 then raise exception 'PLATFORM_RESOURCE_LEASE_ARGUMENT_INVALID' using errcode='22023'; end if;
 actor_id:=platform_private.require_resource_lease_writer(p_actor_device_id,p_module_id,p_resource_type,p_resource_id,p_scope);
 select * into current from platform.resource_leases where module_id=p_module_id and resource_type=p_resource_type and resource_id=p_resource_id and scope=p_scope for update;
 if not found or current.expires_at<=now_at then return jsonb_build_object('status','expired','owned',false,'errorCode','RESOURCE_LEASE_EXPIRED','serverNow',now_at); end if;
 if current.holder_user_id<>actor_id or current.holder_device_id<>p_actor_device_id or not platform_private.resource_lease_session_owner(p_actor_device_id,current.holder_session_id) or current.lease_token<>p_lease_token then
   return jsonb_build_object('status','not_owner','owned',false,'errorCode','RESOURCE_LEASE_NOT_OWNED','expiresAt',current.expires_at,'serverNow',now_at);
 end if;
 exp_at:=now_at+make_interval(secs=>ttl);
 update platform.resource_leases set renewed_at=now_at,expires_at=exp_at where module_id=p_module_id and resource_type=p_resource_type and resource_id=p_resource_id and scope=p_scope;
 return jsonb_build_object('status','renewed','owned',true,'leaseToken',p_lease_token,'expiresAt',exp_at,'serverNow',now_at);
end $$;


--
-- Name: request_device_id(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."request_device_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  select case when platform_private.request_header('x-platform-device-id')
    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    then platform_private.request_header('x-platform-device-id')::uuid else null end;
$_$;


--
-- Name: request_header("text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."request_header"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select nullif(coalesce(nullif(pg_catalog.current_setting('request.headers',true),'')::jsonb->>lower(p_name),''),'');
$$;


--
-- Name: require_accommodation_operation_leases("uuid", "uuid", "text", "jsonb"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."require_accommodation_operation_leases"("p_device" "uuid", "p_conference" "uuid", "p_operation" "text", "p_args" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_source uuid; v_destination uuid; v_room uuid; v_token uuid; v_expected uuid[]; v_supplied uuid[]:=array[]::uuid[]; v_item jsonb;
begin
 if jsonb_typeof(p_args->'p_room_lease_tokens') is distinct from 'array' then
  raise exception 'ROOM_LEASE_TOKENS_REQUIRED' using errcode='42501';
 end if;
 if p_operation in ('move_conference_accommodation','remove_conference_accommodation') then
  select o.room_id into v_source from public.conference_accommodation_occupancies o
  where o.id=(p_args->>'p_occupancy_id')::uuid and o.conference_id=p_conference;
  if v_source is null then raise exception 'ACCOMMODATION_OCCUPANCY_NOT_FOUND' using errcode='22023'; end if;
 end if;
 if p_operation in ('assign_conference_accommodation','move_conference_accommodation') then
  v_destination:=(p_args->>'p_room_id')::uuid;
 end if;
 select array_agg(distinct room_id order by room_id) into v_expected
 from unnest(array[v_source,v_destination]) as room_id where room_id is not null;
 for v_item in select value from jsonb_array_elements(p_args->'p_room_lease_tokens') loop
  if jsonb_typeof(v_item) <> 'object' or
   (select count(*) from jsonb_object_keys(v_item))<>2 or
   not(v_item ? 'roomId' and v_item ? 'token') then
   raise exception 'ROOM_LEASE_TOKEN_INVALID' using errcode='22023';
  end if;
  v_room:=(v_item->>'roomId')::uuid;v_token:=(v_item->>'token')::uuid;
  if v_room=any(v_supplied) then raise exception 'ROOM_LEASE_DUPLICATE' using errcode='22023'; end if;
  v_supplied:=array_append(v_supplied,v_room);
 end loop;
 select array_agg(x order by x) into v_supplied from unnest(v_supplied) x;
 if v_expected is null or v_expected is distinct from v_supplied then
  raise exception 'ROOM_LEASE_SCOPE_MISMATCH' using errcode='42501';
 end if;
 for v_item in select value from jsonb_array_elements(p_args->'p_room_lease_tokens') order by value->>'roomId' loop
  perform platform_private.require_conference_room_lease(p_device,p_conference,(v_item->>'roomId')::uuid,(v_item->>'token')::uuid);
 end loop;
end $$;


--
-- Name: require_canonical_device_authorization("uuid", "uuid", boolean); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."require_canonical_device_authorization"("p_user_id" "uuid", "p_device_id" "uuid", "p_require_active_binding" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_authorization_id uuid;
begin
  if p_user_id is null or p_device_id is null then
    raise exception 'PLATFORM_DEVICE_ACTOR_CONTEXT_REQUIRED' using errcode='22023';
  end if;
  select device_authorization.id into v_authorization_id
  from platform.user_device_authorizations device_authorization
  join platform.devices device on device.id=device_authorization.device_id
  join platform.profiles profile on profile.user_id=device_authorization.user_id
  where device_authorization.user_id=p_user_id and device_authorization.device_id=p_device_id
    and device_authorization.status='approved' and device_authorization.revoked_at is null
    and device.lifecycle_status='active' and device.retired_at is null
    and device.compromised_at is null and profile.account_status='approved'
    and (not p_require_active_binding or exists(
      select 1 from platform.device_key_bindings binding
      where binding.user_id=device_authorization.user_id
        and binding.device_id=device_authorization.device_id
        and binding.device_authorization_id=device_authorization.id
        and binding.lifecycle_status='active' and binding.revoked_at is null
        and binding.retired_at is null
    ));
  if v_authorization_id is null then
    raise exception 'APPROVED_PLATFORM_DEVICE_REQUIRED' using errcode='42501';
  end if;
  return v_authorization_id;
end; $$;


--
-- Name: require_conference_accommodation_context("uuid", "uuid", "text", boolean); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."require_conference_accommodation_context"("p_device" "uuid", "p_conference" "uuid", "p_permission" "text", "p_mutation" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.conferences%rowtype; context jsonb; actor uuid;
begin
  if p_permission not in('conference.accommodation.view','conference.accommodation.manage') then raise exception 'ACCOMMODATION_ARGUMENT_INVALID' using errcode='22023'; end if;
  context:=public.require_effective_module_permission(p_device,'conference',p_permission,'conference',p_conference::text); actor:=(context->>'actorUserId')::uuid;
  if platform_private.validated_phase1c_device_authorization(actor,p_device) is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
  select * into c from public.conferences where id=p_conference;
  if not found or c.deleted_at is not null then raise exception 'CONFERENCE_NOT_FOUND' using errcode='P0002'; end if;
  if p_mutation and c.status<>'active' then raise exception 'COMPLETED_CONFERENCE_IMMUTABLE' using errcode='55000'; end if;
  return context;
end $$;


--
-- Name: require_conference_air_conditioning_context("uuid", "uuid", "text", boolean); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."require_conference_air_conditioning_context"("p_device" "uuid", "p_conference" "uuid", "p_permission" "text", "p_mutation" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c jsonb;actor uuid;conf public.conferences%rowtype;begin if p_permission not in('conference.air_conditioning.view','conference.air_conditioning.manage') then raise exception 'CONFERENCE_AIR_CONDITIONING_ARGUMENT_INVALID' using errcode='22023';end if;c:=public.require_effective_module_permission(p_device,'conference',p_permission,'conference',p_conference::text);actor:=(c->>'actorUserId')::uuid;if platform_private.validated_phase1c_device_authorization(actor,p_device) is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;select * into conf from public.conferences where id=p_conference and deleted_at is null;if not found then raise exception 'CONFERENCE_NOT_FOUND' using errcode='P0002';end if;if p_mutation and conf.status<>'active' then raise exception 'COMPLETED_CONFERENCE_IMMUTABLE' using errcode='55000';end if;return c;end $$;


--
-- Name: require_conference_branding_context("uuid", "uuid", "text", boolean); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."require_conference_branding_context"("p_device" "uuid", "p_conference" "uuid", "p_permission" "text", "p_mutation" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare session_ctx jsonb;ctx jsonb;actor uuid;conf public.conferences%rowtype;
begin
  if p_permission not in('conference.cards.view','conference.lifecycle.manage') then raise exception 'CONFERENCE_BRANDING_ARGUMENT_INVALID' using errcode='22023';end if;
  session_ctx:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;actor:=(session_ctx->>'user_id')::uuid;
  if session_ctx->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' or (session_ctx->>'device_id')::uuid is distinct from p_device
     or platform_private.validated_phase1c_device_authorization(actor,p_device) is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;
  ctx:=public.require_effective_module_permission(p_device,'conference',p_permission,'conference',p_conference::text);
  if (ctx->>'actorUserId')::uuid is distinct from actor then raise exception 'ACTOR_DEVICE_OVERRIDE_DENIED' using errcode='42501';end if;
  select * into conf from public.conferences where id=p_conference and deleted_at is null;
  if not found then raise exception 'CONFERENCE_NOT_FOUND' using errcode='P0002';end if;
  if p_mutation and conf.status<>'active' then raise exception 'COMPLETED_CONFERENCE_IMMUTABLE' using errcode='55000';end if;
  return ctx;
end $$;


--
-- Name: require_conference_family_accommodation_leases("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."require_conference_family_accommodation_leases"("p_device" "uuid", "p_conference" "uuid", "p_payload" "jsonb") RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare room_ids uuid[];supplied uuid[];entry jsonb;
begin
 if jsonb_typeof(p_payload->'roomLeaseTokens') is distinct from 'array' then raise exception 'ROOM_LEASE_TOKENS_REQUIRED' using errcode='42501';end if;
 select array_agg(distinct id order by id) into room_ids from (
   select nullif(s.value->>'targetRoomId','')::uuid id from jsonb_array_elements(p_payload->'stays') s
   union select nullif(s.value->>'roomId','')::uuid from jsonb_array_elements(p_payload->'stays') s
   union select o.room_id from public.conference_accommodation_occupancies o join jsonb_array_elements(p_payload->'stays') s on o.id=nullif(s.value->>'occupancyId','')::uuid where o.conference_id=p_conference
   union select nullif(c.value->>'targetRoomId','')::uuid from jsonb_array_elements(p_payload->'children') c
   union select nullif(p_payload->'roomDraft'->>'roomId','')::uuid
 ) rooms where id is not null;
 if room_ids is null then raise exception 'FAMILY_ACCOMMODATION_ROOMS_REQUIRED' using errcode='22023';end if;
 select array_agg(distinct (token->>'roomId')::uuid order by (token->>'roomId')::uuid) into supplied from jsonb_array_elements(p_payload->'roomLeaseTokens') token;
 if supplied is distinct from room_ids then raise exception 'ROOM_LEASE_SCOPE_MISMATCH' using errcode='42501';end if;
 for entry in select value from jsonb_array_elements(p_payload->'roomLeaseTokens') order by value->>'roomId' loop
   perform platform_private.require_conference_room_lease(p_device,p_conference,(entry->>'roomId')::uuid,(entry->>'token')::uuid);
 end loop;
 return room_ids;
end $$;


