  return c;
end $$;


--
-- Name: require_exact_jsonb_keys("jsonb", "text"[], "text"[]); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."require_exact_jsonb_keys"("p_args" "jsonb", "p_required" "text"[], "p_optional" "text"[] DEFAULT '{}'::"text"[]) RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v_key text;
begin
  if p_args is null or jsonb_typeof(p_args)<>'object' then raise exception 'CONFERENCE_OPERATION_ARGUMENTS_INVALID' using errcode='22023'; end if;
  foreach v_key in array p_required loop
    if not p_args ? v_key then raise exception 'CONFERENCE_OPERATION_ARGUMENT_MISSING' using errcode='22023'; end if;
  end loop;
  if exists(select 1 from jsonb_object_keys(p_args) key where not (key=any(p_required) or key=any(p_optional))) then
    raise exception 'CONFERENCE_OPERATION_ARGUMENT_UNKNOWN' using errcode='22023';
  end if;
end; $$;


--
-- Name: require_owned_accommodation_room_lease("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."require_owned_accommodation_room_lease"("p_actor_device_id" "uuid", "p_room_id" "uuid", "p_lease_token" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_session uuid;
begin
 if p_room_id is null or p_lease_token is null then
  raise exception 'RESOURCE_LEASE_REQUIRED' using errcode='42501';
 end if;
 v_session:=platform_private.require_resource_lease_session(p_actor_device_id);
 perform 1 from platform.resource_leases l
 where l.module_id='conference' and l.resource_type='accommodation_room'
  and l.resource_id=p_room_id::text and l.scope='edit'
  and l.holder_device_id=p_actor_device_id
  and l.holder_session_id=v_session
  and l.lease_token=p_lease_token
  and l.expires_at>pg_catalog.clock_timestamp()
 for update;
 if not found then
  raise exception 'RESOURCE_LEASE_NOT_OWNED' using errcode='42501';
 end if;
end $$;


--
-- Name: device_security_credentials; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."device_security_credentials" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "webauthn_credential_id" "bytea" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "device_id" "uuid" NOT NULL,
    "credential_kind" "text" NOT NULL,
    "public_key_cose" "bytea" NOT NULL,
    "public_key_algorithm" integer NOT NULL,
    "aaguid" "uuid",
    "transports" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "sign_count" bigint DEFAULT 0 NOT NULL,
    "backup_eligible" boolean NOT NULL,
    "backup_state" boolean NOT NULL,
    "user_verification_policy" "text" NOT NULL,
    "lifecycle_status" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "enrolled_at" timestamp with time zone,
    "activated_at" timestamp with time zone,
    "last_used_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    "revoked_by" "uuid",
    "revocation_reason" "text",
    CONSTRAINT "device_security_credentials_credential_kind_check" CHECK (("credential_kind" = ANY (ARRAY['platform_primary'::"text", 'recovery_security_key'::"text"]))),
    CONSTRAINT "device_security_credentials_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['enrollment_pending'::"text", 'active'::"text", 'rotation_pending'::"text", 'revoked'::"text", 'recovery_required'::"text"]))),
    CONSTRAINT "device_security_credentials_lifecycle_timestamps" CHECK (((("lifecycle_status" = 'enrollment_pending'::"text") AND ("enrolled_at" IS NULL) AND ("activated_at" IS NULL) AND ("revoked_at" IS NULL)) OR (("lifecycle_status" = ANY (ARRAY['active'::"text", 'rotation_pending'::"text", 'recovery_required'::"text"])) AND ("enrolled_at" IS NOT NULL) AND ("activated_at" IS NOT NULL) AND ("revoked_at" IS NULL)) OR (("lifecycle_status" = 'revoked'::"text") AND ("revoked_at" IS NOT NULL)))),
    CONSTRAINT "device_security_credentials_non_backup_policy" CHECK (((NOT "backup_state") OR "backup_eligible")),
    CONSTRAINT "device_security_credentials_public_key_algorithm_check" CHECK (("public_key_algorithm" < 0)),
    CONSTRAINT "device_security_credentials_public_key_cose_check" CHECK (("octet_length"("public_key_cose") > 0)),
    CONSTRAINT "device_security_credentials_revocation_context" CHECK (((("revoked_at" IS NULL) AND ("revoked_by" IS NULL) AND ("revocation_reason" IS NULL)) OR (("revoked_at" IS NOT NULL) AND ("revocation_reason" IS NOT NULL) AND (("length"("btrim"("revocation_reason")) >= 1) AND ("length"("btrim"("revocation_reason")) <= 500))))),
    CONSTRAINT "device_security_credentials_sign_count_check" CHECK (("sign_count" >= 0)),
    CONSTRAINT "device_security_credentials_timestamp_order" CHECK (((("enrolled_at" IS NULL) OR ("enrolled_at" >= "created_at")) AND (("activated_at" IS NULL) OR (("enrolled_at" IS NOT NULL) AND ("activated_at" >= "enrolled_at"))) AND (("last_used_at" IS NULL) OR ("last_used_at" >= "created_at")) AND (("revoked_at" IS NULL) OR ("revoked_at" >= "created_at")))),
    CONSTRAINT "device_security_credentials_user_verification_policy_check" CHECK (("user_verification_policy" = 'required'::"text")),
    CONSTRAINT "device_security_credentials_webauthn_credential_id_check" CHECK ((("octet_length"("webauthn_credential_id") >= 16) AND ("octet_length"("webauthn_credential_id") <= 1024)))
);


--
-- Name: require_platform_owner_recovery_credential("uuid", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."require_platform_owner_recovery_credential"("p_owner_user_id" "uuid", "p_credential_id" "uuid") RETURNS "public"."device_security_credentials"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare credential public.device_security_credentials%rowtype;
begin
  perform public.require_platform_device_backend();
  if not platform_private.is_canonical_platform_owner(p_owner_user_id) then
    raise exception 'APPROVED_SYSTEM_OWNER_REQUIRED' using errcode='42501';
  end if;
  select * into credential from public.device_security_credentials stored
  where stored.id=p_credential_id and stored.user_id=p_owner_user_id
    and stored.credential_kind='platform_primary'
    and stored.lifecycle_status='active'
    and stored.user_verification_policy='required'
    and (not stored.backup_state or stored.backup_eligible)
  for update;
  if not found then
    raise exception 'ACTIVE_PLATFORM_RECOVERY_CREDENTIAL_REQUIRED' using errcode='42501';
  end if;
  return credential;
end; $$;


--
-- Name: require_resource_lease_session("uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."require_resource_lease_session"("p_actor_device_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_context jsonb; v_session uuid; v_user uuid;
begin
  begin
    v_context:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;
    v_session:=(v_context->>'session_id')::uuid;
    v_user:=(v_context->>'user_id')::uuid;
  exception when others then
    raise exception 'RESOURCE_LEASE_SESSION_REQUIRED' using errcode='42501';
  end;
  if v_context->>'purpose' is distinct from 'PLATFORM_DEVICE_SESSION_DISPATCH'
     or v_session is null or v_user is null
     or (v_context->>'device_id')::uuid is distinct from p_actor_device_id
     or not exists (
       select 1 from platform_private.device_sessions s
       where s.id=v_session and s.user_id=v_user and s.device_id=p_actor_device_id
         and s.purpose='PLATFORM_DEVICE_SESSION'
         and s.revoked_at is null and s.expires_at>pg_catalog.statement_timestamp()
     ) then
    raise exception 'RESOURCE_LEASE_SESSION_REQUIRED' using errcode='42501';
  end if;
  return v_session;
end $$;


--
-- Name: require_resource_lease_writer("uuid", "text", "text", "text", "text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."require_resource_lease_writer"("p_actor_device_id" "uuid", "p_module_id" "text", "p_resource_type" "text", "p_resource_id" "text", "p_scope" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare authority jsonb; actor_id uuid; conference_id uuid; room_id uuid;
begin
 if p_actor_device_id is null or p_resource_id is null or btrim(p_resource_id)='' then
   raise exception 'PLATFORM_RESOURCE_LEASE_ARGUMENT_INVALID' using errcode='22023';
 end if;
 perform platform_private.resource_lease_permission_key(p_module_id,p_resource_type,p_scope);
 if p_module_id<>'conference' or p_resource_type<>'accommodation_room'
    or p_resource_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
   raise exception 'PLATFORM_RESOURCE_LEASE_RESOURCE_INVALID' using errcode='22023';
 end if;
 begin
   conference_id:=nullif(pg_catalog.current_setting('platform.room_lease_conference_id',true),'')::uuid;
 exception when others then
   raise exception 'PLATFORM_RESOURCE_LEASE_CONFERENCE_REQUIRED' using errcode='42501';
 end;
 if conference_id is null then raise exception 'PLATFORM_RESOURCE_LEASE_CONFERENCE_REQUIRED' using errcode='42501'; end if;
 room_id:=p_resource_id::uuid;
 if not exists (select 1 from public.conference_accommodation_rooms where id=room_id) then
   raise exception 'ACCOMMODATION_ROOM_NOT_FOUND' using errcode='P0002';
 end if;
 if not platform_private.conference_room_is_assigned(conference_id,room_id) then
   raise exception 'ACCOMMODATION_ROOM_CONFERENCE_MISMATCH' using errcode='42501';
 end if;
 authority:=platform_private.require_conference_accommodation_context(
   p_actor_device_id,conference_id,'conference.accommodation.manage',true
 );
 actor_id:=nullif(authority->>'actorUserId','')::uuid;
 if actor_id is null then raise exception 'PLATFORM_RESOURCE_LEASE_AUTHORITY_INVALID' using errcode='42501'; end if;
 return actor_id;
end $_$;


--
-- Name: reservations_person_identity_candidates("text", "text", integer); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."reservations_person_identity_candidates"("p_full_name" "text", "p_phone" "text", "p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'personId',candidate.id,
    'fullName',candidate.full_name,
    'phone',candidate.phone,
    'gender',candidate.gender,
    'dateOfBirth',candidate.date_of_birth,
    'church',candidate.church,
    'governorate',candidate.governorate,
    'cityOrVillage',candidate.city_or_village,
    'serviceSector',candidate.service_sector,
    'serviceSectorOther',candidate.service_sector_other,
    'revision',candidate.revision,
    'matchedName',candidate.name_search=platform_private.person_name_key(p_full_name),
    'matchedPhone',nullif(platform_private.person_phone_key(p_phone),'') is not null
      and candidate.phone_search=platform_private.person_phone_key(p_phone)
  ) order by candidate.full_name,candidate.id),'[]'::jsonb)
  from (
    select person.*
    from platform.people person
    where (platform_private.person_name_key(p_full_name)<>''
           and person.name_search=platform_private.person_name_key(p_full_name))
       or (platform_private.person_phone_key(p_phone)<>''
           and person.phone_search=platform_private.person_phone_key(p_phone))
    order by person.full_name,person.id
    limit least(greatest(coalesce(p_limit,10),1),20)
  ) candidate
$$;


--
-- Name: resolve_startup_device_authorization_status("uuid", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."resolve_startup_device_authorization_status"("p_user_id" "uuid", "p_device_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select device_authorization.status
  from platform.user_device_authorizations device_authorization
  join platform.devices device on device.id=device_authorization.device_id
  where device_authorization.user_id=p_user_id and device_authorization.device_id=p_device_id
    and device.lifecycle_status='active' and device.retired_at is null
    and device.compromised_at is null;
$$;


--
-- Name: resource_lease_permission_key("text", "text", "text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."resource_lease_permission_key"("p_module_id" "text", "p_resource_type" "text", "p_scope" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_scope <> 'edit' then raise exception 'PLATFORM_RESOURCE_LEASE_SCOPE_UNSUPPORTED' using errcode='22023'; end if;
  if p_module_id='conference' and p_resource_type='accommodation_room' then return 'conference.accommodation.manage'; end if;
  raise exception 'PLATFORM_RESOURCE_LEASE_RESOURCE_UNMAPPED: %.%',p_module_id,p_resource_type using errcode='42501';
end $$;


--
-- Name: resource_lease_session_owner("uuid", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."resource_lease_session_owner"("p_device" "uuid", "p_session" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ select p_session=platform_private.require_resource_lease_session(p_device) $$;


--
-- Name: restore_conference_bundle_table("text", "jsonb", "uuid", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."restore_conference_bundle_table"("p_table" "text", "p_rows" "jsonb", "p_source" "uuid", "p_target" "uuid", "p_operation_id" "uuid", "p_actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_row jsonb;v_count integer=0;v_id uuid;
begin
 if not p_table=any(platform_private.conference_bundle_tables()) then raise exception 'CONFERENCE_BUNDLE_TABLE_NOT_ALLOWED' using errcode='22023'; end if;
 for v_row in select value from jsonb_array_elements(p_rows) loop
  v_row:=v_row||jsonb_build_object('conference_id',p_target,'revision',1,'created_at',statement_timestamp(),'updated_at',statement_timestamp(),'created_by',p_actor,'updated_by',p_actor);
  if p_table=any(array['conference_participations','conference_house_assignments','conference_room_assignments','conference_accommodation_occupancies','conference_finance_items','conference_finance_adjustments','conference_restaurant_price_overrides','conference_restaurant_count_overrides','conference_restaurant_participation_overrides','conference_transport_vehicles','conference_transport_assignments']) then
   v_id:=(v_row->>'id')::uuid;v_row:=jsonb_set(v_row,'{id}',to_jsonb(platform_private.conference_bundle_uuid(p_operation_id,v_id)));
  end if;
  if v_row ? 'participation_id' then v_row:=jsonb_set(v_row,'{participation_id}',to_jsonb(platform_private.conference_bundle_uuid(p_operation_id,(v_row->>'participation_id')::uuid))); end if;
  if v_row ? 'guardian_participation_id' and v_row->>'guardian_participation_id' is not null then v_row:=jsonb_set(v_row,'{guardian_participation_id}',to_jsonb(platform_private.conference_bundle_uuid(p_operation_id,(v_row->>'guardian_participation_id')::uuid))); end if;
  if v_row ? 'house_assignment_id' then v_row:=jsonb_set(v_row,'{house_assignment_id}',to_jsonb(platform_private.conference_bundle_uuid(p_operation_id,(v_row->>'house_assignment_id')::uuid))); end if;
  if v_row ? 'key_holder_occupancy_id' and v_row->>'key_holder_occupancy_id' is not null then v_row:=jsonb_set(v_row,'{key_holder_occupancy_id}',to_jsonb(platform_private.conference_bundle_uuid(p_operation_id,(v_row->>'key_holder_occupancy_id')::uuid))); end if;
  if p_table='conference_transport_assignments' then v_row:=jsonb_set(v_row,'{vehicle_id}',to_jsonb(platform_private.conference_bundle_uuid(p_operation_id,(v_row->>'vehicle_id')::uuid))); end if;
  execute format('insert into public.%I select (pg_catalog.jsonb_populate_record(null::public.%I,$1)).*',p_table,p_table) using v_row;
  v_count:=v_count+1;
 end loop;
 return v_count;
end $_$;


--
-- Name: revoke_permission_grant("uuid", "uuid", "uuid", "text", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."revoke_permission_grant"("p_actor" "uuid", "p_device" "uuid", "p_grant" "uuid", "p_reason" "text" DEFAULT NULL::"text", "p_operation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_grant platform.permission_grants%rowtype;v_permission platform.permissions%rowtype;v_device_authorization_id uuid;
begin
 if p_actor is null or p_device is null or p_grant is null or p_operation_id is null then raise exception 'INVALID_PERMISSION_REVOKE' using errcode='22023'; end if;
 v_device_authorization_id:=platform_private.validated_phase1c_device_authorization(p_actor,p_device);
 if v_device_authorization_id is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
 select * into v_grant from platform.permission_grants where id=p_grant for update;
 if not found then raise exception 'PERMISSION_GRANT_NOT_FOUND' using errcode='P0002'; end if;
 if v_grant.revoked_at is null then
  update platform.permission_grants set revoked_at=statement_timestamp(),revoked_by=p_actor,
   metadata=metadata||jsonb_build_object('revokedByDeviceId',p_device,'revocationReason',p_reason,'revocationOperationId',p_operation_id)
  where id=p_grant;
  select * into v_permission from platform.permissions where id=v_grant.permission_id;
  insert into platform.audit_events(
   actor_user_id,actor_device_authorization_id,subject_user_id,domain,module,action,
   entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source
  ) values(
   p_actor,v_device_authorization_id,v_grant.user_id,'platform',v_permission.domain,'permission.revoked',
   'permission_grant',v_grant.id,'platform',
   jsonb_build_object('grantId',v_grant.id,'targetUserId',v_grant.user_id,'moduleKey',v_permission.domain,
    'permissionKey',v_permission.code,'grantScope',v_grant.scope_type,'resourceType',v_grant.resource_type,'resourceId',v_grant.resource_id),
   jsonb_build_object('revoked',true),
   jsonb_build_object('actorDeviceId',p_device,'reason',p_reason),p_operation_id,'rpc'
  );
 end if;
 return p_grant;
end $$;


--
-- Name: route_canonical_conference_operation("uuid", "uuid", "bytea", "uuid", "text", "jsonb"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."route_canonical_conference_operation"("p_user_id" "uuid", "p_session_id" "uuid", "p_token_hash" "bytea", "p_actor_device_id" "uuid", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_operation='export_conference_canonical_bundle' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    return public.export_conference_canonical_bundle(p_actor_device_id,(p_args->>'p_conference_id')::uuid);
  elsif p_operation='validate_conference_canonical_bundle' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_bundle','p_mode','p_target_conference_id','p_expected_revision']);
    return public.validate_conference_canonical_bundle(p_actor_device_id,p_args->'p_bundle',p_args->>'p_mode',nullif(p_args->>'p_target_conference_id','')::uuid,nullif(p_args->>'p_expected_revision','')::bigint);
  elsif p_operation='restore_conference_canonical_bundle' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_bundle','p_mode','p_target_conference_id','p_expected_revision','p_confirmed']);
    return public.restore_conference_canonical_bundle(p_actor_device_id,(p_args->>'p_operation_id')::uuid,p_args->'p_bundle',p_args->>'p_mode',nullif(p_args->>'p_target_conference_id','')::uuid,nullif(p_args->>'p_expected_revision','')::bigint,(p_args->>'p_confirmed')::boolean);
  elsif p_operation='create_canonical_conference' then
    perform platform_private.require_exact_jsonb_keys(p_args,array[
      'p_operation_id','p_requested_conference_id',
      'p_name','p_start_date','p_end_date'
    ]);
    return public.create_canonical_conference(
      p_actor_device_id,(p_args->>'p_operation_id')::uuid,
      (p_args->>'p_requested_conference_id')::uuid,p_args->>'p_name',
      (p_args->>'p_start_date')::date,(p_args->>'p_end_date')::date
    );
  elsif p_operation='mutate_conference_core' then
    perform platform_private.require_exact_jsonb_keys(p_args,array[
      'p_operation_id','p_conference_id','p_expected_revision','p_name',
      'p_place','p_start_date','p_end_date','p_status'
    ]);
    return public.mutate_conference_core(
      p_actor_device_id,(p_args->>'p_operation_id')::uuid,
      (p_args->>'p_conference_id')::uuid,
      (p_args->>'p_expected_revision')::bigint,p_args->>'p_name',
      p_args->>'p_place',(p_args->>'p_start_date')::date,
      (p_args->>'p_end_date')::date,p_args->>'p_status'
    );
  elsif p_operation='list_accessible_conferences' then
    perform platform_private.require_exact_jsonb_keys(p_args,array[]::text[]);
    return public.list_accessible_conferences(p_actor_device_id);
  elsif p_operation='get_conference_core' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    return public.get_conference_core(p_actor_device_id,(p_args->>'p_conference_id')::uuid);
  elsif p_operation='update_conference_canonical_person' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_person_id','p_expected_revision','p_full_name','p_phone','p_church','p_gender','p_date_of_birth']);
    return public.update_conference_canonical_person(p_actor_device_id,(p_args->>'p_conference_id')::uuid,(p_args->>'p_person_id')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->>'p_full_name',p_args->>'p_phone',p_args->>'p_church',p_args->>'p_gender',(p_args->>'p_date_of_birth')::date);
  elsif p_operation='get_conference_canonical_person' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_person_id']);
    return public.get_conference_canonical_person(p_actor_device_id,(p_args->>'p_conference_id')::uuid,(p_args->>'p_person_id')::uuid);
  elsif p_operation='search_conference_people' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_query','p_limit']);
    return public.search_conference_people(p_actor_device_id,(p_args->>'p_conference_id')::uuid,p_args->>'p_query',(p_args->>'p_limit')::integer);
  elsif p_operation='list_conference_participations' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    return public.list_conference_participations(p_actor_device_id,(p_args->>'p_conference_id')::uuid);
  elsif p_operation='create_conference_participation' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_person_id']);
    return public.create_conference_participation(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,(p_args->>'p_person_id')::uuid);
  elsif p_operation='create_conference_participation_with_person' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_full_name','p_phone','p_gender','p_date_of_birth','p_church']);
    return public.create_conference_participation_with_person(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,p_args->>'p_full_name',p_args->>'p_phone',p_args->>'p_gender',(p_args->>'p_date_of_birth')::date,p_args->>'p_church');
  elsif p_operation='set_conference_participation_status' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_participation_id','p_expected_revision','p_status']);
    return public.set_conference_participation_status(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_participation_id')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->>'p_status');
  elsif p_operation='set_conference_participation_guardian' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_participation_id','p_expected_revision','p_guardian_participation_id']);
    return public.set_conference_participation_guardian(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_participation_id')::uuid,(p_args->>'p_expected_revision')::bigint,(p_args->>'p_guardian_participation_id')::uuid);
  elsif p_operation='delete_conference_participation' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_participation_id','p_expected_revision']);
    return public.delete_conference_participation(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_participation_id')::uuid,(p_args->>'p_expected_revision')::bigint);
  elsif p_operation='list_conference_houses' then
    perform platform_private.require_exact_jsonb_keys(p_args,array[]::text[]);
    return public.list_conference_houses(p_actor_device_id);
  elsif p_operation='mutate_conference_house_directory' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_operation','p_payload']);
    return public.mutate_conference_house_directory(p_actor_device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_operation',p_args->'p_payload');
  elsif p_operation='assign_conference_house' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_house_id','p_assign','p_expected_revision']);
    return public.assign_conference_house(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,(p_args->>'p_house_id')::uuid,(p_args->>'p_assign')::boolean,nullif(p_args->>'p_expected_revision','')::bigint);
  elsif p_operation='list_conference_house_room_options' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    return public.list_conference_house_room_options(p_actor_device_id,(p_args->>'p_conference_id')::uuid);
  elsif p_operation='assign_conference_room' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_room_id','p_assign','p_expected_revision']);
    return public.assign_conference_room(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,(p_args->>'p_room_id')::uuid,(p_args->>'p_assign')::boolean,nullif(p_args->>'p_expected_revision','')::bigint);
  elsif p_operation='mutate_conference_accommodation_operations' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_operation','p_payload','p_room_lease_tokens']);
    perform platform_private.require_accommodation_operation_leases(p_actor_device_id,(p_args->>'p_conference_id')::uuid,case when p_args->>'p_operation'='set_arrival' then 'remove_conference_accommodation' else 'assign_conference_accommodation' end,
      case when p_args->>'p_operation'='set_arrival' then jsonb_build_object('p_occupancy_id',p_args->'p_payload'->>'occupancyId','p_room_lease_tokens',p_args->'p_room_lease_tokens') else jsonb_build_object('p_room_id',p_args->'p_payload'->>'roomId','p_room_lease_tokens',p_args->'p_room_lease_tokens') end);
    return public.mutate_conference_accommodation_operations(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,p_args->>'p_operation',p_args->'p_payload');
  elsif p_operation='get_conference_accommodation' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    return public.get_conference_accommodation(p_actor_device_id,(p_args->>'p_conference_id')::uuid);
  elsif p_operation in('create_accommodation_house','update_accommodation_house','delete_accommodation_house','create_accommodation_floor','update_accommodation_floor','delete_accommodation_floor','create_accommodation_room','update_accommodation_room','delete_accommodation_room') then
  if p_operation in ('update_accommodation_room','delete_accommodation_room') then
   if jsonb_typeof(p_args->'p_room_lease_tokens') is distinct from 'array'
      or jsonb_array_length(p_args->'p_room_lease_tokens')<>1 then
    raise exception 'ROOM_LEASE_TOKENS_REQUIRED' using errcode='42501';
   end if;
   if jsonb_typeof(p_args->'p_room_lease_tokens'->0) is distinct from 'object'
      or (select count(*) from jsonb_object_keys(p_args->'p_room_lease_tokens'->0))<>2
      or not ((p_args->'p_room_lease_tokens'->0) ? 'roomId' and (p_args->'p_room_lease_tokens'->0) ? 'token')
      or (p_args->'p_room_lease_tokens'->0->>'roomId') is distinct from (p_args->>'p_room_id') then
    raise exception 'ROOM_LEASE_SCOPE_MISMATCH' using errcode='42501';
   end if;
   perform platform_private.require_conference_room_lease(
    p_actor_device_id,(p_args->>'p_conference_id')::uuid,(p_args->>'p_room_id')::uuid,
    (p_args->'p_room_lease_tokens'->0->>'token')::uuid);
   return public.mutate_conference_accommodation_structure(
    p_actor_device_id,replace(p_operation,'_accommodation_','_'),p_args-'p_room_lease_tokens');
  end if;
  return public.mutate_conference_accommodation_structure(p_actor_device_id,replace(p_operation,'_accommodation_','_'),p_args);
    return public.mutate_conference_accommodation_structure(p_actor_device_id,replace(p_operation,'_accommodation_','_'),p_args);
  elsif p_operation='assign_conference_accommodation' then
    perform platform_private.require_accommodation_operation_leases(p_actor_device_id,(p_args->>'p_conference_id')::uuid,'assign_conference_accommodation',p_args);
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_room_id','p_participation_id','p_arrival_day','p_leave_day','p_bed_type','p_extra_bed_person_type','p_room_lease_tokens']);
    return public.assign_conference_accommodation(p_actor_device_id,(p_args->>'p_conference_id')::uuid,(p_args->>'p_room_id')::uuid,(p_args->>'p_participation_id')::uuid,(p_args->>'p_arrival_day')::integer,(p_args->>'p_leave_day')::integer,p_args->>'p_bed_type',p_args->>'p_extra_bed_person_type');
  elsif p_operation='save_conference_family_accommodation_draft' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_payload']); perform platform_private.require_conference_family_accommodation_leases(p_actor_device_id,(p_args->>'p_conference_id')::uuid,p_args->'p_payload'); return public.save_conference_family_accommodation_draft(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,p_args->'p_payload'); elsif p_operation='save_conference_accommodation_room_draft' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_room_id','p_expected_revision','p_expected_assignment_revision','p_structure','p_assignments','p_updates','p_replacements','p_room_lease_tokens']);
    perform platform_private.require_accommodation_operation_leases(p_actor_device_id,(p_args->>'p_conference_id')::uuid,'assign_conference_accommodation',jsonb_build_object('p_room_id',p_args->>'p_room_id','p_room_lease_tokens',p_args->'p_room_lease_tokens'));
    return public.save_conference_accommodation_room_draft(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,(p_args->>'p_room_id')::uuid,(p_args->>'p_expected_revision')::bigint,(p_args->>'p_expected_assignment_revision')::bigint,p_args->'p_structure',p_args->'p_assignments',p_args->'p_updates',p_args->'p_replacements');
  elsif p_operation='replace_conference_accommodation' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_occupancy_id','p_expected_revision','p_replacement_participation_id','p_effective_day','p_bed_type','p_extra_bed_person_type','p_room_lease_tokens']);
    perform platform_private.require_accommodation_operation_leases(p_actor_device_id,(p_args->>'p_conference_id')::uuid,'remove_conference_accommodation',jsonb_build_object('p_occupancy_id',p_args->>'p_occupancy_id','p_room_lease_tokens',p_args->'p_room_lease_tokens'));
    return public.replace_conference_accommodation(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,(p_args->>'p_occupancy_id')::uuid,(p_args->>'p_expected_revision')::bigint,(p_args->>'p_replacement_participation_id')::uuid,(p_args->>'p_effective_day')::integer,p_args->>'p_bed_type',p_args->>'p_extra_bed_person_type');
  elsif p_operation='move_conference_accommodation' then
    perform platform_private.require_accommodation_operation_leases(p_actor_device_id,(p_args->>'p_conference_id')::uuid,'move_conference_accommodation',p_args);
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_occupancy_id','p_expected_revision','p_room_id','p_arrival_day','p_leave_day','p_bed_type','p_extra_bed_person_type','p_room_lease_tokens']);
    return public.move_conference_accommodation(p_actor_device_id,(p_args->>'p_conference_id')::uuid,(p_args->>'p_occupancy_id')::uuid,(p_args->>'p_expected_revision')::bigint,(p_args->>'p_room_id')::uuid,(p_args->>'p_arrival_day')::integer,(p_args->>'p_leave_day')::integer,p_args->>'p_bed_type',p_args->>'p_extra_bed_person_type');
  elsif p_operation='remove_conference_accommodation' then
    perform platform_private.require_accommodation_operation_leases(p_actor_device_id,(p_args->>'p_conference_id')::uuid,'remove_conference_accommodation',p_args);
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_occupancy_id','p_expected_revision','p_room_lease_tokens']);
    return public.remove_conference_accommodation(p_actor_device_id,(p_args->>'p_conference_id')::uuid,(p_args->>'p_occupancy_id')::uuid,(p_args->>'p_expected_revision')::bigint);
  elsif p_operation='get_conference_transport' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    return public.get_conference_transport(p_actor_device_id,(p_args->>'p_conference_id')::uuid);
  elsif p_operation='mutate_conference_transport_vehicle' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_operation','p_conference_id','p_vehicle_id','p_expected_revision','p_name','p_icon','p_capacity','p_position','p_remove_overflow']);
    return public.mutate_conference_transport_vehicle(p_actor_device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_operation',(p_args->>'p_conference_id')::uuid,nullif(p_args->>'p_vehicle_id','')::uuid,nullif(p_args->>'p_expected_revision','')::bigint,p_args->>'p_name',p_args->>'p_icon',nullif(p_args->>'p_capacity','')::integer,nullif(p_args->>'p_position','')::integer,coalesce((p_args->>'p_remove_overflow')::boolean,false));
  elsif p_operation='set_conference_transport_assignment' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_participation_id','p_vehicle_id','p_mode','p_rider_kind','p_seat_number','p_expected_revision']);
    return public.set_conference_transport_assignment(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,(p_args->>'p_participation_id')::uuid,(p_args->>'p_vehicle_id')::uuid,p_args->>'p_mode',p_args->>'p_rider_kind',nullif(p_args->>'p_seat_number','')::integer,nullif(p_args->>'p_expected_revision','')::bigint);
  elsif p_operation='remove_conference_transport_assignment' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_assignment_id','p_expected_revision']);
    return public.remove_conference_transport_assignment(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_assignment_id')::uuid,(p_args->>'p_expected_revision')::bigint);
  elsif p_operation='get_conference_restaurant' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    return public.get_conference_restaurant(p_actor_device_id,(p_args->>'p_conference_id')::uuid);
  elsif p_operation='mutate_conference_restaurant' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_operation','p_conference_id','p_expected_revision','p_payload']);
    return public.mutate_conference_restaurant(p_actor_device_id,(p_args->>'p_operation_id')::uuid,p_args->>'p_operation',(p_args->>'p_conference_id')::uuid,nullif(p_args->>'p_expected_revision','')::bigint,p_args->'p_payload');
  elsif p_operation='mutate_conference_accommodation_pricing' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_expected_revision','p_payload']);
    return public.mutate_conference_accommodation_pricing(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,nullif(p_args->>'p_expected_revision','')::bigint,p_args->'p_payload');
  elsif p_operation='get_conference_air_conditioning' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    return public.get_conference_air_conditioning(p_actor_device_id,(p_args->>'p_conference_id')::uuid);
  elsif p_operation='mutate_conference_air_conditioning' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_scope','p_scope_id','p_action','p_expected_revision','p_configuration']);
    return public.mutate_conference_air_conditioning(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,p_args->>'p_scope',nullif(p_args->>'p_scope_id','')::uuid,p_args->>'p_action',(p_args->>'p_expected_revision')::bigint,p_args->'p_configuration');
  elsif p_operation='get_conference_finance' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    return public.get_conference_finance(p_actor_device_id,(p_args->>'p_conference_id')::uuid);
  elsif p_operation='mutate_conference_finance' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_entity','p_action','p_entity_id','p_expected_revision','p_payload']);
    return public.mutate_conference_finance(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,p_args->>'p_entity',p_args->>'p_action',nullif(p_args->>'p_entity_id','')::uuid,(p_args->>'p_expected_revision')::bigint,p_args->'p_payload');
  elsif p_operation='get_conference_branding' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    return public.get_conference_branding(p_actor_device_id,(p_args->>'p_conference_id')::uuid);
  elsif p_operation='mutate_conference_branding' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_conference_id','p_action','p_expected_revision','p_payload']);
    return public.mutate_conference_branding(p_actor_device_id,(p_args->>'p_operation_id')::uuid,(p_args->>'p_conference_id')::uuid,p_args->>'p_action',(p_args->>'p_expected_revision')::bigint,p_args->'p_payload');
  elsif p_operation='list_conference_activity' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    return public.list_conference_activity(p_actor_device_id,(p_args->>'p_conference_id')::uuid);
  elsif p_operation='record_conference_output_event' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_event']);
    return public.record_conference_output_event(p_actor_device_id,(p_args->>'p_conference_id')::uuid,p_args->>'p_event');
  elsif p_operation in ('acquire_resource_lease','renew_resource_lease') then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_resource_type','p_resource_id','p_scope','p_lease_token','p_ttl_seconds']);
    perform pg_catalog.set_config('platform.room_lease_conference_id',(p_args->>'p_conference_id')::uuid::text,true);
    if p_operation='acquire_resource_lease' then
      return platform_private.acquire_resource_lease(p_actor_device_id,'conference',p_args->>'p_resource_type',p_args->>'p_resource_id',p_args->>'p_scope',(p_args->>'p_lease_token')::uuid,(p_args->>'p_ttl_seconds')::integer);
    end if;
    return platform_private.renew_resource_lease(p_actor_device_id,'conference',p_args->>'p_resource_type',p_args->>'p_resource_id',p_args->>'p_scope',(p_args->>'p_lease_token')::uuid,(p_args->>'p_ttl_seconds')::integer);
  elsif p_operation='release_resource_lease' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_resource_type','p_resource_id','p_scope','p_lease_token']);
    perform pg_catalog.set_config('platform.room_lease_conference_id',(p_args->>'p_conference_id')::uuid::text,true);
    return platform_private.release_resource_lease(p_actor_device_id,'conference',p_args->>'p_resource_type',p_args->>'p_resource_id',p_args->>'p_scope',(p_args->>'p_lease_token')::uuid);
  elsif p_operation='get_resource_lease' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_resource_type','p_resource_id','p_scope']);
    perform pg_catalog.set_config('platform.room_lease_conference_id',(p_args->>'p_conference_id')::uuid::text,true);
    return platform_private.get_resource_lease(p_actor_device_id,'conference',p_args->>'p_resource_type',p_args->>'p_resource_id',p_args->>'p_scope');
  end if;
  return platform.execute_conference_device_operation_phase1c_core(
    p_user_id,p_session_id,p_token_hash,p_operation,p_args
  );
end $$;


--
-- Name: route_permission_administration("uuid", "text", "jsonb"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."route_permission_administration"("p_user_id" "uuid", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d uuid;
begin
 d:=platform_private.phase1c_context_device_id();
 if d is null or platform_private.validated_phase1c_device_authorization(p_user_id,d) is null then raise exception 'DEVICE_SESSION_INVALID' using errcode='42501'; end if;
 case p_operation
 when 'list_module_permission_grants' then return public.list_module_permission_grants(d,p_args->>'p_module_key',(p_args->>'p_target_user_id')::uuid);
 when 'search_module_permission_candidates' then return public.search_module_permission_candidates(d,p_args->>'p_module_key',p_args->>'p_query',coalesce((p_args->>'p_limit')::integer,50));
 when 'list_module_permission_catalog_for_administration' then return public.list_module_permission_catalog_for_administration(d,p_args->>'p_module_key');
 when 'list_module_permission_resources_for_administration' then return public.list_module_permission_resources_for_administration(d,p_args->>'p_module_key',p_args->>'p_resource_type');
 when 'manage_catalog_module_grant' then return public.manage_catalog_module_grant(d,(p_args->>'p_operation_id')::uuid,p_args->>'p_action',(p_args->>'p_target_user_id')::uuid,p_args->>'p_module_key',p_args->>'p_permission_key',p_args->>'p_resource_type',p_args->>'p_resource_id',(p_args->>'p_grant_id')::uuid,p_args->>'p_revocation_reason');
 else raise exception 'PLATFORM_OPERATION_NOT_ALLOWED' using errcode='42501';
 end case;
end $$;


--
-- Name: people; Type: TABLE; Schema: platform; Owner: -
--

CREATE TABLE "platform"."people" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "full_name" "text" NOT NULL,
    "phone" "text",
    "gender" "text",
    "date_of_birth" "date",
    "church" "text",
    "name_search" "text" GENERATED ALWAYS AS ("platform_private"."person_name_key"("full_name")) STORED,
    "phone_search" "text" GENERATED ALWAYS AS ("platform_private"."person_phone_key"("phone")) STORED,
    "revision" bigint DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "governorate" "text",
    "city_or_village" "text",
    "service_sector" "text",
    "service_sector_other" "text",
    CONSTRAINT "people_church_check" CHECK ((("church" IS NULL) OR (("char_length"("church") <= 200) AND ("platform_private"."person_name_key"("church") <> ''::"text")))),
    CONSTRAINT "people_full_name_check" CHECK (((("char_length"("full_name") >= 1) AND ("char_length"("full_name") <= 240)) AND ("platform_private"."person_name_key"("full_name") <> ''::"text"))),
    CONSTRAINT "people_gender_check" CHECK (("gender" = ANY (ARRAY['male'::"text", 'female'::"text"]))),
    CONSTRAINT "people_phone_check" CHECK ((("phone" IS NULL) OR ((("char_length"("phone") >= 1) AND ("char_length"("phone") <= 40)) AND ("platform_private"."person_phone_key"("phone") <> ''::"text")))),
    CONSTRAINT "people_revision_check" CHECK (("revision" > 0))
);

ALTER TABLE ONLY "platform"."people" FORCE ROW LEVEL SECURITY;


--
-- Name: search_people("text", "text", integer); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."search_people"("p_query" "text" DEFAULT ''::"text", "p_gender" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20) RETURNS SETOF "platform"."people"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare v_name text := platform_private.person_name_key(p_query); v_phone text := platform_private.person_phone_key(p_query); v_phone_query boolean := coalesce(p_query,'') ~ '^[0-9٠-٩۰-۹[:space:]+().-]+$' and v_phone<>''; v_limit integer := greatest(1,least(coalesce(p_limit,20),50)); v_pattern text;
begin
 if p_gender is not null and p_gender not in ('male','female') then raise exception 'PLATFORM_PERSON_GENDER_INVALID' using errcode='22023'; end if;
 v_pattern := replace(replace(replace(v_name,E'\\',E'\\\\'),'%',E'\\%'),'_',E'\\_')||'%';
 return query select p.* from platform.people p where (p_gender is null or p.gender=p_gender) and (v_name='' or p.name_search like v_pattern escape E'\\' or (v_phone_query and p.phone is not null and p.phone_search like v_phone||'%')) order by p.name_search collate "C",p.id limit v_limit;
end; $_$;


--
-- Name: seed_access_reference_data(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."seed_access_reference_data"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  insert into platform.permissions (code, domain, description) values
    ('platform.access.manage','platform','Manage platform access configuration'),
    ('platform.users.view','platform','View platform users'),('platform.users.manage','platform','Approve or block platform users'),
    ('platform.roles.view','platform','View platform roles and grants'),('platform.roles.manage','platform','Manage platform and domain role assignments'),
    ('platform.devices.view','platform','View devices and authorizations'),('platform.devices.approve','platform','Approve pending device authorizations'),
    ('platform.devices.block','platform','Block device authorizations'),('platform.devices.revoke','platform','Permanently revoke device authorizations'),
    ('platform.audit.view','platform','View platform audit events'),
    ('inventory.access','inventory','Access inventory'),('inventory.products.view','inventory','View products'),
    ('inventory.products.create','inventory','Create products'),('inventory.products.edit','inventory','Edit products'),
    ('inventory.products.delete','inventory','Archive or delete eligible products'),('inventory.warehouses.view','inventory','View warehouses'),
    ('inventory.warehouses.manage','inventory','Manage warehouses'),('inventory.parties.view','inventory','View parties'),
    ('inventory.parties.manage','inventory','Manage parties'),('inventory.stock.view','inventory','View stock and movements'),
    ('inventory.stock.receive','inventory','Receive stock'),('inventory.stock.issue','inventory','Issue stock'),
    ('inventory.stock.transfer','inventory','Transfer stock'),('inventory.purchases.view','inventory','View purchases'),
    ('inventory.purchases.manage','inventory','Manage purchases'),('inventory.payments.view','inventory','View payments and balances'),
    ('inventory.payments.manage','inventory','Manage payments and allocations'),('inventory.reports.view','inventory','View inventory reports'),
    ('inventory.settings.manage','inventory','Manage inventory-specific settings')
  on conflict (code) do update set domain=excluded.domain,description=excluded.description,updated_at=pg_catalog.now();

  insert into platform.roles (code,domain,name,description,scope_type,is_system,is_assignable) values
    ('platform_owner','platform','Platform Owner','Bootstrap owner with every platform permission','platform',true,false),
    ('platform_admin','platform','Platform Admin','Administers users, roles, devices, and audit','platform',true,true),
    ('inventory_manager','inventory','Inventory Manager','Manages inventory operations and reporting','inventory',true,false),
    ('inventory_operator','inventory','Inventory Operator','Runs approved daily inventory operations','inventory',true,false),
    ('viewer','inventory','Inventory Viewer','Read-only inventory access','inventory',true,false)
  on conflict (domain,code) do update set name=excluded.name,description=excluded.description,scope_type=excluded.scope_type,
    is_system=excluded.is_system,is_assignable=excluded.is_assignable,updated_at=pg_catalog.now();

  insert into platform.role_permissions (role_id,permission_id)
  select r.id,p.id from platform.roles r cross join platform.permissions p
  where r.domain='platform' and r.code in ('platform_owner','platform_admin') and p.domain='platform' on conflict do nothing;

  insert into platform.role_permissions (role_id,permission_id)
  select r.id,p.id from platform.roles r join platform.permissions p on p.code=any(array[
    'inventory.access','inventory.products.view','inventory.products.create','inventory.products.edit','inventory.warehouses.view',
    'inventory.warehouses.manage','inventory.parties.view','inventory.parties.manage','inventory.stock.view','inventory.stock.receive',
    'inventory.stock.issue','inventory.stock.transfer','inventory.purchases.view','inventory.purchases.manage','inventory.payments.view',
    'inventory.payments.manage','inventory.reports.view','inventory.settings.manage'])
  where r.domain='inventory' and r.code='inventory_manager' on conflict do nothing;

  insert into platform.role_permissions (role_id,permission_id)
  select r.id,p.id from platform.roles r join platform.permissions p on p.code=any(array[
    'inventory.access','inventory.products.view','inventory.products.create','inventory.products.edit','inventory.warehouses.view',
    'inventory.parties.view','inventory.parties.manage','inventory.stock.view','inventory.stock.receive','inventory.stock.issue',
    'inventory.stock.transfer','inventory.purchases.view','inventory.purchases.manage','inventory.payments.view','inventory.reports.view'])
  where r.domain='inventory' and r.code='inventory_operator' on conflict do nothing;

  insert into platform.role_permissions (role_id,permission_id)
  select r.id,p.id from platform.roles r join platform.permissions p on p.code=any(array[
    'inventory.access','inventory.products.view','inventory.warehouses.view','inventory.parties.view','inventory.stock.view',
    'inventory.purchases.view','inventory.payments.view','inventory.reports.view'])
  where r.domain='inventory' and r.code='viewer' on conflict do nothing;
end; $$;


--
-- Name: set_conference_automatic_extra_bed_source(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."set_conference_automatic_extra_bed_source"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare participation public.conference_participations%rowtype;
begin
  if new.bed_type<>'extra' then new.extra_bed_source:=null; return new; end if;
  if tg_op='UPDATE' and new.bed_type=old.bed_type
     and new.participation_id is not distinct from old.participation_id
     and old.extra_bed_source is not null then
    new.extra_bed_source:=old.extra_bed_source; return new;
  end if;
  select * into participation from public.conference_participations
  where id=new.participation_id and conference_id=new.conference_id;
  new.extra_bed_source:=case
    when participation.guardian_participation_id is not null
      and new.extra_bed_person_type='child' then 'automatic'
    else 'manual' end;
  return new;
end $$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin new.updated_at:=pg_catalog.now(); return new; end; $$;


--
-- Name: sync_guardian_linked_child_stays(); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."sync_guardian_linked_child_stays"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  linked public.conference_accommodation_occupancies%rowtype;
  guardian_before public.conference_accommodation_occupancies%rowtype;
begin
  if tg_op='DELETE' then
    delete from public.conference_accommodation_occupancies child_stay
    using public.conference_participations child
    where child.id=child_stay.participation_id
      and child.conference_id=old.conference_id
      and child.guardian_participation_id=old.participation_id
      and child_stay.conference_id=old.conference_id
      and child_stay.room_id=old.room_id
      and child_stay.arrival_day=old.arrival_day
      and child_stay.leave_day is not distinct from old.leave_day;
    return old;
  end if;

  if tg_op='INSERT' then
    select * into guardian_before
      from public.conference_accommodation_occupancies prior
     where prior.conference_id=new.conference_id
       and prior.participation_id=new.participation_id
       and prior.leave_day=new.arrival_day
     order by prior.arrival_day desc,prior.id
     limit 1;
    if not found then return new; end if;

    for linked in
      select child_stay.*
        from public.conference_accommodation_occupancies child_stay
        join public.conference_participations child on child.id=child_stay.participation_id
       where child.conference_id=new.conference_id
         and child.guardian_participation_id=new.participation_id
         and child_stay.conference_id=new.conference_id
         and child_stay.room_id=guardian_before.room_id
         and child_stay.arrival_day=guardian_before.arrival_day
         and child_stay.leave_day is not distinct from guardian_before.leave_day
       order by child_stay.id for update of child_stay
    loop
      if linked.extra_bed_source is distinct from 'automatic' and not platform_private.conference_room_has_capacity(new.conference_id,new.room_id,linked.bed_type,new.arrival_day,new.leave_day,null) then
        raise exception 'ACCOMMODATION_ROOM_CAPACITY_EXCEEDED' using errcode='55000';
      end if;
      insert into public.conference_accommodation_occupancies(
        conference_id,room_id,participation_id,arrival_day,leave_day,bed_type,
        extra_bed_person_type,extra_bed_source,arrived_at,arrived_by,created_by,updated_by
      ) values(
        new.conference_id,new.room_id,linked.participation_id,new.arrival_day,new.leave_day,
        linked.bed_type,linked.extra_bed_person_type,linked.extra_bed_source,new.arrived_at,new.arrived_by,
        linked.created_by,new.updated_by
      );
    end loop;
    return new;
  end if;

  if new.room_id is distinct from old.room_id
     or new.arrival_day is distinct from old.arrival_day
     or new.leave_day is distinct from old.leave_day
     or new.arrived_at is distinct from old.arrived_at
     or new.arrived_by is distinct from old.arrived_by then
    for linked in
      select child_stay.*
        from public.conference_accommodation_occupancies child_stay
        join public.conference_participations child on child.id=child_stay.participation_id
       where child.conference_id=new.conference_id
         and child.guardian_participation_id=new.participation_id
         and child_stay.conference_id=old.conference_id
         and child_stay.room_id=old.room_id
         and child_stay.arrival_day=old.arrival_day
         and child_stay.leave_day is not distinct from old.leave_day
       order by child_stay.id for update of child_stay
    loop
      if linked.extra_bed_source is distinct from 'automatic' and not platform_private.conference_room_has_capacity(new.conference_id,new.room_id,linked.bed_type,new.arrival_day,new.leave_day,linked.id) then
        raise exception 'ACCOMMODATION_ROOM_CAPACITY_EXCEEDED' using errcode='55000';
      end if;
      update public.conference_accommodation_occupancies
         set room_id=new.room_id,arrival_day=new.arrival_day,leave_day=new.leave_day,
             arrived_at=new.arrived_at,arrived_by=new.arrived_by,revision=revision+1,
             updated_at=statement_timestamp(),updated_by=new.updated_by
       where id=linked.id;
    end loop;
  end if;
  return new;
end $$;


--
-- Name: update_canonical_person("uuid", "uuid", "uuid", bigint, "jsonb", "uuid", "text", "text", "jsonb"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."update_canonical_person"("p_device_id" "uuid", "p_actor" "uuid", "p_person_id" "uuid", "p_expected_revision" bigint, "p_patch" "jsonb", "p_operation_id" "uuid", "p_module" "text", "p_permission" "text", "p_metadata" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_person platform.people%rowtype;v_authorization uuid;v_allowed text[];
begin
 if p_module='conference' and p_permission='conference.people.manage' then
  v_allowed:=array['fullName','phone','church','gender','dateOfBirth','governorate','cityOrVillage','serviceSector','serviceSectorOther'];
 elsif p_module='reservations' and p_permission='reservations.people.manage' then
  v_allowed:=array['fullName','phone','church','gender','dateOfBirth','governorate','cityOrVillage','serviceSector','serviceSectorOther'];
 else raise exception 'PERSON_UPDATE_MODULE_INVALID' using errcode='42501';end if;
 if p_actor is null or p_person_id is null or p_expected_revision is null or p_expected_revision<1 or p_patch is null or jsonb_typeof(p_patch)<>'object' or not (p_patch ? 'fullName') then raise exception 'PERSON_UPDATE_ARGUMENT_INVALID' using errcode='22023';end if;
 if exists(select 1 from jsonb_object_keys(p_patch) k where not k=any(v_allowed)) then raise exception 'PERSON_UPDATE_ARGUMENT_UNKNOWN' using errcode='22023';end if;
 if length(btrim(coalesce(p_patch->>'fullName','')))=0 or length(btrim(p_patch->>'fullName'))>240
   or p_patch ? 'gender' and nullif(p_patch->>'gender','') is not null and p_patch->>'gender' not in('male','female')
   or p_patch ? 'dateOfBirth' and nullif(p_patch->>'dateOfBirth','') is not null and (p_patch->>'dateOfBirth')::date>current_date
   or p_patch ? 'serviceSector' and length(btrim(coalesce(p_patch->>'serviceSector','')))>120
   or p_patch ? 'serviceSectorOther' and length(btrim(coalesce(p_patch->>'serviceSectorOther','')))>240 then raise exception 'PERSON_UPDATE_ARGUMENT_INVALID' using errcode='22023';end if;
 v_authorization:=platform_private.validated_phase1c_device_authorization(p_actor,p_device_id);
 if v_authorization is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;
 if p_module='conference' then
  if nullif(p_metadata->>'conferenceId','') is null then raise exception 'CONFERENCE_PERSON_SCOPE_REQUIRED' using errcode='42501';end if;
  perform platform_private.require_conference_participation_context(p_device_id,(p_metadata->>'conferenceId')::uuid,'conference.people.manage',true);
  if not exists(select 1 from public.conference_participations where conference_id=(p_metadata->>'conferenceId')::uuid and person_id=p_person_id) then raise exception 'CONFERENCE_PERSON_NOT_PARTICIPATING' using errcode='42501';end if;
 else perform public.require_effective_module_permission(p_device_id,p_module,p_permission,null,null);end if;
 update platform.people set
  full_name=btrim(p_patch->>'fullName'),
  phone=case when p_patch ? 'phone' then nullif(btrim(coalesce(p_patch->>'phone','')),'') else phone end,
  church=case when p_patch ? 'church' then nullif(btrim(coalesce(p_patch->>'church','')),'') else church end,
  gender=case when p_patch ? 'gender' then nullif(p_patch->>'gender','') else gender end,
  date_of_birth=case when p_patch ? 'dateOfBirth' then nullif(p_patch->>'dateOfBirth','')::date else date_of_birth end,
  governorate=case when p_patch ? 'governorate' then nullif(btrim(coalesce(p_patch->>'governorate','')),'') else governorate end,
  city_or_village=case when p_patch ? 'cityOrVillage' then nullif(btrim(coalesce(p_patch->>'cityOrVillage','')),'') else city_or_village end,
  service_sector=case when p_patch ? 'serviceSector' then nullif(btrim(coalesce(p_patch->>'serviceSector','')),'') else service_sector end,
  service_sector_other=case when p_patch ? 'serviceSectorOther' then nullif(btrim(coalesce(p_patch->>'serviceSectorOther','')),'') else service_sector_other end,
  revision=revision+1,updated_at=statement_timestamp(),updated_by=p_actor
 where id=p_person_id and revision=p_expected_revision returning * into v_person;
 if not found then raise exception 'PERSON_REVISION_CONFLICT' using errcode='40001';end if;
 insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,new_values,metadata,operation_id,source)
 values(p_actor,v_authorization,'platform',p_module,'platform.person.updated','person',p_person_id,'platform',
  jsonb_build_object('id',v_person.id,'fullName',v_person.full_name,'phone',v_person.phone,'church',v_person.church,'gender',v_person.gender,'dateOfBirth',v_person.date_of_birth,'governorate',v_person.governorate,'cityOrVillage',v_person.city_or_village,'serviceSector',v_person.service_sector,'serviceSectorOther',v_person.service_sector_other),
  coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('expectedRevision',p_expected_revision,'permissionKey',p_permission),p_operation_id,'rpc');
 return jsonb_build_object('personId',v_person.id,'fullName',v_person.full_name,'phone',v_person.phone,'church',v_person.church,'gender',v_person.gender,'dateOfBirth',v_person.date_of_birth,'governorate',v_person.governorate,'cityOrVillage',v_person.city_or_village,'serviceSector',v_person.service_sector,'serviceSectorOther',v_person.service_sector_other,'revision',v_person.revision);
end $$;


--
-- Name: user_has_module_permission_for("uuid", "text", "text", "text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."user_has_module_permission_for"("p_user_id" "uuid", "p_permission_key" "text", "p_resource_type" "text" DEFAULT NULL::"text", "p_resource_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select platform_private.is_account_approved(p_user_id) and (
  platform_private.is_canonical_platform_owner(p_user_id)
  or exists(
   select 1 from platform.permission_grants g join platform.permissions p on p.id=g.permission_id
   where g.user_id=p_user_id and g.revoked_at is null and p.status='active'
    and p.code in(p_permission_key,case when p_permission_key=split_part(p_permission_key,'.',1)||'.module.access' then split_part(p_permission_key,'.',1)||'.module.manage' else p_permission_key end)
    and ((p_resource_type is null and g.scope_type='module')
      or (g.scope_type='module' and p.allowed_scope_mode in('module','both'))
      or (g.scope_type='resource' and g.resource_type=p_resource_type and g.resource_id=p_resource_id))
  )
  or exists(
   select 1 from platform.user_roles a
   join platform.roles r on r.id=a.role_id
   join platform.role_permissions rp on rp.role_id=r.id
   join platform.permissions p on p.id=rp.permission_id
   where a.user_id=p_user_id and a.revoked_at is null
    and (a.expires_at is null or a.expires_at>statement_timestamp())
    and p.status='active'
    and p.code in(p_permission_key,case when p_permission_key=split_part(p_permission_key,'.',1)||'.module.access' then split_part(p_permission_key,'.',1)||'.module.manage' else p_permission_key end)
    and ((a.scope_type='platform' and a.scope_id is null and p_resource_type is null)
      or (a.scope_type='conference' and p_resource_type='conference' and a.scope_id::text=p_resource_id))
  )
 );
$$;


--
-- Name: validate_conference_canonical_bundle("uuid", "jsonb", "text", "uuid", bigint); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."validate_conference_canonical_bundle"("p_actor_device_id" "uuid", "p_bundle" "jsonb", "p_mode" "text", "p_target_conference_id" "uuid", "p_expected_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid;v_data jsonb;v_manifest jsonb;v_sections jsonb;v_core jsonb;v_table text;v_rows jsonb;v_row jsonb;v_source uuid;v_target public.conferences%rowtype;v_errors jsonb='[]'::jsonb;v_person uuid;v_house uuid;v_room uuid;
begin
 v_actor:=public.require_current_approved_device(p_actor_device_id);
 if p_mode not in('new','replace') then raise exception 'CONFERENCE_BUNDLE_MODE_INVALID' using errcode='22023'; end if;
 if jsonb_typeof(p_bundle)<>'object' or p_bundle->>'type'<>'conference-canonical-bundle' or p_bundle->>'schemaVersion'<>'1' then
  raise exception 'CONFERENCE_BUNDLE_SCHEMA_UNSUPPORTED' using errcode='22023';
 end if;
 if octet_length(p_bundle::text)>10*1024*1024 then raise exception 'CONFERENCE_BUNDLE_TOO_LARGE' using errcode='22023'; end if;
 if (select count(*) from jsonb_object_keys(p_bundle))<>4 or not (p_bundle ?& array['type','schemaVersion','manifest','data']) then raise exception 'CONFERENCE_BUNDLE_FIELDS_INVALID' using errcode='22023'; end if;
 v_manifest:=p_bundle->'manifest';v_data:=p_bundle->'data';v_core:=v_data->'conference';v_sections:=v_data->'sections';
 if jsonb_typeof(v_manifest)<>'object' or jsonb_typeof(v_data)<>'object' or jsonb_typeof(v_core)<>'object' or jsonb_typeof(v_sections)<>'object' then raise exception 'CONFERENCE_BUNDLE_STRUCTURE_INVALID' using errcode='22023'; end if;
 if encode(extensions.digest(v_data::text,'sha256'),'hex') is distinct from v_manifest->>'payloadSha256' then raise exception 'CONFERENCE_BUNDLE_HASH_MISMATCH' using errcode='22023'; end if;
 v_source:=(v_manifest->>'sourceConferenceId')::uuid;
 if (v_core->>'id')::uuid is distinct from v_source then raise exception 'CONFERENCE_BUNDLE_SOURCE_MISMATCH' using errcode='22023'; end if;
 if exists(select 1 from jsonb_object_keys(v_sections) k where not k=any(platform_private.conference_bundle_tables())) then raise exception 'CONFERENCE_BUNDLE_SECTION_NOT_ALLOWED' using errcode='22023'; end if;
 foreach v_table in array platform_private.conference_bundle_tables() loop
  v_rows:=v_sections->v_table;
  if jsonb_typeof(v_rows)<>'array' then raise exception 'CONFERENCE_BUNDLE_SECTION_REQUIRED: %',v_table using errcode='22023'; end if;
  for v_row in select value from jsonb_array_elements(v_rows) loop
   if jsonb_typeof(v_row)<>'object' or (v_row->>'conference_id')::uuid is distinct from v_source then raise exception 'CONFERENCE_BUNDLE_SECTION_SCOPE_INVALID: %',v_table using errcode='22023'; end if;
   if v_row ?| array['created_by','updated_by','owner_id','actor_user_id','actor_device_id','operation_id','session_id'] then raise exception 'CONFERENCE_BUNDLE_AUTHORITY_FIELD_FORBIDDEN' using errcode='22023'; end if;
  end loop;
 end loop;
 for v_person in select distinct (value->>'person_id')::uuid from jsonb_array_elements(v_sections->'conference_participations') where value ? 'person_id' loop
  if not exists(select 1 from platform.people where id=v_person) then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','PERSON_REFERENCE_NOT_FOUND','id',v_person)); end if;
 end loop;
 for v_house in select distinct (value->>'house_id')::uuid from jsonb_array_elements(v_sections->'conference_house_assignments') loop
  if not exists(select 1 from public.conference_accommodation_houses where id=v_house and is_active) then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','HOUSE_REFERENCE_NOT_FOUND','id',v_house)); end if;
 end loop;
 for v_room in select distinct (value->>'room_id')::uuid from jsonb_array_elements(v_sections->'conference_room_assignments') loop
  if not exists(select 1 from public.conference_accommodation_rooms where id=v_room) then v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','ROOM_REFERENCE_NOT_FOUND','id',v_room)); end if;
 end loop;
 if p_mode='replace' then
  if p_target_conference_id is null or p_expected_revision is null then raise exception 'CONFERENCE_BUNDLE_REPLACE_CONFIRMATION_REQUIRED' using errcode='22023'; end if;
  perform public.require_effective_module_permission(p_actor_device_id,'conference','conference.data.restore','conference',p_target_conference_id::text);
  select * into v_target from public.conferences where id=p_target_conference_id and deleted_at is null for update;
  if not found then raise exception 'CONFERENCE_NOT_FOUND' using errcode='22023'; end if;
  if v_target.revision<>p_expected_revision then raise exception 'CONFERENCE_BUNDLE_REVISION_CONFLICT' using errcode='40001'; end if;
 else
  perform public.require_effective_module_permission(p_actor_device_id,'conference','conference.lifecycle.create');
  if p_target_conference_id is not null and exists(select 1 from public.conferences where id=p_target_conference_id) then raise exception 'CONFERENCE_BUNDLE_TARGET_EXISTS' using errcode='23505'; end if;
  if exists(select 1 from jsonb_array_elements(v_sections->'conference_air_conditioning_house_overrides') item join public.conference_air_conditioning_house_overrides current on current.house_id=(item->>'house_id')::uuid)
     or exists(select 1 from jsonb_array_elements(v_sections->'conference_air_conditioning_room_overrides') item join public.conference_air_conditioning_room_overrides current on current.room_id=(item->>'room_id')::uuid) then
    v_errors:=v_errors||jsonb_build_array(jsonb_build_object('code','SHARED_OVERRIDE_CONFLICT'));
  end if;
 end if;
 return jsonb_build_object('valid',jsonb_array_length(v_errors)=0,'errors',v_errors,'sourceConferenceId',v_source,'targetConferenceId',p_target_conference_id,'mode',p_mode,'schemaVersion',1);
end $$;


--
-- Name: validated_phase1c_device_authorization("uuid", "uuid"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."validated_phase1c_device_authorization"("p_user_id" "uuid", "p_device_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_claims jsonb;
  v_session_id uuid;
  v_authorization_id uuid;
  v_binding_id uuid;
  v_token_hash bytea;
begin
  begin
    v_claims:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;
    if v_claims is null or v_claims->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH'
      or (v_claims->>'user_id')::uuid is distinct from p_user_id
      or (v_claims->>'device_id')::uuid is distinct from p_device_id then return null; end if;
    v_session_id:=(v_claims->>'session_id')::uuid;
    v_authorization_id:=(v_claims->>'authorization_id')::uuid;
    v_binding_id:=(v_claims->>'binding_id')::uuid;
    v_token_hash:=pg_catalog.decode(v_claims->>'token_hash','hex');
  exception when others then return null;
  end;
  if pg_catalog.octet_length(v_token_hash)<>32 then return null; end if;
  if exists(select 1 from platform_private.device_sessions session
    join platform.device_key_bindings binding on binding.id=session.binding_id
    join platform.user_device_authorizations uda on uda.id=session.device_authorization_id
    join platform.devices device on device.id=session.device_id
    join platform.profiles profile on profile.user_id=session.user_id
    where session.id=v_session_id and session.user_id=p_user_id and session.device_id=p_device_id
      and session.device_authorization_id=v_authorization_id and session.binding_id=v_binding_id
      and session.token_hash=v_token_hash and session.purpose='PLATFORM_DEVICE_SESSION'
      and session.revoked_at is null and session.expires_at>pg_catalog.statement_timestamp()
      and binding.user_id=session.user_id and binding.device_id=session.device_id
      and binding.device_authorization_id=session.device_authorization_id
      and binding.public_key_thumbprint=session.public_key_thumbprint
      and binding.algorithm='ECDSA_P256_SHA256' and binding.lifecycle_status='active'
      and binding.revoked_at is null and binding.retired_at is null
      and uda.user_id=session.user_id and uda.device_id=session.device_id
      and uda.status='approved' and uda.revoked_at is null
      and device.lifecycle_status='active' and device.retired_at is null and device.compromised_at is null
      and profile.account_status='approved') then return v_authorization_id; end if;
  return null;
end; $$;


--
-- Name: write_audit_event("uuid", "uuid", "text", "text", "text", "text", "uuid", "text", "jsonb", "jsonb", "jsonb", "uuid", "uuid", "text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."write_audit_event"("p_actor_user_id" "uuid", "p_subject_user_id" "uuid", "p_domain" "text", "p_module" "text", "p_action" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_scope_type" "text", "p_old_values" "jsonb", "p_new_values" "jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_request_id" "uuid" DEFAULT NULL::"uuid", "p_operation_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT 'rpc'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,subject_user_id,domain,module,action,
    entity_type,entity_id,scope_type,scope_id,old_values,new_values,metadata,request_id,operation_id,source)
  values(p_actor_user_id,case when p_source='bootstrap' then null else platform_private.current_device_authorization_id(p_actor_user_id) end,
    p_subject_user_id,p_domain,p_module,p_action,p_entity_type,p_entity_id,p_scope_type,null,p_old_values,p_new_values,
    coalesce(p_metadata,'{}'::jsonb),p_request_id,p_operation_id,p_source) returning id into v_id;
  return v_id;
end; $$;


--
-- Name: write_scoped_audit_event("uuid", "uuid", "text", "text", "text", "text", "uuid", "text", "uuid", "jsonb", "jsonb", "jsonb", "uuid", "uuid", "text"); Type: FUNCTION; Schema: platform_private; Owner: -
--

CREATE FUNCTION "platform_private"."write_scoped_audit_event"("p_actor_user_id" "uuid", "p_subject_user_id" "uuid", "p_domain" "text", "p_module" "text", "p_action" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_scope_type" "text", "p_scope_id" "uuid", "p_old_values" "jsonb", "p_new_values" "jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_request_id" "uuid" DEFAULT NULL::"uuid", "p_operation_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT 'rpc'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
 if p_scope_type<>'reservations' or p_scope_id is null then raise exception 'PLATFORM_AUDIT_SCOPE_INVALID' using errcode='22023'; end if;
 insert into platform.audit_events(actor_user_id,actor_device_authorization_id,subject_user_id,domain,module,action,
 entity_type,entity_id,scope_type,scope_id,old_values,new_values,metadata,request_id,operation_id,source)
 values(p_actor_user_id,platform_private.current_device_authorization_id(p_actor_user_id),p_subject_user_id,p_domain,p_module,p_action,
 p_entity_type,p_entity_id,p_scope_type,p_scope_id,p_old_values,p_new_values,coalesce(p_metadata,'{}'::jsonb),p_request_id,p_operation_id,p_source)
 returning id into v_id;
 return v_id;
end $$;


--
-- Name: acquire_conference_lock("uuid", "uuid", "uuid", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."acquire_conference_lock"("p_conference_id" "uuid", "p_device_id" "uuid", "p_lock_token" "uuid", "p_ttl_seconds" integer DEFAULT 120) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select public.acquire_conference_section_lock(p_conference_id,'conference',p_device_id,p_lock_token,p_ttl_seconds);
$$;


--
-- Name: acquire_conference_section_lock("uuid", "text", "uuid", "uuid", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."acquire_conference_section_lock"("p_conference_id" "uuid", "p_section" "text", "p_device_id" "uuid", "p_lock_token" "uuid", "p_ttl_seconds" integer DEFAULT 120) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare current_user_id uuid; effective_ttl integer := coalesce(p_ttl_seconds,120); normalized_section text := lower(trim(coalesce(p_section,''))); current_lock public.conference_locks%rowtype; server_now timestamptz := clock_timestamp(); new_expiry timestamptz;
begin
  if p_conference_id is null or p_device_id is null or p_lock_token is null or normalized_section !~ '^[a-z][a-z0-9_]{0,31}$' or effective_ttl < 30 or effective_ttl > 300 then raise exception 'INVALID_CONFERENCE_SECTION_LOCK_ARGUMENTS' using errcode='22023'; end if;
  current_user_id := public.require_conference_section_lock_writer(p_conference_id,p_device_id,normalized_section);
  perform 1 from public.conferences as conferences where conferences.id=p_conference_id for update; if not found then raise exception 'CONFERENCE_NOT_FOUND' using errcode='P0002'; end if;
  perform public.require_conference_section_lock_writer(p_conference_id,p_device_id,normalized_section);
  select * into current_lock from public.conference_locks as locks where locks.conference_id=p_conference_id and locks.section=normalized_section for update; new_expiry:=server_now+make_interval(secs=>effective_ttl);
  if not found then insert into public.conference_locks(conference_id,section,user_id,device_id,lock_token,acquired_at,expires_at,last_renewed_at,created_at) values(p_conference_id,normalized_section,current_user_id,p_device_id,p_lock_token,server_now,new_expiry,server_now,server_now); return jsonb_build_object('success',true,'status','acquired','conferenceId',p_conference_id,'section',normalized_section,'lockToken',p_lock_token,'owned',true,'userId',current_user_id,'deviceId',p_device_id,'acquiredAt',server_now,'expiresAt',new_expiry,'lastRenewedAt',server_now,'serverNow',server_now,'isExpired',false); end if;
  if current_lock.expires_at<=server_now then update public.conference_locks set user_id=current_user_id,device_id=p_device_id,lock_token=p_lock_token,acquired_at=server_now,expires_at=new_expiry,last_renewed_at=server_now,created_at=server_now where conference_id=p_conference_id and section=normalized_section; return jsonb_build_object('success',true,'status','acquired','conferenceId',p_conference_id,'section',normalized_section,'lockToken',p_lock_token,'owned',true,'userId',current_user_id,'deviceId',p_device_id,'acquiredAt',server_now,'expiresAt',new_expiry,'lastRenewedAt',server_now,'serverNow',server_now,'isExpired',false); end if;
  if current_lock.user_id=current_user_id and current_lock.device_id=p_device_id then return jsonb_build_object('success',true,'status','already_owned','conferenceId',p_conference_id,'section',normalized_section,'lockToken',current_lock.lock_token,'owned',true,'userId',current_lock.user_id,'deviceId',current_lock.device_id,'acquiredAt',current_lock.acquired_at,'expiresAt',current_lock.expires_at,'lastRenewedAt',current_lock.last_renewed_at,'serverNow',server_now,'isExpired',false); end if;
  return jsonb_build_object('success',true,'status','locked','errorCode','LOCK_NOT_OWNED','conferenceId',p_conference_id,'section',normalized_section,'owned',false,'userId',current_lock.user_id,'deviceId',current_lock.device_id,'acquiredAt',current_lock.acquired_at,'expiresAt',current_lock.expires_at,'lastRenewedAt',current_lock.last_renewed_at,'serverNow',server_now,'isExpired',false);
end; $_$;


--
-- Name: add_conference_guardian_child_accommodation("uuid", "uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."add_conference_guardian_child_accommodation"("p_device" "uuid", "p_operation_id" "uuid", "p_conference" "uuid", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 ctx jsonb;people_ctx jsonb;actor uuid;authz uuid;guardian public.conference_participations%rowtype;child public.conference_participations%rowtype;
 guardian_stay public.conference_accommodation_occupancies%rowtype;child_stay public.conference_accommodation_occupancies%rowtype;
 v_person_id uuid;v_room_id uuid;bed text;result jsonb;old_values jsonb;new_values jsonb;
begin
 perform platform_private.require_exact_jsonb_keys(p_args,array['roomId','guardianParticipationId','childPersonId','childFullName','bedType']);
 ctx:=platform_private.require_conference_accommodation_context(p_device,p_conference,'conference.accommodation.manage',true);
 people_ctx:=platform_private.require_conference_participation_context(p_device,p_conference,'conference.people.manage',true);
 actor:=(ctx->>'actorUserId')::uuid;
 if actor is distinct from (people_ctx->>'actorUserId')::uuid then raise exception 'CONFERENCE_OPERATION_ACTOR_MISMATCH' using errcode='42501';end if;
 authz:=platform_private.validated_phase1c_device_authorization(actor,p_device);
 select ae.new_values into result from platform.audit_events ae where ae.actor_user_id=actor and ae.operation_id=p_operation_id and ae.scope_id=p_conference and ae.action='conference.accommodation.guardian_child_added' limit 1;
 if result is not null then return result||jsonb_build_object('status','duplicate');end if;
 v_room_id:=(p_args->>'roomId')::uuid;bed:=p_args->>'bedType';
 if v_room_id is null or nullif(trim(p_args->>'guardianParticipationId'),'') is null or bed not in('shared','base','extra') then raise exception 'ACCOMMODATION_GUARDIAN_CHILD_INVALID' using errcode='22023';end if;
 if (nullif(p_args->>'childPersonId','') is null)=(nullif(trim(p_args->>'childFullName'),'') is null) then raise exception 'ACCOMMODATION_CHILD_PERSON_OR_NAME_REQUIRED' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('conference-guardian:'||p_conference::text||':'||(p_args->>'guardianParticipationId'),0));
 select * into guardian from public.conference_participations where id=(p_args->>'guardianParticipationId')::uuid and conference_id=p_conference and status='active' for update;
 if not found or guardian.guardian_participation_id is not null then raise exception 'ACCOMMODATION_GUARDIAN_NOT_ACTIVE' using errcode='23514';end if;
 select * into guardian_stay from public.conference_accommodation_occupancies where conference_id=p_conference and public.conference_accommodation_occupancies.room_id=v_room_id and participation_id=guardian.id and arrival_day<=platform_private.conference_operational_day(p_conference) and coalesce(leave_day,platform_private.conference_accommodation_duration(p_conference)+1)>platform_private.conference_operational_day(p_conference) for update;
 if not found then raise exception 'ACCOMMODATION_SHARED_CHILD_GUARDIAN_STAY_REQUIRED' using errcode='23514';end if;
 if nullif(p_args->>'childPersonId','') is not null then
   v_person_id:=(p_args->>'childPersonId')::uuid;
   perform 1 from platform.people where id=v_person_id for key share;
   if not found then raise exception 'CONFERENCE_PERSON_NOT_FOUND' using errcode='P0002';end if;
 else
   insert into platform.people(full_name,created_by,updated_by) values(trim(p_args->>'childFullName'),actor,actor) returning id into v_person_id;
 end if;
 select * into child from public.conference_participations where conference_id=p_conference and public.conference_participations.person_id=v_person_id and status='active' for update;
 if not found then
   insert into public.conference_participations(conference_id,person_id,guardian_participation_id,status,created_by,updated_by) values(p_conference,v_person_id,guardian.id,'active',actor,actor) returning * into child;
 elsif child.guardian_participation_id is null then
   update public.conference_participations set guardian_participation_id=guardian.id,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=child.id returning * into child;
 elsif child.guardian_participation_id is distinct from guardian.id then
   raise exception 'CONFERENCE_CHILD_GUARDIAN_MISMATCH' using errcode='23514';
 end if;
 select * into child_stay from public.conference_accommodation_occupancies where conference_id=p_conference and participation_id=child.id and arrival_day<=platform_private.conference_operational_day(p_conference) and coalesce(leave_day,platform_private.conference_accommodation_duration(p_conference)+1)>platform_private.conference_operational_day(p_conference) for update;
 if found then
   if child_stay.room_id is distinct from v_room_id or child_stay.arrival_day is distinct from guardian_stay.arrival_day or child_stay.leave_day is distinct from guardian_stay.leave_day or child_stay.bed_type is distinct from bed then raise exception 'ACCOMMODATION_CHILD_ALREADY_ASSIGNED_DIFFERENTLY' using errcode='23514';end if;
 else
   perform public.assign_conference_accommodation(p_device,p_conference,v_room_id,child.id,guardian_stay.arrival_day,guardian_stay.leave_day,bed,case when bed='extra' then 'child' else null end);
 end if;
 result:=jsonb_build_object('status','success','roomId',v_room_id,'guardianParticipationId',guardian.id,'childParticipationId',child.id,'bedType',bed);
 insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,scope_id,old_values,new_values,metadata,operation_id,source) values(actor,authz,'platform','conference','conference.accommodation.guardian_child_added','conference_participation',child.id,'conference',p_conference,old_values,result,jsonb_build_object('conferenceId',p_conference,'roomId',v_room_id,'guardianParticipationId',guardian.id,'permissionKey','conference.accommodation.manage','peoplePermissionKey','conference.people.manage','authoritySource',ctx->>'authoritySource','grantId',ctx->'grantId'),p_operation_id,'rpc');
 return result;
end $$;


--
-- Name: apply_library_template_content_operation("uuid", "uuid", "text", "text", "text", bigint, "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."apply_library_template_content_operation"("p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_template_type" "text", "p_template_id" "text", "p_action" "text", "p_base_revision" bigint, "p_payload" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare actor_id uuid:=auth.uid(); current_row public.library_templates%rowtype;
  prior public.library_template_operations%rowtype;
  normalized_id text:=btrim(coalesce(p_template_id,'')); intent text;
  result jsonb; result_status text; next_revision bigint;
begin
  if actor_id is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  perform public.require_current_approved_device(p_actor_device_id);
  if p_operation_id is null or p_template_type not in ('house','conference')
    or p_action not in ('upsert','delete') or length(normalized_id) not between 1 and 160
    or p_base_revision is null or p_base_revision<0
    or (p_action='upsert' and (p_payload is null or jsonb_typeof(p_payload)<>'object'))
    or (p_action='delete' and p_payload is not null)
  then raise exception 'INVALID_TEMPLATE_OPERATION' using errcode='22023'; end if;
  intent:=encode(digest(actor_id::text||'|'||p_template_type||'|'||normalized_id||'|'||
    p_action||'|'||p_base_revision::text||'|'||coalesce(p_payload::text,'null'),'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('library-template-operation:'||p_operation_id::text,0));
  select * into prior from public.library_template_operations where operation_id=p_operation_id;
  if found then
    if prior.actor_user_id<>actor_id or prior.intent_hash<>intent then
      raise exception 'TEMPLATE_OPERATION_INTENT_MISMATCH' using errcode='22023';
    end if;
    return prior.stored_result;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('library-template:'||p_template_type||':'||normalized_id,0));
  select * into current_row from public.library_templates
    where template_type=p_template_type and template_id=normalized_id for update;
  if not found then
    if p_base_revision<>0 or p_action<>'upsert' then
      return jsonb_build_object('status','conflict','templateType',p_template_type,
        'templateId',normalized_id,'currentRevision',0);
    end if;
    insert into public.library_templates(
      template_type,template_id,payload,owner_user_id,created_by,updated_by
    ) values(p_template_type,normalized_id,p_payload,actor_id,actor_id,actor_id);
    result_status:='created'; next_revision:=1;
  else
    if current_row.owner_user_id<>actor_id and not public.is_system_owner(actor_id) then
      raise exception 'TEMPLATE_OWNER_REQUIRED' using errcode='42501';
    end if;
    if current_row.revision<>p_base_revision then
      return jsonb_build_object('status','conflict','templateType',p_template_type,
        'templateId',normalized_id,'currentRevision',current_row.revision);
    end if;
    if p_action='delete' and current_row.deleted_at is not null then
      result_status:='unchanged'; next_revision:=current_row.revision;
    elsif p_action='upsert' and current_row.deleted_at is null and current_row.payload=p_payload then
      result_status:='unchanged'; next_revision:=current_row.revision;
    else
      next_revision:=current_row.revision+1;
      update public.library_templates set
        payload=case when p_action='upsert' then p_payload else payload end,
        deleted_at=case when p_action='delete' then now() else null end,
        revision=next_revision,updated_by=actor_id,updated_at=now()
      where template_type=p_template_type and template_id=normalized_id;
      result_status:=case when p_action='delete' then 'deleted' else 'updated' end;
    end if;
  end if;
  result:=jsonb_build_object('status',result_status,'templateType',p_template_type,
    'templateId',normalized_id,'operationId',p_operation_id,'revision',next_revision);
  insert into public.library_template_operations values(
    p_operation_id,actor_id,p_actor_device_id,p_template_type,normalized_id,p_action,
    p_base_revision,intent,result_status,next_revision,result,now());
  if result_status<>'unchanged' then
    insert into public.library_template_audit_log(
      template_type,template_id,actor_user_id,actor_device_id,operation_id,action,
      previous_revision,resulting_revision
    ) values(p_template_type,normalized_id,actor_id,p_actor_device_id,p_operation_id,
      p_action,p_base_revision,next_revision);
  end if;
  return result;
end
$$;


--
-- Name: assign_conference_accommodation("uuid", "uuid", "uuid", "uuid", integer, integer, "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."assign_conference_accommodation"("p_device" "uuid", "p_conference" "uuid", "p_room" "uuid", "p_participation" "uuid", "p_arrival" integer, "p_leave" integer, "p_bed" "text", "p_extra_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare context jsonb;actor uuid;device_authorization uuid;participation public.conference_participations%rowtype;
 room public.conference_accommodation_rooms%rowtype;days integer;row public.conference_accommodation_occupancies%rowtype;result jsonb;
begin
 context:=platform_private.require_conference_accommodation_context(p_device,p_conference,'conference.accommodation.manage',true);
 actor:=(context->>'actorUserId')::uuid;device_authorization:=platform_private.validated_phase1c_device_authorization(actor,p_device);
 days:=platform_private.conference_accommodation_duration(p_conference);
 if p_arrival<1 or p_arrival>days or (p_leave is not null and (p_leave<=p_arrival or p_leave>days+1)) then raise exception 'ACCOMMODATION_STAY_INVALID' using errcode='22023';end if;
 select * into participation from public.conference_participations where id=p_participation and conference_id=p_conference for update;
 if not found or participation.status<>'active' then raise exception 'ACTIVE_CONFERENCE_PARTICIPATION_REQUIRED' using errcode='42501';end if;
 select * into room from public.conference_accommodation_rooms where id=p_room and platform_private.conference_room_is_assigned(p_conference,id) for update;
 if not found then raise exception 'ACCOMMODATION_ROOM_NOT_FOUND' using errcode='P0002';end if;
 if room.is_closed and (room.closed_day is null or p_arrival>=room.closed_day or coalesce(p_leave,days+1)>room.closed_day) then raise exception 'ACCOMMODATION_ROOM_UNAVAILABLE' using errcode='55000';end if;
 if not (p_bed='extra' and p_extra_type='child' and participation.guardian_participation_id is not null) and not platform_private.conference_room_has_capacity(p_conference,p_room,p_bed,p_arrival,p_leave,null) then raise exception 'ACCOMMODATION_ROOM_CAPACITY_EXCEEDED' using errcode='55000';end if;
 insert into public.conference_accommodation_occupancies(conference_id,room_id,participation_id,arrival_day,leave_day,bed_type,extra_bed_person_type,created_by,updated_by)
 values(p_conference,p_room,p_participation,p_arrival,p_leave,p_bed,p_extra_type,actor,actor) returning * into row;
 result:=jsonb_build_object('occupancyId',row.id,'revision',row.revision,'roomId',row.room_id,'participationId',row.participation_id,'arrivalDay',row.arrival_day,'leaveDay',row.leave_day);
 insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,new_values,metadata,source)
 values(actor,device_authorization,'platform','conference','conference.accommodation.assigned','accommodation_occupancy',row.id,'platform',to_jsonb(row),jsonb_build_object('conferenceId',p_conference,'participationId',p_participation,'permissionKey','conference.accommodation.manage','authoritySource',context->>'authoritySource','grantId',context->'grantId'),'rpc');
 return result;
exception when exclusion_violation then raise exception 'ACCOMMODATION_STAY_OVERLAP' using errcode='23P01';
end $$;


--
-- Name: assign_conference_house("uuid", "uuid", "uuid", "uuid", boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."assign_conference_house"("p_device" "uuid", "p_operation_id" "uuid", "p_conference" "uuid", "p_house" "uuid", "p_assign" boolean, "p_expected" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare context jsonb;actor uuid;auth_id uuid;row public.conference_house_assignments%rowtype;result jsonb;prior jsonb;
begin
 context:=platform_private.require_conference_accommodation_context(p_device,p_conference,'conference.accommodation.manage',true);actor:=(context->>'actorUserId')::uuid;auth_id:=platform_private.validated_phase1c_device_authorization(actor,p_device);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('conference-house:'||p_conference::text||':'||p_house::text,0));
 select new_values into prior from platform.audit_events where actor_user_id=actor and operation_id=p_operation_id and action in('conference.house.assigned','conference.house.unassigned') limit 1;
 if prior is not null then return prior||jsonb_build_object('status','duplicate');end if;
 if p_assign then
  if not exists(select 1 from public.conference_accommodation_houses where id=p_house and is_active) then raise exception 'HOUSE_NOT_AVAILABLE' using errcode='P0002';end if;
  insert into public.conference_house_assignments(conference_id,house_id,created_by,updated_by) values(p_conference,p_house,actor,actor) on conflict(conference_id,house_id) do nothing returning * into row;
  if row.id is null then select * into row from public.conference_house_assignments where conference_id=p_conference and house_id=p_house;return jsonb_build_object('status','duplicate','assignmentId',row.id,'conferenceId',p_conference,'houseId',p_house,'revision',row.revision,'assigned',true);end if;
 else
  select * into row from public.conference_house_assignments where conference_id=p_conference and house_id=p_house for update;
  if not found then return jsonb_build_object('status','duplicate','houseId',p_house);end if;
  if p_expected is distinct from row.revision then raise exception 'HOUSE_ASSIGNMENT_REVISION_CONFLICT' using errcode='40001';end if;
  if exists(select 1 from public.conference_room_assignments where conference_id=p_conference and house_id=p_house) then raise exception 'HOUSE_ASSIGNMENT_HAS_ROOMS' using errcode='55000';end if;
  delete from public.conference_house_assignments where id=row.id;
 end if;
 result:=jsonb_build_object('status','success','assignmentId',row.id,'conferenceId',p_conference,'houseId',p_house,'revision',row.revision,'assigned',p_assign);
 insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,scope_id,new_values,metadata,operation_id,source) values(actor,auth_id,'platform','conference',case when p_assign then 'conference.house.assigned' else 'conference.house.unassigned' end,'conference_house_assignment',row.id,'conference',p_conference,result,jsonb_build_object('permissionKey','conference.accommodation.manage'),p_operation_id,'rpc');
 return result;
end $$;


--
-- Name: assign_conference_room("uuid", "uuid", "uuid", "uuid", boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."assign_conference_room"("p_device" "uuid", "p_operation_id" "uuid", "p_conference" "uuid", "p_room" "uuid", "p_assign" boolean, "p_expected" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare context jsonb;actor uuid;auth_id uuid;conf public.conferences%rowtype;house uuid;house_assignment public.conference_house_assignments%rowtype;row public.conference_room_assignments%rowtype;prior jsonb;result jsonb;
begin
 context:=platform_private.require_conference_accommodation_context(p_device,p_conference,'conference.accommodation.manage',true);actor:=(context->>'actorUserId')::uuid;auth_id:=platform_private.validated_phase1c_device_authorization(actor,p_device);
 select new_values into prior from platform.audit_events where actor_user_id=actor and operation_id=p_operation_id and action in('conference.room.assigned','conference.room.unassigned') limit 1;
 if prior is not null then return prior||jsonb_build_object('status','duplicate');end if;
 select c.* into conf from public.conferences c where c.id=p_conference and c.deleted_at is null for key share;if not found then raise exception 'CONFERENCE_CORE_NOT_FOUND' using errcode='P0002';end if;
 select f.house_id into house from public.conference_accommodation_rooms r join public.conference_accommodation_floors f on f.id=r.floor_id where r.id=p_room;if house is null then raise exception 'ROOM_NOT_FOUND' using errcode='P0002';end if;
 perform platform_private.assert_conference_room_period_available(p_conference,p_room,conf.start_date,conf.end_date);
 if p_assign then
  select * into house_assignment from public.conference_house_assignments where conference_id=p_conference and house_id=house for update;
  if not found then raise exception 'HOUSE_ASSIGNMENT_REQUIRED' using errcode='55000';end if;
  insert into public.conference_room_assignments(conference_id,house_assignment_id,house_id,room_id,created_by,updated_by) values(p_conference,house_assignment.id,house,p_room,actor,actor) on conflict(conference_id,room_id) do nothing returning * into row;
  if row.id is null then select * into row from public.conference_room_assignments where conference_id=p_conference and room_id=p_room;return jsonb_build_object('status','duplicate','roomAssignmentId',row.id,'roomId',p_room,'assigned',true,'revision',row.revision);end if;
 else
  select * into row from public.conference_room_assignments where conference_id=p_conference and room_id=p_room for update;
  if not found then return jsonb_build_object('status','duplicate','roomId',p_room,'assigned',false);end if;
  if p_expected is distinct from row.revision then raise exception 'ROOM_ASSIGNMENT_REVISION_CONFLICT' using errcode='40001';end if;
  if exists(select 1 from public.conference_accommodation_occupancies where conference_id=p_conference and room_id=p_room) then raise exception 'ROOM_ASSIGNMENT_HAS_OCCUPANCIES' using errcode='55000';end if;
  delete from public.conference_room_assignments where id=row.id;
 end if;
 result:=jsonb_build_object('status','success','roomAssignmentId',row.id,'conferenceId',p_conference,'houseId',house,'roomId',p_room,'revision',row.revision,'assigned',p_assign);
 insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,scope_id,new_values,metadata,operation_id,source) values(actor,auth_id,'platform','conference',case when p_assign then 'conference.room.assigned' else 'conference.room.unassigned' end,'conference_room_assignment',row.id,'conference',p_conference,result,jsonb_build_object('permissionKey','conference.accommodation.manage','roomId',p_room),p_operation_id,'rpc');
 return result;
end $$;


--
-- Name: begin_stable_development_platform_device_recovery("uuid", "uuid", "uuid", "uuid", "bytea", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."begin_stable_development_platform_device_recovery"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_credential_id" "uuid", "p_session_id" "uuid", "p_challenge_hash" "bytea", "p_environment" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare recovery platform_private.stable_device_recovery_authorizations%rowtype;
  credential public.device_security_credentials%rowtype; challenge_id uuid;
begin
  perform public.require_platform_device_backend();
  if p_actor_user_id is null or p_actor_device_id is null or p_session_id is null
    or pg_catalog.octet_length(p_challenge_hash)<>32
    or p_environment<>'development_preview' then
    raise exception 'STABLE_DEVICE_RECOVERY_ARGUMENT_INVALID' using errcode='22023';
  end if;
  select * into recovery
  from platform_private.stable_device_recovery_authorizations item
  where item.owner_user_id=p_actor_user_id and item.target_device_id=p_actor_device_id
    and item.credential_id=p_credential_id
    and item.issuance_basis='reviewed_platform_owner_passkey_recovery'
    and item.review_reference is not null and item.environment=p_environment
    and item.expected_origin='https://ramyawny37.github.io'
    and item.expected_rp_id='ramyawny37.github.io'
    and item.consumed_at is null
    and pg_catalog.statement_timestamp() between item.issued_at and item.expires_at
  for update;
  if not found then
    raise exception 'STABLE_DEVICE_RECOVERY_AUTHORIZATION_INVALID' using errcode='42501';
  end if;
  credential:=platform_private.require_platform_owner_recovery_credential(
    recovery.owner_user_id,recovery.credential_id);
  if not exists(select 1 from platform.user_device_authorizations target_authorization
      join platform.devices device on device.id=target_authorization.device_id
      where target_authorization.id=recovery.target_authorization_id
        and target_authorization.user_id=recovery.owner_user_id
        and target_authorization.device_id=recovery.target_device_id
        and target_authorization.status='pending' and target_authorization.revoked_at is null
        and device.lifecycle_status='active' and device.retired_at is null
        and device.compromised_at is null) then
    raise exception 'STABLE_DEVICE_RECOVERY_TARGET_INVALID' using errcode='42501';
  end if;
  update platform_private.stable_device_recovery_challenges challenge
  set failed_at=pg_catalog.statement_timestamp(),failure_code='expired_replaced'
  where challenge.recovery_authorization_id=recovery.id
    and challenge.verified_at is null and challenge.consumed_at is null
    and challenge.failed_at is null
    and challenge.expires_at<=pg_catalog.statement_timestamp();
  if exists(select 1 from platform_private.stable_device_recovery_challenges challenge
      where challenge.recovery_authorization_id=recovery.id
        and challenge.verified_at is null and challenge.consumed_at is null
        and challenge.failed_at is null
        and challenge.expires_at>pg_catalog.statement_timestamp()) then
    raise exception 'STABLE_DEVICE_RECOVERY_CHALLENGE_ACTIVE' using errcode='55000';
  end if;
  insert into platform_private.stable_device_recovery_challenges(
    recovery_authorization_id,session_id,challenge_hash,credential_id,expires_at)
  values(recovery.id,p_session_id,p_challenge_hash,credential.id,
    pg_catalog.statement_timestamp()+interval '2 minutes') returning id into challenge_id;
  return pg_catalog.jsonb_build_object('status','challenge_created','challengeId',challenge_id,
    'recoveryAuthorizationId',recovery.id,'operationId',recovery.operation_id,
    'credentialId',credential.id,
    'credentialExternalId',pg_catalog.encode(credential.webauthn_credential_id,'base64'),
    'publicKeyCose',pg_catalog.translate(pg_catalog.encode(credential.public_key_cose,'base64'),E'\n\r',''),
    'signCount',credential.sign_count,'transports',credential.transports);
end; $$;


--
-- Name: begin_system_owner_credential_enrollment("uuid", "uuid", "uuid", "text", "text", "text", "bytea", "uuid", "bytea"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."begin_system_owner_credential_enrollment"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_session_id" "uuid", "p_environment" "text", "p_expected_origin" "text", "p_expected_rp_id" "text", "p_challenge_hash" "bytea", "p_operation_id" "uuid", "p_bootstrap_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare bootstrap_authorization public.system_owner_credential_bootstrap_authorizations%rowtype;
  challenge_id uuid;
begin
  perform public.require_platform_device_backend();
  if p_session_id is null or p_operation_id is null
    or pg_catalog.octet_length(p_challenge_hash)<>32
    or pg_catalog.octet_length(p_bootstrap_hash)<>32 then
    raise exception 'CREDENTIAL_ENROLLMENT_ARGUMENT_INVALID' using errcode='22023';
  end if;
  if not platform_private.is_canonical_platform_owner(p_actor_user_id) then
    raise exception 'APPROVED_SYSTEM_OWNER_DEVICE_REQUIRED' using errcode='42501';
  end if;
  perform platform_private.require_canonical_device_authorization(
    p_actor_user_id,p_actor_device_id,true);
  select * into bootstrap_authorization
  from public.system_owner_credential_bootstrap_authorizations bootstrap
  where bootstrap.authorization_hash=p_bootstrap_hash
    and bootstrap.intended_user_id=p_actor_user_id
    and bootstrap.intended_device_id=p_actor_device_id
    and bootstrap.environment=p_environment and bootstrap.consumed_at is null
    and pg_catalog.statement_timestamp() between bootstrap.issued_at and bootstrap.expires_at
  for update;
  if not found then
    raise exception 'CREDENTIAL_BOOTSTRAP_AUTHORIZATION_INVALID' using errcode='42501';
  end if;
  insert into public.device_possession_challenges(challenge_hash,user_id,session_id,
    actor_device_id,credential_id,purpose,operation_id,expected_origin,expected_rp_id,
    environment,expires_at)
  values(p_challenge_hash,p_actor_user_id,p_session_id,p_actor_device_id,null,
    'SYSTEM_OWNER_CREDENTIAL_ENROLLMENT',p_operation_id,pg_catalog.lower(p_expected_origin),
    pg_catalog.lower(p_expected_rp_id),p_environment,pg_catalog.now()+interval '2 minutes')
  returning id into challenge_id;
  return pg_catalog.jsonb_build_object('status','challenge_created','challengeId',challenge_id,
    'bootstrapAuthorizationId',bootstrap_authorization.id,'operationId',p_operation_id);
end; $$;


--
-- Name: begin_system_owner_device_possession_challenge("uuid", "uuid", "uuid", "uuid", "text", "uuid", "uuid", "uuid", "text", "text", "text", "bytea"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."begin_system_owner_device_possession_challenge"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_credential_id" "uuid", "p_session_id" "uuid", "p_purpose" "text", "p_target_user_id" "uuid", "p_target_device_id" "uuid", "p_operation_id" "uuid", "p_environment" "text", "p_expected_origin" "text", "p_expected_rp_id" "text", "p_challenge_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare credential public.device_security_credentials%rowtype;
  challenge_id uuid; existing public.system_owner_device_authorization_operations%rowtype;
  challenge_created_at timestamptz:=pg_catalog.statement_timestamp();
begin
  credential:=public.require_system_owner_webauthn_actor(
    p_actor_user_id,p_actor_device_id,p_credential_id);
  if p_session_id is null or pg_catalog.octet_length(p_challenge_hash)<>32
    or p_purpose not in ('SYSTEM_OWNER_PENDING_DEVICE_LIST',
      'SYSTEM_OWNER_PENDING_DEVICE_APPROVE','SYSTEM_OWNER_PENDING_DEVICE_REJECT',
      'SYSTEM_OWNER_DEVICE_REVOKE') then
    raise exception 'PLATFORM_DEVICE_CHALLENGE_ARGUMENT_INVALID' using errcode='22023';
  end if;
  if p_purpose='SYSTEM_OWNER_PENDING_DEVICE_LIST' then
    if p_target_user_id is not null or p_target_device_id is not null
      or p_operation_id is not null then
      raise exception 'PLATFORM_DEVICE_LIST_CHALLENGE_BINDING_INVALID' using errcode='22023';
    end if;
  else
    if p_target_user_id is null or p_target_device_id is null or p_operation_id is null then
      raise exception 'PLATFORM_DEVICE_MUTATION_CHALLENGE_BINDING_INVALID' using errcode='22023';
    end if;
    if p_purpose='SYSTEM_OWNER_DEVICE_REVOKE' and p_target_user_id=p_actor_user_id
      and p_target_device_id=p_actor_device_id then
      raise exception 'ACTOR_DEVICE_REVOCATION_FORBIDDEN' using errcode='42501';
    end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'system-owner-device-operation:'||p_operation_id::text,0));
    select * into existing from public.system_owner_device_authorization_operations operation
    where operation.operation_id=p_operation_id;
    if found then
      if existing.actor_user_id_snapshot=p_actor_user_id
        and existing.actor_device_id=p_actor_device_id
        and existing.target_user_id_snapshot=p_target_user_id
        and existing.target_device_id=p_target_device_id
        and existing.environment=p_environment
        and existing.action=(case p_purpose
          when 'SYSTEM_OWNER_PENDING_DEVICE_APPROVE' then 'approve_system_owner_pending_device'
          when 'SYSTEM_OWNER_PENDING_DEVICE_REJECT' then 'reject_system_owner_pending_device'
          when 'SYSTEM_OWNER_DEVICE_REVOKE' then 'revoke_system_owner_device' end) then
        return pg_catalog.jsonb_build_object('status','completed','result',existing.stored_result);
      end if;
      raise exception 'PLATFORM_DEVICE_OPERATION_MISMATCH' using errcode='22023';
    end if;
    if not exists(select 1 from platform.user_device_authorizations device_authorization
      join platform.devices device on device.id=device_authorization.device_id
      join platform.profiles profile on profile.user_id=device_authorization.user_id
      where device_authorization.user_id=p_target_user_id
        and device_authorization.device_id=p_target_device_id
        and device_authorization.status=(case when p_purpose='SYSTEM_OWNER_DEVICE_REVOKE'
          then 'approved' else 'pending' end)
        and device_authorization.revoked_at is null
        and device.lifecycle_status='active' and device.retired_at is null
        and device.compromised_at is null and profile.account_status='approved'
        and (p_purpose='SYSTEM_OWNER_DEVICE_REVOKE' or exists(
          select 1 from platform.device_key_bindings binding
          where binding.user_id=device_authorization.user_id
            and binding.device_id=device_authorization.device_id
            and binding.device_authorization_id=device_authorization.id
            and binding.lifecycle_status='active' and binding.revoked_at is null
            and binding.retired_at is null))) then
      if p_purpose='SYSTEM_OWNER_DEVICE_REVOKE' then
        raise exception 'APPROVED_UNREVOKED_DEVICE_REQUIRED' using errcode='42501';
      end if;
      raise exception 'PENDING_APPROVED_ACCOUNT_DEVICE_REQUIRED' using errcode='42501';
    end if;
    if p_purpose='SYSTEM_OWNER_DEVICE_REVOKE'
      and platform_private.is_canonical_platform_owner(p_target_user_id)
      and (select pg_catalog.count(*) from platform.user_device_authorizations approved
        join platform.devices device on device.id=approved.device_id
        where approved.user_id=p_target_user_id and approved.status='approved'
          and approved.revoked_at is null and device.lifecycle_status='active'
          and device.retired_at is null and device.compromised_at is null)<=1 then
      raise exception 'OWNER_LAST_APPROVED_DEVICE_REVOCATION_FORBIDDEN' using errcode='42501';
    end if;
  end if;
  insert into public.device_possession_challenges(challenge_hash,user_id,session_id,
    actor_device_id,credential_id,purpose,target_user_id,target_device_id,operation_id,
    expected_origin,expected_rp_id,environment,created_at,expires_at)
  values(p_challenge_hash,p_actor_user_id,p_session_id,p_actor_device_id,p_credential_id,
    p_purpose,p_target_user_id,p_target_device_id,p_operation_id,
    pg_catalog.lower(p_expected_origin),pg_catalog.lower(p_expected_rp_id),p_environment,
    challenge_created_at,challenge_created_at+interval '2 minutes') returning id into challenge_id;
  return pg_catalog.jsonb_build_object('status','challenge_created','challengeId',challenge_id,
    'credentialId',credential.id,
    'credentialExternalId',pg_catalog.encode(credential.webauthn_credential_id,'base64'),
    'publicKeyCose',pg_catalog.encode(credential.public_key_cose,'base64'),
    'signCount',credential.sign_count,'transports',credential.transports,
    'operationId',p_operation_id);
end; $$;


--
-- Name: complete_first_system_bootstrap("text", "uuid", "text", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."complete_first_system_bootstrap"("p_setup_token" "text", "p_device_id" "uuid", "p_device_name" "text", "p_device_platform" "text", "p_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid:=auth.uid(); state_row public.system_bootstrap_state%rowtype; secret_row public.system_bootstrap_secret%rowtype; intent text; result jsonb; role_id uuid; display_name text;
begin
 if actor_id is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_operation_id is null then raise exception 'INVALID_BOOTSTRAP_REQUEST' using errcode='22023'; end if;
 intent:=pg_catalog.encode(extensions.digest(actor_id::text,'sha256'),'hex');
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('first-system-bootstrap',0));
 select * into state_row from public.system_bootstrap_state where singleton_id=1 for update;
 if state_row.completed_at is not null then
  if state_row.completed_by=actor_id and state_row.operation_id=p_operation_id and state_row.intent_hash=intent then return state_row.stored_result; end if;
  raise exception 'BOOTSTRAP_ALREADY_COMPLETED' using errcode='42501';
 end if;
 if exists(select 1 from platform.user_roles a join platform.roles r on r.id=a.role_id where r.domain='platform' and r.code='platform_owner' and a.revoked_at is null) then raise exception 'SYSTEM_OWNER_ALREADY_EXISTS' using errcode='42501'; end if;
 select * into secret_row from public.system_bootstrap_secret where singleton_id=1 for update;
 if not found or secret_row.intended_user_id<>actor_id then raise exception 'BOOTSTRAP_IDENTITY_INVALID' using errcode='42501'; end if;
 if extensions.crypt(coalesce(p_setup_token,''),secret_row.secret_hash)<>secret_row.secret_hash then raise exception 'BOOTSTRAP_CREDENTIAL_INVALID' using errcode='42501'; end if;
 select nullif(pg_catalog.btrim(coalesce(raw_user_meta_data->>'display_name',raw_user_meta_data->>'name','')),'') into display_name from auth.users where id=actor_id;
 if not found then raise exception 'AUTH_USER_NOT_FOUND' using errcode='P0002'; end if;
 insert into platform.profiles(user_id,display_name,account_status,status_changed_at,status_changed_by,approved_at,approved_by)
 values(actor_id,display_name,'approved',pg_catalog.now(),actor_id,pg_catalog.now(),actor_id)
 on conflict(user_id) do update set display_name=coalesce(platform.profiles.display_name,excluded.display_name),account_status='approved',status_reason='first platform owner bootstrap',status_changed_at=pg_catalog.now(),status_changed_by=actor_id,approved_at=pg_catalog.now(),approved_by=actor_id,blocked_at=null,blocked_by=null;
 select id into role_id from platform.roles where domain='platform' and code='platform_owner';
 if role_id is null then raise exception 'REFERENCE_DATA_NOT_SEEDED' using errcode='55000'; end if;
 insert into platform.user_roles(user_id,role_id,scope_type,scope_id,granted_by,metadata)
 values(actor_id,role_id,'platform',null,actor_id,pg_catalog.jsonb_build_object('bootstrap',true))
 on conflict do nothing;
 result:=pg_catalog.jsonb_build_object('status','completed','operationId',p_operation_id);
 update public.system_bootstrap_state set completed_at=pg_catalog.now(),completed_by=actor_id,device_id=null,operation_id=p_operation_id,intent_hash=intent,stored_result=result where singleton_id=1;
 delete from public.system_bootstrap_secret where singleton_id=1;
 perform platform_private.write_audit_event(actor_id,actor_id,'platform','bootstrap','platform.bootstrap_completed','profile',actor_id,'platform',null,pg_catalog.jsonb_build_object('accountStatus','approved','role','platform_owner'),pg_catalog.jsonb_build_object('bootstrap',true,'deviceEnrollment','p256_followup'),null,null,'bootstrap');
 return result;
end $$;


--
-- Name: complete_stable_development_platform_device_recovery("uuid", "uuid", "uuid", "uuid", "uuid", "bytea", "uuid", "uuid", "text", bigint, "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."complete_stable_development_platform_device_recovery"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_credential_id" "uuid", "p_session_id" "uuid", "p_challenge_id" "uuid", "p_challenge_hash" "bytea", "p_recovery_authorization_id" "uuid", "p_operation_id" "uuid", "p_environment" "text", "p_new_sign_count" bigint, "p_origin" "text", "p_rp_id" "text", "p_verification_context" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare recovery platform_private.stable_device_recovery_authorizations%rowtype;
  challenge platform_private.stable_device_recovery_challenges%rowtype;
  credential public.device_security_credentials%rowtype;
  target platform.user_device_authorizations%rowtype;
begin
  perform public.require_platform_device_backend();
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'stable-device-recovery:'||p_recovery_authorization_id::text,0));
  select * into recovery from platform_private.stable_device_recovery_authorizations item
  where item.id=p_recovery_authorization_id and item.operation_id=p_operation_id
    and item.owner_user_id=p_actor_user_id and item.target_device_id=p_actor_device_id
    and item.credential_id=p_credential_id
    and item.issuance_basis='reviewed_platform_owner_passkey_recovery'
    and item.review_reference is not null and item.environment='development_preview'
    and item.environment=p_environment and item.consumed_at is null
    and pg_catalog.statement_timestamp() between item.issued_at and item.expires_at for update;
  if not found then
    raise exception 'STABLE_DEVICE_RECOVERY_AUTHORIZATION_INVALID' using errcode='42501';
  end if;
  credential:=platform_private.require_platform_owner_recovery_credential(
    recovery.owner_user_id,recovery.credential_id);
  select * into challenge from platform_private.stable_device_recovery_challenges item
  where item.id=p_challenge_id and item.recovery_authorization_id=recovery.id
    and item.session_id=p_session_id and item.credential_id=p_credential_id
    and item.challenge_hash=p_challenge_hash for update;
  if not found or challenge.verified_at is not null or challenge.consumed_at is not null
    or challenge.failed_at is not null or challenge.expires_at<=pg_catalog.statement_timestamp()
    or pg_catalog.lower(p_origin)<>recovery.expected_origin
    or pg_catalog.lower(p_rp_id)<>recovery.expected_rp_id
    or p_new_sign_count<credential.sign_count
    or p_verification_context->'userVerified' is distinct from 'true'::jsonb
    or (p_verification_context->>'backupEligible')::boolean is distinct from credential.backup_eligible
    or (p_verification_context->>'backupState')::boolean is distinct from credential.backup_state
    or ((p_verification_context->>'backupState')::boolean
      and not (p_verification_context->>'backupEligible')::boolean) then
    raise exception 'STABLE_DEVICE_RECOVERY_VERIFICATION_INVALID' using errcode='42501';
  end if;
  select * into target from platform.user_device_authorizations item
  where item.id=recovery.target_authorization_id and item.user_id=recovery.owner_user_id
    and item.device_id=recovery.target_device_id and item.status='pending'
    and item.revoked_at is null for update;
  if not found or not exists(select 1 from platform.devices device
      where device.id=recovery.target_device_id and device.lifecycle_status='active'
        and device.retired_at is null and device.compromised_at is null) then
    raise exception 'STABLE_DEVICE_RECOVERY_TARGET_INVALID' using errcode='42501';
  end if;
  update platform_private.stable_device_recovery_challenges
  set verified_at=pg_catalog.statement_timestamp(),verification_context=p_verification_context
  where id=challenge.id;
  update public.device_security_credentials
  set sign_count=p_new_sign_count,last_used_at=pg_catalog.statement_timestamp()
  where id=credential.id;
  update platform.user_device_authorizations
  set status='approved',approved_by=recovery.owner_user_id,
    approved_at=pg_catalog.statement_timestamp(),
    status_reason='Reviewed Development platform-owner passkey recovery'
  where id=recovery.target_authorization_id;
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,
    subject_user_id,domain,module,action,entity_type,entity_id,scope_type,
    old_values,new_values,metadata,operation_id,source)
  values(recovery.owner_user_id,null,recovery.owner_user_id,'platform','devices',
    'device_authorization.approved','user_device_authorization',
    recovery.target_authorization_id,'platform',
    pg_catalog.jsonb_build_object('status','pending'),
    pg_catalog.jsonb_build_object('status','approved'),
    pg_catalog.jsonb_build_object('recoveryAuthorizationId',recovery.id,
      'webauthnVerified',true,'issuanceBasis',recovery.issuance_basis,
      'reviewReference',recovery.review_reference),recovery.operation_id,'system');
  insert into platform_private.stable_device_recovery_audit(
    recovery_authorization_id,challenge_id,operation_id,actor_user_id,
    source_authorization_id,source_device_id,target_authorization_id,target_device_id,
    credential_id,environment,action,result,origin,rp_id,user_verified,
    backup_eligible,backup_state,evidence)
  values(recovery.id,challenge.id,recovery.operation_id,recovery.owner_user_id,null,null,
    recovery.target_authorization_id,recovery.target_device_id,recovery.credential_id,
    recovery.environment,'stable_device_approved','applied',recovery.expected_origin,
    recovery.expected_rp_id,true,credential.backup_eligible,credential.backup_state,
    pg_catalog.jsonb_build_object('challengeConsumed',true,'authorizationConsumed',true,
      'issuanceBasis',recovery.issuance_basis,'reviewReference',recovery.review_reference));
  update platform_private.stable_device_recovery_challenges
  set consumed_at=pg_catalog.statement_timestamp() where id=challenge.id;
  update platform_private.stable_device_recovery_authorizations
  set consumed_at=pg_catalog.statement_timestamp() where id=recovery.id;
  return pg_catalog.jsonb_build_object('status','applied',
    'authorizationStatus','approved','operationId',recovery.operation_id,
    'targetDeviceId',recovery.target_device_id);
end; $$;


--
-- Name: complete_system_owner_credential_enrollment("uuid", "uuid", "uuid", "text", "uuid", "bytea", "uuid", "uuid", "bytea", "bytea", integer, "uuid", "text"[], bigint, "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."complete_system_owner_credential_enrollment"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_session_id" "uuid", "p_environment" "text", "p_challenge_id" "uuid", "p_challenge_hash" "bytea", "p_operation_id" "uuid", "p_bootstrap_authorization_id" "uuid", "p_credential_id" "bytea", "p_public_key_cose" "bytea", "p_public_key_algorithm" integer, "p_aaguid" "uuid", "p_transports" "text"[], "p_sign_count" bigint, "p_origin" "text", "p_rp_id" "text", "p_verification_context" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare challenge public.device_possession_challenges%rowtype; credential_id uuid;
  audit_id uuid;
begin
  perform public.require_platform_device_backend();
  perform pg_advisory_xact_lock(hashtextextended('credential-enrollment:'||p_operation_id::text,0));
  select * into challenge from public.device_possession_challenges challenges
    where challenges.id=p_challenge_id and challenges.user_id=p_actor_user_id
      and challenges.session_id=p_session_id and challenges.actor_device_id=p_actor_device_id
      and challenges.credential_id is null
      and challenges.purpose='SYSTEM_OWNER_CREDENTIAL_ENROLLMENT'
      and challenges.operation_id=p_operation_id and challenges.environment=p_environment
      and challenges.challenge_hash=p_challenge_hash
    for update;
  if not found or challenge.verified_at is not null or challenge.consumed_at is not null
    or challenge.failed_at is not null or challenge.expires_at<=statement_timestamp()
    or challenge.expected_origin<>lower(p_origin) or challenge.expected_rp_id<>lower(p_rp_id)
    or coalesce((p_verification_context->>'userVerified')::boolean,false)<>true
    or jsonb_typeof(p_verification_context->'backupEligible') is distinct from 'boolean'
    or jsonb_typeof(p_verification_context->'backupState') is distinct from 'boolean' then
    raise exception 'CREDENTIAL_ENROLLMENT_VERIFICATION_INVALID' using errcode='42501';
  end if;
  if not exists(select 1 from public.system_owner_credential_bootstrap_authorizations bootstrap
    where bootstrap.id=p_bootstrap_authorization_id
      and bootstrap.intended_user_id=p_actor_user_id
      and bootstrap.intended_device_id=p_actor_device_id
      and bootstrap.environment=p_environment and bootstrap.consumed_at is null
      and statement_timestamp() between bootstrap.issued_at and bootstrap.expires_at) then
    raise exception 'CREDENTIAL_BOOTSTRAP_AUTHORIZATION_INVALID' using errcode='42501';
  end if;
  update public.device_possession_challenges set verified_at=statement_timestamp(),
    verification_context=p_verification_context where id=p_challenge_id;
  insert into public.device_possession_challenge_consumers(challenge_id,user_id,session_id,
    actor_device_id,actor_credential_id,challenge_purpose,environment,consumer_kind,consumer_id)
  values(p_challenge_id,p_actor_user_id,p_session_id,p_actor_device_id,null,
    'SYSTEM_OWNER_CREDENTIAL_ENROLLMENT',p_environment,'credential_enrollment',p_operation_id);
  insert into public.device_security_credentials(webauthn_credential_id,user_id,device_id,
    credential_kind,public_key_cose,public_key_algorithm,aaguid,transports,sign_count,
    backup_eligible,backup_state,user_verification_policy,lifecycle_status)
  values(p_credential_id,p_actor_user_id,p_actor_device_id,'platform_primary',p_public_key_cose,
    p_public_key_algorithm,p_aaguid,coalesce(p_transports,'{}'::text[]),p_sign_count,
    (p_verification_context->>'backupEligible')::boolean,
    (p_verification_context->>'backupState')::boolean,
    'required','enrollment_pending') returning id into credential_id;
  update public.device_security_credentials set lifecycle_status='active',enrolled_at=statement_timestamp(),
    activated_at=statement_timestamp(),last_used_at=statement_timestamp() where id=credential_id;
  insert into public.privileged_device_authorization_audit_log(actor_user_id,
    actor_user_id_snapshot,actor_device_id,actor_credential_id,session_id_hash,session_id,
    challenge_id,challenge_purpose,environment,target_user_id,target_user_id_snapshot,
    target_device_id,action,operation_id,result,origin,rp_id,user_verified,
    backup_eligible,backup_state,security_context)
  values(p_actor_user_id,p_actor_user_id,p_actor_device_id,null,
    extensions.digest(p_session_id::text,'sha256'),p_session_id,p_challenge_id,
    'SYSTEM_OWNER_CREDENTIAL_ENROLLMENT',p_environment,p_actor_user_id,p_actor_user_id,
    p_actor_device_id,'credential_enrolled',p_operation_id,'applied',lower(p_origin),lower(p_rp_id),
    true,(p_verification_context->>'backupEligible')::boolean,
    (p_verification_context->>'backupState')::boolean,p_verification_context) returning id into audit_id;
  update public.system_owner_credential_bootstrap_authorizations set consumed_at=consumed_at
    where id=p_bootstrap_authorization_id;
  update public.device_possession_challenges set consumed_at=statement_timestamp()
    where id=p_challenge_id;
  return jsonb_build_object('status','applied','credentialId',credential_id,'auditId',audit_id);
end;
$$;


--
-- Name: complete_system_owner_pending_device_listing("uuid", "uuid", "uuid", "uuid", "text", "uuid", "bytea", "uuid", "bytea", bigint, "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."complete_system_owner_pending_device_listing"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_credential_id" "uuid", "p_session_id" "uuid", "p_environment" "text", "p_challenge_id" "uuid", "p_challenge_hash" "bytea", "p_listing_id" "uuid", "p_listing_token_hash" "bytea", "p_new_sign_count" bigint, "p_origin" "text", "p_rp_id" "text", "p_verification_context" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare credential public.device_security_credentials%rowtype;
  challenge public.device_possession_challenges%rowtype;
begin
  credential:=public.require_system_owner_webauthn_actor(
    p_actor_user_id,p_actor_device_id,p_credential_id);
  select * into challenge from public.device_possession_challenges stored
  where stored.id=p_challenge_id and stored.user_id=p_actor_user_id
    and stored.session_id=p_session_id and stored.actor_device_id=p_actor_device_id
    and stored.credential_id=p_credential_id
    and stored.purpose='SYSTEM_OWNER_PENDING_DEVICE_LIST'
    and stored.environment=p_environment and stored.challenge_hash=p_challenge_hash
  for update;
  if not found or challenge.verified_at is not null or challenge.consumed_at is not null
    or challenge.failed_at is not null or challenge.expires_at<=pg_catalog.statement_timestamp()
    or challenge.expected_origin<>pg_catalog.lower(p_origin)
    or challenge.expected_rp_id<>pg_catalog.lower(p_rp_id)
    or p_new_sign_count<credential.sign_count or pg_catalog.octet_length(p_listing_token_hash)<>32
    or p_verification_context->'userVerified' is distinct from 'true'::jsonb
    or pg_catalog.jsonb_typeof(p_verification_context->'backupEligible') is distinct from 'boolean'
    or pg_catalog.jsonb_typeof(p_verification_context->'backupState') is distinct from 'boolean'
    or (p_verification_context->>'backupEligible')::boolean is distinct from credential.backup_eligible
    or (p_verification_context->>'backupState')::boolean is distinct from credential.backup_state then
    raise exception 'PLATFORM_DEVICE_LIST_VERIFICATION_INVALID' using errcode='42501';
  end if;
  update public.device_possession_challenges set verified_at=pg_catalog.statement_timestamp(),
    verification_context=p_verification_context where id=p_challenge_id;
  update public.device_security_credentials set sign_count=p_new_sign_count,
    last_used_at=pg_catalog.statement_timestamp() where id=p_credential_id;
  insert into public.device_possession_challenge_consumers(challenge_id,user_id,session_id,
    actor_device_id,actor_credential_id,challenge_purpose,environment,consumer_kind,consumer_id)
  values(p_challenge_id,p_actor_user_id,p_session_id,p_actor_device_id,p_credential_id,
    'SYSTEM_OWNER_PENDING_DEVICE_LIST',p_environment,'listing_session',p_listing_id);
  insert into public.privileged_device_listing_sessions(id,opaque_token_hash,user_id,session_id,
    actor_device_id,credential_id,source_challenge_id,source_challenge_purpose,environment,scope,issued_at,expires_at)
  values(p_listing_id,p_listing_token_hash,p_actor_user_id,p_session_id,p_actor_device_id,
    p_credential_id,p_challenge_id,challenge.purpose,p_environment,
    'SYSTEM_OWNER_PENDING_DEVICE_LIST_READ_ONLY',pg_catalog.statement_timestamp(),pg_catalog.statement_timestamp()+interval '5 minutes');
  insert into public.privileged_device_authorization_audit_log(actor_user_id,
    actor_user_id_snapshot,actor_device_id,actor_credential_id,session_id_hash,session_id,
    challenge_id,challenge_purpose,environment,action,result,origin,rp_id,user_verified,
    backup_eligible,backup_state,security_context)
  values(p_actor_user_id,p_actor_user_id,p_actor_device_id,p_credential_id,
    extensions.digest(p_session_id::text,'sha256'),p_session_id,p_challenge_id,
    'SYSTEM_OWNER_PENDING_DEVICE_LIST',p_environment,'pending_device_listed','verified',
    pg_catalog.lower(p_origin),pg_catalog.lower(p_rp_id),true,credential.backup_eligible,
    credential.backup_state,p_verification_context);
  update public.device_possession_challenges set consumed_at=pg_catalog.statement_timestamp()
  where id=p_challenge_id;
  return pg_catalog.jsonb_build_object('status','listed','listingId',p_listing_id,
    'expiresInSeconds',300);
end; $$;


--
-- Name: complete_system_owner_pending_device_operation("uuid", "uuid", "uuid", "uuid", "text", "uuid", "bytea", "uuid", "uuid", "uuid", "text", bigint, "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."complete_system_owner_pending_device_operation"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_credential_id" "uuid", "p_session_id" "uuid", "p_environment" "text", "p_challenge_id" "uuid", "p_challenge_hash" "bytea", "p_operation_id" "uuid", "p_target_user_id" "uuid", "p_target_device_id" "uuid", "p_action" "text", "p_new_sign_count" bigint, "p_origin" "text", "p_rp_id" "text", "p_verification_context" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare credential public.device_security_credentials%rowtype;
  challenge public.device_possession_challenges%rowtype;
  existing public.system_owner_device_authorization_operations%rowtype;
  target platform.user_device_authorizations%rowtype;
  result jsonb; v_purpose text; operation_action text; audit_action text;
  target_initial_status text; operation_at timestamptz:=pg_catalog.statement_timestamp();
begin
  perform public.require_platform_device_backend();
  if p_action not in ('approve','reject','revoke') then
    raise exception 'PLATFORM_DEVICE_ACTION_INVALID' using errcode='22023';
  end if;
  v_purpose:=case p_action when 'approve' then 'SYSTEM_OWNER_PENDING_DEVICE_APPROVE'
    when 'reject' then 'SYSTEM_OWNER_PENDING_DEVICE_REJECT'
    else 'SYSTEM_OWNER_DEVICE_REVOKE' end;
  operation_action:=case p_action when 'approve' then 'approve_system_owner_pending_device'
    when 'reject' then 'reject_system_owner_pending_device'
    else 'revoke_system_owner_device' end;
  audit_action:=case p_action when 'approve' then 'pending_device_approved'
    when 'reject' then 'pending_device_rejected' else 'device_revoked' end;
  target_initial_status:=case when p_action='revoke' then 'approved' else 'pending' end;
  if p_action='revoke' and p_target_user_id=p_actor_user_id
    and p_target_device_id=p_actor_device_id then
    raise exception 'ACTOR_DEVICE_REVOCATION_FORBIDDEN' using errcode='42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'system-owner-device-operation:'||p_operation_id::text,0));
  select * into existing from public.system_owner_device_authorization_operations operation
  where operation.operation_id=p_operation_id;
  if found then
    if existing.actor_user_id_snapshot=p_actor_user_id
      and existing.actor_device_id=p_actor_device_id
      and existing.target_user_id_snapshot=p_target_user_id
      and existing.target_device_id=p_target_device_id
      and existing.action=operation_action and existing.environment=p_environment then
      return existing.stored_result;
    end if;
    raise exception 'PLATFORM_DEVICE_OPERATION_MISMATCH' using errcode='22023';
  end if;
  credential:=public.require_system_owner_webauthn_actor(
    p_actor_user_id,p_actor_device_id,p_credential_id);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'platform-device-authorization-user:'||p_target_user_id::text,0));
  select * into challenge from public.device_possession_challenges stored
  where stored.id=p_challenge_id and stored.user_id=p_actor_user_id
    and stored.session_id=p_session_id and stored.actor_device_id=p_actor_device_id
    and stored.credential_id=p_credential_id and stored.purpose=v_purpose
    and stored.target_user_id=p_target_user_id and stored.target_device_id=p_target_device_id
    and stored.operation_id=p_operation_id and stored.environment=p_environment
    and stored.challenge_hash=p_challenge_hash for update;
  if not found or challenge.verified_at is not null or challenge.consumed_at is not null
    or challenge.failed_at is not null or challenge.expires_at<=operation_at
    or challenge.expected_origin<>pg_catalog.lower(p_origin)
    or challenge.expected_rp_id<>pg_catalog.lower(p_rp_id)
    or p_new_sign_count<credential.sign_count
    or p_verification_context->'userVerified' is distinct from 'true'::jsonb
    or pg_catalog.jsonb_typeof(p_verification_context->'backupEligible') is distinct from 'boolean'
    or pg_catalog.jsonb_typeof(p_verification_context->'backupState') is distinct from 'boolean'
    or (p_verification_context->>'backupEligible')::boolean is distinct from credential.backup_eligible
    or (p_verification_context->>'backupState')::boolean is distinct from credential.backup_state then
    raise exception 'PLATFORM_DEVICE_OPERATION_VERIFICATION_INVALID' using errcode='42501';
  end if;
  select device_authorization.* into target
  from platform.user_device_authorizations device_authorization
  join platform.devices device on device.id=device_authorization.device_id
  join platform.profiles profile on profile.user_id=device_authorization.user_id
  where device_authorization.user_id=p_target_user_id
    and device_authorization.device_id=p_target_device_id
    and device_authorization.status=target_initial_status
    and device_authorization.revoked_at is null
    and device.lifecycle_status='active' and device.retired_at is null
    and device.compromised_at is null and profile.account_status='approved'
    and (p_action='revoke' or exists(
      select 1 from platform.device_key_bindings binding
      where binding.user_id=device_authorization.user_id
        and binding.device_id=device_authorization.device_id
        and binding.device_authorization_id=device_authorization.id
        and binding.lifecycle_status='active' and binding.revoked_at is null
        and binding.retired_at is null))
  for update of device_authorization;
  if not found then
    if p_action='revoke' then
      raise exception 'APPROVED_UNREVOKED_DEVICE_REQUIRED' using errcode='42501';
    end if;
    raise exception 'PENDING_APPROVED_ACCOUNT_DEVICE_REQUIRED' using errcode='42501';
  end if;
  if p_action='revoke' and platform_private.is_canonical_platform_owner(p_target_user_id)
    and (select pg_catalog.count(*) from platform.user_device_authorizations approved
      join platform.devices device on device.id=approved.device_id
      where approved.user_id=p_target_user_id and approved.status='approved'
        and approved.revoked_at is null and device.lifecycle_status='active'
        and device.retired_at is null and device.compromised_at is null)<=1 then
    raise exception 'OWNER_LAST_APPROVED_DEVICE_REVOCATION_FORBIDDEN' using errcode='42501';
  end if;
  update public.device_possession_challenges set verified_at=operation_at,
    verification_context=p_verification_context where id=p_challenge_id;
  update public.device_security_credentials set sign_count=p_new_sign_count,
    last_used_at=operation_at where id=p_credential_id;
  insert into public.device_possession_challenge_consumers(challenge_id,user_id,session_id,
    actor_device_id,actor_credential_id,challenge_purpose,environment,consumer_kind,consumer_id)
  values(p_challenge_id,p_actor_user_id,p_session_id,p_actor_device_id,p_credential_id,
    v_purpose,p_environment,'device_authorization_operation',p_operation_id);

  if p_action='revoke' then
    update public.device_security_credentials set lifecycle_status='revoked',
      revoked_at=operation_at,revoked_by=p_actor_user_id,
      revocation_reason='system_owner_device_revocation'
    where user_id=p_target_user_id and device_id=p_target_device_id
      and lifecycle_status in ('enrollment_pending','active','rotation_pending','recovery_required')
      and revoked_at is null;
    update platform_private.device_session_challenges set failed_at=operation_at,
      failure_code='DEVICE_AUTHORIZATION_REVOKED'
    where user_id=p_target_user_id and device_id=p_target_device_id
      and consumed_at is null and failed_at is null;
    update platform_private.device_sessions set revoked_at=operation_at
    where user_id=p_target_user_id and device_id=p_target_device_id and revoked_at is null;
    update platform.device_key_bindings set lifecycle_status='revoked',revoked_at=operation_at
    where user_id=p_target_user_id and device_id=p_target_device_id
      and device_authorization_id=target.id and lifecycle_status='active'
      and revoked_at is null and retired_at is null;
  end if;

  update platform.user_device_authorizations set
    status=case p_action when 'approve' then 'approved' else 'revoked' end,
    approved_by=case p_action when 'approve' then p_actor_user_id else approved_by end,
    approved_at=case p_action when 'approve' then operation_at else approved_at end,
    revoked_by=case when p_action in ('reject','revoke') then p_actor_user_id else null end,
    revoked_at=case when p_action in ('reject','revoke') then operation_at else null end,
    status_reason=null
  where id=target.id and user_id=p_target_user_id and device_id=p_target_device_id;
  result:=pg_catalog.jsonb_build_object('status','applied','action',p_action,
    'targetUserId',p_target_user_id,'deviceId',p_target_device_id,
    'authorizationStatus',case p_action when 'approve' then 'approved' else 'revoked' end,
    'operationId',p_operation_id);
  insert into public.system_owner_device_authorization_operations(operation_id,actor_user_id,
    actor_user_id_snapshot,actor_device_id,actor_credential_id,challenge_id,session_id,
    challenge_purpose,environment,target_user_id,target_user_id_snapshot,target_device_id,
    action,outcome,stored_result)
  values(p_operation_id,p_actor_user_id,p_actor_user_id,p_actor_device_id,p_credential_id,
    p_challenge_id,p_session_id,v_purpose,p_environment,p_target_user_id,p_target_user_id,
    p_target_device_id,operation_action,'applied',result);
  insert into public.privileged_device_authorization_audit_log(actor_user_id,
    actor_user_id_snapshot,actor_device_id,actor_credential_id,session_id_hash,session_id,
    challenge_id,challenge_purpose,environment,target_user_id,target_user_id_snapshot,
    target_device_id,challenge_target_user_id,challenge_target_device_id,action,operation_id,
    result,origin,rp_id,user_verified,backup_eligible,backup_state,security_context)
  values(p_actor_user_id,p_actor_user_id,p_actor_device_id,p_credential_id,
    extensions.digest(p_session_id::text,'sha256'),p_session_id,p_challenge_id,v_purpose,
    p_environment,p_target_user_id,p_target_user_id,p_target_device_id,p_target_user_id,
    p_target_device_id,audit_action,p_operation_id,'applied',pg_catalog.lower(p_origin),
    pg_catalog.lower(p_rp_id),true,credential.backup_eligible,credential.backup_state,
    p_verification_context);
  perform platform_private.write_audit_event(p_actor_user_id,p_target_user_id,'platform',
    'devices','device_authorization.'||(case p_action when 'approve' then 'approved'
      when 'reject' then 'rejected' else 'revoked' end),
    'user_device_authorization',target.id,'platform',
    pg_catalog.jsonb_build_object('status',target_initial_status),
    pg_catalog.jsonb_build_object('status',case p_action when 'approve' then 'approved' else 'revoked' end),
    pg_catalog.jsonb_build_object('deviceId',p_target_device_id,'confirmation','webauthn'),
    null,p_operation_id,'system');
  update public.device_possession_challenges set consumed_at=operation_at
  where id=p_challenge_id;
  return result;
end; $$;


--
-- Name: create_canonical_conference("uuid", "uuid", "uuid", "text", "date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_canonical_conference"("p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_requested_conference_id" "uuid", "p_name" "text", "p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_context jsonb;
  v_actor uuid;
  v_device_authorization_id uuid;
  v_name text:=btrim(coalesce(p_name,''));
  v_intent jsonb;
  v_prior public.conference_creation_operations%rowtype;
  v_permission text;
  v_grant_ids jsonb:='{}'::jsonb;
  v_grant_id uuid;
  v_result jsonb;
begin
  if p_operation_id is null or p_requested_conference_id is null
     or v_name='' or char_length(v_name)>500
     or p_start_date is null or p_end_date is null or p_end_date<p_start_date then
    raise exception 'CANONICAL_CONFERENCE_CREATE_ARGUMENT_INVALID' using errcode='22023';
  end if;

  v_context:=public.require_effective_module_permission(
    p_actor_device_id,'conference','conference.lifecycle.create',null,null
  );
  v_actor:=(v_context->>'actorUserId')::uuid;
  v_device_authorization_id:=platform_private.validated_phase1c_device_authorization(
    v_actor,p_actor_device_id
  );
  if v_device_authorization_id is null then
    raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';
  end if;

  v_intent:=jsonb_build_object(
    'contract','final-canonical-conference-create-v1',
    'conferenceId',p_requested_conference_id,
    'name',v_name,'startDate',p_start_date,'endDate',p_end_date
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_actor::text||':conference-create:'||p_operation_id::text,0)
  );
  select operations.* into v_prior
  from public.conference_creation_operations operations
  where operations.user_id=v_actor and operations.operation_id=p_operation_id;
  if found then
    if v_prior.conference_id<>p_requested_conference_id
       or v_prior.initial_metadata<>v_intent then
      raise exception 'CANONICAL_CONFERENCE_CREATE_OPERATION_MISMATCH' using errcode='22023';
    end if;
    if not exists(
      select 1 from public.conferences conference
      where conference.id=p_requested_conference_id and conference.deleted_at is null
    ) or exists(
      select 1 from (values('conference.access.view'),('conference.lifecycle.manage')) expected(permission_key)
      where not exists(
        select 1 from platform.permission_grants grants
        join platform.permissions permission on permission.id=grants.permission_id
        where grants.user_id=v_actor and permission.code=expected.permission_key
          and permission.status='active' and grants.scope_type='resource'
          and grants.resource_type='conference'
          and grants.resource_id=p_requested_conference_id::text
          and grants.revoked_at is null
      )
    ) then
      raise exception 'CANONICAL_CONFERENCE_CREATE_REPLAY_STATE_INVALID' using errcode='55000';
    end if;
    return jsonb_build_object(
      'status','duplicate','operationId',p_operation_id,
      'conferenceId',p_requested_conference_id,
      'name',v_name,'startDate',p_start_date,'endDate',p_end_date,
      'conferenceStatus','active','completedAt',null,'revision',1,'created',false
    );
  end if;

  if exists(select 1 from public.conferences where id=p_requested_conference_id) then
    raise exception 'CONFERENCE_ID_ALREADY_USED' using errcode='23505';
  end if;

  insert into public.conferences(
    id,name,owner_id,start_date,end_date,status,
    completed_at,revision,updated_by
  ) values(
    p_requested_conference_id,v_name,v_actor,
    p_start_date,p_end_date,'active',null,1,v_actor
  );

  insert into public.conference_creation_operations(
    user_id,operation_id,conference_id,initial_metadata
  ) values(v_actor,p_operation_id,p_requested_conference_id,v_intent);

  foreach v_permission in array array[
    'conference.access.view','conference.lifecycle.manage'
  ] loop
    insert into platform.permission_grants(
      user_id,permission_id,scope_type,resource_type,resource_id,
      granted_by,metadata
    )
    select v_actor,permission.id,'resource','conference',
      p_requested_conference_id::text,v_actor,
      jsonb_build_object('actorDeviceId',p_actor_device_id)
    from platform.permissions permission
    where permission.code=v_permission and permission.status='active'
      and permission.allowed_scope_mode='resource'
      and permission.allowed_resource_type='conference'
    returning id into v_grant_id;
    if v_grant_id is null then
      raise exception 'CANONICAL_CONFERENCE_CREATOR_PERMISSION_MISSING' using errcode='55000';
    end if;
    v_grant_ids:=v_grant_ids||jsonb_build_object(v_permission,v_grant_id);
  end loop;

  v_result:=jsonb_build_object(
    'status','created','operationId',p_operation_id,
    'conferenceId',p_requested_conference_id,
    'name',v_name,'startDate',p_start_date,'endDate',p_end_date,
    'conferenceStatus','active','completedAt',null,'revision',1,'created',true
  );
  insert into platform.audit_events(
    actor_user_id,actor_device_authorization_id,subject_user_id,
    domain,module,action,entity_type,entity_id,scope_type,scope_id,
    old_values,new_values,metadata,operation_id,source
  ) values(
    v_actor,v_device_authorization_id,null,
    'platform','conference','conference.lifecycle.created',
    'conference',p_requested_conference_id,'platform',null,
    null,jsonb_build_object(
      'name',v_name,'startDate',p_start_date,'endDate',p_end_date,
      'status','active','completedAt',null,'revision',1
    ),jsonb_build_object(
      'permissionKey','conference.lifecycle.create',
      'authoritySource',v_context->>'authoritySource',
      'authorityGrantId',v_context->'grantId',
      'creatorResourceGrants',v_grant_ids,'deviceId',p_actor_device_id
    ),p_operation_id,'rpc'
  );
  return v_result;
end $$;


--
-- Name: create_conference_participation("uuid", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_conference_participation"("p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_conference_id" "uuid", "p_person_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_context jsonb; v_actor uuid; v_device_authorization uuid; v_request jsonb; v_prior public.conference_participation_operations%rowtype; v_row public.conference_participations%rowtype; v_person platform.people%rowtype; v_result jsonb;
begin
  if p_operation_id is null or p_person_id is null then raise exception 'CONFERENCE_PARTICIPATION_ARGUMENT_INVALID' using errcode='22023'; end if;
  v_context:=platform_private.require_conference_participation_context(p_actor_device_id,p_conference_id,'conference.people.manage',true); v_actor:=(v_context->>'actorUserId')::uuid;
  v_device_authorization:=platform_private.validated_phase1c_device_authorization(v_actor,p_actor_device_id);
  v_request:=jsonb_build_object('conferenceId',p_conference_id,'personId',p_person_id);
  perform pg_advisory_xact_lock(hashtextextended(v_actor::text||':conference-participation:'||p_operation_id::text,0));
  select * into v_prior from public.conference_participation_operations where actor_user_id=v_actor and operation_id=p_operation_id;
  if found then if v_prior.operation<>'create' or v_prior.request<>v_request then raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023'; end if; select * into strict v_person from platform.people where id=p_person_id; return v_prior.result || jsonb_build_object('person',jsonb_build_object('personId',v_person.id,'fullName',v_person.full_name,'phone',v_person.phone,'gender',v_person.gender,'dateOfBirth',v_person.date_of_birth,'church',v_person.church)); end if;
  if not exists(select 1 from platform.people where id=p_person_id) then raise exception 'PLATFORM_PERSON_NOT_FOUND' using errcode='23503'; end if;
  if exists(select 1 from public.conference_participations where conference_id=p_conference_id and person_id=p_person_id) then raise exception 'CONFERENCE_PARTICIPATION_ALREADY_EXISTS' using errcode='23505'; end if;
  insert into public.conference_participations(conference_id,person_id,created_by,updated_by) values(p_conference_id,p_person_id,v_actor,v_actor) returning * into v_row;
  select * into strict v_person from platform.people where id=p_person_id;
  v_result:=jsonb_build_object('person',jsonb_build_object('personId',v_person.id,'fullName',v_person.full_name,'phone',v_person.phone,'gender',v_person.gender,'dateOfBirth',v_person.date_of_birth,'church',v_person.church),'participationId',v_row.id,'conferenceId',v_row.conference_id,'personId',v_row.person_id,'status',v_row.status,'revision',v_row.revision,'createdAt',v_row.created_at,'updatedAt',v_row.updated_at,'createdBy',v_row.created_by,'updatedBy',v_row.updated_by);
  insert into public.conference_participation_operations values(v_actor,p_operation_id,'create',v_request,v_result,statement_timestamp());
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source) values(v_actor,v_device_authorization,'platform','conference','conference.participation.created','conference_participation',v_row.id,'platform',null,jsonb_build_object('conferenceId',p_conference_id,'personId',p_person_id,'status','active','revision',1),jsonb_build_object('permissionKey','conference.people.manage','authoritySource',v_context->>'authoritySource','grantId',v_context->'grantId'),p_operation_id,'rpc');
  return v_result;
end $$;


--
-- Name: create_conference_participation_with_person("uuid", "uuid", "uuid", "text", "text", "text", "date", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_conference_participation_with_person"("p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_conference_id" "uuid", "p_full_name" "text", "p_phone" "text", "p_gender" "text", "p_date_of_birth" "date", "p_church" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_context jsonb; v_actor uuid; v_device_authorization uuid; v_request jsonb;
  v_prior public.conference_participation_operations%rowtype; v_person platform.people%rowtype;
  v_participation public.conference_participations%rowtype; v_person_projection jsonb; v_result jsonb;
begin
  if p_operation_id is null or p_conference_id is null or p_full_name is null or btrim(p_full_name)=''
     or length(btrim(p_full_name))>240
     or (p_phone is not null and (btrim(p_phone)='' or length(btrim(p_phone))>40))
     or (p_gender is not null and p_gender not in('male','female'))
     or (p_church is not null and (btrim(p_church)='' or length(btrim(p_church))>200)) then
    raise exception 'CONFERENCE_PARTICIPANT_PERSON_ARGUMENT_INVALID' using errcode='22023';
  end if;
  v_context:=platform_private.require_conference_participation_context(p_actor_device_id,p_conference_id,'conference.people.manage',true);
  v_actor:=(v_context->>'actorUserId')::uuid;
  v_device_authorization:=platform_private.validated_phase1c_device_authorization(v_actor,p_actor_device_id);
  if v_device_authorization is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
  v_request:=jsonb_build_object('conferenceId',p_conference_id,'fullName',btrim(p_full_name),
    'phone',case when p_phone is null then null else btrim(p_phone) end,'gender',p_gender,
    'dateOfBirth',p_date_of_birth,'church',case when p_church is null then null else btrim(p_church) end);
  perform pg_advisory_xact_lock(hashtextextended(v_actor::text||':conference-participation:'||p_operation_id::text,0));
  select * into v_prior from public.conference_participation_operations where actor_user_id=v_actor and operation_id=p_operation_id;
  if found then
    if v_prior.operation<>'create_with_person' or v_prior.request<>v_request then
      raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023';
    end if;
    return v_prior.result;
  end if;
  insert into platform.people(full_name,phone,gender,date_of_birth,church,created_by,updated_by)
  values(btrim(p_full_name),case when p_phone is null then null else btrim(p_phone) end,p_gender,p_date_of_birth,
    case when p_church is null then null else btrim(p_church) end,v_actor,v_actor) returning * into v_person;
  insert into public.conference_participations(conference_id,person_id,created_by,updated_by)
  values(p_conference_id,v_person.id,v_actor,v_actor) returning * into v_participation;
  v_person_projection:=jsonb_build_object('personId',v_person.id,'fullName',v_person.full_name,'phone',v_person.phone,
    'gender',v_person.gender,'dateOfBirth',v_person.date_of_birth,'church',v_person.church);
  v_result:=jsonb_build_object('participationId',v_participation.id,'conferenceId',v_participation.conference_id,
    'personId',v_participation.person_id,'status',v_participation.status,'revision',v_participation.revision,
    'createdAt',v_participation.created_at,'updatedAt',v_participation.updated_at,'createdBy',v_participation.created_by,
    'updatedBy',v_participation.updated_by,'person',v_person_projection);
  insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at)
  values(v_actor,p_operation_id,'create_with_person',v_request,v_result,statement_timestamp());
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,
    entity_id,scope_type,new_values,metadata,operation_id,source)
  values(v_actor,v_device_authorization,'platform','conference','platform.person.created','person',v_person.id,
      'platform',v_person_projection,jsonb_build_object('conferenceId',p_conference_id,'participationId',v_participation.id,
        'permissionKey','conference.people.manage','authoritySource',v_context->>'authoritySource','grantId',v_context->'grantId'),p_operation_id,'rpc'),
    (v_actor,v_device_authorization,'platform','conference','conference.participation.created','conference_participation',
      v_participation.id,'platform',v_result,jsonb_build_object('conferenceId',p_conference_id,'personId',v_person.id,
        'permissionKey','conference.people.manage','authoritySource',v_context->>'authoritySource','grantId',v_context->'grantId'),p_operation_id,'rpc');
  return v_result;
end $$;


--
-- Name: delete_conference_participation("uuid", "uuid", "uuid", bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_conference_participation"("p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_participation_id" "uuid", "p_expected_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current public.conference_participations%rowtype; member public.conference_participations%rowtype;
  context jsonb; session_context jsonb; actor uuid; v_authorization uuid; request jsonb;
  prior public.conference_participation_operations%rowtype; family_ids uuid[];
  removed_transport_ids jsonb:='[]'::jsonb; result jsonb;
begin
  if p_operation_id is null or p_expected_revision<1 then raise exception 'CONFERENCE_PARTICIPATION_ARGUMENT_INVALID' using errcode='22023'; end if;
  begin
    session_context:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;
    if session_context is null or session_context->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH'
       or (session_context->>'device_id')::uuid is distinct from p_actor_device_id then
      raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
    actor:=(session_context->>'user_id')::uuid;
  exception when invalid_text_representation or null_value_not_allowed then
    raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';
  end;
  v_authorization:=platform_private.validated_phase1c_device_authorization(actor,p_actor_device_id);
  if v_authorization is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
  request:=jsonb_build_object('participationId',p_participation_id,'expectedRevision',p_expected_revision);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':conference-participation:'||p_operation_id::text,0));
  select * into prior from public.conference_participation_operations where actor_user_id=actor and operation_id=p_operation_id;
  if found then
    if prior.operation<>'delete' or prior.request<>request then raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023'; end if;
    return prior.result;
  end if;
  select * into current from public.conference_participations where id=p_participation_id;
  if not found then raise exception 'CONFERENCE_PARTICIPATION_NOT_FOUND' using errcode='P0002'; end if;
  context:=platform_private.require_conference_participation_context(
    p_actor_device_id,current.conference_id,'conference.people.manage',true);
  perform pg_advisory_xact_lock(hashtextextended('conference-guardian:'||current.conference_id::text,0));
  perform 1 from public.conference_participations where id=current.id or guardian_participation_id=current.id order by id for update;
  select * into current from public.conference_participations where id=p_participation_id;
  if current.revision<>p_expected_revision then raise exception 'CONFERENCE_PARTICIPATION_REVISION_CONFLICT' using errcode='40001'; end if;
  if current.guardian_participation_id is null then
    select array_agg(id order by id) into family_ids from public.conference_participations
    where conference_id=current.conference_id and (id=current.id or guardian_participation_id=current.id);
  else family_ids:=array[current.id]; end if;
  for member in select * from public.conference_participations where id=any(family_ids) order by id loop
    perform platform_private.cleanup_conference_accommodation_for_participation(
      member.id,actor,v_authorization,context,'participation_deleted',p_operation_id);
    removed_transport_ids:=removed_transport_ids||platform_private.cleanup_conference_transport_for_participation(
      member.id,actor,v_authorization,'participation_deleted',p_operation_id,'conference.people.manage');
    delete from public.conference_restaurant_participation_overrides where participation_id=member.id;
  end loop;
  delete from public.conference_participations where id=any(family_ids) and id<>current.id;
  delete from public.conference_participations where id=current.id;
  result:=jsonb_build_object('participationId',current.id,'conferenceId',current.conference_id,
    'personId',current.person_id,'deleted',true,'deletedParticipationIds',to_jsonb(family_ids),
    'removedTransportAssignmentIds',removed_transport_ids);
  insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at)
  values(actor,p_operation_id,'delete',request,result,statement_timestamp());
  return result;
end $$;


--
-- Name: device_guarded_acquire_conference_lock("uuid", "uuid", "uuid", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."device_guarded_acquire_conference_lock"("p_actor_device_id" "uuid", "p_conference_id" "uuid", "p_lock_token" "uuid", "p_ttl_seconds" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$ begin perform public.require_current_approved_device(p_actor_device_id); perform pg_advisory_xact_lock(hashtextextended('conference-lock:'||p_conference_id::text,0)); return public.acquire_conference_lock(p_conference_id,p_actor_device_id,p_lock_token,p_ttl_seconds); end; $$;


--
-- Name: device_guarded_get_conference_lock("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."device_guarded_get_conference_lock"("p_actor_device_id" "uuid", "p_conference_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$ begin
  perform public.require_current_approved_device(p_actor_device_id);
  return public.get_conference_lock(p_conference_id, p_actor_device_id);
end; $$;


--
-- Name: device_guarded_manage_system_user("uuid", "uuid", "uuid", "text", boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."device_guarded_manage_system_user"("p_actor_device_id" "uuid", "p_target_user_id" "uuid", "p_operation_id" "uuid", "p_action" "text", "p_requested_value" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid; existing public.system_access_admin_operations%rowtype; result jsonb; target_status text;
begin
 if p_target_user_id is null or p_operation_id is null or p_action not in ('approve','block','unblock') or p_requested_value is not null then
  raise exception 'INVALID_SYSTEM_ACCESS_OPERATION' using errcode='22023';
 end if;
 actor_id:=public.require_current_approved_device(p_actor_device_id);
 if not public.is_system_owner(actor_id) then raise exception 'SYSTEM_OWNER_REQUIRED' using errcode='42501'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('system-access-operation:'||p_operation_id::text,0));
 select * into existing from public.system_access_admin_operations where operation_id=p_operation_id;
 if found then
  if existing.actor_user_id=actor_id and existing.actor_device_id=p_actor_device_id and existing.target_user_id=p_target_user_id and existing.action=p_action and existing.requested_value is null then return existing.stored_result; end if;
  raise exception 'SYSTEM_ACCESS_OPERATION_MISMATCH' using errcode='22023';
 end if;
 target_status:=case p_action when 'block' then 'blocked' else 'approved' end;
 perform platform.set_account_status(p_target_user_id,target_status,'device_guarded_manage_system_user:'||p_action);
 result:=pg_catalog.jsonb_build_object('status',target_status,'userId',p_target_user_id);
 insert into public.system_access_admin_operations(operation_id,actor_user_id,actor_device_id,target_user_id,action,requested_value,result_status,stored_result)
 values(p_operation_id,actor_id,p_actor_device_id,p_target_user_id,p_action,null,target_status,result);
 return result;
end $$;


--
-- Name: device_guarded_release_conference_lock("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."device_guarded_release_conference_lock"("p_actor_device_id" "uuid", "p_conference_id" "uuid", "p_lock_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$ begin perform public.require_current_approved_device(p_actor_device_id); perform pg_advisory_xact_lock(hashtextextended('conference-lock:'||p_conference_id::text,0)); return public.release_conference_lock(p_conference_id,p_actor_device_id,p_lock_token); end; $$;


--
-- Name: device_guarded_renew_conference_lock("uuid", "uuid", "uuid", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."device_guarded_renew_conference_lock"("p_actor_device_id" "uuid", "p_conference_id" "uuid", "p_lock_token" "uuid", "p_ttl_seconds" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$ begin perform public.require_current_approved_device(p_actor_device_id); perform pg_advisory_xact_lock(hashtextextended('conference-lock:'||p_conference_id::text,0)); return public.renew_conference_lock(p_conference_id,p_actor_device_id,p_lock_token,p_ttl_seconds); end; $$;


--
-- Name: export_conference_canonical_bundle("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."export_conference_canonical_bundle"("p_actor_device_id" "uuid", "p_conference_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid;v_core public.conferences%rowtype;v_data jsonb;v_sections jsonb='{}'::jsonb;v_table text;v_rows jsonb;v_counts jsonb='{}'::jsonb;
begin
 v_actor:=public.require_current_approved_device(p_actor_device_id);
 perform public.require_effective_module_permission(p_actor_device_id,'conference','conference.data.export','conference',p_conference_id::text);
 select * into v_core from public.conferences where id=p_conference_id and deleted_at is null;
 if not found then raise exception 'CONFERENCE_NOT_FOUND' using errcode='22023'; end if;
 foreach v_table in array platform_private.conference_bundle_tables() loop
  v_rows:=platform_private.conference_bundle_rows(v_table,p_conference_id);
  v_sections:=v_sections||jsonb_build_object(v_table,v_rows);
  v_counts:=v_counts||jsonb_build_object(v_table,jsonb_array_length(v_rows));
 end loop;
 v_data:=jsonb_build_object(
  'conference',to_jsonb(v_core)-array['owner_id','updated_by','created_at','updated_at','deleted_at','revision'],
  'sections',v_sections
 );
 return jsonb_build_object(
  'type','conference-canonical-bundle','schemaVersion',1,
  'manifest',jsonb_build_object(
   'sourceConferenceId',p_conference_id,'sourceRevision',v_core.revision,
   'exportedAt',statement_timestamp(),'sectionCounts',v_counts,
   'payloadSha256',encode(extensions.digest(v_data::text,'sha256'),'hex'),
   'excludedAuthorities',jsonb_build_array('platform-identities','permissions','devices','sessions','locks','audit','operation-ledgers','reservations')
  ),'data',v_data
 );
end $$;


--
-- Name: fail_stable_development_platform_device_recovery("uuid", "uuid", "uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fail_stable_development_platform_device_recovery"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_session_id" "uuid", "p_challenge_id" "uuid", "p_failure_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare challenge platform_private.stable_device_recovery_challenges%rowtype;
  recovery platform_private.stable_device_recovery_authorizations%rowtype;
begin
  perform public.require_platform_device_backend();
  if p_failure_code not in ('ASSERTION_VERIFICATION_FAILED','ASSERTION_NOT_VERIFIED',
      'CREDENTIAL_POLICY_DENIED') then
    raise exception 'STABLE_DEVICE_RECOVERY_FAILURE_CODE_INVALID' using errcode='22023';
  end if;
  select * into challenge from platform_private.stable_device_recovery_challenges item
  where item.id=p_challenge_id and item.session_id=p_session_id for update;
  if not found or challenge.verified_at is not null or challenge.consumed_at is not null
    or challenge.failed_at is not null then
    return pg_catalog.jsonb_build_object('status','unchanged');
  end if;
  select * into recovery from platform_private.stable_device_recovery_authorizations item
  where item.id=challenge.recovery_authorization_id and item.owner_user_id=p_actor_user_id
    and item.target_device_id=p_actor_device_id and item.consumed_at is null;
  if not found then
    raise exception 'STABLE_DEVICE_RECOVERY_AUTHORIZATION_INVALID' using errcode='42501';
  end if;
  update platform_private.stable_device_recovery_challenges
  set failed_at=pg_catalog.statement_timestamp(),failure_code=p_failure_code where id=challenge.id;
  insert into platform_private.stable_device_recovery_audit(
    recovery_authorization_id,challenge_id,operation_id,actor_user_id,
    source_authorization_id,source_device_id,target_authorization_id,target_device_id,
    credential_id,environment,action,result,origin,rp_id,user_verified,
    backup_eligible,backup_state,evidence)
  values(recovery.id,challenge.id,recovery.operation_id,recovery.owner_user_id,null,null,
    recovery.target_authorization_id,recovery.target_device_id,recovery.credential_id,
    recovery.environment,'passkey_verification_failed','denied',recovery.expected_origin,
    recovery.expected_rp_id,false,false,false,
    pg_catalog.jsonb_build_object('failureCode',p_failure_code));
  return pg_catalog.jsonb_build_object('status','failed');
end; $$;


--
-- Name: fail_system_owner_device_possession_challenge("uuid", "uuid", "uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fail_system_owner_device_possession_challenge"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_session_id" "uuid", "p_challenge_id" "uuid", "p_failure_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare challenge public.device_possession_challenges%rowtype;
begin
  perform public.require_platform_device_backend();
  select * into challenge from public.device_possession_challenges challenges
    where challenges.id=p_challenge_id and challenges.user_id=p_actor_user_id
      and challenges.actor_device_id=p_actor_device_id and challenges.session_id=p_session_id
    for update;
  if not found or challenge.verified_at is not null or challenge.consumed_at is not null
    or challenge.failed_at is not null then
    raise exception 'PLATFORM_DEVICE_CHALLENGE_TERMINAL' using errcode='42501';
  end if;
  update public.device_possession_challenges set failed_at=statement_timestamp(),
    failure_code=left(regexp_replace(upper(coalesce(p_failure_code,'VERIFICATION_FAILED')),
      '[^A-Z0-9_]+','','g'),80) where id=p_challenge_id;
  return jsonb_build_object('status','failed','challengeId',p_challenge_id);
end;
$$;


--
-- Name: get_conference_accommodation("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_conference_accommodation"("p_device" "uuid", "p_conference" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare context jsonb;result jsonb;
begin
 context:=platform_private.require_conference_accommodation_context(p_device,p_conference,'conference.accommodation.view',false);
 select coalesce(jsonb_agg(jsonb_build_object('assignmentId',a.id,'assignmentRevision',a.revision,'houseId',h.id,'name',h.name,'description',h.description,'position',h.position,'revision',h.revision,'floors',(select coalesce(jsonb_agg(jsonb_build_object('floorId',f.id,'name',f.name,'position',f.position,'revision',f.revision,'rooms',(select coalesce(jsonb_agg(jsonb_build_object('roomAssignmentId',ra.id,'roomAssignmentRevision',ra.revision,'keyHolderOccupancyId',case when exists(select 1 from public.conference_accommodation_occupancies ko where ko.id=ra.key_holder_occupancy_id and ko.room_id=ra.room_id and ko.conference_id=ra.conference_id and ko.arrival_day<=platform_private.conference_operational_day(ra.conference_id) and coalesce(ko.leave_day,platform_private.conference_accommodation_duration(ra.conference_id)+1)>platform_private.conference_operational_day(ra.conference_id)) then ra.key_holder_occupancy_id else null end,'keyHolderPersonId',(select p.person_id from public.conference_accommodation_occupancies ko join public.conference_participations p on p.id=ko.participation_id where ko.id=ra.key_holder_occupancy_id and ko.room_id=ra.room_id),'keyHolderName',(select pe.full_name from public.conference_accommodation_occupancies ko join public.conference_participations p on p.id=ko.participation_id join platform.people pe on pe.id=p.person_id where ko.id=ra.key_holder_occupancy_id and ko.room_id=ra.room_id),'keyDeliveredAt',ra.key_delivered_at,'keyDeliveredBy',ra.key_delivered_by,'roomId',r.id,'roomNumber',r.room_number,'baseCapacity',r.base_capacity,'extraBedCapacity',ra.extra_bed_capacity,'notes',r.notes,'isClosed',r.is_closed,'closedDay',r.closed_day,'position',r.position,'revision',r.revision,'occupancies',(select coalesce(jsonb_agg(jsonb_build_object('occupancyId',o.id,'revision',o.revision,'arrivedAt',o.arrived_at,'arrivedBy',o.arrived_by,'arrivalDay',o.arrival_day,'leaveDay',o.leave_day,'bedType',o.bed_type,'extraBedPersonType',o.extra_bed_person_type,'extraBedSource',o.extra_bed_source,'participationId',p.id,'participationStatus',p.status,'guardianParticipationId',p.guardian_participation_id,'guardianPersonId',gp.person_id,'guardianFullName',gpe.full_name,'guardianParticipationStatus',gp.status,'person',jsonb_build_object('personId',pe.id,'fullName',pe.full_name,'phone',pe.phone,'gender',pe.gender,'dateOfBirth',pe.date_of_birth,'church',pe.church)) order by pe.full_name,o.id),'[]') from public.conference_accommodation_occupancies o join public.conference_participations p on p.id=o.participation_id join platform.people pe on pe.id=p.person_id left join public.conference_participations gp on gp.id=p.guardian_participation_id and gp.conference_id=p.conference_id left join platform.people gpe on gpe.id=gp.person_id where o.room_id=r.id and o.conference_id=p_conference)) order by r.position,r.id),'[]') from public.conference_room_assignments ra join public.conference_accommodation_rooms r on r.id=ra.room_id where ra.conference_id=p_conference and ra.house_id=h.id and r.floor_id=f.id)) order by f.position,f.id),'[]') from public.conference_accommodation_floors f where f.house_id=h.id and exists(select 1 from public.conference_room_assignments ra where ra.conference_id=p_conference and ra.house_id=h.id and ra.room_id in(select rr.id from public.conference_accommodation_rooms rr where rr.floor_id=f.id)))) order by h.position,h.id),'[]') into result from public.conference_house_assignments a join public.conference_accommodation_houses h on h.id=a.house_id where a.conference_id=p_conference and exists(select 1 from public.conference_room_assignments ra where ra.conference_id=p_conference and ra.house_id=h.id);
 return jsonb_build_object('conferenceId',p_conference,'houses',result,'pricing',platform_private.conference_accommodation_pricing_projection(p_conference));
end $$;


--
-- Name: get_conference_air_conditioning("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_conference_air_conditioning"("p_device" "uuid", "p_conference" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c jsonb; d jsonb; h jsonb; r jsonb;begin
 c:=platform_private.require_conference_air_conditioning_context(p_device,p_conference,'conference.air_conditioning.view',false);
 select coalesce(to_jsonb(x)-'conference_id'-'created_at'-'created_by','{}') into d from public.conference_air_conditioning_defaults x where conference_id=p_conference;
 select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'created_at'-'created_by' order by house_id),'[]') into h from public.conference_air_conditioning_house_overrides x where conference_id=p_conference;
 select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'created_at'-'created_by' order by room_id),'[]') into r from public.conference_air_conditioning_room_overrides x where conference_id=p_conference;
 return jsonb_build_object('conferenceId',p_conference,'defaultConfiguration',coalesce(d,jsonb_build_object('enabled',true,'pricing_basis','PER_ROOM','time_basis','DAY','duration_basis','CONFERENCE','unit_price',0,'fixed_amount',null,'include_empty_rooms',false,'include_closed_rooms',false,'units_count',null,'revision',0)),'houseOverrides',h,'roomOverrides',r);
end $$;


