-- Name: get_conference_branding("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_conference_branding"("p_device" "uuid", "p_conference" "uuid") RETURNS "jsonb"
