--
-- Name: get_conference_restaurant("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_conference_restaurant"("p_device" "uuid", "p_conference" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ declare c jsonb;s public.conference_restaurant_settings%rowtype;can_manage boolean:=false;begin
  c:=platform_private.require_conference_restaurant_context(p_device,p_conference,'conference.restaurant.view',false);
  begin perform public.require_effective_module_permission(p_device,'conference','conference.restaurant.manage','conference',p_conference::text);can_manage:=true;exception when insufficient_privilege then null;end;
  select * into s from public.conference_restaurant_settings where conference_id=p_conference;
  return jsonb_build_object('conferenceId',p_conference,'canManage',can_manage,'settings',jsonb_build_object('enabled',coalesce(s.enabled,true),'firstMeal',coalesce(s.first_meal,'dinner'),'lastMeal',coalesce(s.last_meal,'lunch'),'prices',jsonb_build_object('breakfast',coalesce(s.breakfast_price,0),'lunch',coalesce(s.lunch_price,0),'dinner',coalesce(s.dinner_price,0)),'revision',coalesce(s.revision,0)),
    'priceOverrides',coalesce((select jsonb_agg(jsonb_build_object('id',id,'day',day_number,'meal',meal,'price',price,'revision',revision) order by day_number,meal) from public.conference_restaurant_price_overrides where conference_id=p_conference),'[]'),
    'countOverrides',coalesce((select jsonb_agg(jsonb_build_object('id',id,'day',day_number,'meal',meal,'extra',extra_count,'deduction',deduction_count,'note',note,'revision',revision) order by day_number,meal) from public.conference_restaurant_count_overrides where conference_id=p_conference),'[]'),
    'participationOverrides',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'participationId',o.participation_id,'day',o.day_number,'meal',o.meal,'included',o.included,'note',o.note,'revision',o.revision) order by o.day_number,o.meal,o.participation_id) from public.conference_restaurant_participation_overrides o where o.conference_id=p_conference),'[]'),
    'participations',coalesce((select jsonb_agg(jsonb_build_object('participationId',p.id,'status',p.status,'person',jsonb_build_object('personId',person.id,'fullName',person.full_name,'phone',person.phone),'roomNumber',room.room_number) order by person.full_name,p.id) from public.conference_participations p join platform.people person on person.id=p.person_id left join lateral (select o.room_id from public.conference_accommodation_occupancies o where o.participation_id=p.id and o.arrival_day<=platform_private.conference_operational_day(p.conference_id) and coalesce(o.leave_day,platform_private.conference_accommodation_duration(p.conference_id)+1)>platform_private.conference_operational_day(p.conference_id) order by o.arrival_day desc,o.id limit 1) occupancy on true left join public.conference_accommodation_rooms room on room.id=occupancy.room_id where p.conference_id=p_conference),'[]'));
end $$;


--
-- Name: get_conference_section_lock("uuid", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_conference_section_lock"("p_conference_id" "uuid", "p_section" "text", "p_device_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare current_user_id uuid; normalized_section text:=lower(trim(coalesce(p_section,''))); current_lock public.conference_locks%rowtype; server_now timestamptz:=clock_timestamp(); owned_by_requester boolean;
begin
 if p_conference_id is null or p_device_id is null or normalized_section !~ '^[a-z][a-z0-9_]{0,31}$' then raise exception 'INVALID_CONFERENCE_SECTION_LOCK_ARGUMENTS' using errcode='22023'; end if;
 current_user_id:=public.require_conference_section_lock_writer(p_conference_id,p_device_id,normalized_section); select * into current_lock from public.conference_locks as locks where locks.conference_id=p_conference_id and locks.section=normalized_section;
 if not found then return jsonb_build_object('success',true,'status','not_found','conferenceId',p_conference_id,'section',normalized_section,'locked',false,'owned',false,'serverNow',server_now,'isExpired',false); end if;
 owned_by_requester:=current_lock.user_id=current_user_id and current_lock.device_id=p_device_id; return jsonb_strip_nulls(jsonb_build_object('success',true,'status',case when current_lock.expires_at<=server_now then 'not_found' else 'locked' end,'conferenceId',p_conference_id,'section',normalized_section,'locked',current_lock.expires_at>server_now,'owned',owned_by_requester and current_lock.expires_at>server_now,'lockToken',case when owned_by_requester then current_lock.lock_token else null end,'userId',current_lock.user_id,'deviceId',current_lock.device_id,'acquiredAt',current_lock.acquired_at,'expiresAt',current_lock.expires_at,'lastRenewedAt',current_lock.last_renewed_at,'serverNow',server_now,'isExpired',current_lock.expires_at<=server_now));
end; $_$;


--
-- Name: get_conference_transport("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_conference_transport"("p_actor_device_id" "uuid", "p_conference_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c jsonb; vehicles jsonb; assignments jsonb; can_manage boolean:=false;
begin
  c:=platform_private.require_conference_transport_context(p_actor_device_id,p_conference_id,'conference.transport.view',false);
  begin
    perform public.require_effective_module_permission(p_actor_device_id,'conference','conference.transport.manage','conference',p_conference_id::text);
    can_manage:=true;
  exception when insufficient_privilege then null;
  end;
  select coalesce(jsonb_agg(jsonb_build_object('vehicleId',v.id,'name',v.name,'icon',v.icon,'capacity',v.capacity,'position',v.position,'revision',v.revision) order by v.position,v.id),'[]') into vehicles from public.conference_transport_vehicles v where v.conference_id=p_conference_id;
  select coalesce(jsonb_agg(jsonb_build_object('assignmentId',a.id,'vehicleId',a.vehicle_id,'participationId',a.participation_id,'mode',a.assignment_mode,'riderKind',a.rider_kind,'seatNumber',a.seat_number,'revision',a.revision,'participationStatus',p.status,'person',jsonb_build_object('personId',p.person_id,'fullName',person.full_name,'phone',person.phone),'guardianParticipationId',p.guardian_participation_id,'guardianParticipationStatus',gp.status,'guardianFullName',gperson.full_name,'roomNumber',room.room_number,'sharingEligible',a.assignment_mode<>'shared' or gp.status='active') order by a.vehicle_id,a.seat_number nulls last,a.id),'[]') into assignments
  from public.conference_transport_assignments a join public.conference_participations p on p.id=a.participation_id
  join platform.people person on person.id=p.person_id left join public.conference_participations gp on gp.id=p.guardian_participation_id
  left join platform.people gperson on gperson.id=gp.person_id left join lateral (select stay.room_id from public.conference_accommodation_occupancies stay where stay.participation_id=p.id and stay.arrival_day<=platform_private.conference_operational_day(p.conference_id) and coalesce(stay.leave_day,platform_private.conference_accommodation_duration(p.conference_id)+1)>platform_private.conference_operational_day(p.conference_id) order by stay.arrival_day desc,stay.id limit 1) o on true
  left join public.conference_accommodation_rooms room on room.id=o.room_id where a.conference_id=p_conference_id;
  return jsonb_build_object('conferenceId',p_conference_id,'canManage',can_manage,'vehicles',vehicles,'assignments',assignments);
end $$;


--
-- Name: get_first_system_bootstrap_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_first_system_bootstrap_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid:=auth.uid(); intended_id uuid;
begin
 if actor_id is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if exists(select 1 from platform.user_roles a join platform.roles r on r.id=a.role_id where r.domain='platform' and r.code='platform_owner' and a.revoked_at is null)
   or exists(select 1 from public.system_bootstrap_state where singleton_id=1 and completed_at is not null) then
  return pg_catalog.jsonb_build_object('status','completed','setupRequired',false);
 end if;
 select intended_user_id into intended_id from public.system_bootstrap_secret where singleton_id=1;
 if not found then return pg_catalog.jsonb_build_object('status','not_provisioned','setupRequired',false); end if;
 if intended_id<>actor_id then return pg_catalog.jsonb_build_object('status','not_authorized','setupRequired',false); end if;
 return pg_catalog.jsonb_build_object('status','setup_required','setupRequired',true);
end $$;


--
-- Name: get_my_platform_system_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_my_platform_system_access"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_user_id uuid:=auth.uid(); v_profile platform.profiles%rowtype;
begin
 if v_user_id is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into v_profile from platform.profiles where user_id=v_user_id;
 if not found then raise exception 'PLATFORM_PROFILE_NOT_FOUND' using errcode='P0002'; end if;
 return pg_catalog.jsonb_build_object(
  'userId',v_user_id,
  'accountStatus',v_profile.account_status,
  'systemRoles',coalesce((
   select pg_catalog.jsonb_agg(case r.code when 'platform_owner' then 'system_owner' when 'platform_admin' then 'system_admin' else r.code end order by r.code)
   from platform.user_roles a join platform.roles r on r.id=a.role_id
   where a.user_id=v_user_id and a.revoked_at is null
    and (a.expires_at is null or a.expires_at>pg_catalog.now())
    and r.domain='platform' and a.scope_type='platform' and a.scope_id is null
  ),'[]'::jsonb),
  'checkedAt',pg_catalog.clock_timestamp()
 );
end $$;


--
-- Name: get_stable_development_platform_device_recovery_material("uuid", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_stable_development_platform_device_recovery_material"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_session_id" "uuid", "p_challenge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare challenge platform_private.stable_device_recovery_challenges%rowtype;
  recovery platform_private.stable_device_recovery_authorizations%rowtype;
  credential public.device_security_credentials%rowtype;
begin
  perform public.require_platform_device_backend();
  select * into challenge from platform_private.stable_device_recovery_challenges item
  where item.id=p_challenge_id and item.session_id=p_session_id for update;
  if not found or challenge.verified_at is not null or challenge.consumed_at is not null
    or challenge.failed_at is not null or challenge.expires_at<=pg_catalog.statement_timestamp() then
    raise exception 'STABLE_DEVICE_RECOVERY_CHALLENGE_INVALID' using errcode='42501';
  end if;
  select * into recovery from platform_private.stable_device_recovery_authorizations item
  where item.id=challenge.recovery_authorization_id and item.owner_user_id=p_actor_user_id
    and item.target_device_id=p_actor_device_id
    and item.issuance_basis='reviewed_platform_owner_passkey_recovery'
    and item.consumed_at is null and pg_catalog.statement_timestamp()<=item.expires_at;
  if not found then
    raise exception 'STABLE_DEVICE_RECOVERY_AUTHORIZATION_INVALID' using errcode='42501';
  end if;
  credential:=platform_private.require_platform_owner_recovery_credential(
    recovery.owner_user_id,challenge.credential_id);
  return pg_catalog.jsonb_build_object('credentialId',credential.id,
    'credentialExternalId',pg_catalog.encode(credential.webauthn_credential_id,'base64'),
    'publicKeyCose',pg_catalog.translate(pg_catalog.encode(credential.public_key_cose,'base64'),E'\n\r',''),
    'signCount',credential.sign_count,'transports',credential.transports,
    'expectedOrigin',recovery.expected_origin,'expectedRpId',recovery.expected_rp_id,
    'targetDeviceId',recovery.target_device_id);
end; $$;


--
-- Name: get_stable_development_platform_device_recovery_state("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_stable_development_platform_device_recovery_state"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare recovery platform_private.stable_device_recovery_authorizations%rowtype;
  credential public.device_security_credentials%rowtype;
begin
  perform public.require_platform_device_backend();
  if p_actor_user_id is null or p_actor_device_id is null then
    raise exception 'STABLE_DEVICE_RECOVERY_TARGET_REQUIRED' using errcode='22023';
  end if;
  select * into recovery
  from platform_private.stable_device_recovery_authorizations item
  where item.owner_user_id=p_actor_user_id
    and item.target_device_id=p_actor_device_id
    and item.issuance_basis='reviewed_platform_owner_passkey_recovery'
    and item.environment='development_preview'
    and item.expected_origin='https://ramyawny37.github.io'
    and item.expected_rp_id='ramyawny37.github.io'
    and item.review_reference is not null
    and item.consumed_at is null
    and pg_catalog.statement_timestamp() between item.issued_at and item.expires_at
  for update;
  if not found then
    raise exception 'STABLE_DEVICE_RECOVERY_AUTHORIZATION_INVALID' using errcode='42501';
  end if;
  if not exists(select 1 from platform.user_device_authorizations target_authorization
      join platform.devices device on device.id=target_authorization.device_id
      where target_authorization.id=recovery.target_authorization_id
        and target_authorization.user_id=recovery.owner_user_id
        and target_authorization.device_id=recovery.target_device_id
        and target_authorization.status='pending' and target_authorization.revoked_at is null
        and device.lifecycle_status='active' and device.retired_at is null
        and device.compromised_at is null) then
    raise exception 'STABLE_DEVICE_RECOVERY_TARGET_INVALID' using errcode='42501';
  end if;
  credential:=platform_private.require_platform_owner_recovery_credential(
    recovery.owner_user_id,recovery.credential_id);
  return pg_catalog.jsonb_build_object('status','ready','credentialId',credential.id,
    'targetDeviceId',recovery.target_device_id);
end; $$;


--
-- Name: get_system_owner_device_challenge_verification_material("uuid", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_system_owner_device_challenge_verification_material"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_session_id" "uuid", "p_challenge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare challenge public.device_possession_challenges%rowtype;
  credential public.device_security_credentials%rowtype;
begin
  perform public.require_platform_device_backend();
  select * into challenge from public.device_possession_challenges stored
  where stored.id=p_challenge_id and stored.user_id=p_actor_user_id
    and stored.actor_device_id=p_actor_device_id and stored.session_id=p_session_id;
  if not found or challenge.credential_id is null or challenge.verified_at is not null
    or challenge.consumed_at is not null or challenge.failed_at is not null
    or challenge.expires_at<=pg_catalog.statement_timestamp() then
    raise exception 'PLATFORM_DEVICE_CHALLENGE_NOT_VERIFIABLE' using errcode='42501';
  end if;
  credential:=public.require_system_owner_webauthn_actor(
    p_actor_user_id,p_actor_device_id,challenge.credential_id);
  return pg_catalog.jsonb_build_object('credentialId',credential.id,
    'credentialExternalId',pg_catalog.encode(credential.webauthn_credential_id,'base64'),
    'publicKeyCose',pg_catalog.replace(pg_catalog.replace(
      pg_catalog.encode(credential.public_key_cose,'base64'),pg_catalog.chr(10),''),
      pg_catalog.chr(13),''),
    'signCount',credential.sign_count,'transports',credential.transports,
    'purpose',challenge.purpose,'targetUserId',challenge.target_user_id,
    'targetDeviceId',challenge.target_device_id,'operationId',challenge.operation_id,
    'environment',challenge.environment,'expectedOrigin',challenge.expected_origin,
    'expectedRpId',challenge.expected_rp_id);
end; $$;


--
-- Name: get_system_owner_device_operation_result("uuid", "uuid", "uuid", "uuid", "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_system_owner_device_operation_result"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_target_user_id" "uuid", "p_target_device_id" "uuid", "p_action" "text", "p_environment" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare stored public.system_owner_device_authorization_operations%rowtype;
begin
  perform public.require_platform_device_backend();
  if not platform_private.is_canonical_platform_owner(p_actor_user_id) then
    raise exception 'APPROVED_SYSTEM_OWNER_DEVICE_REQUIRED' using errcode='42501';
  end if;
  perform platform_private.require_canonical_device_authorization(
    p_actor_user_id,p_actor_device_id,true);
  select * into stored from public.system_owner_device_authorization_operations operation
  where operation.operation_id=p_operation_id;
  if not found then return pg_catalog.jsonb_build_object('status','not_found'); end if;
  if stored.actor_user_id_snapshot<>p_actor_user_id
    or stored.actor_device_id<>p_actor_device_id
    or stored.target_user_id_snapshot<>p_target_user_id
    or stored.target_device_id<>p_target_device_id or stored.environment<>p_environment
    or stored.action<>(case p_action when 'approve' then 'approve_system_owner_pending_device'
      when 'reject' then 'reject_system_owner_pending_device'
      when 'revoke' then 'revoke_system_owner_device' else '' end) then
    raise exception 'PLATFORM_DEVICE_OPERATION_MISMATCH' using errcode='22023';
  end if;
  return pg_catalog.jsonb_build_object('status','completed','result',stored.stored_result);
end; $$;


--
-- Name: get_system_owner_platform_device_administration_state("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_system_owner_platform_device_administration_state"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare credential public.device_security_credentials%rowtype;
begin
  perform public.require_platform_device_backend();
  if not platform_private.is_canonical_platform_owner(p_actor_user_id) then
    raise exception 'APPROVED_SYSTEM_OWNER_DEVICE_REQUIRED' using errcode='42501';
  end if;
  perform platform_private.require_canonical_device_authorization(
    p_actor_user_id,p_actor_device_id,true);
  select * into credential from public.device_security_credentials stored
  where stored.user_id=p_actor_user_id and stored.credential_kind='platform_primary'
    and stored.lifecycle_status='active' and stored.user_verification_policy='required'
    and (not stored.backup_state or stored.backup_eligible)
    and ((stored.backup_eligible and stored.backup_state)
      or stored.device_id=p_actor_device_id)
  order by (stored.device_id=p_actor_device_id) desc,stored.activated_at desc limit 1;
  if not found then
    return pg_catalog.jsonb_build_object('status','enrollment_required');
  end if;
  return pg_catalog.jsonb_build_object('status','ready','credentialId',credential.id,
    'credentialExternalId',pg_catalog.encode(credential.webauthn_credential_id,'base64'),
    'transports',credential.transports);
end; $$;


--
-- Name: get_user_management_account("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_user_management_account"("p_actor_device_id" "uuid", "p_target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid;target_profile platform.profiles%rowtype;can_manage boolean;
begin
 if p_target_user_id is null then raise exception 'TARGET_USER_REQUIRED' using errcode='22023'; end if;
 actor_id:=public.require_current_approved_device(p_actor_device_id);
 if not platform_private.user_has_module_permission_for(actor_id,'platform.users.view',null,null)
 then raise exception 'ACCOUNT_READ_SCOPE_DENIED' using errcode='42501'; end if;
 select * into target_profile from platform.profiles where user_id=p_target_user_id;
 if not found then raise exception 'PROFILE_NOT_FOUND' using errcode='P0002'; end if;
 can_manage:=public.is_system_owner(actor_id) and actor_id<>p_target_user_id
             and not public.is_system_owner(p_target_user_id);
 return pg_catalog.jsonb_build_object(
  'status','success',
  'account',pg_catalog.jsonb_build_object(
   'accountStatus',target_profile.account_status,
   'capabilities',pg_catalog.jsonb_build_object(
    'canBlock',can_manage and target_profile.account_status='approved',
    'canUnblock',can_manage and target_profile.account_status='blocked'
   )
  )
 );
end $$;


--
-- Name: get_user_management_actor_capabilities("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_user_management_actor_capabilities"("p_actor_device_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid;
begin
 actor_id:=public.require_current_approved_device(p_actor_device_id);
 if not platform_private.user_has_module_permission_for(actor_id,'platform.users.view',null,null)
  and not platform_private.user_has_module_permission_for(actor_id,'platform.roles.view',null,null)
  and not platform_private.user_has_module_permission_for(actor_id,'platform.devices.view',null,null)
 then raise exception 'USER_MANAGEMENT_SCOPE_DENIED' using errcode='42501'; end if;
 return jsonb_build_object('status','success',
  'canOpenUserManagement',platform_private.user_has_module_permission_for(actor_id,'platform.users.view',null,null),
  'canViewAccount',platform_private.user_has_module_permission_for(actor_id,'platform.users.view',null,null),
  'canManageAccount',platform_private.user_has_module_permission_for(actor_id,'platform.users.manage',null,null),
  'canViewDevices',platform_private.user_has_module_permission_for(actor_id,'platform.devices.view',null,null),
  'canManageDevices',platform_private.user_has_module_permission_for(actor_id,'platform.devices.approve',null,null)
    or platform_private.user_has_module_permission_for(actor_id,'platform.devices.block',null,null)
    or platform_private.user_has_module_permission_for(actor_id,'platform.devices.revoke',null,null),
  'canViewRoles',platform_private.user_has_module_permission_for(actor_id,'platform.roles.view',null,null),
  'canManageRoles',platform_private.user_has_module_permission_for(actor_id,'platform.roles.manage',null,null),
  'canViewAudit',platform_private.user_has_module_permission_for(actor_id,'platform.audit.view',null,null),
  'canManageSecurity',platform_private.user_has_module_permission_for(actor_id,'platform.access.manage',null,null));
end $$;


--
-- Name: get_user_management_devices("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_user_management_devices"("p_actor_device_id" "uuid", "p_target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid;
begin
  if p_target_user_id is null then
    raise exception 'TARGET_USER_REQUIRED' using errcode='22023';
  end if;
  actor_id:=public.require_current_approved_device(p_actor_device_id);
  if not platform_private.user_has_module_permission_for(
    actor_id,'platform.devices.view',null,null
  ) then
    raise exception 'DEVICE_READ_SCOPE_DENIED' using errcode='42501';
  end if;
  return pg_catalog.jsonb_build_object('status','success','devices',
    coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'deviceId',da.device_id,'deviceName',d.display_name,'platform',d.platform,
      'lastSeenAt',d.last_seen_at,'authorizationStatus',da.status,
      'requestedAt',da.requested_at,'approvedAt',da.approved_at,
      'revokedAt',da.revoked_at,'lastRegisteredAt',da.last_authorized_seen_at,
      'capabilities',pg_catalog.jsonb_build_object(
        'canApprove',platform_private.user_has_module_permission_for(actor_id,'platform.devices.approve',null,null) and da.status='pending',
        'canReject',platform_private.user_has_module_permission_for(actor_id,'platform.devices.block',null,null) and da.status='pending',
        'canRevoke',platform_private.user_has_module_permission_for(actor_id,'platform.devices.revoke',null,null) and da.status='approved'
      )
    ) order by da.created_at,da.device_id)
    from platform.user_device_authorizations da
    join platform.devices d on d.id=da.device_id
    where da.user_id=p_target_user_id and da.status in ('pending','approved')
    ),'[]'::jsonb));
end $$;


--
-- Name: get_user_management_overview("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_user_management_overview"("p_actor_device_id" "uuid", "p_target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid;target_user auth.users%rowtype;target_profile platform.profiles%rowtype;
begin
 if p_target_user_id is null then raise exception 'TARGET_USER_REQUIRED' using errcode='22023'; end if;
 actor_id:=public.require_current_approved_device(p_actor_device_id);
 if not platform_private.user_has_module_permission_for(actor_id,'platform.users.view',null,null) then raise exception 'USER_MANAGEMENT_SCOPE_DENIED' using errcode='42501'; end if;
 select * into target_user from auth.users where id=p_target_user_id;
 if not found then raise exception 'TARGET_USER_NOT_FOUND' using errcode='P0002'; end if;
 select * into target_profile from platform.profiles where user_id=p_target_user_id;
 if not found then raise exception 'PROFILE_NOT_FOUND' using errcode='P0002'; end if;
 return jsonb_build_object('status','success','user',jsonb_build_object('userId',target_user.id,'displayName',target_profile.display_name,'email',target_user.email),'account',jsonb_build_object('accountStatus',target_profile.account_status),'capabilities',public.get_user_management_actor_capabilities(p_actor_device_id)-'status');
end $$;


--
-- Name: guard_device_authorization_security_credential_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_device_authorization_security_credential_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op='DELETE' then
    if exists(select 1 from public.device_security_credentials credentials
      where credentials.user_id=old.user_id and credentials.device_id=old.device_id
        and credentials.lifecycle_status<>'revoked') then
      raise exception 'DEVICE_AUTHORIZATION_HAS_LIVE_SECURITY_CREDENTIAL' using errcode='42501';
    end if;
    return old;
  end if;
  if (new.authorization_status='revoked' or new.revoked_at is not null)
    and exists(select 1 from public.device_security_credentials credentials
      where credentials.user_id=old.user_id and credentials.device_id=old.device_id
        and credentials.lifecycle_status<>'revoked') then
    raise exception 'DEVICE_AUTHORIZATION_HAS_LIVE_SECURITY_CREDENTIAL' using errcode='42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_device_possession_challenge_consumer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_device_possession_challenge_consumer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  challenge_row public.device_possession_challenges%rowtype;
begin
  if tg_op<>'INSERT' then
    raise exception 'DEVICE_POSSESSION_CHALLENGE_CONSUMER_IMMUTABLE' using errcode='42501';
  end if;
  select * into challenge_row from public.device_possession_challenges challenges
    where challenges.id=new.challenge_id and challenges.user_id=new.user_id
      and challenges.session_id=new.session_id
      and challenges.actor_device_id=new.actor_device_id
      and challenges.credential_id is not distinct from new.actor_credential_id
      and challenges.purpose=new.challenge_purpose
      and challenges.environment=new.environment
    for update;
  if not found or challenge_row.verified_at is null
    or challenge_row.failed_at is not null or challenge_row.consumed_at is not null
    or challenge_row.expires_at<=now() then
    raise exception 'DEVICE_POSSESSION_CHALLENGE_NOT_CONSUMABLE' using errcode='42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_device_possession_challenge_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_device_possession_challenge_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op='INSERT' then
    if new.verified_at is not null or new.consumed_at is not null
      or new.failed_at is not null or new.failure_code is not null
      or new.verification_context is not null then
      raise exception 'DEVICE_POSSESSION_CHALLENGE_INITIAL_STATE_INVALID' using errcode='42501';
    end if;
    return new;
  end if;
  if tg_op='DELETE' then
    raise exception 'DEVICE_POSSESSION_CHALLENGE_DELETE_FORBIDDEN' using errcode='42501';
  end if;
  if new.id<>old.id or new.challenge_hash<>old.challenge_hash
    or new.user_id<>old.user_id or new.session_id<>old.session_id
    or new.actor_device_id<>old.actor_device_id
    or new.credential_id is distinct from old.credential_id
    or new.purpose<>old.purpose
    or new.target_user_id is distinct from old.target_user_id
    or new.target_device_id is distinct from old.target_device_id
    or new.replaced_device_id is distinct from old.replaced_device_id
    or new.replacement_device_id is distinct from old.replacement_device_id
    or new.operation_id is distinct from old.operation_id
    or new.expected_origin<>old.expected_origin
    or new.expected_rp_id<>old.expected_rp_id
    or new.environment<>old.environment
    or new.expires_at<>old.expires_at or new.created_at<>old.created_at then
    raise exception 'DEVICE_POSSESSION_CHALLENGE_BINDING_IMMUTABLE' using errcode='42501';
  end if;
  if old.consumed_at is not null or old.failed_at is not null then
    raise exception 'DEVICE_POSSESSION_CHALLENGE_TERMINAL' using errcode='42501';
  end if;
  if old.verified_at is null and new.verified_at is not null then
    if new.failed_at is not null or new.consumed_at is not null
      or new.verification_context is null or new.verification_context='{}'::jsonb then
      raise exception 'DEVICE_POSSESSION_CHALLENGE_VERIFICATION_INVALID' using errcode='42501';
    end if;
  elsif new.verified_at is distinct from old.verified_at
    or new.verification_context is distinct from old.verification_context then
    raise exception 'DEVICE_POSSESSION_CHALLENGE_VERIFICATION_IMMUTABLE' using errcode='42501';
  end if;
  if old.verified_at is not null and new.failed_at is not null then
    raise exception 'DEVICE_POSSESSION_CHALLENGE_VERIFIED_CANNOT_FAIL' using errcode='42501';
  end if;
  if new.consumed_at is not null and old.verified_at is null then
    raise exception 'DEVICE_POSSESSION_CHALLENGE_CONSUME_REQUIRES_VERIFICATION' using errcode='42501';
  end if;
  if old.consumed_at is null and new.consumed_at is not null and new.failed_at is not null then
    raise exception 'DEVICE_POSSESSION_CHALLENGE_TERMINAL_CONFLICT' using errcode='42501';
  end if;
  if old.consumed_at is null and new.consumed_at is not null
    and not exists(select 1 from public.device_possession_challenge_consumers consumers
      where consumers.challenge_id=old.id and consumers.challenge_purpose=old.purpose) then
    raise exception 'DEVICE_POSSESSION_CHALLENGE_CONSUMER_REQUIRED' using errcode='42501';
  end if;
  if old.failed_at is null and new.failed_at is not null and new.verified_at is not null then
    raise exception 'DEVICE_POSSESSION_CHALLENGE_FAILURE_INVALID' using errcode='42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_device_security_credential_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_device_security_credential_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare recovery_counter_update boolean:=false;
  owner_assertion_counter_update boolean:=false;
  counter_only_update boolean:=false;
begin
  if tg_op='INSERT' then
    if new.lifecycle_status<>'enrollment_pending' then
      raise exception 'DEVICE_SECURITY_CREDENTIAL_MUST_ENROLL_PENDING' using errcode='42501';
    end if;
    perform platform_private.require_canonical_device_authorization(new.user_id,new.device_id,true);
    return new;
  end if;
  if tg_op='DELETE' then
    raise exception 'DEVICE_SECURITY_CREDENTIAL_DELETE_FORBIDDEN' using errcode='42501';
  end if;
  if new.id<>old.id or new.webauthn_credential_id<>old.webauthn_credential_id
    or new.user_id<>old.user_id or new.device_id<>old.device_id
    or new.credential_kind<>old.credential_kind or new.public_key_cose<>old.public_key_cose
    or new.public_key_algorithm<>old.public_key_algorithm or new.aaguid is distinct from old.aaguid
    or new.transports<>old.transports or new.backup_eligible<>old.backup_eligible
    or new.backup_state<>old.backup_state or new.user_verification_policy<>old.user_verification_policy
    or new.created_at<>old.created_at then
    raise exception 'DEVICE_SECURITY_CREDENTIAL_IDENTITY_IMMUTABLE' using errcode='42501';
  end if;
  if (old.enrolled_at is not null and new.enrolled_at is distinct from old.enrolled_at)
    or (old.activated_at is not null and new.activated_at is distinct from old.activated_at)
    or (old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at) then
    raise exception 'DEVICE_SECURITY_CREDENTIAL_SECURITY_TIME_IMMUTABLE' using errcode='42501';
  end if;
  if old.lifecycle_status='revoked'
    or (old.lifecycle_status='enrollment_pending' and new.lifecycle_status not in ('enrollment_pending','active','revoked'))
    or (old.lifecycle_status='active' and new.lifecycle_status not in ('active','rotation_pending','recovery_required','revoked'))
    or (old.lifecycle_status='rotation_pending' and new.lifecycle_status not in ('rotation_pending','active','recovery_required','revoked'))
    or (old.lifecycle_status='recovery_required' and new.lifecycle_status not in ('recovery_required','revoked')) then
    raise exception 'DEVICE_SECURITY_CREDENTIAL_TRANSITION_INVALID' using errcode='42501';
  end if;
  if new.sign_count<old.sign_count then
    raise exception 'DEVICE_SECURITY_CREDENTIAL_COUNTER_REGRESSION' using errcode='42501';
  end if;
  counter_only_update:=new.lifecycle_status='active' and old.lifecycle_status='active'
    and (pg_catalog.to_jsonb(new)-array['sign_count','last_used_at']::text[])
      =(pg_catalog.to_jsonb(old)-array['sign_count','last_used_at']::text[])
    and new.last_used_at is not null
    and (old.last_used_at is null or new.last_used_at>=old.last_used_at);
  if counter_only_update and new.credential_kind='platform_primary'
    and new.user_verification_policy='required' and new.backup_eligible and new.backup_state then
    select exists(select 1 from public.device_possession_challenges challenge
      join platform.user_device_authorizations actor_authorization
        on actor_authorization.user_id=challenge.user_id
       and actor_authorization.device_id=challenge.actor_device_id
      join platform.devices actor_device on actor_device.id=challenge.actor_device_id
      join platform.profiles actor_profile on actor_profile.user_id=challenge.user_id
      where challenge.user_id=new.user_id and challenge.credential_id=new.id
        and challenge.purpose in ('SYSTEM_OWNER_PENDING_DEVICE_LIST',
          'SYSTEM_OWNER_PENDING_DEVICE_APPROVE','SYSTEM_OWNER_PENDING_DEVICE_REJECT',
          'SYSTEM_OWNER_DEVICE_REVOKE')
        and challenge.verified_at is not null and challenge.consumed_at is null
        and challenge.failed_at is null and challenge.expires_at>pg_catalog.statement_timestamp()
        and challenge.verification_context->'userVerified'='true'::jsonb
        and (challenge.verification_context->>'backupEligible')::boolean is true
        and (challenge.verification_context->>'backupState')::boolean is true
        and actor_authorization.status='approved' and actor_authorization.revoked_at is null
        and actor_device.lifecycle_status='active' and actor_device.retired_at is null
        and actor_device.compromised_at is null and actor_profile.account_status='approved'
        and platform_private.is_canonical_platform_owner(challenge.user_id)
        and exists(select 1 from platform.device_key_bindings binding
          where binding.user_id=actor_authorization.user_id
            and binding.device_id=actor_authorization.device_id
            and binding.device_authorization_id=actor_authorization.id
            and binding.lifecycle_status='active' and binding.revoked_at is null
            and binding.retired_at is null)) into owner_assertion_counter_update;
  end if;
  if counter_only_update and not owner_assertion_counter_update then
    select exists(select 1 from platform_private.stable_device_recovery_authorizations recovery
      join platform_private.stable_device_recovery_challenges challenge
        on challenge.recovery_authorization_id=recovery.id and challenge.credential_id=recovery.credential_id
      join platform.user_device_authorizations target_authorization
        on target_authorization.id=recovery.target_authorization_id
       and target_authorization.user_id=recovery.owner_user_id
       and target_authorization.device_id=recovery.target_device_id
      join platform.devices target_device on target_device.id=recovery.target_device_id
      where recovery.owner_user_id=new.user_id and recovery.credential_id=new.id
        and recovery.issuance_basis='reviewed_platform_owner_passkey_recovery'
        and recovery.review_reference is not null and recovery.environment='development_preview'
        and recovery.expected_origin='https://ramyawny37.github.io'
        and recovery.expected_rp_id='ramyawny37.github.io' and recovery.consumed_at is null
        and pg_catalog.statement_timestamp() between recovery.issued_at and recovery.expires_at
        and target_authorization.status='pending' and target_authorization.revoked_at is null
        and target_device.lifecycle_status='active' and target_device.retired_at is null
        and target_device.compromised_at is null and challenge.verified_at is not null
        and challenge.consumed_at is null and challenge.failed_at is null
        and challenge.expires_at>pg_catalog.statement_timestamp()
        and challenge.verification_context->'userVerified'='true'::jsonb
        and (challenge.verification_context->>'backupEligible')::boolean is not distinct from new.backup_eligible
        and (challenge.verification_context->>'backupState')::boolean is not distinct from new.backup_state
        and (not (challenge.verification_context->>'backupState')::boolean
          or (challenge.verification_context->>'backupEligible')::boolean)) into recovery_counter_update;
  end if;
  if new.lifecycle_status='active'
    and not recovery_counter_update and not owner_assertion_counter_update then
    perform platform_private.require_canonical_device_authorization(new.user_id,new.device_id,true);
  end if;
  return new;
end; $$;


--
-- Name: guard_privileged_device_listing_session_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_privileged_device_listing_session_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op='INSERT' then
    perform 1 from public.device_possession_challenges challenges
      where challenges.id=new.source_challenge_id
        and challenges.user_id=new.user_id and challenges.session_id=new.session_id
        and challenges.actor_device_id=new.actor_device_id
        and challenges.credential_id=new.credential_id
        and challenges.purpose='SYSTEM_OWNER_PENDING_DEVICE_LIST'
        and challenges.verified_at is not null
        and challenges.failed_at is null and challenges.consumed_at is null
        and challenges.expires_at>now()
      for update;
    if not found then
      raise exception 'PRIVILEGED_LISTING_SESSION_SOURCE_CHALLENGE_INVALID' using errcode='42501';
    end if;
    return new;
  end if;
  if tg_op='DELETE' then
    raise exception 'PRIVILEGED_LISTING_SESSION_DELETE_FORBIDDEN' using errcode='42501';
  end if;
  if new.id<>old.id or new.opaque_token_hash<>old.opaque_token_hash
    or new.user_id<>old.user_id or new.session_id<>old.session_id
    or new.actor_device_id<>old.actor_device_id or new.credential_id<>old.credential_id
    or new.source_challenge_id<>old.source_challenge_id
    or new.source_challenge_purpose<>old.source_challenge_purpose
    or new.environment<>old.environment
    or new.scope<>old.scope or new.issued_at<>old.issued_at or new.expires_at<>old.expires_at then
    raise exception 'PRIVILEGED_LISTING_SESSION_BINDING_IMMUTABLE' using errcode='42501';
  end if;
  if old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
    raise exception 'PRIVILEGED_LISTING_SESSION_REVOKED_TERMINAL' using errcode='42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_system_owner_bootstrap_authorization_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_system_owner_bootstrap_authorization_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op='INSERT' then
    if new.consumed_at is not null then
      raise exception 'SYSTEM_OWNER_BOOTSTRAP_INITIAL_STATE_INVALID' using errcode='42501';
    end if;
    return new;
  end if;
  if tg_op='DELETE' then
    raise exception 'SYSTEM_OWNER_BOOTSTRAP_DELETE_FORBIDDEN' using errcode='42501';
  end if;
  if new.id<>old.id or new.authorization_hash<>old.authorization_hash
    or new.intended_user_id<>old.intended_user_id or new.intended_device_id<>old.intended_device_id
    or new.environment<>old.environment or new.purpose<>old.purpose
    or new.intended_device_authorization_status<>old.intended_device_authorization_status
    or new.intended_device_revoked_at is distinct from old.intended_device_revoked_at
    or new.intended_user_system_owner<>old.intended_user_system_owner
    or new.issued_at<>old.issued_at or new.expires_at<>old.expires_at
    or new.operator_user_id<>old.operator_user_id or new.reason<>old.reason
    or new.issuance_audit_id<>old.issuance_audit_id then
    raise exception 'SYSTEM_OWNER_BOOTSTRAP_BINDING_IMMUTABLE' using errcode='42501';
  end if;
  if old.consumed_at is not null then
    raise exception 'SYSTEM_OWNER_BOOTSTRAP_CONSUMPTION_ONE_WAY' using errcode='42501';
  end if;
  if new.consumed_at is not null then
    raise exception 'SYSTEM_OWNER_BOOTSTRAP_CALLER_CONSUMED_AT_FORBIDDEN' using errcode='42501';
  end if;
  if statement_timestamp()<old.issued_at or statement_timestamp()>old.expires_at then
    raise exception 'SYSTEM_OWNER_BOOTSTRAP_CONSUMPTION_OUTSIDE_WINDOW' using errcode='42501';
  end if;
  new.consumed_at=statement_timestamp();
  return new;
end;
$$;


--
-- Name: guard_system_owner_recovery_authorization_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_system_owner_recovery_authorization_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op='INSERT' then
    if new.status<>'pending_wait' or new.consumed_at is not null
      or new.not_before<=new.issued_at then
      raise exception 'SYSTEM_OWNER_RECOVERY_INITIAL_STATE_INVALID' using errcode='42501';
    end if;
    return new;
  end if;
  if tg_op='DELETE' then
    raise exception 'SYSTEM_OWNER_RECOVERY_DELETE_FORBIDDEN' using errcode='42501';
  end if;
  if new.id<>old.id or new.intended_user_id<>old.intended_user_id
    or new.intended_device_id<>old.intended_device_id
    or new.authorizing_credential_id is distinct from old.authorizing_credential_id
    or new.operator_user_id is distinct from old.operator_user_id
    or new.recovery_method<>old.recovery_method or new.issued_at<>old.issued_at
    or new.environment<>old.environment
    or new.not_before<>old.not_before or new.expires_at<>old.expires_at
    or new.reason<>old.reason or new.issuance_audit_id<>old.issuance_audit_id then
    raise exception 'SYSTEM_OWNER_RECOVERY_BINDING_IMMUTABLE' using errcode='42501';
  end if;
  if old.status in ('consumed','revoked','expired') then
    raise exception 'SYSTEM_OWNER_RECOVERY_TERMINAL' using errcode='42501';
  end if;
  if old.status='pending_wait' and new.status='ready'
    and statement_timestamp()<old.not_before then
    raise exception 'SYSTEM_OWNER_RECOVERY_WAITING_PERIOD_ACTIVE' using errcode='42501';
  end if;
  if (old.status='pending_wait' and new.status not in ('pending_wait','ready','revoked','expired'))
    or (old.status='ready' and new.status not in ('ready','consumed','revoked','expired'))
    or (old.consumed_at is not null and new.consumed_at is distinct from old.consumed_at)
    or (old.consumed_at is null and new.status<>'consumed' and new.consumed_at is not null) then
    raise exception 'SYSTEM_OWNER_RECOVERY_TRANSITION_INVALID' using errcode='42501';
  end if;
  if old.status='ready' and new.status='consumed' then
    if new.consumed_at is not null then
      raise exception 'SYSTEM_OWNER_RECOVERY_CALLER_CONSUMED_AT_FORBIDDEN' using errcode='42501';
    end if;
    if statement_timestamp()<old.not_before or statement_timestamp()>old.expires_at then
      raise exception 'SYSTEM_OWNER_RECOVERY_CONSUMPTION_OUTSIDE_WINDOW' using errcode='42501';
    end if;
    new.consumed_at=statement_timestamp();
  end if;
  return new;
end;
$$;


--
-- Name: handle_new_user_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."handle_new_user_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_display_name text:=nullif(pg_catalog.btrim(coalesce(new.raw_user_meta_data->>'display_name',new.raw_user_meta_data->>'name','')),'');
begin
 insert into public.profiles(id,display_name) values(new.id,v_display_name) on conflict(id) do update set display_name=coalesce(public.profiles.display_name,excluded.display_name);
 insert into platform.profiles(user_id,display_name,account_status) values(new.id,v_display_name,'pending')
 on conflict(user_id) do update set display_name=coalesce(platform.profiles.display_name,excluded.display_name);
 return new;
end $$;


--
-- Name: is_account_approved("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."is_account_approved"("user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select user_id is not null and exists(
  select 1 from platform.profiles p
  where p.user_id=is_account_approved.user_id and p.account_status='approved'
 );
$$;


--
-- Name: is_system_admin("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."is_system_admin"("user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select user_id is not null and exists(
  select 1 from platform.user_roles a
  join platform.roles r on r.id=a.role_id
  where a.user_id=is_system_admin.user_id and a.revoked_at is null
    and (a.expires_at is null or a.expires_at>pg_catalog.now())
    and r.domain='platform' and r.code in ('platform_owner','platform_admin')
    and r.scope_type='platform' and a.scope_type='platform' and a.scope_id is null
 );
$$;


--
-- Name: is_system_owner("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."is_system_owner"("user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select user_id is not null and exists(
  select 1 from platform.user_roles a
  join platform.roles r on r.id=a.role_id
  where a.user_id=is_system_owner.user_id and a.revoked_at is null
    and (a.expires_at is null or a.expires_at>pg_catalog.now())
    and r.domain='platform' and r.code='platform_owner'
    and r.scope_type='platform' and a.scope_type='platform' and a.scope_id is null
 );
$$;


--
-- Name: issue_system_owner_credential_bootstrap_authorization("uuid", "uuid", "uuid", "uuid", "text", "bytea", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."issue_system_owner_credential_bootstrap_authorization"("p_operator_user_id" "uuid", "p_operator_device_id" "uuid", "p_intended_user_id" "uuid", "p_intended_device_id" "uuid", "p_environment" "text", "p_authorization_hash" "bytea", "p_origin" "text", "p_rp_id" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare audit_id uuid; authorization_id uuid;
begin
  perform public.require_platform_device_backend();
  if pg_catalog.octet_length(p_authorization_hash)<>32
    or pg_catalog.length(pg_catalog.btrim(coalesce(p_reason,''))) not between 1 and 500 then
    raise exception 'CREDENTIAL_BOOTSTRAP_ISSUANCE_ARGUMENT_INVALID' using errcode='22023';
  end if;
  if not platform_private.is_canonical_platform_owner(p_operator_user_id)
    or not platform_private.is_canonical_platform_owner(p_intended_user_id) then
    raise exception 'CREDENTIAL_BOOTSTRAP_APPROVED_SYSTEM_OWNER_DEVICE_REQUIRED' using errcode='42501';
  end if;
  perform platform_private.require_canonical_device_authorization(
    p_operator_user_id,p_operator_device_id,true);
  perform platform_private.require_canonical_device_authorization(
    p_intended_user_id,p_intended_device_id,true);
  insert into public.privileged_device_authorization_audit_log(actor_user_id,
    actor_user_id_snapshot,actor_device_id,actor_credential_id,session_id_hash,session_id,
    challenge_id,challenge_purpose,environment,target_user_id,target_user_id_snapshot,
    target_device_id,action,operation_id,result,origin,rp_id,user_verified,
    backup_eligible,backup_state,security_context)
  values(p_operator_user_id,p_operator_user_id,p_operator_device_id,null,
    extensions.digest('bootstrap-issuance:'||p_authorization_hash::text,'sha256'),
    null,null,null,p_environment,p_intended_user_id,p_intended_user_id,p_intended_device_id,
    'credential_bootstrap_authorization_issued',null,'issued',pg_catalog.lower(p_origin),
    pg_catalog.lower(p_rp_id),false,false,false,
    pg_catalog.jsonb_build_object('reason',pg_catalog.btrim(p_reason))) returning id into audit_id;
  insert into public.system_owner_credential_bootstrap_authorizations(authorization_hash,
    intended_user_id,intended_device_id,environment,intended_device_authorization_status,
    intended_device_revoked_at,intended_user_system_owner,expires_at,operator_user_id,reason,
    issuance_audit_id)
  values(p_authorization_hash,p_intended_user_id,p_intended_device_id,p_environment,
    'approved',null,true,pg_catalog.statement_timestamp()+interval '10 minutes',
    p_operator_user_id,pg_catalog.btrim(p_reason),audit_id) returning id into authorization_id;
  return pg_catalog.jsonb_build_object('status','issued','authorizationId',authorization_id,
    'expiresInSeconds',600,'auditId',audit_id);
end; $$;


--
-- Name: list_accessible_conferences("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_accessible_conferences"("p_actor_device_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_conference public.conferences%rowtype;
  v_items jsonb:='[]'::jsonb;
  v_capabilities jsonb;
  v_permission text;
  v_capability text;
begin
  perform public.require_current_approved_device(p_actor_device_id);
  for v_conference in
    select conferences.* from public.conferences conferences
    where conferences.deleted_at is null order by conferences.created_at,conferences.id
  loop
    begin
      perform public.require_effective_module_permission(
        p_actor_device_id,'conference','conference.access.view','conference',v_conference.id::text);
      v_capabilities:=jsonb_build_object('core',true);
      for v_permission,v_capability in select * from (values
        ('conference.people.view','people'),
        ('conference.people.manage','peopleManage'),
        ('conference.accommodation.view','accommodation'),
        ('conference.accommodation.manage','accommodationManage'),
        ('conference.air_conditioning.view','airConditioning'),
        ('conference.cards.view','branding'),
        ('conference.accounts.view','finance'),
        ('conference.transport.view','transport'),
        ('conference.restaurant.view','restaurant')
      ) permissions(permission_code,capability_key)
      loop
        begin
          perform public.require_effective_module_permission(
            p_actor_device_id,'conference',v_permission,'conference',v_conference.id::text);
          v_capabilities:=v_capabilities||jsonb_build_object(v_capability,true);
        exception when insufficient_privilege then
          v_capabilities:=v_capabilities||jsonb_build_object(v_capability,false);
        end;
      end loop;
      v_items:=v_items||jsonb_build_array(jsonb_build_object(
        'conferenceId',v_conference.id,'name',v_conference.name,
        'startDate',v_conference.start_date,'endDate',v_conference.end_date,
        'status',v_conference.status,'completedAt',v_conference.completed_at,
        'revision',v_conference.revision,'createdAt',v_conference.created_at,
        'updatedAt',v_conference.updated_at,'capabilities',v_capabilities));
    exception when insufficient_privilege then null;
    end;
  end loop;
  return jsonb_build_object('conferences',v_items);
end $$;


--
-- Name: list_conference_activity("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_conference_activity"("p_actor_device_id" "uuid", "p_conference_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  perform public.require_effective_module_permission(p_actor_device_id,'conference','conference.settings.view','conference',p_conference_id::text);
  select coalesce(jsonb_agg(jsonb_build_object(
    'eventId',e.id,'action',e.action,'entityId',e.entity_id,
    'person',case when e.action='platform.person.updated' then (select jsonb_build_object('personId',person.id,'fullName',person.full_name,'phone',person.phone,'church',person.church,'gender',person.gender,'dateOfBirth',person.date_of_birth,'revision',person.revision) from platform.people person where person.id=e.entity_id) else null end,
    'section',case when e.action='platform.person.updated' then 'people' when e.action like 'conference.branding.%' then 'settings' when e.action like 'conference.accommodation.%' then 'accommodation' when e.action like 'conference.output.%' then 'cards' else 'conference' end,
    'title',case e.action when 'conference.branding.changed' then 'تم تعديل هوية المؤتمر' when 'conference.output.card_shared' then 'تمت مشاركة كارت' when 'conference.output.card_printed' then 'تمت طباعة كارت' when 'conference.output.cards_printed' then 'تمت طباعة الكروت' else 'تم تحديث بيانات المؤتمر' end,
    'createdAt',e.occurred_at
  ) order by e.occurred_at desc,e.id desc),'[]'::jsonb) into result
  from (
    select event.* from platform.audit_events event
    where event.action in('conference.core.updated','conference.lifecycle.completed','conference.branding.changed','conference.participation.created','conference.participation.status_changed','conference.participation.guardian_changed','conference.participation.deleted','conference.accommodation.assigned','conference.accommodation.moved','conference.accommodation.removed','conference.accommodation.pricing_updated','conference.accommodation.pricing_room_excluded','conference.accommodation.pricing_room_included','conference.transport.assignment_set','conference.transport.assignment_removed','conference.restaurant.participation_override_removed','conference.air_conditioning.configuration_changed','conference.finance.changed','conference.output.card_shared','conference.output.card_printed','conference.output.cards_printed','platform.person.updated')
      and (
        event.module='conference' and event.metadata->>'conferenceId'=p_conference_id::text
        or event.action='platform.person.updated' and event.module='reservations'
          and exists(select 1 from reservations.events reservations_event where reservations_event.id::text=event.metadata->>'eventId' and reservations_event.conference_id=p_conference_id)
          and exists(select 1 from public.conference_participations participation where participation.conference_id=p_conference_id and participation.person_id=event.entity_id)
      )
    order by event.occurred_at desc,event.id desc limit 200
  ) e;
  return jsonb_build_object('conferenceId',p_conference_id,'items',result);
end $$;


--
-- Name: list_conference_house_room_options("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_conference_house_room_options"("p_device" "uuid", "p_conference" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare context jsonb;conf public.conferences%rowtype;result jsonb;
begin
 context:=platform_private.require_conference_accommodation_context(p_device,p_conference,'conference.accommodation.view',false);
 select * into conf from public.conferences where id=p_conference and deleted_at is null;if not found then raise exception 'CONFERENCE_CORE_NOT_FOUND' using errcode='P0002';end if;
 select coalesce(jsonb_agg(jsonb_build_object('houseId',h.id,'name',h.name,'isActive',h.is_active,'houseAssigned',ha.id is not null,'houseAssignmentRevision',ha.revision,'floors',(select coalesce(jsonb_agg(jsonb_build_object('floorId',f.id,'name',f.name,'rooms',(select coalesce(jsonb_agg(jsonb_build_object('roomId',r.id,'roomNumber',r.room_number,'assigned',mine.id is not null,'assignmentRevision',mine.revision,'available',mine.id is not null or blocker.conference_id is null,'unavailableReason',case when mine.id is not null or blocker.conference_id is null then null else 'ROOM_CONFERENCE_PERIOD_OVERLAP' end) order by r.position,r.id),'[]') from public.conference_accommodation_rooms r left join public.conference_room_assignments mine on mine.room_id=r.id and mine.conference_id=p_conference left join lateral(select a.conference_id from public.conference_room_assignments a join public.conferences c on c.id=a.conference_id where a.room_id=r.id and a.conference_id<>p_conference and c.deleted_at is null and conf.start_date<=c.end_date and c.start_date<=conf.end_date limit 1) blocker on true where r.floor_id=f.id)) order by f.position,f.id),'[]') from public.conference_accommodation_floors f where f.house_id=h.id)) order by h.position,h.id),'[]') into result from public.conference_accommodation_houses h left join public.conference_house_assignments ha on ha.house_id=h.id and ha.conference_id=p_conference;
 return jsonb_build_object('conferenceId',p_conference,'startDate',conf.start_date,'endDate',conf.end_date,'houses',result);
end $$;


--
-- Name: list_conference_houses("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_conference_houses"("p_device" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare context jsonb; result jsonb;
begin
 context:=platform_private.require_conference_house_directory_context(p_device,'conference.houses.view');
 select coalesce(jsonb_agg(jsonb_build_object('houseId',h.id,'name',h.name,'description',h.description,'position',h.position,'isActive',h.is_active,'revision',h.revision,'floors',
  (select coalesce(jsonb_agg(jsonb_build_object('floorId',f.id,'name',f.name,'position',f.position,'revision',f.revision,'rooms',
   (select coalesce(jsonb_agg(jsonb_build_object('roomId',r.id,'roomNumber',r.room_number,'baseCapacity',r.base_capacity,'extraBedCapacity',r.extra_bed_capacity,'notes',r.notes,'position',r.position,'revision',r.revision) order by r.position,r.id),'[]') from public.conference_accommodation_rooms r where r.floor_id=f.id)
  ) order by f.position,f.id),'[]') from public.conference_accommodation_floors f where f.house_id=h.id)
 ) order by h.position,h.id),'[]') into result from public.conference_accommodation_houses h;
 return jsonb_build_object('houses',result);
end $$;


--
-- Name: list_conference_participations("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_conference_participations"("p_actor_device_id" "uuid", "p_conference_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_context jsonb; v_items jsonb; v_total bigint; v_active bigint; v_apologized bigint;
begin
  v_context:=platform_private.require_conference_participation_context(p_actor_device_id,p_conference_id,'conference.people.view',false);
  select count(*),count(*) filter(where participation.status='active'),count(*) filter(where participation.status='apologized'),
    coalesce(jsonb_agg(jsonb_build_object('participationId',participation.id,'conferenceId',participation.conference_id,
      'personId',participation.person_id,'status',participation.status,'revision',participation.revision,
      'guardianParticipationId',guardian.id,'guardianPersonId',guardian_person.id,'guardianFullName',guardian_person.full_name,
      'guardianParticipationStatus',guardian.status,'createdAt',participation.created_at,'updatedAt',participation.updated_at,
      'createdBy',participation.created_by,'updatedBy',participation.updated_by,
      'person',jsonb_build_object('personId',person.id,'fullName',person.full_name,'phone',person.phone,
        'gender',person.gender,'dateOfBirth',person.date_of_birth,'church',person.church),
      'bookings',coalesce(booking_links.items,'[]'::jsonb)) order by participation.created_at,participation.id),'[]'::jsonb)
  into v_total,v_active,v_apologized,v_items
  from public.conference_participations participation
  join platform.people person on person.id=participation.person_id
  left join public.conference_participations guardian on guardian.id=participation.guardian_participation_id
  left join platform.people guardian_person on guardian_person.id=guardian.person_id
  left join lateral(
    select jsonb_agg(jsonb_build_object('bookingId',booking.id,'bookingNumber',booking.booking_number,
      'bookingTypeId',booking.booking_type_id,
      'bookingTypeNameSnapshot',booking.booking_type_name_snapshot,'priceSnapshot',booking.price_snapshot,
      'attendanceSegmentsSnapshot',booking.attendance_segments_snapshot,
      'attendancePeriods',(
        select coalesce(jsonb_agg(jsonb_build_object('kind',segment.kind,'label',coalesce(period.label,segment.kind)) order by segment.ordinality),'[]'::jsonb)
        from unnest(booking.attendance_segments_snapshot) with ordinality segment(kind,ordinality)
        left join reservations.event_periods period on period.event_id=booking.event_id and period.scope_partition_id=booking.scope_partition_id and period.kind=segment.kind
      ),'createdAt',booking.created_at)
      order by booking.created_at desc,booking.id desc) items
    from reservations.events event
    join reservations.bookings_operational booking on booking.event_id=event.id and booking.scope_partition_id=event.scope_partition_id
    join reservations.participants reservation_participant on reservation_participant.id=booking.participant_id and reservation_participant.scope_partition_id=booking.scope_partition_id
    where event.conference_id=p_conference_id and reservation_participant.person_id=participation.person_id
  ) booking_links on true
  where participation.conference_id=p_conference_id;
  return jsonb_build_object('conferenceId',p_conference_id,'totalCount',v_total,'activeCount',v_active,'apologizedCount',v_apologized,'items',v_items);
end $$;


--
-- Name: list_library_templates("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_library_templates"("p_actor_device_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  actor_id uuid:=auth.uid();
begin
  if actor_id is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;
  perform public.require_current_approved_device(p_actor_device_id);
  return jsonb_build_object(
    'status','success',
    'templates',coalesce((
      select jsonb_agg(jsonb_build_object(
        'templateType',template_type,
        'templateId',template_id,
        'payload',payload,
        'revision',revision,
        'deletedAt',deleted_at,
        'createdAt',created_at,
        'updatedAt',updated_at
      ) order by template_type,template_id)
      from public.library_templates
      where owner_user_id=actor_id
    ),'[]'::jsonb)
  );
end
$$;


--
-- Name: list_module_permission_catalog_for_administration("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_module_permission_catalog_for_administration"("p_actor_device_id" "uuid", "p_module_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a uuid;allowed boolean;
begin
 a:=public.require_current_approved_device(p_actor_device_id);
 if p_module_key not in('conference','warehouse','reservations') then raise exception 'ACTIVE_MODULE_REQUIRED' using errcode='42501'; end if;
 allowed:=platform_private.is_canonical_platform_owner(a) or platform_private.user_has_module_permission_for(a,p_module_key||'.module.manage',null,null);
 if not allowed and p_module_key='conference' then allowed:=exists(select 1 from public.conferences c where c.deleted_at is null and platform_private.user_has_module_permission_for(a,'conference.members.manage','conference',c.id::text)); end if;
 if not allowed then raise exception 'MODULE_PERMISSION_REQUIRED' using errcode='42501'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('permissionKey',p.code,'displayName',p.code,'description',p.description,'allowedScopeMode',p.allowed_scope_mode,'allowedResourceType',p.allowed_resource_type,'sensitiveMutation',p.sensitive_mutation,'catalogVersion',1) order by p.code) from platform.permissions p where p.domain=p_module_key and p.status='active' and p.code not in(p_module_key||'.module.access',p_module_key||'.module.manage')),'[]'::jsonb);
end $$;


--
-- Name: list_module_permission_grants("uuid", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_module_permission_grants"("p_actor_device_id" "uuid", "p_module_key" "text", "p_target_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a uuid;t uuid;owner_or_manager boolean;
begin
 a:=public.require_current_approved_device(p_actor_device_id);t:=coalesce(p_target_user_id,a);
 if p_module_key not in('conference','warehouse','reservations') then raise exception 'ACTIVE_MODULE_REQUIRED' using errcode='42501'; end if;
 owner_or_manager:=platform_private.is_canonical_platform_owner(a) or platform_private.user_has_module_permission_for(a,p_module_key||'.module.manage',null,null);
 if t<>a and not owner_or_manager and not(p_module_key='conference' and exists(select 1 from public.conferences c where c.deleted_at is null and platform_private.user_has_module_permission_for(a,'conference.members.manage','conference',c.id::text) and platform_private.user_has_module_permission_for(t,'conference.access.view','conference',c.id::text))) then raise exception 'MODULE_PERMISSION_REQUIRED' using errcode='42501'; end if;
 return jsonb_build_object('status','success','targetUserId',t,'moduleKey',p_module_key,
  'grants',coalesce((select jsonb_agg(jsonb_build_object('grantId',g.id,'permissionKey',p.code,'resourceType',g.resource_type,'resourceId',g.resource_id,'grantedAt',g.granted_at,'revokedAt',g.revoked_at,'source','direct') order by g.granted_at,g.id) from platform.permission_grants g join platform.permissions p on p.id=g.permission_id where g.user_id=t and p.domain=p_module_key and (owner_or_manager or g.resource_type<>'conference' or exists(select 1 from public.conferences c where c.id::text=g.resource_id and platform_private.user_has_module_permission_for(a,'conference.members.manage','conference',c.id::text)))),'[]'::jsonb),
  'roles',coalesce((select jsonb_agg(jsonb_build_object('roleCode',r.code,'displayName',r.name,'description',r.description,'permissions',(select coalesce(jsonb_agg(p.code order by p.code),'[]'::jsonb) from platform.role_permissions rp join platform.permissions p on p.id=rp.permission_id where rp.role_id=r.id)) order by r.code) from platform.roles r where r.domain=p_module_key and r.is_assignable),'[]'::jsonb),
  'roleAssignments',coalesce((select jsonb_agg(jsonb_build_object('assignmentId',ur.id,'roleCode',r.code,'scopeType',ur.scope_type,'scopeId',ur.scope_id,'grantedAt',ur.granted_at,'revokedAt',ur.revoked_at,'source','role') order by ur.granted_at,ur.id) from platform.user_roles ur join platform.roles r on r.id=ur.role_id where ur.user_id=t and r.domain=p_module_key and (owner_or_manager or ur.scope_type<>'conference' or platform_private.user_has_module_permission_for(a,'conference.members.manage','conference',ur.scope_id::text))),'[]'::jsonb));
end $$;


--
-- Name: list_module_permission_resources_for_administration("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_module_permission_resources_for_administration"("p_actor_device_id" "uuid", "p_module_key" "text", "p_resource_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a uuid;owner_or_manager boolean;
begin
 a:=public.require_current_approved_device(p_actor_device_id);
 if not exists(select 1 from platform.permissions p where p.domain=p_module_key and p.status='active' and p.allowed_resource_type=p_resource_type) then raise exception 'MODULE_PERMISSION_RESOURCE_TYPE_NOT_ALLOWED' using errcode='42501'; end if;
 owner_or_manager:=platform_private.is_canonical_platform_owner(a) or platform_private.user_has_module_permission_for(a,p_module_key||'.module.manage',null,null);
 if p_module_key='conference' and p_resource_type='conference' then return coalesce((select jsonb_agg(jsonb_build_object('resourceId',c.id,'resourceType','conference','code',null,'name',c.name,'displayName',c.name,'status',c.status) order by c.name,c.id) from public.conferences c where c.deleted_at is null and (owner_or_manager or platform_private.user_has_module_permission_for(a,'conference.members.manage','conference',c.id::text))),'[]'::jsonb); end if;
 if not owner_or_manager then raise exception 'MODULE_PERMISSION_REQUIRED' using errcode='42501'; end if;
 if p_module_key='warehouse' and p_resource_type='store' then return coalesce((select jsonb_agg(jsonb_build_object('resourceId',s.id,'resourceType','store','code',s.code,'name',s.name,'displayName',s.name,'status',s.status) order by s.code,s.id) from warehouse.stores s where s.status='active'),'[]'::jsonb); end if;
 if p_module_key='reservations' and p_resource_type='event' then return coalesce((select jsonb_agg(jsonb_build_object('resourceId',e.id,'resourceType','event','code',null,'name',e.name,'displayName',e.name,'status',e.status) order by e.start_date desc,e.name,e.id) from reservations.events e where reservations_private.has_event_permission(a,'reservations.event.manage',e.id)),'[]'::jsonb); end if;
 raise exception 'MODULE_PERMISSION_RESOURCE_DISCOVERY_UNSUPPORTED' using errcode='42501';
end $$;


--
-- Name: list_system_owner_pending_device_authorizations("uuid", "uuid", "uuid", "text", "bytea"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_system_owner_pending_device_authorizations"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_session_id" "uuid", "p_environment" "text", "p_listing_token_hash" "bytea") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.require_platform_device_backend();
  if not exists(select 1 from public.privileged_device_listing_sessions session
    where session.opaque_token_hash=p_listing_token_hash and session.user_id=p_actor_user_id
      and session.session_id=p_session_id and session.actor_device_id=p_actor_device_id
      and session.environment=p_environment
      and session.scope='SYSTEM_OWNER_PENDING_DEVICE_LIST_READ_ONLY'
      and session.revoked_at is null and session.expires_at>pg_catalog.statement_timestamp())
    or not platform_private.is_canonical_platform_owner(p_actor_user_id) then
    raise exception 'PRIVILEGED_LISTING_SESSION_INVALID' using errcode='42501';
  end if;
  perform platform_private.require_canonical_device_authorization(
    p_actor_user_id,p_actor_device_id,true);
  return pg_catalog.jsonb_build_object('status','success','devices',coalesce((
    select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'targetUserId',device_authorization.user_id,'authorizationId',device_authorization.id,
      'deviceId',device_authorization.device_id,'deviceName',device.display_name,
      'platform',device.platform,'authorizationStatus',device_authorization.status,
      'requestedAt',device_authorization.requested_at,'displayName',profile.display_name,
      'email',users.email
    ) order by device_authorization.requested_at,device_authorization.id)
    from platform.user_device_authorizations device_authorization
    join platform.devices device on device.id=device_authorization.device_id
    join platform.profiles profile on profile.user_id=device_authorization.user_id
    join auth.users users on users.id=device_authorization.user_id
    where device_authorization.status='pending' and device_authorization.revoked_at is null
      and device.lifecycle_status='active' and device.retired_at is null
      and device.compromised_at is null and profile.account_status='approved'
  ),'[]'::jsonb));
end; $$;


--
-- Name: list_system_owner_pending_device_authorizations_for_session("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_system_owner_pending_device_authorizations_for_session"("p_actor_device_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor_user_id uuid;
begin
  v_actor_user_id:=public.require_current_approved_device(p_actor_device_id);
  if not platform_private.is_canonical_platform_owner(v_actor_user_id) then
    raise exception 'SYSTEM_OWNER_REQUIRED' using errcode='42501';
  end if;

  return pg_catalog.jsonb_build_object('status','success','devices',coalesce((
    select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'targetUserId',device_authorization.user_id,
      'authorizationId',device_authorization.id,
      'deviceId',device_authorization.device_id,
      'deviceName',device.display_name,
      'platform',device.platform,
      'browser',device.browser,
      'authorizationStatus',device_authorization.status,
      'requestedAt',device_authorization.requested_at,
      'displayName',profile.display_name,
      'email',users.email
    ) order by device_authorization.requested_at,device_authorization.id)
    from platform.user_device_authorizations device_authorization
    join platform.devices device on device.id=device_authorization.device_id
    join platform.profiles profile on profile.user_id=device_authorization.user_id
    join auth.users users on users.id=device_authorization.user_id
    where device_authorization.status='pending'
      and device_authorization.revoked_at is null
      and device.lifecycle_status='active'
      and device.retired_at is null
      and device.compromised_at is null
      and profile.account_status='approved'
  ),'[]'::jsonb));
end;
$$;


--
-- Name: manage_catalog_module_grant("uuid", "uuid", "text", "uuid", "text", "text", "text", "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."manage_catalog_module_grant"("p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_action" "text", "p_target_user_id" "uuid", "p_module_key" "text", "p_permission_key" "text", "p_resource_type" "text" DEFAULT NULL::"text", "p_resource_id" "text" DEFAULT NULL::"text", "p_grant_id" "uuid" DEFAULT NULL::"uuid", "p_revocation_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a uuid;g uuid;expected_code text;role_row platform.roles%rowtype;assignment platform.user_roles%rowtype;authz uuid;
begin
 if p_operation_id is null or p_target_user_id is null or p_module_key not in('conference','warehouse','reservations') or p_action not in('grant','revoke','create','role_grant','role_revoke') then raise exception 'INVALID_MODULE_GRANT_OPERATION' using errcode='22023'; end if;
 a:=public.require_current_approved_device(p_actor_device_id);authz:=platform_private.validated_phase1c_device_authorization(a,p_actor_device_id);
 if p_action in('role_grant','role_revoke') then
  if p_module_key<>'conference' or p_resource_type<>'conference' or p_resource_id is null or p_permission_key not like 'role:%' then raise exception 'INVALID_ROLE_ASSIGNMENT_OPERATION' using errcode='22023'; end if;
  select * into role_row from platform.roles where domain='conference' and code=substring(p_permission_key from 6) and is_assignable;
  if not found then raise exception 'ROLE_NOT_ASSIGNABLE' using errcode='42501'; end if;
  if not platform_private.is_canonical_platform_owner(a) then
   if not platform_private.user_has_module_permission_for(a,'conference.members.manage','conference',p_resource_id) then raise exception 'CONFERENCE_ROLE_DELEGATION_DENIED' using errcode='42501'; end if;
   if exists(select 1 from platform.role_permissions rp join platform.permissions p on p.id=rp.permission_id where rp.role_id=role_row.id and not platform_private.user_has_module_permission_for(a,p.code,'conference',p_resource_id)) then raise exception 'ROLE_EXCEEDS_ACTOR_AUTHORITY' using errcode='42501'; end if;
  end if;
  if not exists(select 1 from public.conferences where id::text=p_resource_id and deleted_at is null) or not exists(select 1 from platform.profiles where user_id=p_target_user_id and account_status='approved') then raise exception 'ROLE_SCOPE_OR_TARGET_INVALID' using errcode='P0002'; end if;
  perform pg_advisory_xact_lock(hashtextextended('conference-role:'||p_target_user_id::text||':'||role_row.id::text||':'||p_resource_id,0));
  if p_action='role_grant' then
   if p_grant_id is not null then raise exception 'INVALID_ROLE_ASSIGNMENT_OPERATION' using errcode='22023'; end if;
   select ur.* into assignment from platform.user_roles ur where ur.user_id=p_target_user_id and ur.role_id=role_row.id and ur.scope_type='conference' and ur.scope_id::text=p_resource_id and ur.revoked_at is null;
   if assignment.id is null then insert into platform.user_roles(user_id,role_id,scope_type,scope_id,granted_by,metadata) values(p_target_user_id,role_row.id,'conference',p_resource_id::uuid,a,jsonb_build_object('operationId',p_operation_id,'source','platform_administration')) returning * into assignment; insert into platform.audit_events(actor_user_id,actor_device_authorization_id,subject_user_id,domain,module,action,entity_type,entity_id,scope_type,scope_id,new_values,metadata,operation_id,source) values(a,authz,p_target_user_id,'platform','roles','role.granted','user_role',assignment.id,'conference',p_resource_id::uuid,jsonb_build_object('roleCode',role_row.code),jsonb_build_object('permissionKey','conference.members.manage'),p_operation_id,'rpc'); end if;
  else
   select ur.* into assignment from platform.user_roles ur where ur.id=p_grant_id and ur.user_id=p_target_user_id and ur.role_id=role_row.id and ur.scope_type='conference' and ur.scope_id::text=p_resource_id;
   if assignment.id is null then raise exception 'ROLE_ASSIGNMENT_NOT_FOUND' using errcode='P0002'; end if;
   if assignment.revoked_at is null then update platform.user_roles set revoked_at=statement_timestamp(),revoked_by=a,metadata=metadata||jsonb_build_object('revocationReason',nullif(btrim(p_revocation_reason),''),'revocationOperationId',p_operation_id) where id=assignment.id; insert into platform.audit_events(actor_user_id,actor_device_authorization_id,subject_user_id,domain,module,action,entity_type,entity_id,scope_type,scope_id,old_values,new_values,metadata,operation_id,source) values(a,authz,p_target_user_id,'platform','roles','role.revoked','user_role',assignment.id,'conference',p_resource_id::uuid,jsonb_build_object('roleCode',role_row.code),jsonb_build_object('revoked',true),jsonb_build_object('permissionKey','conference.members.manage','reason',p_revocation_reason),p_operation_id,'rpc'); end if;
  end if;
  return jsonb_build_object('status',case when p_action='role_revoke' then 'revoked' else 'applied' end,'grantId',assignment.id,'targetUserId',p_target_user_id,'moduleKey',p_module_key,'permissionKey',p_permission_key,'resourceType',p_resource_type,'resourceId',p_resource_id);
 end if;
 expected_code:=p_module_key||'.module.manage';
 if p_permission_key=expected_code then if not platform_private.is_canonical_platform_owner(a) then raise exception 'PLATFORM_OWNER_REQUIRED' using errcode='42501'; end if; elsif not platform_private.is_canonical_platform_owner(a) then perform public.require_effective_module_permission(p_actor_device_id,p_module_key,expected_code,null,null); end if;
 if p_action in('grant','create') then if p_grant_id is not null then raise exception 'INVALID_MODULE_GRANT_OPERATION' using errcode='22023'; end if;g:=platform_private.create_permission_grant(a,p_actor_device_id,p_target_user_id,p_module_key,p_permission_key,p_resource_type,p_resource_id,p_operation_id); else select x.id into g from platform.permission_grants x join platform.permissions p on p.id=x.permission_id where x.id=p_grant_id and x.user_id=p_target_user_id and p.domain=p_module_key and p.code=p_permission_key and x.resource_type is not distinct from p_resource_type and x.resource_id is not distinct from p_resource_id;if g is null then raise exception 'PERMISSION_GRANT_NOT_FOUND_OR_STALE' using errcode='P0002'; end if;perform platform_private.revoke_permission_grant(a,p_actor_device_id,g,p_revocation_reason,p_operation_id); end if;
 return jsonb_build_object('status',case when p_action='revoke' then 'revoked' else 'applied' end,'grantId',g,'targetUserId',p_target_user_id,'moduleKey',p_module_key,'permissionKey',p_permission_key,'resourceType',p_resource_type,'resourceId',p_resource_id);
end $$;


--
-- Name: manage_foundation_module_grant("uuid", "uuid", "text", "uuid", "text", "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."manage_foundation_module_grant"("p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_action" "text", "p_target_user_id" "uuid", "p_module_key" "text", "p_permission_key" "text", "p_grant_id" "uuid" DEFAULT NULL::"uuid", "p_revocation_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ begin raise exception 'PLATFORM_OPERATION_NOT_ALLOWED' using errcode='42501'; end $$;


--
-- Name: move_conference_accommodation("uuid", "uuid", "uuid", bigint, "uuid", integer, integer, "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."move_conference_accommodation"("p_device" "uuid", "p_conference" "uuid", "p_occupancy" "uuid", "p_expected" bigint, "p_room" "uuid", "p_arrival" integer, "p_leave" integer, "p_bed" "text", "p_extra_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 context jsonb;actor uuid;device_authorization uuid;participation public.conference_participations%rowtype;
 current public.conference_accommodation_occupancies%rowtype;destination public.conference_accommodation_rooms%rowtype;
 guardian_stay public.conference_accommodation_occupancies%rowtype;child_stay public.conference_accommodation_occupancies%rowtype;
 days integer;updated public.conference_accommodation_occupancies%rowtype;created public.conference_accommodation_occupancies%rowtype;
 child_updated public.conference_accommodation_occupancies%rowtype;child_created public.conference_accommodation_occupancies%rowtype;
 historical boolean;effective_day integer;conference_start date;child_results jsonb:='[]';
begin
 context:=platform_private.require_conference_accommodation_context(p_device,p_conference,'conference.accommodation.manage',true);
 actor:=(context->>'actorUserId')::uuid;device_authorization:=platform_private.validated_phase1c_device_authorization(actor,p_device);days:=platform_private.conference_accommodation_duration(p_conference);
 if p_arrival<1 or p_arrival>days or (p_leave is not null and (p_leave<=p_arrival or p_leave>days+1)) then raise exception 'ACCOMMODATION_STAY_INVALID' using errcode='22023';end if;
 select * into current from public.conference_accommodation_occupancies where id=p_occupancy and conference_id=p_conference;
 if not found then raise exception 'ACCOMMODATION_OCCUPANCY_NOT_FOUND' using errcode='P0002';end if;
 select * into participation from public.conference_participations where id=current.participation_id and conference_id=p_conference for update;
 if not found or participation.status<>'active' then raise exception 'ACTIVE_CONFERENCE_PARTICIPATION_REQUIRED' using errcode='42501';end if;
 if participation.guardian_participation_id is not null and current.bed_type='shared' then
   select * into guardian_stay from public.conference_accommodation_occupancies guardian where guardian.conference_id=p_conference and guardian.participation_id=participation.guardian_participation_id and guardian.room_id=current.room_id and guardian.arrival_day=current.arrival_day and guardian.leave_day is not distinct from current.leave_day order by guardian.id limit 1 for key share;
   if not found then raise exception 'ACCOMMODATION_CHILD_GUARDIAN_STAY_REQUIRED' using errcode='23514';end if;
   if p_room is distinct from guardian_stay.room_id or p_arrival is distinct from guardian_stay.arrival_day or p_leave is distinct from guardian_stay.leave_day then raise exception 'ACCOMMODATION_CHILD_STAY_INHERITED' using errcode='23514';end if;
   if p_bed='extra' and p_extra_type is distinct from 'child' or p_bed<>'extra' and p_extra_type is not null then raise exception 'ACCOMMODATION_CHILD_BED_TYPE_INVALID' using errcode='23514';end if;
 end if;
 perform 1 from public.conference_accommodation_rooms where id in(current.room_id,p_room) order by id for update;
 select * into current from public.conference_accommodation_occupancies where id=p_occupancy and participation_id=participation.id for update;
 if current.revision<>p_expected then raise exception 'ACCOMMODATION_REVISION_CONFLICT' using errcode='40001';end if;
 select * into destination from public.conference_accommodation_rooms where id=p_room and platform_private.conference_room_is_assigned(p_conference,id);
 if not found then raise exception 'ACCOMMODATION_ROOM_NOT_FOUND' using errcode='P0002';end if;
 if destination.is_closed and (destination.closed_day is null or p_arrival>=destination.closed_day or coalesce(p_leave,days+1)>destination.closed_day) then raise exception 'ACCOMMODATION_ROOM_UNAVAILABLE' using errcode='55000';end if;
 select start_date into conference_start from public.conferences where id=p_conference;
 effective_day:=greatest(1,least(days+1,(current_date-conference_start+1)::integer));
 if p_arrival<effective_day and current.arrival_day<effective_day then raise exception 'ACCOMMODATION_HISTORICAL_TRANSFER_DAY_IMMUTABLE' using errcode='55000';end if;
 historical:=p_arrival>current.arrival_day and current.arrival_day<effective_day;
 if not historical and current.arrival_day>=effective_day then p_arrival:=current.arrival_day;end if;
 if historical and p_arrival>=coalesce(current.leave_day,days+1) then raise exception 'ACCOMMODATION_TRANSFER_DAY_OUTSIDE_STAY' using errcode='22023';end if;
 if not (p_bed='extra' and p_extra_type='child' and participation.guardian_participation_id is not null) and not platform_private.conference_room_has_capacity(p_conference,p_room,p_bed,p_arrival,p_leave,case when historical then null else p_occupancy end) then raise exception 'ACCOMMODATION_ROOM_CAPACITY_EXCEEDED' using errcode='55000';end if;

 -- A guardian move is a household move: lock all currently housed children first and validate their inherited stay.
 if participation.guardian_participation_id is null then
   for child_stay in
     select o.* from public.conference_accommodation_occupancies o
     join public.conference_participations cp on cp.id=o.participation_id
     where o.conference_id=p_conference and o.room_id=current.room_id and o.arrival_day=current.arrival_day and o.leave_day is not distinct from current.leave_day and cp.guardian_participation_id=participation.id
     order by o.id for update
   loop
     if not platform_private.conference_room_has_capacity(p_conference,p_room,child_stay.bed_type,p_arrival,p_leave,case when historical then null else child_stay.id end) then raise exception 'ACCOMMODATION_ROOM_CAPACITY_EXCEEDED' using errcode='55000';end if;
   end loop;
 end if;

 if historical then
   update public.conference_accommodation_occupancies set leave_day=p_arrival,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=current.id returning * into updated;
   insert into public.conference_accommodation_occupancies(conference_id,room_id,participation_id,arrival_day,leave_day,bed_type,extra_bed_person_type,created_by,updated_by) values(p_conference,p_room,current.participation_id,p_arrival,p_leave,p_bed,p_extra_type,actor,actor) returning * into created;
 else
   update public.conference_accommodation_occupancies set room_id=p_room,arrival_day=p_arrival,leave_day=p_leave,bed_type=p_bed,extra_bed_person_type=p_extra_type,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=current.id returning * into updated;
   created:=updated;
 end if;

 -- Move every child with the guardian, preserving each child's bed type and extra-bed designation.
 if participation.guardian_participation_id is null then
   for child_stay in
     select o.* from public.conference_accommodation_occupancies o
     join public.conference_participations cp on cp.id=o.participation_id
     where o.conference_id=p_conference and cp.guardian_participation_id=participation.id
       and ((historical and o.room_id=current.room_id and o.arrival_day=current.arrival_day and o.leave_day is not distinct from current.leave_day)
         or (not historical and o.id<>current.id and o.room_id=current.room_id and o.arrival_day=current.arrival_day and o.leave_day is not distinct from current.leave_day))
     order by o.id for update
   loop
     if historical then
       update public.conference_accommodation_occupancies set leave_day=p_arrival,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=child_stay.id returning * into child_updated;
       insert into public.conference_accommodation_occupancies(conference_id,room_id,participation_id,arrival_day,leave_day,bed_type,extra_bed_person_type,created_by,updated_by) values(p_conference,p_room,child_stay.participation_id,p_arrival,p_leave,child_stay.bed_type,child_stay.extra_bed_person_type,actor,actor) returning * into child_created;
     else
       update public.conference_accommodation_occupancies set room_id=p_room,arrival_day=p_arrival,leave_day=p_leave,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=child_stay.id returning * into child_updated;
       child_created:=child_updated;
     end if;
     child_results:=child_results||jsonb_build_array(jsonb_build_object('occupancyId',child_created.id,'previousOccupancyId',case when historical then child_stay.id else null end,'revision',child_created.revision,'roomId',child_created.room_id,'arrivalDay',child_created.arrival_day,'leaveDay',child_created.leave_day,'bedType',child_created.bed_type,'extraBedPersonType',child_created.extra_bed_person_type));
   end loop;
 end if;

 insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,old_values,new_values,metadata,source)
 values(actor,device_authorization,'platform','conference','conference.accommodation.moved','accommodation_occupancy',created.id,'platform',to_jsonb(current),to_jsonb(created),jsonb_build_object('conferenceId',p_conference,'participationId',current.participation_id,'oldRoomId',current.room_id,'newRoomId',p_room,'previousOccupancyId',case when historical then current.id else null end,'historicalSegmentPreserved',historical,'childrenMoved',jsonb_array_length(child_results),'permissionKey','conference.accommodation.manage','authoritySource',context->>'authoritySource','grantId',context->'grantId'),'rpc');
 return jsonb_build_object('occupancyId',created.id,'revision',created.revision,'roomId',created.room_id,'previousOccupancyId',case when historical then current.id else null end,'historicalSegmentPreserved',historical,'arrivalDay',created.arrival_day,'leaveDay',created.leave_day,'childrenMoved',child_results);
exception when exclusion_violation then raise exception 'ACCOMMODATION_STAY_OVERLAP' using errcode='23P01';
end $$;


--
-- Name: mutate_conference_accommodation_operations("uuid", "uuid", "uuid", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mutate_conference_accommodation_operations"("p_device" "uuid", "p_operation_id" "uuid", "p_conference" "uuid", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 ctx jsonb;actor uuid;authz uuid;occupancy public.conference_accommodation_occupancies%rowtype;
 assignment public.conference_room_assignments%rowtype;holder public.conference_accommodation_occupancies%rowtype;
 holder_participation public.conference_participations%rowtype;old_values jsonb;new_values jsonb;result jsonb;expected bigint;room_id uuid;holder_id uuid;
begin
 if p_operation_id is null or p_operation not in('set_arrival','set_room_key','add_guardian_child') then raise exception 'ACCOMMODATION_OPERATION_INVALID' using errcode='22023';end if;
 ctx:=platform_private.require_conference_accommodation_context(p_device,p_conference,'conference.accommodation.manage',true);
 actor:=(ctx->>'actorUserId')::uuid;authz:=platform_private.validated_phase1c_device_authorization(actor,p_device);
 select ae.new_values into result from platform.audit_events ae where actor_user_id=actor and operation_id=p_operation_id and scope_id=p_conference and action=case when p_operation='set_arrival' then 'conference.accommodation.arrival_updated' when p_operation='set_room_key' then 'conference.accommodation.room_key_updated' else 'conference.accommodation.guardian_child_added' end limit 1;
 if result is not null then return result||jsonb_build_object('status','duplicate');end if;
 if p_operation='add_guardian_child' then return public.add_conference_guardian_child_accommodation(p_device,p_operation_id,p_conference,p_args); end if; if p_operation='set_arrival' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['occupancyId','expectedRevision','arrived']);
  if jsonb_typeof(p_args->'arrived') is distinct from 'boolean' then raise exception 'ARRIVAL_BOOLEAN_REQUIRED' using errcode='22023';end if;
  expected:=(p_args->>'expectedRevision')::bigint;
  select * into occupancy from public.conference_accommodation_occupancies where id=(p_args->>'occupancyId')::uuid and conference_id=p_conference for update;
  if not found then raise exception 'ACCOMMODATION_OCCUPANCY_NOT_FOUND' using errcode='P0002';end if;
  select * into holder_participation from public.conference_participations where id=occupancy.participation_id and conference_id=p_conference;
  if holder_participation.guardian_participation_id is not null then raise exception 'ACCOMMODATION_CHILD_ARRIVAL_INHERITED' using errcode='23514';end if;
  if occupancy.revision<>expected then raise exception 'ACCOMMODATION_REVISION_CONFLICT' using errcode='40001';end if;
  room_id:=occupancy.room_id;old_values:=to_jsonb(occupancy);
  update public.conference_accommodation_occupancies set arrived_at=case when (p_args->>'arrived')::boolean then coalesce(arrived_at,statement_timestamp()) else null end,arrived_by=case when (p_args->>'arrived')::boolean then coalesce(arrived_by,actor) else null end,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=occupancy.id returning * into occupancy;
  new_values:=to_jsonb(occupancy);result:=jsonb_build_object('status','success','occupancyId',occupancy.id,'revision',occupancy.revision,'arrivedAt',occupancy.arrived_at,'arrivedBy',occupancy.arrived_by);
 else
  perform platform_private.require_exact_jsonb_keys(p_args,array['roomId','expectedRevision','holderOccupancyId']);
  room_id:=(p_args->>'roomId')::uuid;expected:=(p_args->>'expectedRevision')::bigint;holder_id:=nullif(p_args->>'holderOccupancyId','')::uuid;
  select * into assignment from public.conference_room_assignments where conference_id=p_conference and public.conference_room_assignments.room_id=(p_args->>'roomId')::uuid for update;
  if not found then raise exception 'ROOM_ASSIGNMENT_NOT_FOUND' using errcode='P0002';end if;
  if assignment.revision<>expected then raise exception 'ROOM_ASSIGNMENT_REVISION_CONFLICT' using errcode='40001';end if;
  if holder_id is not null then
   select * into holder from public.conference_accommodation_occupancies where id=holder_id and conference_id=p_conference and public.conference_accommodation_occupancies.room_id=(p_args->>'roomId')::uuid and arrival_day<=platform_private.conference_operational_day(p_conference) and coalesce(leave_day,platform_private.conference_accommodation_duration(p_conference)+1)>platform_private.conference_operational_day(p_conference) for key share;
   if not found then raise exception 'ROOM_KEY_HOLDER_NOT_CURRENT_OCCUPANT' using errcode='22023';end if;
   select * into holder_participation from public.conference_participations where id=holder.participation_id and conference_id=p_conference;
   if holder_participation.guardian_participation_id is not null then raise exception 'ACCOMMODATION_CHILD_KEY_INHERITED' using errcode='23514';end if;
  end if;
  old_values:=to_jsonb(assignment);
  update public.conference_room_assignments set key_holder_occupancy_id=holder_id,key_delivered_at=case when holder_id is null then null else statement_timestamp() end,key_delivered_by=case when holder_id is null then null else actor end,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=assignment.id returning * into assignment;
  new_values:=to_jsonb(assignment);result:=jsonb_build_object('status','success','roomId',room_id,'roomAssignmentId',assignment.id,'revision',assignment.revision,'keyHolderOccupancyId',assignment.key_holder_occupancy_id,'keyDeliveredAt',assignment.key_delivered_at,'keyDeliveredBy',assignment.key_delivered_by);
 end if;
 insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,scope_id,old_values,new_values,metadata,operation_id,source) values(actor,authz,'platform','conference',case when p_operation='set_arrival' then 'conference.accommodation.arrival_updated' when p_operation='set_room_key' then 'conference.accommodation.room_key_updated' else 'conference.accommodation.guardian_child_added' end,case when p_operation='set_arrival' then 'accommodation_occupancy' else 'conference_room_assignment' end,case when p_operation='set_arrival' then occupancy.id else assignment.id end,'conference',p_conference,old_values,new_values,jsonb_build_object('conferenceId',p_conference,'roomId',room_id,'permissionKey','conference.accommodation.manage','authoritySource',ctx->>'authoritySource','grantId',ctx->'grantId'),p_operation_id,'rpc');
 return result;
end $$;


--
-- Name: mutate_conference_accommodation_pricing("uuid", "uuid", "uuid", bigint, "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mutate_conference_accommodation_pricing"("p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_conference_id" "uuid", "p_expected_revision" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx jsonb;session_ctx jsonb;actor uuid;authz uuid;prior public.conference_participation_operations%rowtype;
  current_row public.conference_accommodation_pricing%rowtype;changed public.conference_accommodation_pricing%rowtype;
  req jsonb;result jsonb;mode text;vals numeric[];action text;v_room_id uuid;room public.conference_accommodation_rooms%rowtype;excluded boolean;was_excluded boolean;
begin
  if p_operation_id is null or p_conference_id is null or jsonb_typeof(p_payload)<>'object' then raise exception 'CONFERENCE_ACCOMMODATION_PRICING_ARGUMENT_INVALID' using errcode='22023';end if;
  if p_payload ? 'action' then
    perform platform_private.require_exact_jsonb_keys(p_payload,array['action','roomId']);
    action:=p_payload->>'action';
    if action not in('EXCLUDE_ROOM','REMOVE_ROOM_EXCLUSION') then raise exception 'CONFERENCE_ACCOMMODATION_PRICING_ARGUMENT_INVALID' using errcode='22023';end if;
    begin v_room_id:=(p_payload->>'roomId')::uuid;exception when others then raise exception 'CONFERENCE_ACCOMMODATION_PRICING_ARGUMENT_INVALID' using errcode='22023';end;
  else
    perform platform_private.require_exact_jsonb_keys(p_payload,array['enabled','pricingMode','prices','roomTypePrices']);
    perform platform_private.require_exact_jsonb_keys(p_payload->'prices',array['personNight','roomNight','personDay','roomDay','packagePrice','packageDayPrice']);
    perform platform_private.require_exact_jsonb_keys(p_payload->'roomTypePrices',array['single','double','triple','quadruple','quintuple','sextuple','sevenPlus']);
    mode:=p_payload->>'pricingMode';if mode not in('per_person_night','per_room_night','per_person_day','per_room_day','fixed_package','per_day_package','room_type') then raise exception 'CONFERENCE_ACCOMMODATION_PRICING_ARGUMENT_INVALID' using errcode='22023';end if;
    begin vals:=array[(p_payload->'prices'->>'personNight')::numeric,(p_payload->'prices'->>'roomNight')::numeric,(p_payload->'prices'->>'personDay')::numeric,(p_payload->'prices'->>'roomDay')::numeric,(p_payload->'prices'->>'packagePrice')::numeric,(p_payload->'prices'->>'packageDayPrice')::numeric,(p_payload->'roomTypePrices'->>'single')::numeric,(p_payload->'roomTypePrices'->>'double')::numeric,(p_payload->'roomTypePrices'->>'triple')::numeric,(p_payload->'roomTypePrices'->>'quadruple')::numeric,(p_payload->'roomTypePrices'->>'quintuple')::numeric,(p_payload->'roomTypePrices'->>'sextuple')::numeric,(p_payload->'roomTypePrices'->>'sevenPlus')::numeric];exception when others then raise exception 'CONFERENCE_ACCOMMODATION_PRICING_ARGUMENT_INVALID' using errcode='22023';end;
    if exists(select 1 from unnest(vals) v where v<0) then raise exception 'CONFERENCE_ACCOMMODATION_PRICING_ARGUMENT_INVALID' using errcode='22023';end if;
  end if;
  session_ctx:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;actor:=(session_ctx->>'user_id')::uuid;
  if session_ctx->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' or (session_ctx->>'device_id')::uuid is distinct from p_actor_device_id then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;
  authz:=platform_private.validated_phase1c_device_authorization(actor,p_actor_device_id);if authz is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;
  ctx:=platform_private.require_conference_accommodation_context(p_actor_device_id,p_conference_id,'conference.accommodation.manage',true);
  if (ctx->>'actorUserId')::uuid is distinct from actor then raise exception 'ACTOR_DEVICE_OVERRIDE_DENIED' using errcode='42501';end if;
  req:=jsonb_build_object('conferenceId',p_conference_id,'expectedRevision',p_expected_revision,'payload',p_payload);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':conference-participation:'||p_operation_id::text,0));
  select * into prior from public.conference_participation_operations where actor_user_id=actor and operation_id=p_operation_id;
  if found then if prior.operation<>'accommodation_pricing_mutation' or prior.request<>req then raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023';end if;return prior.result;end if;
  perform pg_advisory_xact_lock(hashtextextended('conference-accommodation-pricing:'||p_conference_id::text,0));
  select * into current_row from public.conference_accommodation_pricing where conference_id=p_conference_id for update;
  if found and (p_expected_revision is null or current_row.revision<>p_expected_revision) then raise exception 'CONFERENCE_ACCOMMODATION_PRICING_REVISION_CONFLICT' using errcode='40001';end if;
  if not found and p_expected_revision is not null and p_expected_revision<>0 then raise exception 'CONFERENCE_ACCOMMODATION_PRICING_REVISION_CONFLICT' using errcode='40001';end if;
  if action is not null then
    select * into room from public.conference_accommodation_rooms where id=v_room_id and platform_private.conference_room_is_assigned(p_conference_id,id) for update;
    if not found then raise exception 'ACCOMMODATION_ROOM_NOT_FOUND' using errcode='P0002';end if;
    excluded:=exists(select 1 from public.conference_accommodation_pricing_room_exclusions where conference_id=p_conference_id and room_id=v_room_id);
    was_excluded:=excluded;
    if (action='EXCLUDE_ROOM' and excluded) or (action='REMOVE_ROOM_EXCLUSION' and not excluded) then raise exception 'CONFERENCE_ACCOMMODATION_PRICING_ROOM_INCLUSION_UNCHANGED' using errcode='55000';end if;
    if current_row.conference_id is null then
      insert into public.conference_accommodation_pricing(conference_id,created_by,updated_by) values(p_conference_id,actor,actor) returning * into changed;
    else
      update public.conference_accommodation_pricing set revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where conference_id=p_conference_id returning * into changed;
    end if;
    if action='EXCLUDE_ROOM' then
      insert into public.conference_accommodation_pricing_room_exclusions(conference_id,room_id,created_by) values(p_conference_id,v_room_id,actor);excluded:=true;
    else
      delete from public.conference_accommodation_pricing_room_exclusions where conference_id=p_conference_id and room_id=v_room_id;excluded:=false;
    end if;
    result:=jsonb_build_object('conferenceId',p_conference_id,'roomId',v_room_id,'includedInPricing',not excluded,'pricing',platform_private.conference_accommodation_pricing_projection(p_conference_id));
    insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at) values(actor,p_operation_id,'accommodation_pricing_mutation',req,result,statement_timestamp());
    insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source)
    values(actor,authz,'platform','conference',case when excluded then 'conference.accommodation.pricing_room_excluded' else 'conference.accommodation.pricing_room_included' end,'conference_accommodation_pricing_room',v_room_id,'platform',jsonb_build_object('includedInPricing',not was_excluded),jsonb_build_object('includedInPricing',not excluded),jsonb_build_object('conferenceId',p_conference_id,'permissionKey','conference.accommodation.manage','authoritySource',ctx->>'authoritySource','grantId',ctx->'grantId'),p_operation_id,'rpc');
    return result;
  end if;
  insert into public.conference_accommodation_pricing(conference_id,enabled,pricing_mode,person_night,room_night,person_day,room_day,package_price,package_day_price,single_price,double_price,triple_price,quadruple_price,quintuple_price,sextuple_price,seven_plus_price,revision,created_by,updated_by)
  values(p_conference_id,(p_payload->>'enabled')::boolean,mode,vals[1],vals[2],vals[3],vals[4],vals[5],vals[6],vals[7],vals[8],vals[9],vals[10],vals[11],vals[12],vals[13],1,actor,actor)
  on conflict(conference_id) do update set enabled=excluded.enabled,pricing_mode=excluded.pricing_mode,person_night=excluded.person_night,room_night=excluded.room_night,person_day=excluded.person_day,room_day=excluded.room_day,package_price=excluded.package_price,package_day_price=excluded.package_day_price,single_price=excluded.single_price,double_price=excluded.double_price,triple_price=excluded.triple_price,quadruple_price=excluded.quadruple_price,quintuple_price=excluded.quintuple_price,sextuple_price=excluded.sextuple_price,seven_plus_price=excluded.seven_plus_price,revision=public.conference_accommodation_pricing.revision+1,updated_at=statement_timestamp(),updated_by=actor returning * into changed;
  result:=jsonb_build_object('conferenceId',p_conference_id,'pricing',platform_private.conference_accommodation_pricing_projection(p_conference_id));
  insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at) values(actor,p_operation_id,'accommodation_pricing_mutation',req,result,statement_timestamp());
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source) values(actor,authz,'platform','conference','conference.accommodation.pricing_updated','conference_accommodation_pricing',p_conference_id,'platform',case when current_row.conference_id is null then null else to_jsonb(current_row) end,to_jsonb(changed),jsonb_build_object('conferenceId',p_conference_id,'permissionKey','conference.accommodation.manage','authoritySource',ctx->>'authoritySource','grantId',ctx->'grantId'),p_operation_id,'rpc');
  return result;
exception when invalid_text_representation or null_value_not_allowed then raise exception 'CONFERENCE_ACCOMMODATION_PRICING_ARGUMENT_INVALID' using errcode='22023';
end $$;


--
-- Name: mutate_conference_accommodation_structure("uuid", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mutate_conference_accommodation_structure"("p_device" "uuid", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 raise exception 'PLATFORM_OPERATION_NOT_ALLOWED' using errcode='42501';
end $$;


--
-- Name: mutate_conference_air_conditioning("uuid", "uuid", "uuid", "text", "uuid", "text", bigint, "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mutate_conference_air_conditioning"("p_device" "uuid", "p_operation_id" "uuid", "p_conference" "uuid", "p_scope" "text", "p_scope_id" "uuid", "p_action" "text", "p_expected_revision" bigint, "p_configuration" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c jsonb;s jsonb;actor uuid;authz uuid;prior public.conference_participation_operations%rowtype;req jsonb;result jsonb;current_revision bigint;begin
 if p_operation_id is null or p_conference is null or p_scope not in('CONFERENCE','HOUSE','ROOM') or p_action not in('SET','CLEAR','CLEAR_SUBTREE') or (p_action='CLEAR_SUBTREE' and p_scope<>'HOUSE') or (p_scope='CONFERENCE' and p_scope_id is not null) or (p_scope<>'CONFERENCE' and p_scope_id is null) then raise exception 'CONFERENCE_AIR_CONDITIONING_ARGUMENT_INVALID' using errcode='22023';end if;
 s:=nullif(current_setting('platform.phase1c_context',true),'')::jsonb;actor:=(s->>'user_id')::uuid;if s->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' or (s->>'device_id')::uuid is distinct from p_device then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;
 authz:=platform_private.validated_phase1c_device_authorization(actor,p_device);if authz is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;
 c:=platform_private.require_conference_air_conditioning_context(p_device,p_conference,'conference.air_conditioning.manage',true);
 req:=jsonb_build_object('conferenceId',p_conference,'scope',p_scope,'scopeId',p_scope_id,'action',p_action,'expectedRevision',p_expected_revision,'configuration',p_configuration);
 perform pg_advisory_xact_lock(hashtextextended(actor::text||':conference-participation:'||p_operation_id::text,0));select * into prior from public.conference_participation_operations where actor_user_id=actor and operation_id=p_operation_id;if found then if prior.operation<>'air_conditioning_mutation' or prior.request<>req then raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023';end if;return prior.result;end if;
 if p_scope='CONFERENCE' then select revision into current_revision from public.conference_air_conditioning_defaults where conference_id=p_conference for update;
 elsif p_scope='HOUSE' then perform 1 from public.conference_house_assignments where conference_id=p_conference and house_id=p_scope_id;if not found then raise exception 'CONFERENCE_ACCOMMODATION_HOUSE_NOT_FOUND' using errcode='P0002';end if;select revision into current_revision from public.conference_air_conditioning_house_overrides where house_id=p_scope_id for update;
 else perform 1 from public.conference_accommodation_rooms rr join public.conference_accommodation_floors f on f.id=rr.floor_id join public.conference_house_assignments a on a.house_id=f.house_id and a.conference_id=p_conference where rr.id=p_scope_id;if not found then raise exception 'CONFERENCE_ACCOMMODATION_ROOM_NOT_FOUND' using errcode='P0002';end if;select revision into current_revision from public.conference_air_conditioning_room_overrides where room_id=p_scope_id for update;end if;
 if current_revision is null then current_revision:=0;end if;if p_expected_revision is distinct from current_revision then raise exception 'CONFERENCE_AIR_CONDITIONING_REVISION_CONFLICT' using errcode='40001';end if;
 if p_action='CLEAR' and p_scope='CONFERENCE' then raise exception 'CONFERENCE_AIR_CONDITIONING_ARGUMENT_INVALID' using errcode='22023';end if;
 if p_action in('CLEAR','CLEAR_SUBTREE') then if p_scope='HOUSE' then if p_action='CLEAR_SUBTREE' then delete from public.conference_air_conditioning_room_overrides ro using public.conference_accommodation_rooms rr,public.conference_accommodation_floors f where ro.room_id=rr.id and rr.floor_id=f.id and f.house_id=p_scope_id;end if;delete from public.conference_air_conditioning_house_overrides where house_id=p_scope_id;else delete from public.conference_air_conditioning_room_overrides where room_id=p_scope_id;end if;
 else
  if jsonb_typeof(p_configuration)<>'object' or p_configuration ? 'manualTotal' or p_configuration ? 'dayOverrides' then raise exception 'CONFERENCE_AIR_CONDITIONING_ARGUMENT_INVALID' using errcode='22023';end if;
  if p_scope='CONFERENCE' then perform platform_private.require_exact_jsonb_keys(p_configuration,array['enabled','pricingBasis','timeBasis','durationBasis','unitPrice','fixedAmount','includeEmptyRooms','includeClosedRooms','unitsCount']);insert into public.conference_air_conditioning_defaults(conference_id,enabled,pricing_basis,time_basis,duration_basis,unit_price,fixed_amount,include_empty_rooms,include_closed_rooms,units_count,revision,created_by,updated_by) values(p_conference,(p_configuration->>'enabled')::boolean,p_configuration->>'pricingBasis',p_configuration->>'timeBasis',p_configuration->>'durationBasis',(p_configuration->>'unitPrice')::numeric,nullif(p_configuration->>'fixedAmount','')::numeric,(p_configuration->>'includeEmptyRooms')::boolean,(p_configuration->>'includeClosedRooms')::boolean,nullif(p_configuration->>'unitsCount','')::integer,1,actor,actor) on conflict(conference_id) do update set enabled=excluded.enabled,pricing_basis=excluded.pricing_basis,time_basis=excluded.time_basis,duration_basis=excluded.duration_basis,unit_price=excluded.unit_price,fixed_amount=excluded.fixed_amount,include_empty_rooms=excluded.include_empty_rooms,include_closed_rooms=excluded.include_closed_rooms,units_count=excluded.units_count,revision=public.conference_air_conditioning_defaults.revision+1,updated_at=statement_timestamp(),updated_by=actor;
  elsif p_scope='HOUSE' then perform platform_private.require_exact_jsonb_keys(p_configuration,array['enabled','pricingBasis','timeBasis','durationBasis','unitPrice','fixedAmount','includeEmptyRooms','includeClosedRooms','unitsCount']);insert into public.conference_air_conditioning_house_overrides(house_id,conference_id,enabled,pricing_basis,time_basis,duration_basis,unit_price,fixed_amount,include_empty_rooms,include_closed_rooms,units_count,revision,created_by,updated_by) values(p_scope_id,p_conference,nullif(p_configuration->>'enabled','')::boolean,nullif(p_configuration->>'pricingBasis',''),nullif(p_configuration->>'timeBasis',''),nullif(p_configuration->>'durationBasis',''),nullif(p_configuration->>'unitPrice','')::numeric,nullif(p_configuration->>'fixedAmount','')::numeric,nullif(p_configuration->>'includeEmptyRooms','')::boolean,nullif(p_configuration->>'includeClosedRooms','')::boolean,nullif(p_configuration->>'unitsCount','')::integer,1,actor,actor) on conflict(house_id) do update set enabled=excluded.enabled,pricing_basis=excluded.pricing_basis,time_basis=excluded.time_basis,duration_basis=excluded.duration_basis,unit_price=excluded.unit_price,fixed_amount=excluded.fixed_amount,include_empty_rooms=excluded.include_empty_rooms,include_closed_rooms=excluded.include_closed_rooms,units_count=excluded.units_count,revision=public.conference_air_conditioning_house_overrides.revision+1,updated_at=statement_timestamp(),updated_by=actor;
  else perform platform_private.require_exact_jsonb_keys(p_configuration,array['included','enabled','pricingBasis','timeBasis','durationBasis','unitPrice','fixedAmount','includeEmptyRooms','includeClosedRooms','unitsCount']);insert into public.conference_air_conditioning_room_overrides(room_id,conference_id,included,enabled,pricing_basis,time_basis,duration_basis,unit_price,fixed_amount,include_empty_rooms,include_closed_rooms,units_count,revision,created_by,updated_by) values(p_scope_id,p_conference,nullif(p_configuration->>'included','')::boolean,nullif(p_configuration->>'enabled','')::boolean,nullif(p_configuration->>'pricingBasis',''),nullif(p_configuration->>'timeBasis',''),nullif(p_configuration->>'durationBasis',''),nullif(p_configuration->>'unitPrice','')::numeric,nullif(p_configuration->>'fixedAmount','')::numeric,nullif(p_configuration->>'includeEmptyRooms','')::boolean,nullif(p_configuration->>'includeClosedRooms','')::boolean,nullif(p_configuration->>'unitsCount','')::integer,1,actor,actor) on conflict(room_id) do update set included=excluded.included,enabled=excluded.enabled,pricing_basis=excluded.pricing_basis,time_basis=excluded.time_basis,duration_basis=excluded.duration_basis,unit_price=excluded.unit_price,fixed_amount=excluded.fixed_amount,include_empty_rooms=excluded.include_empty_rooms,include_closed_rooms=excluded.include_closed_rooms,units_count=excluded.units_count,revision=public.conference_air_conditioning_room_overrides.revision+1,updated_at=statement_timestamp(),updated_by=actor;end if;
 end if;
 result:=public.get_conference_air_conditioning(p_device,p_conference);insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at) values(actor,p_operation_id,'air_conditioning_mutation',req,result,statement_timestamp());insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source) values(actor,authz,'platform','conference','conference.air_conditioning.configuration_changed','conference_air_conditioning_configuration',coalesce(p_scope_id,p_conference),'platform',null,p_configuration,jsonb_build_object('conferenceId',p_conference,'scope',p_scope,'permissionKey','conference.air_conditioning.manage'),p_operation_id,'rpc');return result;
end $$;


--
-- Name: mutate_conference_branding("uuid", "uuid", "uuid", "text", bigint, "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mutate_conference_branding"("p_device" "uuid", "p_operation_id" "uuid", "p_conference" "uuid", "p_action" "text", "p_expected_revision" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx jsonb;session_ctx jsonb;actor uuid;authz uuid;prior public.conference_participation_operations%rowtype;
  req jsonb;result jsonb;before_row public.conference_branding%rowtype;after_row public.conference_branding%rowtype;image_value text;
begin
  if p_operation_id is null or p_conference is null or p_expected_revision is null or p_expected_revision<1
     or p_action not in('SETTINGS_UPDATE','BANNER_SET','BANNER_REMOVE','SERVICE_LOGO_SET','SERVICE_LOGO_REMOVE')
     or p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'CONFERENCE_BRANDING_ARGUMENT_INVALID' using errcode='22023';end if;
  session_ctx:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;actor:=(session_ctx->>'user_id')::uuid;
  if session_ctx->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' or (session_ctx->>'device_id')::uuid is distinct from p_device then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;
  authz:=platform_private.validated_phase1c_device_authorization(actor,p_device);if authz is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;
  ctx:=platform_private.require_conference_branding_context(p_device,p_conference,'conference.lifecycle.manage',true);
  req:=jsonb_build_object('conferenceId',p_conference,'action',p_action,'expectedRevision',p_expected_revision,'payload',p_payload);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':conference-participation:'||p_operation_id::text,0));
  select * into prior from public.conference_participation_operations where actor_user_id=actor and operation_id=p_operation_id;
  if found then if prior.operation<>'conference_branding_mutation' or prior.request<>req then raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023';end if;return prior.result;end if;
  select * into before_row from public.conference_branding where conference_id=p_conference for update;
  if not found then raise exception 'CONFERENCE_BRANDING_NOT_FOUND' using errcode='P0002';end if;
  if before_row.revision<>p_expected_revision then raise exception 'CONFERENCE_BRANDING_REVISION_CONFLICT' using errcode='40001';end if;
  if p_action='SETTINGS_UPDATE' then
    perform platform_private.require_exact_jsonb_keys(p_payload,array['autoColors','bannerPosition','cardTheme','primaryColor','secondaryColor','textColor']);
    update public.conference_branding set auto_colors=(p_payload->>'autoColors')::boolean,banner_position=p_payload->>'bannerPosition',card_theme=p_payload->>'cardTheme',primary_color=p_payload->>'primaryColor',secondary_color=p_payload->>'secondaryColor',text_color=p_payload->>'textColor',revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where conference_id=p_conference returning * into after_row;
  elsif p_action in('BANNER_SET','SERVICE_LOGO_SET') then
    perform platform_private.require_exact_jsonb_keys(p_payload,array['image']);image_value:=p_payload->>'image';
    if not platform_private.is_prepared_jpeg_data_url(image_value) then raise exception 'CONFERENCE_BRANDING_JPEG_DATA_URL_INVALID' using errcode='22023';end if;
    if p_action='BANNER_SET' then update public.conference_branding set banner=image_value,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where conference_id=p_conference returning * into after_row;
    else update public.conference_branding set service_logo=image_value,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where conference_id=p_conference returning * into after_row;end if;
  else
    perform platform_private.require_exact_jsonb_keys(p_payload,array[]::text[]);
    if p_action='BANNER_REMOVE' then update public.conference_branding set banner='',revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where conference_id=p_conference returning * into after_row;
    else update public.conference_branding set service_logo='',revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where conference_id=p_conference returning * into after_row;end if;
  end if;
  result:=platform_private.conference_branding_projection(p_conference);
  insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at) values(actor,p_operation_id,'conference_branding_mutation',req,result,statement_timestamp());
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source)
  values(actor,authz,'platform','conference','conference.branding.changed','conference_branding',p_conference,'platform',
    jsonb_build_object('revision',before_row.revision,'action',p_action),jsonb_build_object('revision',after_row.revision,'action',p_action),
    jsonb_build_object('conferenceId',p_conference,'permissionKey','conference.lifecycle.manage','authoritySource',ctx->>'authoritySource','grantId',ctx->'grantId'),p_operation_id,'rpc');
  return result;
end $$;


--
-- Name: mutate_conference_core("uuid", "uuid", "uuid", bigint, "text", "text", "date", "date", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mutate_conference_core"("p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_conference_id" "uuid", "p_expected_revision" bigint, "p_name" "text", "p_place" "text", "p_start_date" "date", "p_end_date" "date", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx jsonb; session_ctx jsonb; actor uuid; authz uuid;
  prior public.conference_participation_operations%rowtype;
  current_row public.conferences%rowtype; changed public.conferences%rowtype;
  req jsonb; result jsonb; schedule jsonb; clean_name text:=btrim(coalesce(p_name,''));
  clean_place text:=btrim(coalesce(p_place,'')); completed timestamptz;
begin
  if p_operation_id is null or p_conference_id is null or p_expected_revision is null
     or p_expected_revision<1 or clean_name='' or char_length(clean_name)>500
     or char_length(clean_place)>500 or p_start_date is null or p_end_date is null
     or p_end_date<p_start_date or p_status not in('active','completed') then
    raise exception 'CONFERENCE_CORE_ARGUMENT_INVALID' using errcode='22023';
  end if;
  session_ctx:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;
  actor:=(session_ctx->>'user_id')::uuid;
  if session_ctx->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH'
     or (session_ctx->>'device_id')::uuid is distinct from p_actor_device_id then
    raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';
  end if;
  authz:=platform_private.validated_phase1c_device_authorization(actor,p_actor_device_id);
  if authz is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
  ctx:=public.require_effective_module_permission(p_actor_device_id,'conference',
    'conference.lifecycle.manage','conference',p_conference_id::text);
  if (ctx->>'actorUserId')::uuid is distinct from actor then
    raise exception 'ACTOR_DEVICE_OVERRIDE_DENIED' using errcode='42501';
  end if;
  req:=jsonb_build_object('conferenceId',p_conference_id,'expectedRevision',p_expected_revision,
    'name',clean_name,'place',clean_place,'startDate',p_start_date,
    'endDate',p_end_date,'status',p_status);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':conference-participation:'||p_operation_id::text,0));
  select * into prior from public.conference_participation_operations
    where actor_user_id=actor and operation_id=p_operation_id;
  if found then
    if prior.operation<>'conference_core_mutation' or prior.request<>req then
      raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023';
    end if;
    return prior.result;
  end if;
  select * into current_row from public.conferences where id=p_conference_id for update;
  if not found or current_row.deleted_at is not null then raise exception 'CONFERENCE_CORE_NOT_FOUND' using errcode='P0002'; end if;
  if current_row.revision<>p_expected_revision then raise exception 'CONFERENCE_CORE_REVISION_CONFLICT' using errcode='40001'; end if;
  if current_row.status='completed' then raise exception 'CONFERENCE_LIFECYCLE_TRANSITION_INVALID' using errcode='55000'; end if;
  completed:=case when p_status='completed' then statement_timestamp() else null end;
  update public.conferences c set name=clean_name,place=clean_place,start_date=p_start_date,
    end_date=p_end_date,status=p_status,completed_at=completed,revision=c.revision+1,
    updated_by=actor,updated_at=statement_timestamp() where c.id=p_conference_id returning c.* into changed;
  select coalesce(jsonb_agg(to_jsonb(day::date) order by day),'[]'::jsonb) into schedule
    from generate_series(p_start_date::timestamp,p_end_date::timestamp,interval '1 day') day;
  result:=jsonb_build_object('conferenceId',changed.id,'name',changed.name,'place',changed.place,
    'startDate',changed.start_date,'endDate',changed.end_date,'status',changed.status,
    'completedAt',changed.completed_at,'revision',changed.revision,'updatedAt',changed.updated_at,
    'updatedBy',changed.updated_by,'days',(changed.end_date-changed.start_date)+1,
    'nights',changed.end_date-changed.start_date,'schedule',schedule);
  insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at)
    values(actor,p_operation_id,'conference_core_mutation',req,result,statement_timestamp());
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,
    entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source)
  values(actor,authz,'platform','conference',case when p_status='completed' then 'conference.lifecycle.completed' else 'conference.core.updated' end,
    'conference',p_conference_id,'platform',jsonb_build_object('name',current_row.name,'place',current_row.place,
    'startDate',current_row.start_date,'endDate',current_row.end_date,'status',current_row.status,'revision',current_row.revision),
    jsonb_build_object('name',changed.name,'place',changed.place,'startDate',changed.start_date,
    'endDate',changed.end_date,'status',changed.status,'revision',changed.revision),
    jsonb_build_object('permissionKey','conference.lifecycle.manage','authoritySource',ctx->>'authoritySource','grantId',ctx->'grantId'),
    p_operation_id,'rpc');
  return result;
end $$;


--
-- Name: mutate_conference_finance("uuid", "uuid", "uuid", "text", "text", "uuid", bigint, "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mutate_conference_finance"("p_device" "uuid", "p_operation_id" "uuid", "p_conference" "uuid", "p_entity" "text", "p_action" "text", "p_entity_id" "uuid", "p_expected_revision" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c jsonb;s jsonb;actor uuid;authz uuid;prior public.conference_participation_operations%rowtype;req jsonb;result jsonb;current_revision bigint;begin
 if p_operation_id is null or p_conference is null or p_entity not in('SETTINGS','EXPENSE','INCOME','SETTLEMENT','ADJUSTMENT') or p_action not in('UPSERT','DELETE') or (p_entity='SETTINGS' and (p_action<>'UPSERT' or p_entity_id is not null)) or (p_entity<>'SETTINGS' and p_entity_id is null) then raise exception 'CONFERENCE_FINANCE_ARGUMENT_INVALID' using errcode='22023';end if;
 s:=nullif(current_setting('platform.phase1c_context',true),'')::jsonb;actor:=(s->>'user_id')::uuid;if s->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' or (s->>'device_id')::uuid is distinct from p_device then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;authz:=platform_private.validated_phase1c_device_authorization(actor,p_device);if authz is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;
 c:=platform_private.require_conference_finance_context(p_device,p_conference,'conference.accounts.manage',true);req:=jsonb_build_object('conferenceId',p_conference,'entity',p_entity,'action',p_action,'entityId',p_entity_id,'expectedRevision',p_expected_revision,'payload',p_payload);
 perform pg_advisory_xact_lock(hashtextextended(actor::text||':conference-participation:'||p_operation_id::text,0));select * into prior from public.conference_participation_operations where actor_user_id=actor and operation_id=p_operation_id;if found then if prior.operation<>'finance_mutation' or prior.request<>req then raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023';end if;return prior.result;end if;
 if p_entity='SETTINGS' then select revision into current_revision from public.conference_finance_settings where conference_id=p_conference for update;else if p_entity='ADJUSTMENT' then select revision into current_revision from public.conference_finance_adjustments where conference_id=p_conference and id=p_entity_id for update;else select revision into current_revision from public.conference_finance_items where conference_id=p_conference and id=p_entity_id for update;end if;end if;current_revision:=coalesce(current_revision,0);if p_expected_revision is distinct from current_revision then raise exception 'CONFERENCE_FINANCE_REVISION_CONFLICT' using errcode='40001';end if;
 if p_action='DELETE' then if p_entity='ADJUSTMENT' then delete from public.conference_finance_adjustments where conference_id=p_conference and id=p_entity_id;else delete from public.conference_finance_items where conference_id=p_conference and id=p_entity_id;end if;
 elsif p_entity='SETTINGS' then perform platform_private.require_exact_jsonb_keys(p_payload,array['currency','roundingPrecision','expensesEnabled','incomeEnabled','settlementsEnabled','adjustmentsEnabled']);insert into public.conference_finance_settings(conference_id,currency,rounding_precision,expenses_enabled,income_enabled,settlements_enabled,adjustments_enabled,revision,created_by,updated_by) values(p_conference,btrim(p_payload->>'currency'),(p_payload->>'roundingPrecision')::smallint,(p_payload->>'expensesEnabled')::boolean,(p_payload->>'incomeEnabled')::boolean,(p_payload->>'settlementsEnabled')::boolean,(p_payload->>'adjustmentsEnabled')::boolean,1,actor,actor) on conflict(conference_id) do update set currency=excluded.currency,rounding_precision=excluded.rounding_precision,expenses_enabled=excluded.expenses_enabled,income_enabled=excluded.income_enabled,settlements_enabled=excluded.settlements_enabled,adjustments_enabled=excluded.adjustments_enabled,revision=public.conference_finance_settings.revision+1,updated_at=statement_timestamp(),updated_by=actor;
 elsif p_entity='ADJUSTMENT' then perform platform_private.require_exact_jsonb_keys(p_payload,array['type','category','amount','note']);insert into public.conference_finance_adjustments(id,conference_id,type,category,amount,note,revision,created_by,updated_by) values(p_entity_id,p_conference,p_payload->>'type',p_payload->>'category',(p_payload->>'amount')::numeric,coalesce(p_payload->>'note',''),1,actor,actor) on conflict(id) do update set type=excluded.type,category=excluded.category,amount=excluded.amount,note=excluded.note,revision=public.conference_finance_adjustments.revision+1,updated_at=statement_timestamp(),updated_by=actor where public.conference_finance_adjustments.conference_id=p_conference;
 else perform platform_private.require_exact_jsonb_keys(p_payload,array['name','enabled','calculationMethod','target','operation','quantity','unitPrice','amount','notes']);insert into public.conference_finance_items(id,conference_id,kind,name,enabled,calculation_method,target,operation,quantity,unit_price,amount,notes,revision,created_by,updated_by) values(p_entity_id,p_conference,p_entity,coalesce(p_payload->>'name',''),(p_payload->>'enabled')::boolean,p_payload->>'calculationMethod',nullif(p_payload->>'target',''),nullif(p_payload->>'operation',''),nullif(p_payload->>'quantity','')::numeric,nullif(p_payload->>'unitPrice','')::numeric,nullif(p_payload->>'amount','')::numeric,coalesce(p_payload->>'notes',''),1,actor,actor) on conflict(id) do update set name=excluded.name,enabled=excluded.enabled,calculation_method=excluded.calculation_method,target=excluded.target,operation=excluded.operation,quantity=excluded.quantity,unit_price=excluded.unit_price,amount=excluded.amount,notes=excluded.notes,revision=public.conference_finance_items.revision+1,updated_at=statement_timestamp(),updated_by=actor where public.conference_finance_items.conference_id=p_conference;
 end if;
 result:=platform_private.conference_finance_projection(p_conference);insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at) values(actor,p_operation_id,'finance_mutation',req,result,statement_timestamp());insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source) values(actor,authz,'platform','conference','conference.finance.changed','conference_finance',coalesce(p_entity_id,p_conference),'platform',null,p_payload,jsonb_build_object('conferenceId',p_conference,'entity',p_entity,'permissionKey','conference.accounts.manage'),p_operation_id,'rpc');return result;
end $$;


--
-- Name: mutate_conference_house_directory("uuid", "uuid", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mutate_conference_house_directory"("p_device" "uuid", "p_operation_id" "uuid", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare context jsonb;actor uuid;auth_id uuid;entity_id uuid;expected bigint;old_row jsonb;result jsonb;parent_id uuid;
begin
 if p_operation_id is null or p_operation not in('create_house','update_house','deactivate_house','create_floor','update_floor','delete_floor','create_room','update_room','delete_room') then raise exception 'HOUSE_DIRECTORY_ARGUMENT_INVALID' using errcode='22023'; end if;
 context:=platform_private.require_conference_house_directory_context(p_device,'conference.houses.manage');actor:=(context->>'actorUserId')::uuid;auth_id:=platform_private.validated_phase1c_device_authorization(actor,p_device);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor::text||':house-directory:'||p_operation_id::text,0));
 select new_values into result from platform.audit_events where actor_user_id=actor and operation_id=p_operation_id and action='conference.houses.'||p_operation limit 1;
 if result is not null then return result||jsonb_build_object('status','duplicate'); end if;
 if p_operation='create_house' then
  insert into public.conference_accommodation_houses(name,description,position,created_by,updated_by) values(btrim(p_args->>'name'),nullif(btrim(p_args->>'description'),''),coalesce((p_args->>'position')::integer,0),actor,actor) returning id into entity_id;
 elsif p_operation in('update_house','deactivate_house') then
  entity_id:=(p_args->>'houseId')::uuid;expected:=(p_args->>'expectedRevision')::bigint;select to_jsonb(h) into old_row from public.conference_accommodation_houses h where h.id=entity_id for update;if old_row is null then raise exception 'HOUSE_NOT_FOUND' using errcode='P0002';end if;if (old_row->>'revision')::bigint<>expected then raise exception 'HOUSE_REVISION_CONFLICT' using errcode='40001';end if;
  if p_operation='deactivate_house' then update public.conference_accommodation_houses set is_active=false,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=entity_id;else update public.conference_accommodation_houses set name=btrim(p_args->>'name'),description=nullif(btrim(p_args->>'description'),''),position=coalesce((p_args->>'position')::integer,position),is_active=coalesce((p_args->>'isActive')::boolean,is_active),revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=entity_id;end if;
 elsif p_operation='create_floor' then parent_id:=(p_args->>'houseId')::uuid;if not exists(select 1 from public.conference_accommodation_houses where id=parent_id) then raise exception 'HOUSE_NOT_FOUND' using errcode='P0002';end if;insert into public.conference_accommodation_floors(house_id,name,position,created_by,updated_by) values(parent_id,btrim(p_args->>'name'),coalesce((p_args->>'position')::integer,0),actor,actor) returning id into entity_id;
 elsif p_operation in('update_floor','delete_floor') then entity_id:=(p_args->>'floorId')::uuid;expected:=(p_args->>'expectedRevision')::bigint;select to_jsonb(f) into old_row from public.conference_accommodation_floors f where f.id=entity_id for update;if old_row is null then raise exception 'FLOOR_NOT_FOUND' using errcode='P0002';end if;if (old_row->>'revision')::bigint<>expected then raise exception 'HOUSE_REVISION_CONFLICT' using errcode='40001';end if;if p_operation='delete_floor' then if exists(select 1 from public.conference_accommodation_rooms where floor_id=entity_id) then raise exception 'FLOOR_NOT_EMPTY' using errcode='55000';end if;delete from public.conference_accommodation_floors where id=entity_id;else update public.conference_accommodation_floors set name=btrim(p_args->>'name'),position=coalesce((p_args->>'position')::integer,position),revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=entity_id;end if;
 elsif p_operation='create_room' then parent_id:=(p_args->>'floorId')::uuid;if not exists(select 1 from public.conference_accommodation_floors where id=parent_id) then raise exception 'FLOOR_NOT_FOUND' using errcode='P0002';end if;insert into public.conference_accommodation_rooms(floor_id,room_number,base_capacity,extra_bed_capacity,notes,position,created_by,updated_by) values(parent_id,btrim(p_args->>'roomNumber'),(p_args->>'baseCapacity')::integer,coalesce((p_args->>'extraBedCapacity')::integer,0),nullif(btrim(p_args->>'notes'),''),coalesce((p_args->>'position')::integer,0),actor,actor) returning id into entity_id;
 else entity_id:=(p_args->>'roomId')::uuid;expected:=(p_args->>'expectedRevision')::bigint;select to_jsonb(r) into old_row from public.conference_accommodation_rooms r where r.id=entity_id for update;if old_row is null then raise exception 'ROOM_NOT_FOUND' using errcode='P0002';end if;if (old_row->>'revision')::bigint<>expected then raise exception 'HOUSE_REVISION_CONFLICT' using errcode='40001';end if;if p_operation='delete_room' then if exists(select 1 from public.conference_accommodation_occupancies where room_id=entity_id) then raise exception 'ROOM_HAS_OCCUPANCIES' using errcode='55000';end if;delete from public.conference_accommodation_rooms where id=entity_id;else update public.conference_accommodation_rooms set room_number=btrim(p_args->>'roomNumber'),base_capacity=(p_args->>'baseCapacity')::integer,extra_bed_capacity=coalesce((p_args->>'extraBedCapacity')::integer,0),notes=nullif(btrim(p_args->>'notes'),''),position=coalesce((p_args->>'position')::integer,position),revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=entity_id;end if;
 end if;
 result:=jsonb_build_object('status','success','entityId',entity_id,'operationId',p_operation_id);
 insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source) values(actor,auth_id,'platform','conference','conference.houses.'||p_operation,'conference_house_directory',entity_id,'platform',old_row,result,jsonb_build_object('permissionKey','conference.houses.manage','deviceId',p_device),p_operation_id,'rpc');return result;
end $$;


--
-- Name: mutate_conference_restaurant("uuid", "uuid", "text", "uuid", bigint, "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mutate_conference_restaurant"("p_device" "uuid", "p_operation_id" "uuid", "p_operation" "text", "p_conference" "uuid", "p_expected_revision" bigint, "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ declare c jsonb;actor uuid;authz uuid;req jsonb;prior public.conference_participation_operations%rowtype;old jsonb;result jsonb;entity uuid;rev bigint;maximum_day integer;begin
  if p_operation_id is null or p_operation not in('update_settings','upsert_price','delete_price','upsert_count','delete_count','upsert_participation','delete_participation') or jsonb_typeof(p_payload)<>'object' then raise exception 'CONFERENCE_RESTAURANT_ARGUMENT_INVALID' using errcode='22023';end if;
  c:=platform_private.require_conference_restaurant_context(p_device,p_conference,'conference.restaurant.manage',true);actor:=(c->>'actorUserId')::uuid;authz:=platform_private.validated_phase1c_device_authorization(actor,p_device);req:=jsonb_build_object('operation',p_operation,'conferenceId',p_conference,'expectedRevision',p_expected_revision,'payload',p_payload);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':conference-participation:'||p_operation_id::text,0));select * into prior from public.conference_participation_operations where actor_user_id=actor and operation_id=p_operation_id;
  if found then if prior.operation<>'restaurant_mutation' or prior.request<>req then raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023';end if;return prior.result;end if;
  if p_operation='update_settings' then
    perform platform_private.require_exact_jsonb_keys(p_payload,array['enabled','firstMeal','lastMeal','prices']);perform platform_private.require_exact_jsonb_keys(p_payload->'prices',array['breakfast','lunch','dinner']);
    insert into public.conference_restaurant_settings(conference_id,enabled,first_meal,last_meal,breakfast_price,lunch_price,dinner_price,created_by,updated_by) values(p_conference,coalesce((p_payload->>'enabled')::boolean,true),p_payload->>'firstMeal',p_payload->>'lastMeal',(p_payload->'prices'->>'breakfast')::numeric,(p_payload->'prices'->>'lunch')::numeric,(p_payload->'prices'->>'dinner')::numeric,actor,actor)
    on conflict(conference_id) do update set enabled=excluded.enabled,first_meal=excluded.first_meal,last_meal=excluded.last_meal,breakfast_price=excluded.breakfast_price,lunch_price=excluded.lunch_price,dinner_price=excluded.dinner_price,revision=conference_restaurant_settings.revision+1,updated_at=statement_timestamp(),updated_by=actor where p_expected_revision=conference_restaurant_settings.revision returning conference_id,revision into entity,rev;
  elsif p_operation like '%price' then
    perform platform_private.require_exact_jsonb_keys(p_payload,case when p_operation='upsert_price' then array['day','meal','price'] else array['day','meal'] end);select (end_date-start_date)+1 into maximum_day from public.conferences where id=p_conference;if (p_payload->>'day')::integer not between 1 and maximum_day then raise exception 'CONFERENCE_RESTAURANT_DAY_INVALID' using errcode='22023';end if;
    select to_jsonb(x),x.id,x.revision into old,entity,rev from public.conference_restaurant_price_overrides x where conference_id=p_conference and day_number=(p_payload->>'day')::integer and meal=p_payload->>'meal' for update;
    if p_operation='delete_price' then if entity is null then raise exception 'CONFERENCE_RESTAURANT_NOT_FOUND' using errcode='P0002';end if;if rev<>p_expected_revision then raise exception 'CONFERENCE_RESTAURANT_REVISION_CONFLICT' using errcode='40001';end if;delete from public.conference_restaurant_price_overrides where id=entity;
    elsif entity is null then insert into public.conference_restaurant_price_overrides(conference_id,day_number,meal,price,created_by,updated_by) values(p_conference,(p_payload->>'day')::integer,p_payload->>'meal',(p_payload->>'price')::numeric,actor,actor) returning id,revision into entity,rev;
    else if rev<>p_expected_revision then raise exception 'CONFERENCE_RESTAURANT_REVISION_CONFLICT' using errcode='40001';end if;update public.conference_restaurant_price_overrides set price=(p_payload->>'price')::numeric,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=entity returning revision into rev;end if;
  elsif p_operation like '%count' then
    perform platform_private.require_exact_jsonb_keys(p_payload,case when p_operation='upsert_count' then array['day','meal','extra','deduction','note'] else array['day','meal'] end);select (end_date-start_date)+1 into maximum_day from public.conferences where id=p_conference;if (p_payload->>'day')::integer not between 1 and maximum_day then raise exception 'CONFERENCE_RESTAURANT_DAY_INVALID' using errcode='22023';end if;
    select to_jsonb(x),x.id,x.revision into old,entity,rev from public.conference_restaurant_count_overrides x where conference_id=p_conference and day_number=(p_payload->>'day')::integer and meal=p_payload->>'meal' for update;
    if p_operation='delete_count' then if entity is null then raise exception 'CONFERENCE_RESTAURANT_NOT_FOUND' using errcode='P0002';end if;if rev<>p_expected_revision then raise exception 'CONFERENCE_RESTAURANT_REVISION_CONFLICT' using errcode='40001';end if;delete from public.conference_restaurant_count_overrides where id=entity;
    elsif entity is null then insert into public.conference_restaurant_count_overrides(conference_id,day_number,meal,extra_count,deduction_count,note,created_by,updated_by) values(p_conference,(p_payload->>'day')::integer,p_payload->>'meal',(p_payload->>'extra')::integer,(p_payload->>'deduction')::integer,nullif(p_payload->>'note',''),actor,actor) returning id,revision into entity,rev;
    else if rev<>p_expected_revision then raise exception 'CONFERENCE_RESTAURANT_REVISION_CONFLICT' using errcode='40001';end if;update public.conference_restaurant_count_overrides set extra_count=(p_payload->>'extra')::integer,deduction_count=(p_payload->>'deduction')::integer,note=nullif(p_payload->>'note',''),revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=entity returning revision into rev;end if;
  else
    perform platform_private.require_exact_jsonb_keys(p_payload,case when p_operation='upsert_participation' then array['participationId','day','meal','included','note'] else array['participationId','day','meal'] end);select (end_date-start_date)+1 into maximum_day from public.conferences where id=p_conference;if (p_payload->>'day')::integer not between 1 and maximum_day or not exists(select 1 from public.conference_participations where id=(p_payload->>'participationId')::uuid and conference_id=p_conference and status='active') then raise exception 'CONFERENCE_RESTAURANT_PARTICIPATION_INELIGIBLE' using errcode='23514';end if;
    select to_jsonb(x),x.id,x.revision into old,entity,rev from public.conference_restaurant_participation_overrides x where conference_id=p_conference and participation_id=(p_payload->>'participationId')::uuid and day_number=(p_payload->>'day')::integer and meal=p_payload->>'meal' for update;
    if p_operation='delete_participation' then if entity is null then raise exception 'CONFERENCE_RESTAURANT_NOT_FOUND' using errcode='P0002';end if;if rev<>p_expected_revision then raise exception 'CONFERENCE_RESTAURANT_REVISION_CONFLICT' using errcode='40001';end if;delete from public.conference_restaurant_participation_overrides where id=entity;
    elsif entity is null then insert into public.conference_restaurant_participation_overrides(conference_id,participation_id,day_number,meal,included,note,created_by,updated_by) values(p_conference,(p_payload->>'participationId')::uuid,(p_payload->>'day')::integer,p_payload->>'meal',(p_payload->>'included')::boolean,nullif(p_payload->>'note',''),actor,actor) returning id,revision into entity,rev;
    else if rev<>p_expected_revision then raise exception 'CONFERENCE_RESTAURANT_REVISION_CONFLICT' using errcode='40001';end if;update public.conference_restaurant_participation_overrides set included=(p_payload->>'included')::boolean,note=nullif(p_payload->>'note',''),revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=entity returning revision into rev;end if;
  end if;
  if entity is null then raise exception 'CONFERENCE_RESTAURANT_REVISION_CONFLICT' using errcode='40001';end if;result:=jsonb_build_object('conferenceId',p_conference,'entityId',entity,'operation',p_operation,'revision',rev,'deleted',p_operation like 'delete_%');
  insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at) values(actor,p_operation_id,'restaurant_mutation',req,result,statement_timestamp());
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source) values(actor,authz,'platform','conference','conference.restaurant.'||p_operation,'conference_restaurant_fact',entity,'platform',old,case when p_operation like 'delete_%' then null else p_payload end,jsonb_build_object('conferenceId',p_conference,'permissionKey','conference.restaurant.manage'),p_operation_id,'rpc');return result;
end $$;


--
-- Name: mutate_conference_transport_vehicle("uuid", "uuid", "text", "uuid", "uuid", bigint, "text", "text", integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."mutate_conference_transport_vehicle"("p_device" "uuid", "p_operation_id" "uuid", "p_operation" "text", "p_conference" "uuid", "p_vehicle" "uuid", "p_expected_revision" bigint, "p_name" "text", "p_icon" "text", "p_capacity" integer, "p_position" integer, "p_remove_overflow" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c jsonb; actor uuid; authz uuid; req jsonb; prior public.conference_participation_operations%rowtype;
  old public.conference_transport_vehicles%rowtype; row public.conference_transport_vehicles%rowtype;
  removed public.conference_transport_assignments%rowtype; removed_ids jsonb:='[]'::jsonb; result jsonb;
begin
  if p_operation_id is null or p_operation not in('create','update','delete') then raise exception 'CONFERENCE_TRANSPORT_ARGUMENT_INVALID' using errcode='22023'; end if;
  c:=platform_private.require_conference_transport_context(p_device,p_conference,'conference.transport.manage',true); actor:=(c->>'actorUserId')::uuid; authz:=platform_private.validated_phase1c_device_authorization(actor,p_device);
  req:=jsonb_build_object('operation',p_operation,'conferenceId',p_conference,'vehicleId',p_vehicle,'expectedRevision',p_expected_revision,'name',p_name,'icon',p_icon,'capacity',p_capacity,'position',p_position,'removeOverflow',p_remove_overflow);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':conference-participation:'||p_operation_id::text,0));
  select * into prior from public.conference_participation_operations where actor_user_id=actor and operation_id=p_operation_id;
  if found then if prior.operation<>'transport_vehicle_'||p_operation or prior.request<>req then raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023'; end if; return prior.result; end if;
  if p_operation='create' then insert into public.conference_transport_vehicles(conference_id,name,icon,capacity,position,created_by,updated_by) values(p_conference,btrim(p_name),coalesce(nullif(p_icon,''),'🚌'),p_capacity,coalesce(p_position,0),actor,actor) returning * into row;
  else select * into old from public.conference_transport_vehicles where id=p_vehicle and conference_id=p_conference for update; if not found then raise exception 'CONFERENCE_TRANSPORT_VEHICLE_NOT_FOUND' using errcode='P0002'; end if; if old.revision<>p_expected_revision then raise exception 'CONFERENCE_TRANSPORT_REVISION_CONFLICT' using errcode='40001'; end if;
    if p_operation='delete' then
      for removed in select * from public.conference_transport_assignments where vehicle_id=p_vehicle order by id for update loop
        perform platform_private.audit_conference_transport_assignment_removal(actor,authz,removed,p_operation_id,'vehicle_deleted','conference.transport.manage'); removed_ids:=removed_ids||jsonb_build_array(removed.id);
      end loop;
      delete from public.conference_transport_assignments where vehicle_id=p_vehicle; delete from public.conference_transport_vehicles where id=p_vehicle; row:=old;
    else
      if p_capacity<old.capacity and exists(select 1 from public.conference_transport_assignments where vehicle_id=p_vehicle and seat_number>p_capacity) and not coalesce(p_remove_overflow,false) then raise exception 'CONFERENCE_TRANSPORT_CAPACITY_OCCUPIED' using errcode='23514'; end if;
      if p_capacity<old.capacity then
        for removed in select * from public.conference_transport_assignments where vehicle_id=p_vehicle and seat_number>p_capacity order by id for update loop
          perform platform_private.audit_conference_transport_assignment_removal(actor,authz,removed,p_operation_id,'capacity_reduced','conference.transport.manage'); removed_ids:=removed_ids||jsonb_build_array(removed.id);
        end loop;
        delete from public.conference_transport_assignments where vehicle_id=p_vehicle and seat_number>p_capacity;
      end if;
      update public.conference_transport_vehicles set name=btrim(p_name),icon=coalesce(nullif(p_icon,''),'🚌'),capacity=p_capacity,position=coalesce(p_position,position),revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=p_vehicle returning * into row;
    end if;
  end if;
  result:=jsonb_build_object('vehicleId',row.id,'conferenceId',row.conference_id,'name',row.name,'icon',row.icon,'capacity',row.capacity,'position',row.position,'revision',row.revision,'deleted',p_operation='delete','removedAssignmentIds',removed_ids);
  insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at) values(actor,p_operation_id,'transport_vehicle_'||p_operation,req,result,statement_timestamp());
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source) values(actor,authz,'platform','conference','conference.transport.vehicle_'||p_operation,'conference_transport_vehicle',row.id,'platform',case when p_operation='create' then null else to_jsonb(old) end,case when p_operation='delete' then null else to_jsonb(row) end,jsonb_build_object('conferenceId',p_conference,'permissionKey','conference.transport.manage'),p_operation_id,'rpc'); return result;
end $$;


