--
-- Name: protect_module_permission_catalog_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."protect_module_permission_catalog_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'MODULE_PERMISSION_CATALOG_DELETE_PROHIBITED' using errcode = '55000';
  end if;

  if new.permission_key is distinct from old.permission_key
     or new.module_key is distinct from old.module_key
     or new.created_at is distinct from old.created_at then
    raise exception 'MODULE_PERMISSION_CATALOG_IDENTITY_IMMUTABLE' using errcode = '55000';
  end if;

  if old.status = 'retired' and new.status <> 'retired' then
    raise exception 'MODULE_PERMISSION_CATALOG_REACTIVATION_PROHIBITED' using errcode = '55000';
  end if;

  if (
    new.display_name is distinct from old.display_name
    or new.description is distinct from old.description
    or new.status is distinct from old.status
    or new.allowed_scope_mode is distinct from old.allowed_scope_mode
    or new.allowed_resource_type is distinct from old.allowed_resource_type
    or new.sensitive_mutation is distinct from old.sensitive_mutation
    or new.retired_at is distinct from old.retired_at
  ) and new.catalog_version <= old.catalog_version then
    raise exception 'MODULE_PERMISSION_CATALOG_VERSION_INCREMENT_REQUIRED' using errcode = '55000';
  end if;

  return new;
end;
$$;


--
-- Name: protect_module_permission_grant_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."protect_module_permission_grant_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'MODULE_GRANT_DELETE_PROHIBITED' using errcode = '55000';
  end if;

  if old.revoked_at is not null then
    raise exception 'REVOKED_MODULE_GRANT_IMMUTABLE' using errcode = '55000';
  end if;

  if new.grant_id is distinct from old.grant_id
     or new.user_id is distinct from old.user_id
     or new.module_key is distinct from old.module_key
     or new.permission_key is distinct from old.permission_key
     or new.resource_type is distinct from old.resource_type
     or new.resource_id is distinct from old.resource_id
     or new.granted_by is distinct from old.granted_by
     or new.granted_by_device_id is distinct from old.granted_by_device_id
     or new.granted_at is distinct from old.granted_at
     or new.revoked_at is null
     or new.revoked_by is null
     or new.revoked_by_device_id is null then
    raise exception 'MODULE_GRANT_UPDATE_PROHIBITED' using errcode = '55000';
  end if;

  return new;
end;
$$;


--
-- Name: protect_platform_module_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."protect_platform_module_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.module_key is distinct from old.module_key
     or new.created_at is distinct from old.created_at then
    raise exception 'PLATFORM_MODULE_IDENTITY_IMMUTABLE' using errcode = '55000';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: record_conference_output_event("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."record_conference_output_event"("p_actor_device_id" "uuid", "p_conference_id" "uuid", "p_event" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx jsonb;session_ctx jsonb;actor uuid;authz uuid;event_id uuid;
begin
  if p_event not in('card_shared','card_printed','cards_printed') then raise exception 'CONFERENCE_OUTPUT_EVENT_INVALID' using errcode='22023';end if;
  session_ctx:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;actor:=(session_ctx->>'user_id')::uuid;
  if session_ctx->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' or (session_ctx->>'device_id')::uuid is distinct from p_actor_device_id then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;
  authz:=platform_private.validated_phase1c_device_authorization(actor,p_actor_device_id);if authz is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;
  ctx:=public.require_effective_module_permission(p_actor_device_id,'conference','conference.cards.export','conference',p_conference_id::text);
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,metadata,source)
  values(actor,authz,'platform','conference','conference.output.'||p_event,'conference',p_conference_id,'platform',jsonb_build_object('conferenceId',p_conference_id,'permissionKey','conference.cards.export','authoritySource',ctx->>'authoritySource','grantId',ctx->'grantId'),'rpc') returning id into event_id;
  return jsonb_build_object('recorded',true,'eventId',event_id);
end $$;


--
-- Name: recover_revoke_final_module_manager("uuid", "uuid", "text", "uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
