    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ begin raise exception 'PLATFORM_OPERATION_NOT_ALLOWED' using errcode='42501'; end $$;


--
-- Name: release_conference_lock("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."release_conference_lock"("p_conference_id" "uuid", "p_device_id" "uuid", "p_lock_token" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select public.release_conference_section_lock(p_conference_id,'conference',p_device_id,p_lock_token);
$$;


--
-- Name: release_conference_section_lock("uuid", "text", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."release_conference_section_lock"("p_conference_id" "uuid", "p_section" "text", "p_device_id" "uuid", "p_lock_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare current_user_id uuid; normalized_section text:=lower(trim(coalesce(p_section,''))); current_lock public.conference_locks%rowtype; lock_found boolean; server_now timestamptz:=clock_timestamp();
begin
 if p_conference_id is null or p_device_id is null or p_lock_token is null or normalized_section !~ '^[a-z][a-z0-9_]{0,31}$' then raise exception 'INVALID_CONFERENCE_SECTION_LOCK_ARGUMENTS' using errcode='22023'; end if;
 current_user_id:=public.require_conference_section_lock_writer(p_conference_id,p_device_id,normalized_section); select * into current_lock from public.conference_locks as locks where locks.conference_id=p_conference_id and locks.section=normalized_section for update; lock_found:=found; perform public.require_conference_section_lock_writer(p_conference_id,p_device_id,normalized_section);
 if not lock_found then return jsonb_build_object('success',true,'status','not_found','errorCode','LOCK_NOT_OWNED','conferenceId',p_conference_id,'section',normalized_section,'owned',false,'serverNow',server_now); end if;
 if current_lock.user_id<>current_user_id or current_lock.device_id<>p_device_id then return jsonb_build_object('success',true,'status','not_owner','errorCode','LOCK_NOT_OWNED','conferenceId',p_conference_id,'section',normalized_section,'owned',false,'serverNow',server_now); end if;
 if current_lock.lock_token<>p_lock_token then return jsonb_build_object('success',true,'status','not_owner','errorCode','LOCK_TOKEN_MISMATCH','conferenceId',p_conference_id,'section',normalized_section,'owned',false,'serverNow',server_now); end if;
 delete from public.conference_locks where conference_id=p_conference_id and section=normalized_section; return jsonb_build_object('success',true,'status','released','conferenceId',p_conference_id,'section',normalized_section,'lockToken',p_lock_token,'owned',false,'serverNow',server_now);
end; $_$;


--
-- Name: remove_conference_accommodation("uuid", "uuid", "uuid", bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."remove_conference_accommodation"("p_device" "uuid", "p_conference" "uuid", "p_occupancy" "uuid", "p_expected" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  context jsonb; actor uuid; v_authorization uuid;
  current public.conference_accommodation_occupancies%rowtype;
  member record; family_ids uuid[]; changed_ids jsonb:='[]'::jsonb;
  removed_transport_ids jsonb:='[]'::jsonb;
begin
  context:=platform_private.require_conference_accommodation_context(
    p_device,p_conference,'conference.accommodation.manage',true);
  actor:=(context->>'actorUserId')::uuid;
  v_authorization:=platform_private.validated_phase1c_device_authorization(actor,p_device);
  select * into current from public.conference_accommodation_occupancies
  where id=p_occupancy and conference_id=p_conference for update;
  if not found then raise exception 'ACCOMMODATION_OCCUPANCY_NOT_FOUND' using errcode='P0002'; end if;
  if current.revision<>p_expected then raise exception 'ACCOMMODATION_REVISION_CONFLICT' using errcode='40001'; end if;

  if exists(select 1 from public.conference_participations where id=current.participation_id and guardian_participation_id is null) then
    select array_agg(id order by id) into family_ids from public.conference_participations
    where conference_id=p_conference
      and (id=current.participation_id or guardian_participation_id=current.participation_id);
  else
    family_ids:=array[current.participation_id];
  end if;
  perform 1 from public.conference_participations where id=any(family_ids) order by id for update;
  perform 1 from public.conference_accommodation_rooms where id in(
    select distinct room_id from public.conference_accommodation_occupancies where participation_id=any(family_ids)
  ) order by id for update;
  for member in select unnest(family_ids) participation_id loop
    if platform_private.cleanup_conference_accommodation_for_participation(
      member.participation_id,actor,v_authorization,context,'accommodation_removed',null) is not null then
      changed_ids:=changed_ids||jsonb_build_array(member.participation_id);
    end if;
    removed_transport_ids:=removed_transport_ids||platform_private.cleanup_conference_transport_for_participation(
      member.participation_id,actor,v_authorization,'accommodation_removed',null,'conference.accommodation.manage');
  end loop;
  return jsonb_build_object('occupancyId',current.id,'deleted',true,'familyParticipationIds',to_jsonb(family_ids),
    'changedParticipationIds',changed_ids,'removedTransportAssignmentIds',removed_transport_ids);
end $$;


--
-- Name: remove_conference_transport_assignment("uuid", "uuid", "uuid", bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."remove_conference_transport_assignment"("p_device" "uuid", "p_operation_id" "uuid", "p_assignment" "uuid", "p_expected_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare old public.conference_transport_assignments%rowtype; removed public.conference_transport_assignments%rowtype;
  c jsonb; session_context jsonb; actor uuid; authz uuid; req jsonb; prior public.conference_participation_operations%rowtype;
  removed_ids jsonb:='[]'::jsonb; result jsonb;
begin
  if p_operation_id is null or p_assignment is null or p_expected_revision is null then raise exception 'CONFERENCE_TRANSPORT_ARGUMENT_INVALID' using errcode='22023'; end if;
  begin
    session_context:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;
    if session_context is null or session_context->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' or (session_context->>'device_id')::uuid is distinct from p_device then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
    actor:=(session_context->>'user_id')::uuid;
  exception when invalid_text_representation or null_value_not_allowed then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end;
  authz:=platform_private.validated_phase1c_device_authorization(actor,p_device); if authz is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
  req:=jsonb_build_object('assignmentId',p_assignment,'expectedRevision',p_expected_revision);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':conference-participation:'||p_operation_id::text,0)); select * into prior from public.conference_participation_operations where actor_user_id=actor and operation_id=p_operation_id;
  if found then if prior.operation<>'transport_assignment_remove' or prior.request<>req then raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023'; end if; c:=platform_private.require_conference_transport_context(p_device,(prior.result->>'conferenceId')::uuid,'conference.transport.manage',false); if (c->>'actorUserId')::uuid is distinct from actor then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if; return prior.result; end if;
  select * into old from public.conference_transport_assignments where id=p_assignment for update; if not found then raise exception 'CONFERENCE_TRANSPORT_ASSIGNMENT_NOT_FOUND' using errcode='P0002'; end if;
  c:=platform_private.require_conference_transport_context(p_device,old.conference_id,'conference.transport.manage',true); if (c->>'actorUserId')::uuid is distinct from actor then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
  if old.revision<>p_expected_revision then raise exception 'CONFERENCE_TRANSPORT_REVISION_CONFLICT' using errcode='40001'; end if;
  if old.assignment_mode='independent' then
    for removed in select child_assignment.* from public.conference_transport_assignments child_assignment join public.conference_participations child on child.id=child_assignment.participation_id where child.guardian_participation_id=old.participation_id and child_assignment.assignment_mode='shared' and child_assignment.vehicle_id=old.vehicle_id order by child_assignment.id for update of child_assignment loop
      perform platform_private.audit_conference_transport_assignment_removal(actor,authz,removed,p_operation_id,'guardian_assignment_removed','conference.transport.manage'); removed_ids:=removed_ids||jsonb_build_array(removed.id);
    end loop;
    delete from public.conference_transport_assignments child_assignment using public.conference_participations child where child.id=child_assignment.participation_id and child.guardian_participation_id=old.participation_id and child_assignment.assignment_mode='shared' and child_assignment.vehicle_id=old.vehicle_id;
  end if;
  perform platform_private.audit_conference_transport_assignment_removal(actor,authz,old,p_operation_id,'assignment_removed','conference.transport.manage'); removed_ids:=removed_ids||jsonb_build_array(old.id);
  delete from public.conference_transport_assignments where id=p_assignment;
  result:=jsonb_build_object('assignmentId',p_assignment,'conferenceId',old.conference_id,'deleted',true,'removedAssignmentIds',removed_ids);
  insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at) values(actor,p_operation_id,'transport_assignment_remove',req,result,statement_timestamp()); return result;
end $$;


--
-- Name: renew_conference_lock("uuid", "uuid", "uuid", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."renew_conference_lock"("p_conference_id" "uuid", "p_device_id" "uuid", "p_lock_token" "uuid", "p_ttl_seconds" integer DEFAULT 120) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select public.renew_conference_section_lock(p_conference_id,'conference',p_device_id,p_lock_token,p_ttl_seconds);
$$;


--
-- Name: renew_conference_section_lock("uuid", "text", "uuid", "uuid", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."renew_conference_section_lock"("p_conference_id" "uuid", "p_section" "text", "p_device_id" "uuid", "p_lock_token" "uuid", "p_ttl_seconds" integer DEFAULT 120) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare current_user_id uuid; effective_ttl integer:=coalesce(p_ttl_seconds,120); normalized_section text:=lower(trim(coalesce(p_section,''))); current_lock public.conference_locks%rowtype; lock_found boolean; server_now timestamptz:=clock_timestamp(); new_expiry timestamptz;
begin
 if p_conference_id is null or p_device_id is null or p_lock_token is null or normalized_section !~ '^[a-z][a-z0-9_]{0,31}$' or effective_ttl<30 or effective_ttl>300 then raise exception 'INVALID_CONFERENCE_SECTION_LOCK_ARGUMENTS' using errcode='22023'; end if;
 current_user_id:=public.require_conference_section_lock_writer(p_conference_id,p_device_id,normalized_section); select * into current_lock from public.conference_locks as locks where locks.conference_id=p_conference_id and locks.section=normalized_section for update; lock_found:=found; perform public.require_conference_section_lock_writer(p_conference_id,p_device_id,normalized_section);
 if not lock_found then return jsonb_build_object('success',true,'status','not_found','errorCode','LOCK_NOT_OWNED','conferenceId',p_conference_id,'section',normalized_section,'owned',false,'serverNow',server_now,'isExpired',false); end if;
 if current_lock.expires_at<=server_now then return jsonb_build_object('success',true,'status','expired','errorCode','LOCK_EXPIRED','conferenceId',p_conference_id,'section',normalized_section,'owned',false,'expiresAt',current_lock.expires_at,'lastRenewedAt',current_lock.last_renewed_at,'serverNow',server_now,'isExpired',true); end if;
 if current_lock.user_id<>current_user_id or current_lock.device_id<>p_device_id then return jsonb_build_object('success',true,'status','not_owner','errorCode','LOCK_NOT_OWNED','conferenceId',p_conference_id,'section',normalized_section,'owned',false,'expiresAt',current_lock.expires_at,'lastRenewedAt',current_lock.last_renewed_at,'serverNow',server_now,'isExpired',false); end if;
 if current_lock.lock_token<>p_lock_token then return jsonb_build_object('success',true,'status','not_owner','errorCode','LOCK_TOKEN_MISMATCH','conferenceId',p_conference_id,'section',normalized_section,'owned',false,'expiresAt',current_lock.expires_at,'lastRenewedAt',current_lock.last_renewed_at,'serverNow',server_now,'isExpired',false); end if;
 new_expiry:=server_now+make_interval(secs=>effective_ttl); update public.conference_locks set expires_at=new_expiry,last_renewed_at=server_now where conference_id=p_conference_id and section=normalized_section; return jsonb_build_object('success',true,'status','renewed','conferenceId',p_conference_id,'section',normalized_section,'lockToken',p_lock_token,'owned',true,'userId',current_user_id,'deviceId',p_device_id,'acquiredAt',current_lock.acquired_at,'expiresAt',new_expiry,'lastRenewedAt',server_now,'serverNow',server_now,'isExpired',false);
end; $_$;


--
-- Name: replace_conference_accommodation("uuid", "uuid", "uuid", "uuid", bigint, "uuid", integer, "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."replace_conference_accommodation"("p_device" "uuid", "p_operation_id" "uuid", "p_conference" "uuid", "p_occupancy" "uuid", "p_expected" bigint, "p_replacement_participation" "uuid", "p_effective_day" integer, "p_bed" "text", "p_extra_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare ctx jsonb;actor uuid;authz uuid;days integer;
 old_stay public.conference_accommodation_occupancies%rowtype;
 replacement public.conference_participations%rowtype;
 room public.conference_accommodation_rooms%rowtype;
 new_stay public.conference_accommodation_occupancies%rowtype;
 child_stay public.conference_accommodation_occupancies%rowtype;
 prior_old jsonb;result jsonb;
begin
 if p_operation_id is null then raise exception 'ACCOMMODATION_OPERATION_ID_REQUIRED' using errcode='22023';end if;
 ctx:=platform_private.require_conference_accommodation_context(p_device,p_conference,'conference.accommodation.manage',true);
 actor:=(ctx->>'actorUserId')::uuid;
 authz:=platform_private.validated_phase1c_device_authorization(actor,p_device);
 select new_values into result from platform.audit_events
  where actor_user_id=actor and operation_id=p_operation_id and scope_id=p_conference
    and action='conference.accommodation.replaced' limit 1;
 if result is not null then return result||jsonb_build_object('status','duplicate');end if;
 days:=platform_private.conference_accommodation_duration(p_conference);
 if p_effective_day<1 or p_effective_day>days or p_bed not in('base','extra')
    or (p_bed='base' and p_extra_type is not null)
    or (p_bed='extra' and p_extra_type not in('adult','child')) then
   raise exception 'ACCOMMODATION_REPLACEMENT_ARGUMENT_INVALID' using errcode='22023';
 end if;
 -- Participation locks precede the room and occupancy locks, matching the
 -- canonical accommodation lock order and serializing status changes.
 perform 1 from public.conference_participations
  where id in(p_replacement_participation,(select participation_id from public.conference_accommodation_occupancies where id=p_occupancy))
  order by id for update;
 select * into old_stay from public.conference_accommodation_occupancies
  where id=p_occupancy and conference_id=p_conference;
 if not found then raise exception 'ACCOMMODATION_OCCUPANCY_NOT_FOUND' using errcode='P0002';end if;
 if not exists(select 1 from public.conference_participations where id=old_stay.participation_id and conference_id=p_conference and status='active') then
   raise exception 'ACTIVE_CONFERENCE_PARTICIPATION_REQUIRED' using errcode='42501';
 end if;
 select * into replacement from public.conference_participations
  where id=p_replacement_participation and conference_id=p_conference and status='active';
 if not found then raise exception 'ACTIVE_CONFERENCE_PARTICIPATION_REQUIRED' using errcode='42501';end if;
 if replacement.id=old_stay.participation_id then raise exception 'ACCOMMODATION_REPLACEMENT_PERSON_UNCHANGED' using errcode='22023';end if;
 select * into room from public.conference_accommodation_rooms
  where id=old_stay.room_id and platform_private.conference_room_is_assigned(p_conference,id) for update;
 if not found then raise exception 'ACCOMMODATION_ROOM_NOT_FOUND' using errcode='P0002';end if;
 select * into old_stay from public.conference_accommodation_occupancies where id=p_occupancy for update;
 if old_stay.revision<>p_expected then raise exception 'ACCOMMODATION_REVISION_CONFLICT' using errcode='40001';end if;
 if p_effective_day<old_stay.arrival_day or p_effective_day>=coalesce(old_stay.leave_day,days+1) then
   raise exception 'ACCOMMODATION_REPLACEMENT_DAY_OUTSIDE_STAY' using errcode='22023';
 end if;
 if room.is_closed and (room.closed_day is null or p_effective_day>=room.closed_day) then
   raise exception 'ACCOMMODATION_ROOM_UNAVAILABLE' using errcode='55000';
 end if;
 if exists(select 1 from public.conference_accommodation_occupancies o
   where o.participation_id=p_replacement_participation
     and o.arrival_day<coalesce(old_stay.leave_day,days+1)
     and p_effective_day<coalesce(o.leave_day,days+1)) then
   raise exception 'ACCOMMODATION_STAY_OVERLAP' using errcode='23P01';
 end if;
 if not platform_private.conference_room_has_capacity(p_conference,old_stay.room_id,p_bed,p_effective_day,old_stay.leave_day,old_stay.id) then
   raise exception 'ACCOMMODATION_ROOM_CAPACITY_EXCEEDED' using errcode='55000';
 end if;
 prior_old:=to_jsonb(old_stay);
 -- A room key cannot silently remain attributed to the replaced person.
 update public.conference_room_assignments set key_holder_occupancy_id=null,
  key_delivered_at=null,key_delivered_by=null,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor
  where conference_id=p_conference and room_id=old_stay.room_id and key_holder_occupancy_id=old_stay.id;
 insert into public.conference_accommodation_occupancies(
  conference_id,room_id,participation_id,arrival_day,leave_day,bed_type,
  extra_bed_person_type,arrived_at,arrived_by,created_by,updated_by
 ) values(
  p_conference,old_stay.room_id,replacement.id,p_effective_day,old_stay.leave_day,p_bed,
  p_extra_type,null,null,actor,actor
 ) returning * into new_stay;
 -- Replacing a guardian removes only the children currently housed
 -- under that guardian from accommodation. Their central participation and
 -- guardian relationship remain intact. This is part of the same transaction.
 for child_stay in
   select o.*
   from public.conference_accommodation_occupancies o
   join public.conference_participations cp on cp.id=o.participation_id
   where o.conference_id=p_conference
     and o.room_id=old_stay.room_id
     and cp.guardian_participation_id=old_stay.participation_id and o.bed_type='shared'
     and o.arrival_day<=p_effective_day
     and p_effective_day<coalesce(o.leave_day,days+1)
     and o.id<>old_stay.id
   order by o.id
   for update
 loop
   update public.conference_room_assignments set key_holder_occupancy_id=null,key_delivered_at=null,key_delivered_by=null,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where conference_id=p_conference and room_id=old_stay.room_id and key_holder_occupancy_id=child_stay.id;
   if p_effective_day=child_stay.arrival_day then
     delete from public.conference_accommodation_occupancies where id=child_stay.id;
   else
     update public.conference_accommodation_occupancies
       set leave_day=p_effective_day,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor
       where id=child_stay.id;
   end if;
 end loop;

 if p_effective_day=old_stay.arrival_day then
   -- The original row cannot represent a zero-length segment. Its complete
   -- value remains immutable in the audit event; deletion occurs only inside
   -- this transaction and therefore rolls back if the replacement fails.
   delete from public.conference_accommodation_occupancies where id=old_stay.id;
 else
   update public.conference_accommodation_occupancies set leave_day=p_effective_day,
    revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=old_stay.id;
 end if;
 result:=jsonb_build_object('status','success','occupancyId',new_stay.id,'revision',new_stay.revision,
  'roomId',new_stay.room_id,'participationId',new_stay.participation_id,
  'previousOccupancyId',old_stay.id,'previousParticipationId',old_stay.participation_id,
  'effectiveDay',p_effective_day,'historicalSegmentPreserved',p_effective_day>old_stay.arrival_day);
 insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,
  entity_type,entity_id,scope_type,scope_id,old_values,new_values,metadata,operation_id,source)
 values(actor,authz,'platform','conference','conference.accommodation.replaced','accommodation_occupancy',
  new_stay.id,'conference',p_conference,prior_old,result,
  jsonb_build_object('conferenceId',p_conference,'roomId',old_stay.room_id,
   'previousOccupancyId',old_stay.id,'previousParticipationId',old_stay.participation_id,
   'replacementParticipationId',replacement.id,'effectiveDay',p_effective_day,
   'permissionKey','conference.accommodation.manage','authoritySource',ctx->>'authoritySource','grantId',ctx->'grantId'),
  p_operation_id,'rpc');
 return result;
exception when exclusion_violation then raise exception 'ACCOMMODATION_STAY_OVERLAP' using errcode='23P01';
end $$;


--
-- Name: require_conference_section_lock_writer("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."require_conference_section_lock_writer"("p_conference_id" "uuid", "p_actor_device_id" "uuid", "p_section" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  authority jsonb;
  actor_id uuid;
  normalized_section text := lower(trim(coalesce(p_section,'')));
  permission_key text;
begin
  if p_conference_id is null or p_actor_device_id is null then
    raise exception 'INVALID_CONFERENCE_LOCK_AUTHORIZATION_ARGUMENTS' using errcode='22023';
  end if;
  permission_key := case
    when normalized_section = 'accommodation' then 'conference.accommodation.manage'
    when normalized_section = '' or normalized_section = 'conference' then 'conference.sync.write'
    else null
  end;
  if permission_key is null then
    raise exception 'UNMAPPED_CONFERENCE_LOCK_SECTION: %',normalized_section using errcode='42501';
  end if;
  authority := public.require_effective_module_permission(
    p_actor_device_id,'conference',permission_key,'conference',p_conference_id::text
  );
  actor_id := nullif(authority->>'actorUserId','')::uuid;
  if actor_id is null then
    raise exception 'CANONICAL_CONFERENCE_LOCK_AUTHORITY_INVALID' using errcode='42501';
  end if;
  return actor_id;
end;
$$;


--
-- Name: require_current_approved_device("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."require_current_approved_device"("p_actor_device_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare current_user_id uuid:=auth.uid(); platform_authorization_id uuid;
begin
  if current_user_id is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_actor_device_id is null then raise exception 'DEVICE_REQUIRED' using errcode='22023'; end if;
  platform_authorization_id:=platform_private.validated_phase1c_device_authorization(
    current_user_id,p_actor_device_id);
  if platform_authorization_id is null then
    raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';
  end if;
  perform platform_private.require_canonical_device_authorization(
    current_user_id,p_actor_device_id,true);
  return current_user_id;
end; $$;


--
-- Name: require_effective_module_permission("uuid", "text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."require_effective_module_permission"("p_actor_device_id" "uuid", "p_module_key" "text", "p_permission_key" "text", "p_resource_type" "text" DEFAULT NULL::"text", "p_resource_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid;v_permission platform.permissions%rowtype;v_grant platform.permission_grants%rowtype;v_assignment platform.user_roles%rowtype;v_role_code text;v_requested_scope text;
begin
 v_actor:=public.require_current_approved_device(p_actor_device_id);
 if p_module_key not in('conference','warehouse','reservations') or p_permission_key is null
  or split_part(p_permission_key,'.',1)<>p_module_key or ((p_resource_type is null)<>(p_resource_id is null))
 then raise exception 'INVALID_MODULE_PERMISSION_REQUEST' using errcode='22023'; end if;
 select * into v_permission from platform.permissions where code=p_permission_key and domain=p_module_key and status='active';
 if not found then raise exception 'ACTIVE_MODULE_PERMISSION_REQUIRED' using errcode='42501'; end if;
 v_requested_scope:=case when p_resource_type is null then 'module' else 'resource' end;
 if v_requested_scope='module' and v_permission.allowed_scope_mode not in('module','both') then raise exception 'MODULE_PERMISSION_SCOPE_NOT_ALLOWED' using errcode='42501'; end if;
 if v_requested_scope='resource' and (v_permission.allowed_scope_mode not in('resource','both') or v_permission.allowed_resource_type<>p_resource_type or p_resource_id is null or length(p_resource_id) not between 1 and 255 or p_resource_id<>btrim(p_resource_id)) then raise exception 'MODULE_PERMISSION_RESOURCE_TYPE_INVALID' using errcode='42501'; end if;
 if platform_private.is_canonical_platform_owner(v_actor) then return jsonb_build_object('actorUserId',v_actor,'actorDeviceId',p_actor_device_id,'moduleKey',p_module_key,'permissionKey',p_permission_key,'resourceType',p_resource_type,'resourceId',p_resource_id,'authoritySource','platform_owner','grantId',null,'roleCode','platform_owner'); end if;
 if v_requested_scope='resource' then select g.* into v_grant from platform.permission_grants g where g.user_id=v_actor and g.permission_id=v_permission.id and g.scope_type='resource' and g.resource_type=p_resource_type and g.resource_id=p_resource_id and g.revoked_at is null limit 1; end if;
 if v_grant.id is null and v_permission.allowed_scope_mode in('module','both') then select g.* into v_grant from platform.permission_grants g where g.user_id=v_actor and g.permission_id in(v_permission.id,case when p_permission_key=p_module_key||'.module.access' then (select id from platform.permissions where code=p_module_key||'.module.manage' and status='active') else v_permission.id end) and g.scope_type='module' and g.resource_type is null and g.resource_id is null and g.revoked_at is null limit 1; end if;
 if v_grant.id is not null then return jsonb_build_object('actorUserId',v_actor,'actorDeviceId',p_actor_device_id,'moduleKey',p_module_key,'permissionKey',p_permission_key,'resourceType',p_resource_type,'resourceId',p_resource_id,'authoritySource',case when v_grant.scope_type='module' then 'module_grant' else 'resource_grant' end,'grantId',v_grant.id,'roleCode',null); end if;
 select a.* into v_assignment from platform.user_roles a join platform.roles r on r.id=a.role_id join platform.role_permissions rp on rp.role_id=r.id join platform.permissions p on p.id=rp.permission_id where a.user_id=v_actor and a.revoked_at is null and (a.expires_at is null or a.expires_at>statement_timestamp()) and p.status='active' and p.code in(p_permission_key,case when p_permission_key=p_module_key||'.module.access' then p_module_key||'.module.manage' else p_permission_key end) and ((v_requested_scope='resource' and a.scope_type=p_resource_type and a.scope_id::text=p_resource_id) or (v_requested_scope='module' and a.scope_type='platform' and a.scope_id is null)) order by a.granted_at limit 1;
 if v_assignment.id is null then raise exception 'MODULE_PERMISSION_REQUIRED' using errcode='42501'; end if;
 select code into v_role_code from platform.roles where id=v_assignment.role_id;
 return jsonb_build_object('actorUserId',v_actor,'actorDeviceId',p_actor_device_id,'moduleKey',p_module_key,'permissionKey',p_permission_key,'resourceType',p_resource_type,'resourceId',p_resource_id,'authoritySource','role','grantId',v_assignment.id,'roleCode',v_role_code);
end $$;


--
-- Name: require_platform_device_backend(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."require_platform_device_backend"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if coalesce(auth.jwt()->>'role','')<>'service_role' then
    raise exception 'PLATFORM_DEVICE_BACKEND_REQUIRED' using errcode='42501';
  end if;
end;
$$;


--
-- Name: require_system_owner_webauthn_actor("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."require_system_owner_webauthn_actor"("p_actor_user_id" "uuid", "p_actor_device_id" "uuid", "p_credential_id" "uuid") RETURNS "public"."device_security_credentials"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare credential public.device_security_credentials%rowtype;
begin
  perform public.require_platform_device_backend();
  if not platform_private.is_canonical_platform_owner(p_actor_user_id) then
    raise exception 'APPROVED_SYSTEM_OWNER_REQUIRED' using errcode='42501';
  end if;
  perform platform_private.require_canonical_device_authorization(
    p_actor_user_id,p_actor_device_id,true);
  select * into credential from public.device_security_credentials stored
  where stored.id=p_credential_id and stored.user_id=p_actor_user_id
    and stored.credential_kind='platform_primary' and stored.lifecycle_status='active'
    and stored.user_verification_policy='required'
    and (not stored.backup_state or stored.backup_eligible)
    and ((stored.backup_eligible and stored.backup_state)
      or stored.device_id=p_actor_device_id)
  for update;
  if not found then
    raise exception 'ACTIVE_PLATFORM_CREDENTIAL_REQUIRED' using errcode='42501';
  end if;
  return credential;
end; $$;


--
-- Name: restore_conference_canonical_bundle("uuid", "uuid", "jsonb", "text", "uuid", bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."restore_conference_canonical_bundle"("p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_bundle" "jsonb", "p_mode" "text", "p_target_conference_id" "uuid", "p_expected_revision" bigint, "p_confirmed" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_actor uuid;v_check jsonb;v_source uuid;v_target uuid;v_core jsonb;v_sections jsonb;v_hash text;v_existing platform_private.conference_bundle_operations%rowtype;v_table text;v_result jsonb;v_auth uuid;
declare v_delete_order text[]=array['conference_transport_assignments','conference_restaurant_participation_overrides','conference_accommodation_occupancies','conference_room_assignments','conference_transport_vehicles','conference_restaurant_count_overrides','conference_restaurant_price_overrides','conference_restaurant_settings','conference_finance_adjustments','conference_finance_items','conference_finance_settings','conference_air_conditioning_room_overrides','conference_air_conditioning_house_overrides','conference_air_conditioning_defaults','conference_accommodation_pricing_room_exclusions','conference_accommodation_pricing','conference_branding','conference_house_assignments','conference_participations'];
declare v_insert_order text[]=array['conference_participations','conference_house_assignments','conference_room_assignments','conference_transport_vehicles','conference_accommodation_pricing','conference_accommodation_pricing_room_exclusions','conference_air_conditioning_defaults','conference_air_conditioning_house_overrides','conference_air_conditioning_room_overrides','conference_branding','conference_finance_settings','conference_finance_items','conference_finance_adjustments','conference_restaurant_settings','conference_restaurant_price_overrides','conference_restaurant_count_overrides','conference_restaurant_participation_overrides','conference_accommodation_occupancies','conference_transport_assignments'];
begin
 v_actor:=public.require_current_approved_device(p_actor_device_id);
 if p_operation_id is null then raise exception 'CONFERENCE_BUNDLE_OPERATION_ID_REQUIRED' using errcode='22023'; end if;
 if p_mode='replace' and p_confirmed is distinct from true then raise exception 'CONFERENCE_BUNDLE_REPLACE_CONFIRMATION_REQUIRED' using errcode='42501'; end if;
 v_check:=platform_private.validate_conference_canonical_bundle(p_actor_device_id,p_bundle,p_mode,p_target_conference_id,p_expected_revision);
 if not (v_check->>'valid')::boolean then raise exception 'CONFERENCE_BUNDLE_REFERENCE_VALIDATION_FAILED' using errcode='22023',detail=v_check->'errors'::text; end if;
 v_source:=(v_check->>'sourceConferenceId')::uuid;v_target:=coalesce(p_target_conference_id,platform_private.conference_bundle_uuid(p_operation_id,v_source));v_core:=p_bundle->'data'->'conference';v_sections:=p_bundle->'data'->'sections';
 v_hash:=encode(extensions.digest(jsonb_build_object('bundle',p_bundle,'mode',p_mode,'target',v_target,'expectedRevision',p_expected_revision)::text,'sha256'),'hex');
 select * into v_existing from platform_private.conference_bundle_operations where actor_user_id=v_actor and operation_id=p_operation_id for update;
 if found then
  if v_existing.request_hash<>v_hash then raise exception 'CONFERENCE_BUNDLE_IDEMPOTENCY_CONFLICT' using errcode='40001'; end if;
  if v_existing.completed_at is not null then return v_existing.result; end if;
 end if;
 insert into platform_private.conference_bundle_operations(actor_user_id,operation_id,actor_device_id,mode,source_conference_id,target_conference_id,request_hash)
 values(v_actor,p_operation_id,p_actor_device_id,p_mode,v_source,v_target,v_hash)
 on conflict(actor_user_id,operation_id) do nothing;
 if p_mode='replace' then
  update public.conferences set name=v_core->>'name',place=coalesce(v_core->>'place',''),start_date=(v_core->>'start_date')::date,end_date=(v_core->>'end_date')::date,status=v_core->>'status',completed_at=nullif(v_core->>'completed_at','')::timestamptz,revision=revision+1,updated_at=statement_timestamp(),updated_by=v_actor where id=v_target;
 else
  insert into public.conferences(id,name,owner_id,start_date,end_date,status,completed_at,revision,updated_by,place)
  values(v_target,v_core->>'name',v_actor,(v_core->>'start_date')::date,(v_core->>'end_date')::date,v_core->>'status',nullif(v_core->>'completed_at','')::timestamptz,1,v_actor,coalesce(v_core->>'place',''));
 end if;
 foreach v_table in array v_delete_order loop execute format('delete from public.%I where conference_id=$1',v_table) using v_target; end loop;
 -- Guardians are linked after every participation exists.
 perform platform_private.restore_conference_bundle_table('conference_participations',(
  select coalesce(jsonb_agg(value-'guardian_participation_id'),'[]'::jsonb) from jsonb_array_elements(v_sections->'conference_participations')
 ),v_source,v_target,p_operation_id,v_actor);
 foreach v_table in array v_insert_order loop
  if v_table<>'conference_participations' then perform platform_private.restore_conference_bundle_table(v_table,v_sections->v_table,v_source,v_target,p_operation_id,v_actor); end if;
 end loop;
 update public.conference_participations p set guardian_participation_id=platform_private.conference_bundle_uuid(p_operation_id,(source.value->>'guardian_participation_id')::uuid)
 from jsonb_array_elements(v_sections->'conference_participations') source
 where source.value->>'guardian_participation_id' is not null and p.id=platform_private.conference_bundle_uuid(p_operation_id,(source.value->>'id')::uuid) and p.conference_id=v_target;
 v_result:=jsonb_build_object('ok',true,'mode',p_mode,'sourceConferenceId',v_source,'conferenceId',v_target,'revision',(select revision from public.conferences where id=v_target),'operationId',p_operation_id);
 update platform_private.conference_bundle_operations set result=v_result,completed_at=statement_timestamp() where actor_user_id=v_actor and operation_id=p_operation_id;
 select id into v_auth from platform.user_device_authorizations where user_id=v_actor and device_id=p_actor_device_id and status='approved' and revoked_at is null order by approved_at desc nulls last limit 1;
 insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,scope_id,new_values,metadata,operation_id,source)
 values(v_actor,v_auth,'platform','conference','conference_bundle_'||p_mode,'conference',v_target,'conference',v_target,v_result,jsonb_build_object('sourceConferenceId',v_source,'schemaVersion',1),p_operation_id,'rpc');
 return v_result;
end $_$;


--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


--
-- Name: save_conference_accommodation_room_draft("uuid", "uuid", "uuid", "uuid", bigint, bigint, "jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_conference_accommodation_room_draft"("p_device" "uuid", "p_operation_id" "uuid", "p_conference" "uuid", "p_room" "uuid", "p_expected_revision" bigint, "p_expected_assignment_revision" bigint, "p_structure" "jsonb", "p_assignments" "jsonb", "p_updates" "jsonb", "p_replacements" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ctx jsonb; actor uuid; authz uuid;
  room public.conference_accommodation_rooms%rowtype;
  room_assignment public.conference_room_assignments%rowtype;
  item jsonb; mutation_result jsonb; assignment_results jsonb:='[]'; update_results jsonb:='[]'; replacement_results jsonb:='[]';
  structure_result jsonb; result jsonb; old_values jsonb; extra_capacity integer; days integer;
begin
  if p_operation_id is null then raise exception 'ACCOMMODATION_OPERATION_ID_REQUIRED' using errcode='22023'; end if;
  if p_assignments is null or jsonb_typeof(p_assignments)<>'array' then raise exception 'ACCOMMODATION_ROOM_DRAFT_ASSIGNMENTS_INVALID' using errcode='22023'; end if;
  if p_updates is null or jsonb_typeof(p_updates)<>'array' then raise exception 'ACCOMMODATION_ROOM_DRAFT_UPDATES_INVALID' using errcode='22023'; end if;
  if p_replacements is null or jsonb_typeof(p_replacements)<>'array' then raise exception 'ACCOMMODATION_ROOM_DRAFT_REPLACEMENTS_INVALID' using errcode='22023'; end if;
  if (p_structure is null or jsonb_typeof(p_structure)='null') and jsonb_array_length(p_assignments)=0 and jsonb_array_length(p_updates)=0 and jsonb_array_length(p_replacements)=0 then raise exception 'ACCOMMODATION_ROOM_DRAFT_EMPTY' using errcode='22023'; end if;

  ctx:=platform_private.require_conference_accommodation_context(p_device,p_conference,'conference.accommodation.manage',true);
  actor:=(ctx->>'actorUserId')::uuid;
  authz:=platform_private.validated_phase1c_device_authorization(actor,p_device);
  select new_values into result from platform.audit_events where actor_user_id=actor and operation_id=p_operation_id and scope_id=p_conference and action='conference.accommodation.room_draft_saved' limit 1;
  if result is not null then return result||jsonb_build_object('status','duplicate'); end if;

  -- Match move_conference_accommodation: participation locks first, then room and stay locks.
  perform 1
  from public.conference_participations p
  where p.conference_id=p_conference and p.id in (
    select (value->>'participationId')::uuid from jsonb_array_elements(p_assignments)
    union
    select (value->>'participationId')::uuid from jsonb_array_elements(p_replacements)
    union
    select o.participation_id from public.conference_accommodation_occupancies o join jsonb_array_elements(p_replacements) u on o.id=(u.value->>'occupancyId')::uuid where o.conference_id=p_conference
    union
    select o.participation_id from public.conference_accommodation_occupancies o join jsonb_array_elements(p_updates) u on o.id=(u.value->>'occupancyId')::uuid where o.conference_id=p_conference
  )
  order by p.id for update;

  select * into room_assignment from public.conference_room_assignments where conference_id=p_conference and room_id=p_room for update;
  if not found then raise exception 'ROOM_ASSIGNMENT_NOT_FOUND' using errcode='P0002'; end if;
  if room_assignment.revision<>p_expected_assignment_revision then raise exception 'ROOM_ASSIGNMENT_REVISION_CONFLICT' using errcode='40001'; end if;
  select * into room from public.conference_accommodation_rooms where id=p_room for update;
  if not found then raise exception 'ACCOMMODATION_ROOM_NOT_FOUND' using errcode='P0002'; end if;
  if room.revision<>p_expected_revision then raise exception 'ACCOMMODATION_REVISION_CONFLICT' using errcode='40001'; end if;
  perform 1 from public.conference_accommodation_occupancies o where o.conference_id=p_conference and o.id in(select (value->>'occupancyId')::uuid from jsonb_array_elements(p_updates) union select (value->>'occupancyId')::uuid from jsonb_array_elements(p_replacements)) order by o.id for update;
  old_values:=jsonb_build_object('room',to_jsonb(room),'assignment',to_jsonb(room_assignment));

  if p_structure is not null and jsonb_typeof(p_structure)<>'null' then
    perform platform_private.require_exact_jsonb_keys(p_structure,array['roomNumber','baseCapacity','extraBedCapacity','notes','isClosed','closedDay','position']);
    extra_capacity:=(p_structure->>'extraBedCapacity')::integer;
    if extra_capacity<0 then raise exception 'ACCOMMODATION_CAPACITY_INVALID' using errcode='22023'; end if;
    -- Increases must precede stay mutations; decreases are checked against the final draft below.
    if extra_capacity>room_assignment.extra_bed_capacity then
      update public.conference_room_assignments set extra_bed_capacity=extra_capacity,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=room_assignment.id;
    end if;
    if (p_structure->>'baseCapacity')::integer>=room.base_capacity and (room.room_number is distinct from p_structure->>'roomNumber' or room.base_capacity is distinct from (p_structure->>'baseCapacity')::integer or coalesce(room.notes,'') is distinct from coalesce(p_structure->>'notes','') or room.is_closed is distinct from (p_structure->>'isClosed')::boolean or room.closed_day is distinct from (p_structure->>'closedDay')::integer or room.position is distinct from (p_structure->>'position')::integer) then
      structure_result:=public.mutate_conference_accommodation_structure(p_device,'update_room',jsonb_build_object('p_conference_id',p_conference,'p_room_id',p_room,'p_expected_revision',p_expected_revision,'p_room_number',p_structure->>'roomNumber','p_base_capacity',p_structure->'baseCapacity','p_extra_bed_capacity',room.extra_bed_capacity,'p_notes',p_structure->'notes','p_is_closed',p_structure->'isClosed','p_closed_day',p_structure->'closedDay','p_position',p_structure->'position'));
    end if;
  end if;

  -- Reject ambiguous simultaneous edits and guardians with linked children; replacement never rewrites person identity.
  if exists(select 1 from jsonb_array_elements(p_replacements) r join jsonb_array_elements(p_updates) u on r.value->>'occupancyId'=u.value->>'occupancyId') then raise exception 'ACCOMMODATION_REPLACEMENT_UPDATE_CONFLICT' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(p_replacements) r join public.conference_accommodation_occupancies o on o.id=(r.value->>'occupancyId')::uuid join public.conference_participations child on child.guardian_participation_id=o.participation_id and child.conference_id=p_conference join public.conference_accommodation_occupancies child_stay on child_stay.participation_id=child.id and child_stay.conference_id=p_conference and child_stay.room_id=p_room and child_stay.arrival_day=o.arrival_day and child_stay.leave_day is not distinct from o.leave_day) then raise exception 'ACCOMMODATION_GUARDIAN_REPLACEMENT_REQUIRES_CHILD_REASSIGNMENT' using errcode='23514'; end if;
  for item in select value from jsonb_array_elements(p_replacements) order by value->>'occupancyId' loop
    perform platform_private.require_exact_jsonb_keys(item,array['occupancyId','expectedRevision','participationId','effectiveDay','bedType','extraBedPersonType']);
    if not exists(select 1 from public.conference_accommodation_occupancies where id=(item->>'occupancyId')::uuid and conference_id=p_conference and room_id=p_room) then raise exception 'ACCOMMODATION_REPLACEMENT_ROOM_MISMATCH' using errcode='22023'; end if;
    mutation_result:=public.replace_conference_accommodation(p_device,gen_random_uuid(),p_conference,(item->>'occupancyId')::uuid,(item->>'expectedRevision')::bigint,(item->>'participationId')::uuid,(item->>'effectiveDay')::integer,item->>'bedType',item->>'extraBedPersonType');
    replacement_results:=replacement_results||jsonb_build_array(mutation_result);
  end loop;
  for item in select value from jsonb_array_elements(p_updates) order by value->>'occupancyId' loop
    perform platform_private.require_exact_jsonb_keys(item,array['occupancyId','expectedRevision','arrivalDay','leaveDay','bedType','extraBedPersonType']);
    mutation_result:=public.move_conference_accommodation(p_device,p_conference,(item->>'occupancyId')::uuid,(item->>'expectedRevision')::bigint,p_room,(item->>'arrivalDay')::integer,(item->>'leaveDay')::integer,item->>'bedType',item->>'extraBedPersonType');
    update_results:=update_results||jsonb_build_array(mutation_result);
  end loop;
  for item in select value from jsonb_array_elements(p_assignments) order by value->>'participationId' loop
    perform platform_private.require_exact_jsonb_keys(item,array['participationId','arrivalDay','leaveDay','bedType','extraBedPersonType']);
    mutation_result:=public.assign_conference_accommodation(p_device,p_conference,p_room,(item->>'participationId')::uuid,(item->>'arrivalDay')::integer,(item->>'leaveDay')::integer,item->>'bedType',item->>'extraBedPersonType');
    assignment_results:=assignment_results||jsonb_build_array(mutation_result);
  end loop;

  if extra_capacity is not null and extra_capacity<room_assignment.extra_bed_capacity then
    days:=platform_private.conference_accommodation_duration(p_conference);
    if exists(select 1 from generate_series(1,days) d(day) join public.conference_accommodation_occupancies o on o.conference_id=p_conference and o.room_id=p_room and o.bed_type='extra' and o.extra_bed_source='manual' and o.arrival_day<=d.day and d.day<coalesce(o.leave_day,days+1) group by d.day having count(*)>extra_capacity) then raise exception 'ACCOMMODATION_CAPACITY_CONFLICT' using errcode='55000'; end if;
    update public.conference_room_assignments set extra_bed_capacity=extra_capacity,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=room_assignment.id;
  end if;
  if p_structure is not null and jsonb_typeof(p_structure)<>'null' and (p_structure->>'baseCapacity')::integer<room.base_capacity then
    structure_result:=public.mutate_conference_accommodation_structure(p_device,'update_room',jsonb_build_object('p_conference_id',p_conference,'p_room_id',p_room,'p_expected_revision',p_expected_revision,'p_room_number',p_structure->>'roomNumber','p_base_capacity',p_structure->'baseCapacity','p_extra_bed_capacity',room.extra_bed_capacity,'p_notes',p_structure->'notes','p_is_closed',p_structure->'isClosed','p_closed_day',p_structure->'closedDay','p_position',p_structure->'position'));
  end if;

  result:=jsonb_build_object('status','success','operationId',p_operation_id,'roomId',p_room,'structureChanged',p_structure is not null and jsonb_typeof(p_structure)<>'null','structure',structure_result,'assignments',assignment_results,'updates',update_results,'replacements',replacement_results);
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,scope_id,old_values,new_values,metadata,operation_id,source)
  values(actor,authz,'platform','conference','conference.accommodation.room_draft_saved','accommodation_room',p_room,'conference',p_conference,old_values,result,jsonb_build_object('conferenceId',p_conference,'permissionKey','conference.accommodation.manage','authoritySource',ctx->>'authoritySource','grantId',ctx->'grantId'),p_operation_id,'rpc');
  return result;
end $$;


--
-- Name: save_conference_family_accommodation_draft("uuid", "uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_conference_family_accommodation_draft"("p_device" "uuid", "p_operation_id" "uuid", "p_conference" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 ctx jsonb;actor uuid;authz uuid;stay jsonb;child_draft jsonb;room_ids uuid[];v_room_id uuid;result jsonb;mutation jsonb;room_draft jsonb;resolved_children jsonb:='[]'::jsonb;mutation_results jsonb:='[]'::jsonb;
 guardian_draft jsonb;guardian_participation public.conference_participations%rowtype;child_participation public.conference_participations%rowtype;
 guardian_stay public.conference_accommodation_occupancies%rowtype;v_guardian_person_id uuid;v_child_person_id uuid;
 draft_room public.conference_accommodation_rooms%rowtype;draft_assignment public.conference_room_assignments%rowtype;
begin
 ctx:=platform_private.require_conference_accommodation_context(p_device,p_conference,'conference.accommodation.manage',true);
 perform platform_private.require_conference_participation_context(p_device,p_conference,'conference.people.manage',true);
 actor:=(ctx->>'actorUserId')::uuid;authz:=platform_private.validated_phase1c_device_authorization(actor,p_device);
 perform platform_private.require_exact_jsonb_keys(p_payload,array['roomDraft','guardian','children','stays','roomLeaseTokens']);
 if p_operation_id is null or jsonb_typeof(p_payload->'stays')<>'array' or jsonb_typeof(p_payload->'roomLeaseTokens')<>'array' then raise exception 'FAMILY_ACCOMMODATION_DRAFT_INVALID' using errcode='22023';end if;
 select ae.new_values into result from platform.audit_events ae where ae.actor_user_id=actor and ae.operation_id=p_operation_id and ae.scope_id=p_conference and ae.action='conference.accommodation.family_draft_saved' limit 1;
 if result is not null then return result||jsonb_build_object('status','duplicate');end if;
 -- Existing participation locks always precede room and occupancy locks.
 perform 1 from public.conference_participations cp where cp.conference_id=p_conference and cp.id in(
   select nullif(p_payload->'guardian'->>'participationId','')::uuid
   union select nullif(c.value->>'participationId','')::uuid from jsonb_array_elements(p_payload->'children') c
   union select nullif(c.value->>'guardianParticipationId','')::uuid from jsonb_array_elements(p_payload->'children') c
   union select nullif(s.value->>'participationId','')::uuid from jsonb_array_elements(p_payload->'stays') s
   union select o.participation_id from public.conference_accommodation_occupancies o join jsonb_array_elements(p_payload->'stays') s on o.id=nullif(s.value->>'occupancyId','')::uuid where o.conference_id=p_conference
 ) order by cp.id for update;
 room_ids:=platform_private.require_conference_family_accommodation_leases(p_device,p_conference,p_payload);
 foreach v_room_id in array room_ids loop perform 1 from public.conference_accommodation_rooms where id=v_room_id for update; end loop;
	 guardian_draft:=p_payload->'guardian';
	 if guardian_draft is not null and jsonb_typeof(guardian_draft)<>'null' then
	   perform platform_private.require_exact_jsonb_keys(guardian_draft,array['draftId','participationId','personId','fullName','phone','church','gender','dateOfBirth']);
   if nullif(guardian_draft->>'participationId','') is not null then
     select * into guardian_participation from public.conference_participations where id=(guardian_draft->>'participationId')::uuid and conference_id=p_conference and status='active';
   else
     if nullif(guardian_draft->>'personId','') is not null then v_guardian_person_id:=(guardian_draft->>'personId')::uuid;
     else if nullif(trim(guardian_draft->>'fullName'),'') is null then raise exception 'FAMILY_GUARDIAN_NAME_REQUIRED' using errcode='22023';end if;insert into platform.people(full_name,phone,church,gender,date_of_birth,created_by,updated_by) values(trim(guardian_draft->>'fullName'),nullif(trim(guardian_draft->>'phone'),''),nullif(trim(guardian_draft->>'church'),''),nullif(guardian_draft->>'gender',''),nullif(guardian_draft->>'dateOfBirth','')::date,actor,actor) returning id into v_guardian_person_id;end if;
     select * into guardian_participation from public.conference_participations cp where cp.conference_id=p_conference and cp.person_id=v_guardian_person_id and cp.status='active';
     if not found then insert into public.conference_participations(conference_id,person_id,status,created_by,updated_by) values(p_conference,v_guardian_person_id,'active',actor,actor) returning * into guardian_participation;end if;
   end if;
   if guardian_participation.id is null or guardian_participation.guardian_participation_id is not null then raise exception 'FAMILY_GUARDIAN_PARTICIPATION_INVALID' using errcode='23514';end if;
 end if;
	 for child_draft in select value from jsonb_array_elements(p_payload->'children') loop
	   perform platform_private.require_exact_jsonb_keys(child_draft,array['draftId','guardianDraftId','guardianParticipationId','participationId','personId','fullName','targetRoomId','arrivalDay','leaveDay','bedType']);
	   if nullif(child_draft->>'guardianDraftId','') is not null and (guardian_draft is null or child_draft->>'guardianDraftId' is distinct from guardian_draft->>'draftId') then raise exception 'FAMILY_CHILD_GUARDIAN_DRAFT_MISMATCH' using errcode='23514';end if;
   if nullif(child_draft->>'guardianParticipationId','') is not null then select * into guardian_participation from public.conference_participations where id=(child_draft->>'guardianParticipationId')::uuid and conference_id=p_conference and status='active';end if;
   if guardian_participation.id is null then raise exception 'FAMILY_CHILD_GUARDIAN_REQUIRED' using errcode='23514';end if;
   if nullif(child_draft->>'participationId','') is not null then
     select * into child_participation from public.conference_participations where id=(child_draft->>'participationId')::uuid and conference_id=p_conference and status='active';
   else
     if nullif(child_draft->>'personId','') is not null then v_child_person_id:=(child_draft->>'personId')::uuid;
     else if nullif(trim(child_draft->>'fullName'),'') is null then raise exception 'FAMILY_CHILD_NAME_REQUIRED' using errcode='22023';end if;insert into platform.people(full_name,created_by,updated_by) values(trim(child_draft->>'fullName'),actor,actor) returning id into v_child_person_id;end if;
     select * into child_participation from public.conference_participations cp where cp.conference_id=p_conference and cp.person_id=v_child_person_id and cp.status='active';
     if not found then insert into public.conference_participations(conference_id,person_id,guardian_participation_id,status,created_by,updated_by) values(p_conference,v_child_person_id,guardian_participation.id,'active',actor,actor) returning * into child_participation;end if;
   end if;
   if child_participation.id is null then raise exception 'FAMILY_CHILD_PARTICIPATION_INVALID' using errcode='23514';end if;
   if child_participation.guardian_participation_id is null then update public.conference_participations set guardian_participation_id=guardian_participation.id,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=child_participation.id returning * into child_participation;
   elsif child_participation.guardian_participation_id is distinct from guardian_participation.id then raise exception 'FAMILY_CHILD_GUARDIAN_MISMATCH' using errcode='23514';end if;
   resolved_children:=resolved_children||jsonb_build_array(child_draft||jsonb_build_object('resolvedParticipationId',child_participation.id,'resolvedGuardianParticipationId',guardian_participation.id));
 end loop;
	 room_draft:=p_payload->'roomDraft';
	 if room_draft is not null and jsonb_typeof(room_draft)<>'null' then
	   perform platform_private.require_exact_jsonb_keys(room_draft,array['roomId','expectedRevision','expectedAssignmentRevision','structure']);
	   select * into draft_assignment from public.conference_room_assignments where conference_id=p_conference and room_id=(room_draft->>'roomId')::uuid for update;
	   if not found then raise exception 'ROOM_ASSIGNMENT_NOT_FOUND' using errcode='P0002';end if;
	   if draft_assignment.revision<>(room_draft->>'expectedAssignmentRevision')::bigint then raise exception 'ROOM_ASSIGNMENT_REVISION_CONFLICT' using errcode='40001';end if;
	   select * into draft_room from public.conference_accommodation_rooms where id=(room_draft->>'roomId')::uuid for update;
	   if not found then raise exception 'ACCOMMODATION_ROOM_NOT_FOUND' using errcode='P0002';end if;
	   if draft_room.revision<>(room_draft->>'expectedRevision')::bigint then raise exception 'ACCOMMODATION_REVISION_CONFLICT' using errcode='40001';end if;
	 end if;
	 if room_draft is not null and jsonb_typeof(room_draft)<>'null' and room_draft->'structure' is not null and jsonb_typeof(room_draft->'structure')<>'null' then
   perform public.save_conference_accommodation_room_draft(p_device,gen_random_uuid(),p_conference,(room_draft->>'roomId')::uuid,(room_draft->>'expectedRevision')::bigint,(room_draft->>'expectedAssignmentRevision')::bigint,room_draft->'structure','[]'::jsonb,'[]'::jsonb,'[]'::jsonb);
 end if;
	 for stay in select value from jsonb_array_elements(p_payload->'stays') loop
	   if stay->>'operation'='assign' then perform platform_private.require_exact_jsonb_keys(stay,array['operation','sourceRoomId','targetRoomId','roomId','participationId','guardianDraftId','arrivalDay','leaveDay','bedType','extraBedPersonType']);
	   elsif stay->>'operation'='move' then perform platform_private.require_exact_jsonb_keys(stay,array['operation','sourceRoomId','targetRoomId','roomId','occupancyId','expectedRevision','arrivalDay','leaveDay','bedType','extraBedPersonType']);
	   elsif stay->>'operation'='replace' then perform platform_private.require_exact_jsonb_keys(stay,array['operation','sourceRoomId','targetRoomId','roomId','occupancyId','expectedRevision','participationId','effectiveDay','bedType','extraBedPersonType']);
	   elsif stay->>'operation'='remove' then perform platform_private.require_exact_jsonb_keys(stay,array['operation','sourceRoomId','targetRoomId','roomId','occupancyId','expectedRevision']);
	   else raise exception 'FAMILY_ACCOMMODATION_OPERATION_INVALID' using errcode='22023';end if;
	   case stay->>'operation'
    when 'assign' then
      if nullif(stay->>'guardianDraftId','') is not null then
        if guardian_participation.id is null or stay->>'guardianDraftId' is distinct from guardian_draft->>'draftId' then raise exception 'FAMILY_GUARDIAN_DRAFT_ASSIGNMENT_INVALID' using errcode='23514';end if;
        mutation:=public.assign_conference_accommodation(p_device,p_conference,(stay->>'targetRoomId')::uuid,guardian_participation.id,(stay->>'arrivalDay')::integer,nullif(stay->>'leaveDay','')::integer,stay->>'bedType',nullif(stay->>'extraBedPersonType',''));
      else mutation:=public.assign_conference_accommodation(p_device,p_conference,(stay->>'targetRoomId')::uuid,(stay->>'participationId')::uuid,(stay->>'arrivalDay')::integer,nullif(stay->>'leaveDay','')::integer,stay->>'bedType',nullif(stay->>'extraBedPersonType',''));end if;
    when 'move' then mutation:=public.move_conference_accommodation(p_device,p_conference,(stay->>'occupancyId')::uuid,(stay->>'expectedRevision')::bigint,(stay->>'targetRoomId')::uuid,(stay->>'arrivalDay')::integer,nullif(stay->>'leaveDay','')::integer,stay->>'bedType',nullif(stay->>'extraBedPersonType',''));
    when 'replace' then mutation:=public.replace_conference_accommodation(p_device,gen_random_uuid(),p_conference,(stay->>'occupancyId')::uuid,(stay->>'expectedRevision')::bigint,(stay->>'participationId')::uuid,(stay->>'effectiveDay')::integer,stay->>'bedType',nullif(stay->>'extraBedPersonType',''));
    when 'remove' then mutation:=public.remove_conference_accommodation(p_device,p_conference,(stay->>'occupancyId')::uuid,(stay->>'expectedRevision')::bigint);
	    else raise exception 'FAMILY_ACCOMMODATION_OPERATION_INVALID' using errcode='22023';
	   end case;
	   mutation_results:=mutation_results||jsonb_build_array(mutation);
 end loop;
 for child_draft in select value from jsonb_array_elements(resolved_children) loop
   if child_draft->>'bedType'='shared' then
     select * into guardian_stay from public.conference_accommodation_occupancies where conference_id=p_conference and participation_id=(child_draft->>'resolvedGuardianParticipationId')::uuid and room_id=(child_draft->>'targetRoomId')::uuid and arrival_day=(child_draft->>'arrivalDay')::integer and leave_day is not distinct from nullif(child_draft->>'leaveDay','')::integer for key share;
     if not found then raise exception 'ACCOMMODATION_SHARED_CHILD_GUARDIAN_STAY_REQUIRED' using errcode='23514';end if;
   end if;
   mutation:=public.assign_conference_accommodation(p_device,p_conference,(child_draft->>'targetRoomId')::uuid,(child_draft->>'resolvedParticipationId')::uuid,(child_draft->>'arrivalDay')::integer,nullif(child_draft->>'leaveDay','')::integer,child_draft->>'bedType',case when child_draft->>'bedType'='extra' then 'child' else null end);
 end loop;
	 result:=jsonb_build_object('status','success','operationId',p_operation_id,'roomIds',to_jsonb(room_ids),'mutations',mutation_results,'children',resolved_children);
 insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,scope_id,new_values,metadata,operation_id,source) values(actor,authz,'platform','conference','conference.accommodation.family_draft_saved','conference',p_conference,'conference',p_conference,result,jsonb_build_object('roomIds',room_ids,'permissionKey','conference.accommodation.manage'),p_operation_id,'rpc');
 return result;
end $$;


--
-- Name: search_conference_people("uuid", "uuid", "text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."search_conference_people"("p_actor_device_id" "uuid", "p_conference_id" "uuid", "p_query" "text", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_items jsonb;
begin
  perform platform_private.require_conference_participation_context(p_actor_device_id,p_conference_id,'conference.people.view',false);
  if length(coalesce(p_query,''))>240 then raise exception 'PERSON_SEARCH_QUERY_TOO_LONG' using errcode='22023'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('personId',p.id,'fullName',p.full_name,'phone',p.phone,'church',p.church,'gender',p.gender,'dateOfBirth',p.date_of_birth,'revision',p.revision) order by p.full_name,p.id),'[]'::jsonb)
  into v_items from platform_private.search_people(coalesce(p_query,''),null,least(greatest(coalesce(p_limit,20),1),20)) p;
  return jsonb_build_object('items',v_items);
end $$;


--
-- Name: search_module_permission_candidates("uuid", "text", "text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."search_module_permission_candidates"("p_actor_device_id" "uuid", "p_module_key" "text", "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a uuid;q text:=lower(btrim(coalesce(p_query,'')));lim integer:=least(greatest(coalesce(p_limit,50),1),100);owner_or_manager boolean;
begin
 a:=public.require_current_approved_device(p_actor_device_id);
 if p_module_key not in('conference','warehouse','reservations') then raise exception 'ACTIVE_MODULE_REQUIRED' using errcode='42501'; end if;
 owner_or_manager:=platform_private.is_canonical_platform_owner(a) or platform_private.user_has_module_permission_for(a,p_module_key||'.module.manage',null,null);
 if not owner_or_manager and not(p_module_key='conference' and exists(select 1 from public.conferences c where c.deleted_at is null and platform_private.user_has_module_permission_for(a,'conference.members.manage','conference',c.id::text))) then raise exception 'MODULE_PERMISSION_REQUIRED' using errcode='42501'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('userId',x.user_id,'displayName',x.display_name,'email',x.email,'accountStatus',x.account_status) order by coalesce(x.display_name,x.email),x.user_id) from (select p.user_id,p.display_name,u.email,p.account_status from platform.profiles p join auth.users u on u.id=p.user_id where p.account_status='approved' and (q='' or position(q in lower(coalesce(p.display_name,'')||' '||coalesce(u.email,'')))>0) and (owner_or_manager or exists(select 1 from public.conferences c where c.deleted_at is null and platform_private.user_has_module_permission_for(a,'conference.members.manage','conference',c.id::text) and platform_private.user_has_module_permission_for(p.user_id,'conference.access.view','conference',c.id::text))) order by coalesce(p.display_name,u.email),p.user_id limit lim) x),'[]'::jsonb);
end $$;


--
-- Name: search_reservations_people("uuid", "text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."search_reservations_people"("p_actor_device_id" "uuid", "p_query" "text" DEFAULT ''::"text", "p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_context jsonb; v_items jsonb;
begin
  v_context := public.require_effective_module_permission(
    p_actor_device_id, 'reservations', 'reservations.booking.create', null, null
  );
  if length(coalesce(p_query,'')) > 240 then
    raise exception 'PERSON_SEARCH_QUERY_TOO_LONG' using errcode='22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'personId',p.id,'fullName',p.full_name,'phone',p.phone,
    'church',p.church,'gender',p.gender,'dateOfBirth',p.date_of_birth,
    'revision',p.revision,'governorate',p.governorate,
    'cityOrVillage',p.city_or_village,'serviceSector',p.service_sector,
    'serviceSectorOther',p.service_sector_other
  ) order by p.full_name,p.id),'[]'::jsonb)
  into v_items
  from platform_private.search_people(
    coalesce(p_query,''),null,least(greatest(coalesce(p_limit,20),1),20)
  ) p;
  return jsonb_build_object('items',v_items);
end $$;


--
-- Name: search_user_management_users("uuid", "text", "text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."search_user_management_users"("p_actor_device_id" "uuid", "p_query" "text" DEFAULT NULL::"text", "p_account_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid;normalized_query text:=lower(btrim(coalesce(p_query,'')));effective_limit integer:=least(greatest(coalesce(p_limit,100),1),500);
begin
 actor_id:=public.require_current_approved_device(p_actor_device_id);
 if not platform_private.user_has_module_permission_for(actor_id,'platform.users.view',null,null)
  and not platform_private.user_has_module_permission_for(actor_id,'platform.audit.view',null,null)
  and not platform_private.user_has_module_permission_for(actor_id,'platform.access.manage',null,null)
 then raise exception 'USER_MANAGEMENT_SCOPE_DENIED' using errcode='42501'; end if;
 if p_account_status is not null and p_account_status not in('pending','approved','blocked') then raise exception 'INVALID_ACCOUNT_STATUS' using errcode='22023'; end if;
 return jsonb_build_object('status','success','capabilities',public.get_user_management_actor_capabilities(p_actor_device_id)-'status',
  'users',case when platform_private.user_has_module_permission_for(actor_id,'platform.users.view',null,null) then coalesce((select jsonb_agg(jsonb_build_object('userId',ordered.id,'displayName',ordered.display_name,'email',ordered.email,'accountStatus',ordered.account_status,'deviceCount',platform_private.canonical_device_count(ordered.id)) order by ordered.sort_name,ordered.id) from (select u.id,p.display_name,u.email,p.account_status,coalesce(p.display_name,u.email) sort_name from auth.users u join platform.profiles p on p.user_id=u.id where (p_account_status is null or p.account_status=p_account_status) and (normalized_query='' or lower(coalesce(p.display_name,'')) like '%'||normalized_query||'%' or lower(coalesce(u.email,'')) like '%'||normalized_query||'%') order by coalesce(p.display_name,u.email),u.id limit effective_limit) ordered),'[]'::jsonb) else '[]'::jsonb end,
  'audit',case when platform_private.user_has_module_permission_for(actor_id,'platform.audit.view',null,null) then coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'occurredAt',x.occurred_at,'module',x.module,'action',x.action,'subjectUserId',x.subject_user_id,'scopeType',x.scope_type,'scopeId',x.scope_id,'source',x.source) order by x.occurred_at desc,x.id desc) from (select e.* from platform.audit_events e order by e.occurred_at desc,e.id desc limit 100) x),'[]'::jsonb) else null end,
  'security',jsonb_build_object('approvedDeviceRequired',true,'deviceSessionRequired',true,'selfElevationAllowed',false,'legacyTenancyEnabled',false,'canManageSecurity',platform_private.user_has_module_permission_for(actor_id,'platform.access.manage',null,null)));
end $$;


--
-- Name: set_conference_participation_guardian("uuid", "uuid", "uuid", bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."set_conference_participation_guardian"("p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_participation_id" "uuid", "p_expected_revision" bigint, "p_guardian_participation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_child public.conference_participations%rowtype; v_updated public.conference_participations%rowtype;
  v_guardian public.conference_participations%rowtype; v_context jsonb; v_actor uuid; v_device_authorization uuid;
  v_request jsonb; v_prior public.conference_participation_operations%rowtype; v_result jsonb;
  v_guardian_person platform.people%rowtype;
begin
  if p_operation_id is null or p_participation_id is null or p_expected_revision is null or p_expected_revision<1 then
    raise exception 'CONFERENCE_GUARDIAN_ARGUMENT_INVALID' using errcode='22023';
  end if;
  select * into v_child from public.conference_participations where id=p_participation_id;
  if not found then raise exception 'CONFERENCE_PARTICIPATION_NOT_FOUND' using errcode='P0002'; end if;
  v_context:=platform_private.require_conference_participation_context(
    p_actor_device_id,v_child.conference_id,'conference.people.manage',true);
  v_actor:=(v_context->>'actorUserId')::uuid;
  v_device_authorization:=platform_private.validated_phase1c_device_authorization(v_actor,p_actor_device_id);
  if v_device_authorization is null then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
  v_request:=jsonb_build_object('participationId',p_participation_id,'expectedRevision',p_expected_revision,
    'guardianParticipationId',p_guardian_participation_id);
  perform pg_advisory_xact_lock(hashtextextended(v_actor::text||':conference-participation:'||p_operation_id::text,0));
  select * into v_prior from public.conference_participation_operations
  where actor_user_id=v_actor and operation_id=p_operation_id;
  if found then
    if v_prior.operation<>'set_guardian' or v_prior.request<>v_request then
      raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023';
    end if;
    return v_prior.result;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('conference-guardian:'||v_child.conference_id::text,0));
  perform 1 from public.conference_participations
  where id in(p_participation_id,p_guardian_participation_id) order by id for update;
  select * into v_child from public.conference_participations where id=p_participation_id;
  if not found then raise exception 'CONFERENCE_PARTICIPATION_NOT_FOUND' using errcode='P0002'; end if;
  v_context:=platform_private.require_conference_participation_context(
    p_actor_device_id,v_child.conference_id,'conference.people.manage',true);
  if (v_context->>'actorUserId')::uuid is distinct from v_actor then
    raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';
  end if;
  if v_child.revision<>p_expected_revision then
    raise exception 'CONFERENCE_PARTICIPATION_REVISION_CONFLICT' using errcode='40001';
  end if;
  if p_guardian_participation_id is not null then
    if p_guardian_participation_id=p_participation_id then
      raise exception 'CONFERENCE_GUARDIAN_SELF_REFERENCE' using errcode='23514';
    end if;
    select * into v_guardian from public.conference_participations where id=p_guardian_participation_id;
    if not found or v_guardian.conference_id<>v_child.conference_id then
      raise exception 'CONFERENCE_GUARDIAN_SAME_CONFERENCE_REQUIRED' using errcode='23503';
    end if;
    if v_guardian.guardian_participation_id is not null
       or exists(select 1 from public.conference_participations
         where conference_id=v_child.conference_id and guardian_participation_id=v_child.id) then
      raise exception 'CONFERENCE_GUARDIAN_ONE_LEVEL_REQUIRED' using errcode='23514';
    end if;
  end if;
  update public.conference_participations
  set guardian_participation_id=p_guardian_participation_id,revision=revision+1,
      updated_at=statement_timestamp(),updated_by=v_actor
  where id=p_participation_id returning * into v_updated;
  if v_updated.guardian_participation_id is not null then
    select * into v_guardian from public.conference_participations
    where id=v_updated.guardian_participation_id;
    select * into v_guardian_person from platform.people where id=v_guardian.person_id;
  end if;
  v_result:=jsonb_build_object('participationId',v_updated.id,'conferenceId',v_updated.conference_id,
    'personId',v_updated.person_id,'status',v_updated.status,'revision',v_updated.revision,
    'guardianParticipationId',v_guardian.id,'guardianPersonId',v_guardian_person.id,
    'guardianFullName',v_guardian_person.full_name,'guardianParticipationStatus',v_guardian.status,
    'updatedAt',v_updated.updated_at,'updatedBy',v_updated.updated_by);
  insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at)
  values(v_actor,p_operation_id,'set_guardian',v_request,v_result,statement_timestamp());
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,
    entity_id,scope_type,old_values,new_values,metadata,operation_id,source)
  values(v_actor,v_device_authorization,'platform','conference','conference.participation.guardian_changed',
    'conference_participation',v_updated.id,'platform',
    jsonb_build_object('guardianParticipationId',v_child.guardian_participation_id,'revision',v_child.revision),
    jsonb_build_object('guardianParticipationId',v_updated.guardian_participation_id,'revision',v_updated.revision),
    jsonb_build_object('conferenceId',v_updated.conference_id,'permissionKey','conference.people.manage',
      'authoritySource',v_context->>'authoritySource','grantId',v_context->'grantId'),p_operation_id,'rpc');
  return v_result;
end $$;


--
-- Name: set_conference_participation_status("uuid", "uuid", "uuid", bigint, "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."set_conference_participation_status"("p_actor_device_id" "uuid", "p_operation_id" "uuid", "p_participation_id" "uuid", "p_expected_revision" bigint, "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current public.conference_participations%rowtype; member public.conference_participations%rowtype;
  context jsonb; actor uuid; v_authorization uuid; request jsonb; prior public.conference_participation_operations%rowtype;
  family_ids uuid[]; changed_ids jsonb:='[]'::jsonb; removed_transport_ids jsonb:='[]'::jsonb; result jsonb;
begin
  if p_operation_id is null or p_expected_revision<1 or p_status not in('active','apologized') then
    raise exception 'CONFERENCE_PARTICIPATION_ARGUMENT_INVALID' using errcode='22023'; end if;
  select * into current from public.conference_participations where id=p_participation_id;
  if not found then raise exception 'CONFERENCE_PARTICIPATION_NOT_FOUND' using errcode='P0002'; end if;
  context:=platform_private.require_conference_participation_context(
    p_actor_device_id,current.conference_id,'conference.people.manage',true);
  actor:=(context->>'actorUserId')::uuid;
  v_authorization:=platform_private.validated_phase1c_device_authorization(actor,p_actor_device_id);
  request:=jsonb_build_object('participationId',p_participation_id,'expectedRevision',p_expected_revision,'status',p_status);
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':conference-participation:'||p_operation_id::text,0));
  select * into prior from public.conference_participation_operations where actor_user_id=actor and operation_id=p_operation_id;
  if found then
    if prior.operation<>'set_status' or prior.request<>request then raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023'; end if;
    return prior.result;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('conference-guardian:'||current.conference_id::text,0));
  perform 1 from public.conference_participations where id=p_participation_id or guardian_participation_id=p_participation_id order by id for update;
  select * into current from public.conference_participations where id=p_participation_id;
  if current.revision<>p_expected_revision then raise exception 'CONFERENCE_PARTICIPATION_REVISION_CONFLICT' using errcode='40001'; end if;
  if p_status='active' and current.guardian_participation_id is not null and exists(
    select 1 from public.conference_participations guardian
    where guardian.id=current.guardian_participation_id and guardian.status<>'active') then
    raise exception 'ACTIVE_CHILD_GUARDIAN_REQUIRED' using errcode='23514';
  end if;
  if p_status='apologized' and current.guardian_participation_id is null then
    select array_agg(id order by id) into family_ids from public.conference_participations
    where conference_id=current.conference_id and (id=current.id or guardian_participation_id=current.id);
  else family_ids:=array[current.id]; end if;
  for member in select * from public.conference_participations where id=any(family_ids) order by id loop
    if p_status='apologized' and member.status='active' then
      perform platform_private.cleanup_conference_accommodation_for_participation(
        member.id,actor,v_authorization,context,'participation_apologized',p_operation_id);
      removed_transport_ids:=removed_transport_ids||platform_private.cleanup_conference_transport_for_participation(
        member.id,actor,v_authorization,'participation_apologized',p_operation_id,'conference.people.manage');
    end if;
    update public.conference_participations set status=p_status,revision=revision+1,
      updated_at=statement_timestamp(),updated_by=actor where id=member.id;
    changed_ids:=changed_ids||jsonb_build_array(member.id);
  end loop;
  result:=jsonb_build_object('participationId',current.id,'conferenceId',current.conference_id,'status',p_status,
    'revision',current.revision+1,'changedParticipationIds',changed_ids,
    'removedTransportAssignmentIds',removed_transport_ids);
  insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at)
  values(actor,p_operation_id,'set_status',request,result,statement_timestamp());
  return result;
end $$;


--
-- Name: set_conference_transport_assignment("uuid", "uuid", "uuid", "uuid", "uuid", "text", "text", integer, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."set_conference_transport_assignment"("p_device" "uuid", "p_operation_id" "uuid", "p_conference" "uuid", "p_participation" "uuid", "p_vehicle" "uuid", "p_mode" "text", "p_rider_kind" "text", "p_seat" integer, "p_expected_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c jsonb; actor uuid; authz uuid; req jsonb; prior public.conference_participation_operations%rowtype; part public.conference_participations%rowtype; guardian public.conference_participations%rowtype; vehicle public.conference_transport_vehicles%rowtype; old public.conference_transport_assignments%rowtype; row public.conference_transport_assignments%rowtype; result jsonb;
begin
  c:=platform_private.require_conference_transport_context(p_device,p_conference,'conference.transport.manage',true); actor:=(c->>'actorUserId')::uuid; authz:=platform_private.validated_phase1c_device_authorization(actor,p_device);
  req:=jsonb_build_object('conferenceId',p_conference,'participationId',p_participation,'vehicleId',p_vehicle,'mode',p_mode,'riderKind',p_rider_kind,'seatNumber',p_seat,'expectedRevision',p_expected_revision); perform pg_advisory_xact_lock(hashtextextended(actor::text||':conference-participation:'||p_operation_id::text,0)); select * into prior from public.conference_participation_operations where actor_user_id=actor and operation_id=p_operation_id; if found then if prior.operation<>'transport_assignment_set' or prior.request<>req then raise exception 'CONFERENCE_PARTICIPATION_OPERATION_MISMATCH' using errcode='22023'; end if; return prior.result; end if;
  select * into part from public.conference_participations where id=p_participation and conference_id=p_conference for key share; if not found or part.status<>'active' then raise exception 'CONFERENCE_TRANSPORT_PARTICIPATION_INELIGIBLE' using errcode='23514'; end if;
  select * into vehicle from public.conference_transport_vehicles where id=p_vehicle and conference_id=p_conference for update; if not found then raise exception 'CONFERENCE_TRANSPORT_VEHICLE_NOT_FOUND' using errcode='P0002'; end if;
  if p_mode='independent' then if p_seat is null or p_seat>vehicle.capacity then raise exception 'CONFERENCE_TRANSPORT_SEAT_INVALID' using errcode='23514'; end if;
  elsif p_mode='shared' then select * into guardian from public.conference_participations where id=part.guardian_participation_id and conference_id=p_conference; if not found or guardian.status<>'active' or not exists(select 1 from public.conference_transport_assignments where participation_id=guardian.id and vehicle_id=p_vehicle and assignment_mode='independent') then raise exception 'CONFERENCE_TRANSPORT_GUARDIAN_INELIGIBLE' using errcode='23514'; end if; p_seat:=null;
  else raise exception 'CONFERENCE_TRANSPORT_MODE_INVALID' using errcode='22023'; end if;
  select * into old from public.conference_transport_assignments where conference_id=p_conference and participation_id=p_participation for update;
  if found then if p_expected_revision is null or old.revision<>p_expected_revision then raise exception 'CONFERENCE_TRANSPORT_REVISION_CONFLICT' using errcode='40001'; end if; update public.conference_transport_assignments set vehicle_id=p_vehicle,assignment_mode=p_mode,rider_kind=p_rider_kind,seat_number=p_seat,revision=revision+1,updated_at=statement_timestamp(),updated_by=actor where id=old.id returning * into row;
  else insert into public.conference_transport_assignments(conference_id,vehicle_id,participation_id,assignment_mode,rider_kind,seat_number,created_by,updated_by) values(p_conference,p_vehicle,p_participation,p_mode,p_rider_kind,p_seat,actor,actor) returning * into row; end if;
  if row.assignment_mode='independent' then
    update public.conference_transport_assignments child_assignment set vehicle_id=row.vehicle_id,revision=child_assignment.revision+1,updated_at=statement_timestamp(),updated_by=actor
    from public.conference_participations child where child.id=child_assignment.participation_id and child.guardian_participation_id=row.participation_id and child_assignment.assignment_mode='shared' and child_assignment.conference_id=row.conference_id and child_assignment.vehicle_id<>row.vehicle_id;
  end if;
  result:=jsonb_build_object('assignmentId',row.id,'conferenceId',row.conference_id,'vehicleId',row.vehicle_id,'participationId',row.participation_id,'mode',row.assignment_mode,'riderKind',row.rider_kind,'seatNumber',row.seat_number,'revision',row.revision); insert into public.conference_participation_operations(actor_user_id,operation_id,operation,request,result,created_at) values(actor,p_operation_id,'transport_assignment_set',req,result,statement_timestamp());
  insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source) values(actor,authz,'platform','conference','conference.transport.assignment_set','conference_transport_assignment',row.id,'platform',case when old.id is null then null else to_jsonb(old) end,to_jsonb(row),jsonb_build_object('conferenceId',p_conference,'permissionKey','conference.transport.manage'),p_operation_id,'rpc'); return result;
end $$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: update_conference_canonical_person("uuid", "uuid", "uuid", bigint, "text", "text", "text", "text", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_conference_canonical_person"("p_actor_device_id" "uuid", "p_conference_id" "uuid", "p_person_id" "uuid", "p_expected_revision" bigint, "p_full_name" "text", "p_phone" "text", "p_church" "text", "p_gender" "text", "p_date_of_birth" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_context jsonb;v_actor uuid;
begin
 v_context:=platform_private.require_conference_participation_context(p_actor_device_id,p_conference_id,'conference.people.manage',true);
 v_actor:=(v_context->>'actorUserId')::uuid;
 if not exists(select 1 from public.conference_participations where conference_id=p_conference_id and person_id=p_person_id) then raise exception 'CONFERENCE_PERSON_NOT_PARTICIPATING' using errcode='42501';end if;
 return platform_private.update_canonical_person(p_actor_device_id,v_actor,p_person_id,p_expected_revision,jsonb_build_object('fullName',p_full_name,'phone',p_phone,'church',p_church,'gender',p_gender,'dateOfBirth',p_date_of_birth),null,'conference','conference.people.manage',jsonb_build_object('conferenceId',p_conference_id));
end $$;


