--

CREATE FUNCTION "public"."validate_conference_canonical_bundle"("p_actor_device_id" "uuid", "p_bundle" "jsonb", "p_mode" "text", "p_target_conference_id" "uuid", "p_expected_revision" bigint) RETURNS "jsonb"
