    SET "search_path" TO ''
    AS $$
 select platform_private.validate_conference_canonical_bundle(p_actor_device_id,p_bundle,p_mode,p_target_conference_id,p_expected_revision)
$$;


--
-- Name: mutate("uuid", "text", "jsonb"); Type: FUNCTION; Schema: reservations; Owner: -
--

CREATE FUNCTION "reservations"."mutate"("p_device_id" "uuid", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_operation='create_event' then
    return reservations_private.create_event_authorized(p_device_id,p_args);
  end if;
  return reservations.mutate_pre_authorization_architecture_reconciliation(p_device_id,p_operation,p_args);
end $$;


--
-- Name: mutate_pre_authorization_architecture_reconciliation("uuid", "text", "jsonb"); Type: FUNCTION; Schema: reservations; Owner: -
--

CREATE FUNCTION "reservations"."mutate_pre_authorization_architecture_reconciliation"("p_device_id" "uuid", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_args jsonb:=p_args;
  v_context jsonb;
  v_stored_event_id uuid;
  v_operation_id uuid:=nullif(p_args->>'p_operation_id','')::uuid;
  v_result jsonb;
  v_booking_id uuid;
  v_projection_permission text;
  v_created_booking jsonb;
  v_created_participant jsonb;
begin
  if p_operation='create_event' and not p_args ? 'p_scope_type' and p_args ? 'p_conference_id' then
    v_args:=p_args||jsonb_build_object('p_scope_type','conference');
  elsif p_operation='update_event' and p_args ? 'p_conference_id' then
    v_context:=reservations_private.resolve_event_scope(
      p_device_id,(p_args->>'p_event_id')::uuid,'reservations.event.manage'
    );
    if nullif(p_args->>'p_conference_id','')::uuid is distinct from nullif(v_context->>'conferenceId','')::uuid then
      raise exception 'RESERVATIONS_EVENT_CONFERENCE_IMMUTABLE' using errcode='55000';
    end if;
    v_args:=p_args-'p_conference_id';
  elsif p_operation in('update_event_period','delete_event_period') and p_args ? 'p_event_id' then
    select event_id into v_stored_event_id
    from reservations.event_periods
    where id=(p_args->>'p_period_id')::uuid;
    if found then
      v_context:=reservations_private.resolve_event_period_scope(
        p_device_id,(p_args->>'p_period_id')::uuid,'reservations.event.manage'
      );
      v_stored_event_id:=(v_context->>'eventId')::uuid;
    elsif p_operation='delete_event_period' and v_operation_id is not null then
      select nullif(old_values->>'event_id','')::uuid into v_stored_event_id
      from platform.audit_events
      where operation_id=v_operation_id
        and module='reservations'
        and action='event_period.deleted'
        and entity_id=(p_args->>'p_period_id')::uuid;
    end if;
    if v_stored_event_id is null then
      perform reservations_private.resolve_event_period_scope(
        p_device_id,(p_args->>'p_period_id')::uuid,'reservations.event.manage'
      );
    end if;
    if nullif(p_args->>'p_event_id','')::uuid is distinct from v_stored_event_id then
      raise exception 'RESERVATIONS_EVENT_PERIOD_EVENT_IMMUTABLE' using errcode='55000';
    end if;
    v_args:=p_args-'p_event_id';
  elsif p_operation='update_booking_type' and p_args ? 'p_event_id' then
    v_context:=reservations_private.resolve_booking_type_scope(
      p_device_id,(p_args->>'p_booking_type_id')::uuid,'reservations.event.manage'
    );
    v_stored_event_id:=(v_context->>'eventId')::uuid;
    if nullif(p_args->>'p_event_id','')::uuid is distinct from v_stored_event_id then
      raise exception 'RESERVATIONS_BOOKING_TYPE_EVENT_IMMUTABLE' using errcode='55000';
    end if;
    v_args:=p_args-'p_event_id';
  end if;

  v_result:=reservations_private.mutate_scoped(p_device_id,p_operation,v_args);

  if p_operation in('create_booking','update_participant_booking') then
    v_booking_id:=nullif(v_result->>'bookingId','')::uuid;
    if v_booking_id is not null and exists(
      select 1
      from reservations.bookings booking
      join reservations.events event on event.id=booking.event_id
      where booking.id=v_booking_id and event.conference_id is not null
    ) then
      v_projection_permission:=case
        when p_operation='create_booking' then 'reservations.booking.create'
        else 'reservations.booking.update'
      end;
      v_context:=reservations_private.resolve_booking_scope(
        p_device_id,v_booking_id,v_projection_permission
      );
      v_result:=v_result||jsonb_build_object(
        'conferencePerson',
        reservations_private.link_booking_to_canonical_participation(
          v_booking_id,v_operation_id,v_context
        )
      );
    end if;
  end if;

  if p_operation='create_booking' and v_booking_id is not null then
    select to_jsonb(booking),to_jsonb(participant)
      into v_created_booking,v_created_participant
    from reservations.bookings booking
    join reservations.participants participant on participant.id=booking.participant_id
    where booking.id=v_booking_id;
    if v_created_booking is null or v_created_participant is null then
      raise exception 'RESERVATIONS_BOOKING_NOT_FOUND' using errcode='P0002';
    end if;
    v_result:=v_result||jsonb_build_object(
      'booking',v_created_booking,
      'participant',v_created_participant
    );
  end if;

  return v_result;
end $$;


--
-- Name: read("uuid", "text", "jsonb"); Type: FUNCTION; Schema: reservations; Owner: -
--

CREATE FUNCTION "reservations"."read"("p_device_id" "uuid", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_context jsonb; v_conference_id uuid; v_event_id uuid;
  v_limit integer:=coalesce((p_args->>'p_limit')::integer,100);
begin
  if p_args is null or jsonb_typeof(p_args)<>'object' then
    raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023';
  end if;
  if p_operation='search_people' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_query'],array['p_limit']);
    return public.search_reservations_people(p_device_id,p_args->>'p_query',(p_args->>'p_limit')::integer);
  end if;
  if p_operation='list_conference_options' then
    perform platform_private.require_exact_jsonb_keys(p_args,array[]::text[]);
    perform reservations_private.booking_target_context(p_device_id);
    return coalesce(public.list_accessible_conferences(p_device_id)->'conferences','[]'::jsonb);
  end if;
  if p_operation='list_events' then
    perform reservations_private.booking_target_context(p_device_id);
    if v_limit<1 or v_limit>5000 then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
    if p_args ? 'p_conference_id' and not p_args ? 'p_scope_type' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_status','p_limit']);
      v_conference_id:=nullif(p_args->>'p_conference_id','')::uuid;
      if v_conference_id is null then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
      perform reservations_private.conference_context(p_device_id,v_conference_id,'reservations.booking.create');
      return (select coalesce(jsonb_agg(to_jsonb(x) order by x.start_date desc,x.id),'[]'::jsonb)
        from (select e.* from reservations.events e where e.scope_type='conference'
          and e.conference_id=v_conference_id and e.scope_partition_id=v_conference_id
          and ((p_args->>'p_status') is null or e.status=p_args->>'p_status')
          order by e.start_date desc,e.id limit v_limit) x);
    elsif p_args ? 'p_scope_type' and not p_args ? 'p_conference_id' then
      perform platform_private.require_exact_jsonb_keys(p_args,array['p_scope_type','p_status','p_limit']);
      if p_args->>'p_scope_type'<>'standalone' then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
      return (select coalesce(jsonb_agg(to_jsonb(x) order by x.start_date desc,x.id),'[]'::jsonb)
        from (select e.* from reservations.events e where e.scope_type='standalone'
          and e.conference_id is null and ((p_args->>'p_status') is null or e.status=p_args->>'p_status')
          order by e.start_date desc,e.id limit v_limit) x);
    end if;
    raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023';
  end if;
  if p_operation='list_booking_types' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_event_id']);
    v_event_id:=nullif(p_args->>'p_event_id','')::uuid;
    if v_event_id is null then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
    v_context:=reservations_private.resolve_event_scope(p_device_id,v_event_id,'reservations.booking.create');
    return (select coalesce(jsonb_agg(to_jsonb(t) order by t.display_order),'[]'::jsonb)
      from reservations.booking_types t where t.event_id=v_event_id
        and t.scope_partition_id=(v_context->>'scopePartitionId')::uuid);
  end if;
  if p_operation = 'get_booking_creation_context' then
    return reservations_private.booking_creation_context(p_device_id,p_args);
  end if;
  if p_operation = 'get_effective_capabilities' then
   return reservations_private.effective_capabilities(p_device_id,p_args);
 end if;
 if p_operation='get_dashboard_summary' and p_args ? 'p_scope_type' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_scope_type']);
  if p_args->>'p_scope_type'<>'platform' then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
  return reservations_private.platform_dashboard_summary(p_device_id);
 end if;
 return reservations_private.read_scoped(p_device_id,p_operation,p_args);
end $$;


--
-- Name: read_pre_effective_capability_contract("uuid", "text", "jsonb"); Type: FUNCTION; Schema: reservations; Owner: -
--

CREATE FUNCTION "reservations"."read_pre_effective_capability_contract"("p_device_id" "uuid", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_operation='get_booking_creation_context' then
    return reservations_private.booking_creation_context(p_device_id,p_args);
  end if;
  -- Administrative reads retain their own read permission contract.
  if p_operation in('list_events','list_booking_types') then
    return reservations_private.read_scoped(p_device_id,p_operation,p_args);
  end if;
  return reservations.read_pre_authorization_architecture_reconciliation(p_device_id,p_operation,p_args);
end $$;


--
-- Name: allocate_booking_number("uuid", integer); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."allocate_booking_number"("p_scope_partition_id" "uuid", "p_year" integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_number bigint;
begin
 if p_scope_partition_id is null then raise exception 'RESERVATIONS_SCOPE_PARTITION_REQUIRED' using errcode='22023';end if;
 insert into reservations.booking_number_counters(scope_partition_id,booking_year,next_value)
 values(p_scope_partition_id,p_year,2)
 on conflict(scope_partition_id,booking_year) do update
 set next_value=reservations.booking_number_counters.next_value+1,updated_at=statement_timestamp()
 returning next_value-1 into v_number;
 return 'RES-'||lpad(p_year::text,4,'0')||'-'||lpad(v_number::text,4,'0');
end $$;


--
-- Name: audit("jsonb", "text", "text", "uuid", "uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."audit"("p_context" "jsonb", "p_action" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_operation_id" "uuid", "p_old" "jsonb", "p_new" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid:=(p_context->>'actorUserId')::uuid;
  v_device uuid:=(p_context->>'actorDeviceId')::uuid;
  v_authorization uuid; v_scope_type text:=p_context->>'scopeType';
  v_partition uuid:=nullif(p_context->>'scopePartitionId','')::uuid; v_metadata jsonb;
begin
  v_authorization:=platform_private.validated_phase1c_device_authorization(v_actor,v_device);
  if v_authorization is null then raise exception 'RESERVATIONS_DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
  if v_scope_type is null and v_partition is null then
    insert into platform.audit_events(actor_user_id,actor_device_authorization_id,domain,module,action,
      entity_type,entity_id,scope_type,old_values,new_values,metadata,operation_id,source)
    values(v_actor,v_authorization,'platform','reservations',p_action,p_entity_type,p_entity_id,
      'platform',p_old,p_new,jsonb_build_object('deviceId',v_device),p_operation_id,'rpc');
    return;
  end if;
  if v_scope_type not in('conference','standalone') or v_partition is null then
    raise exception 'RESERVATIONS_AUDIT_SCOPE_CONTEXT_INVALID' using errcode='22023';
  end if;
  v_metadata:=jsonb_strip_nulls(jsonb_build_object(
    'reservationsScopeType',v_scope_type,
    'conferenceId',case when v_scope_type='conference' then p_context->>'conferenceId' end,
    'deviceId',v_device));
  perform platform_private.write_scoped_audit_event(v_actor,null,'platform','reservations',p_action,
    p_entity_type,p_entity_id,'reservations',v_partition,p_old,p_new,v_metadata,null,p_operation_id,'rpc');
end $$;


--
-- Name: begin_operation("uuid", "jsonb", "text", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."begin_operation"("p_operation_id" "uuid", "p_context" "jsonb", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_prior reservations.operations%rowtype;
  v_partition uuid:=(p_context->>'scopePartitionId')::uuid;
  v_intent text; v_linked_intent text; v_linked_partition boolean:=false;
begin
  if p_operation_id is null then raise exception 'RESERVATIONS_OPERATION_ID_REQUIRED' using errcode='22023'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('reservations-operation:'||p_operation_id::text,0));
  select * into v_prior from reservations.operations where operation_id=p_operation_id;
  if not found then return null; end if;
  v_intent:=reservations_private.intent(p_operation,v_partition,p_args-'p_operation_id');
  select exists(select 1 from reservations.scope_partition_links link
    where link.old_scope_partition_id=v_prior.scope_partition_id
      and link.new_scope_partition_id=v_partition) into v_linked_partition;
  if v_linked_partition then
    v_linked_intent:=reservations_private.intent(p_operation,v_prior.scope_partition_id,p_args-'p_operation_id');
  end if;
  if v_prior.actor_user_id<>(p_context->>'actorUserId')::uuid
     or v_prior.device_id<>(p_context->>'actorDeviceId')::uuid
     or v_prior.operation_name<>p_operation
     or not ((v_prior.scope_partition_id=v_partition and v_prior.intent_hash=v_intent)
       or (v_linked_partition and v_prior.intent_hash=v_linked_intent)) then
    raise exception 'RESERVATIONS_OPERATION_IDEMPOTENCY_CONFLICT' using errcode='40001';
  end if;
  return v_prior.result;
end $$;


--
-- Name: begin_standalone_create("uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."begin_standalone_create"("p_operation_id" "uuid", "p_context" "jsonb", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_prior reservations.operations%rowtype; v_intent text:=reservations_private.standalone_create_intent(p_args);
begin
 if p_operation_id is null then raise exception 'RESERVATIONS_OPERATION_ID_REQUIRED' using errcode='22023'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('reservations-operation:'||p_operation_id::text,0));
 select * into v_prior from reservations.operations where operation_id=p_operation_id;
 if not found then return null; end if;
 if v_prior.actor_user_id<>(p_context->>'actorUserId')::uuid or v_prior.device_id<>(p_context->>'actorDeviceId')::uuid or v_prior.operation_name<>'create_event' or v_prior.intent_hash<>v_intent then raise exception 'RESERVATIONS_OPERATION_IDEMPOTENCY_CONFLICT' using errcode='40001'; end if;
 return v_prior.result;
end $$;


--
-- Name: booking_creation_context("uuid", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."booking_creation_context"("p_device_id" "uuid", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid;v_conference_id uuid;
begin
 if p_args is null or jsonb_typeof(p_args)<>'object' then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
 v_actor:=public.require_current_approved_device(p_device_id);
 if p_args ? 'p_conference_id' and not p_args ? 'p_scope_type' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);v_conference_id:=nullif(p_args->>'p_conference_id','')::uuid;
  if v_conference_id is null or not exists(select 1 from public.conferences c where c.id=v_conference_id and c.deleted_at is null) then raise exception 'RESERVATIONS_CONFERENCE_ACCESS_REQUIRED' using errcode='42501'; end if;
 elsif p_args ? 'p_scope_type' and not p_args ? 'p_conference_id' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_scope_type']);if p_args->>'p_scope_type'<>'standalone' then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
 else raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
 return (select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'conference_id',e.conference_id,'name',e.name,'start_date',e.start_date,'end_date',e.end_date,'location',e.location,'capacity',e.capacity,'status',e.status,'notes','','revision',e.revision,'bookingTypes',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'event_id',t.event_id,'name',t.name,'code',t.code,'price',t.price,'active',t.active,'display_order',t.display_order,'eligible_attendance_segments',t.eligible_attendance_segments,'revision',t.revision) order by t.display_order,t.id) from reservations.booking_types t where t.event_id=e.id and t.scope_partition_id=e.scope_partition_id and t.active),'[]'::jsonb)) order by e.start_date desc,e.id),'[]'::jsonb)
 from reservations.events e where e.status not in('closed','full') and ((v_conference_id is null and e.scope_type='standalone' and e.conference_id is null) or (v_conference_id is not null and e.scope_type='conference' and e.conference_id=v_conference_id)) and reservations_private.has_event_permission(v_actor,'reservations.booking.create',e.id));
end $$;


--
-- Name: booking_target_context("uuid"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."booking_target_context"("p_device_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_context jsonb;
begin
  begin
    v_context:=public.require_effective_module_permission(
      p_device_id,'reservations','reservations.event.view',null,null
    );
  exception when sqlstate '42501' then
    v_context:=public.require_effective_module_permission(
      p_device_id,'reservations','reservations.booking.create',null,null
    );
  end;
  return v_context;
end $$;


--
-- Name: cancel_booking_scoped("uuid", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."cancel_booking_scoped"("p_device_id" "uuid", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  context jsonb; replay jsonb; result jsonb; booking reservations.bookings%rowtype;
  actor uuid; operation_id uuid:=(p_args->>'p_operation_id')::uuid;
  collected numeric(18,2); non_refundable numeric(18,2); refunded numeric(18,2);
  credited numeric(18,2); pending numeric(18,2); settlement_id uuid;
  person_id uuid; credit_balance numeric(18,2); conference_id uuid;
  participation_id uuid; participation_revision bigint; conference_result jsonb;
begin
  perform platform_private.require_exact_jsonb_keys(p_args,array[
    'p_operation_id','p_booking_id','p_expected_revision','p_reason',
    'p_non_refundable_amount','p_refunded_amount','p_credit_amount','p_pending_refund_amount'
  ]);
  context:=reservations_private.resolve_booking_scope(
    p_device_id,(p_args->>'p_booking_id')::uuid,'reservations.booking.cancel'
  );
  if coalesce((p_args->>'p_non_refundable_amount')::numeric,0)>0
     or coalesce((p_args->>'p_refunded_amount')::numeric,0)>0
     or coalesce((p_args->>'p_credit_amount')::numeric,0)>0
     or coalesce((p_args->>'p_pending_refund_amount')::numeric,0)>0 then
    perform public.require_effective_module_permission(
      p_device_id,'reservations','reservations.payment.settle','event',context->>'eventId'
    );
  end if;
  replay:=reservations_private.begin_operation(operation_id,context,'cancel_booking',p_args);
  if replay is not null then return replay; end if;
  select * into booking from reservations.bookings
   where id=(context->>'bookingId')::uuid
     and event_id=(context->>'eventId')::uuid
     and scope_partition_id=(context->>'scopePartitionId')::uuid for update;
  if not found then raise exception 'RESERVATIONS_BOOKING_NOT_FOUND' using errcode='P0002'; end if;
  if booking.revision<>(p_args->>'p_expected_revision')::bigint then
    raise exception 'RESERVATIONS_REVISION_CONFLICT' using errcode='40001';
  end if;
  if booking.lifecycle_status<>'active' then
    raise exception 'RESERVATIONS_BOOKING_ALREADY_APOLOGIZED' using errcode='55000';
  end if;
  if nullif(btrim(p_args->>'p_reason'),'') is null then
    raise exception 'RESERVATIONS_APOLOGY_REASON_REQUIRED' using errcode='22023';
  end if;
  perform 1 from reservations.payments
   where booking_id=booking.id and scope_partition_id=booking.scope_partition_id and status='active'
   order by id for update;
  select coalesce(sum(amount),0) into collected from reservations.payments
   where booking_id=booking.id and scope_partition_id=booking.scope_partition_id and status='active';
  non_refundable:=coalesce((p_args->>'p_non_refundable_amount')::numeric,0);
  refunded:=coalesce((p_args->>'p_refunded_amount')::numeric,0);
  credited:=coalesce((p_args->>'p_credit_amount')::numeric,0);
  pending:=coalesce((p_args->>'p_pending_refund_amount')::numeric,0);
  if credited>0 then raise exception 'RESERVATIONS_EVENT_CREDIT_ISOLATION_REQUIRED' using errcode='55000'; end if;
  if refunded>0 then raise exception 'RESERVATIONS_REFUND_DISBURSEMENT_REQUIRED' using errcode='55000'; end if;
  if least(non_refundable,refunded,credited,pending)<0
     or non_refundable+refunded+credited+pending<>collected then
    raise exception 'RESERVATIONS_SETTLEMENT_ALLOCATION_INVALID' using errcode='23514';
  end if;
  select participant.person_id into person_id from reservations.participants participant
   where participant.id=booking.participant_id and participant.scope_partition_id=booking.scope_partition_id;
  actor:=(context->>'actorUserId')::uuid;

  select event.conference_id into conference_id from reservations.events event
   where event.id=booking.event_id and event.scope_partition_id=booking.scope_partition_id
     and event.scope_type='conference';
  if conference_id is not null then
    select participation.id,participation.revision into participation_id,participation_revision
      from public.conference_participations participation
     where participation.conference_id=conference_id and participation.person_id=person_id
       and participation.status='active' for update;
    if participation_id is not null then
      if exists(
        select 1 from public.conference_participations child
        join reservations.participants child_participant on child_participant.person_id=child.person_id
        join reservations.bookings child_booking on child_booking.participant_id=child_participant.id
          and child_booking.scope_partition_id=child_participant.scope_partition_id
        
        where child.guardian_participation_id=participation_id
          and child.status='active' and child_booking.lifecycle_status='active'
          and child_booking.id<>booking.id
      ) then raise exception 'RESERVATIONS_CHILD_BOOKING_SETTLEMENT_REQUIRED' using errcode='55000'; end if;
      conference_result:=public.set_conference_participation_status(
        p_device_id,operation_id,participation_id,participation_revision,'apologized'
      );
      update reservations.bookings child_booking set
        lifecycle_status='apologized',apologized_at=statement_timestamp(),
        apology_reason=btrim(p_args->>'p_reason'),apologized_by=actor,
        apologized_by_device_id=p_device_id,revision=revision+1,
        updated_at=statement_timestamp(),updated_by=actor
      where child_booking.id<>booking.id and child_booking.lifecycle_status='active'
        and exists(
          select 1 from reservations.participants child_participant
          join public.conference_participations changed
            on changed.person_id=child_participant.person_id and changed.conference_id=conference_id
          where child_participant.id=child_booking.participant_id
            and child_participant.scope_partition_id=child_booking.scope_partition_id
            and changed.id in (select value::uuid from jsonb_array_elements_text(conference_result->'changedParticipationIds'))
        );
    end if;
  end if;

  update reservations.bookings set lifecycle_status='apologized',
    apologized_at=statement_timestamp(),apology_reason=btrim(p_args->>'p_reason'),
    apologized_by=actor,apologized_by_device_id=p_device_id,
    revision=revision+1,updated_at=statement_timestamp(),updated_by=actor
  where id=booking.id returning revision into booking.revision;
  insert into reservations.booking_cancellation_settlements(
    scope_partition_id,booking_id,person_id,collected_amount,non_refundable_amount,
    refunded_amount,credit_amount,pending_refund_amount,reason,created_by,
    created_by_device_id,operation_id
  ) values (
    booking.scope_partition_id,booking.id,person_id,collected,non_refundable,
    refunded,credited,pending,btrim(p_args->>'p_reason'),actor,p_device_id,operation_id
  ) returning id into settlement_id;
  result:=jsonb_build_object(
    'bookingId',booking.id,'revision',booking.revision,'status','apologized',
    'settlementId',settlement_id,'collectedAmount',collected,
    'nonRefundableAmount',non_refundable,'refundedAmount',refunded,
    'creditAmount',credited,'pendingRefundAmount',pending
  );
  perform reservations_private.audit(context,'booking.apologized','booking',booking.id,
    operation_id,to_jsonb(booking),result);
  return reservations_private.complete_operation(operation_id,context,'cancel_booking',p_args,result);
end $$;


--
-- Name: complete_operation("uuid", "jsonb", "text", "jsonb", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."complete_operation"("p_operation_id" "uuid", "p_context" "jsonb", "p_operation" "text", "p_args" "jsonb", "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform set_config('reservations.scope_partition_id',p_context->>'scopePartitionId',true);
  insert into reservations.operations(
    operation_id,scope_partition_id,actor_user_id,device_id,operation_name,intent_hash,result
  ) values(
    p_operation_id,(p_context->>'scopePartitionId')::uuid,
    (p_context->>'actorUserId')::uuid,(p_context->>'actorDeviceId')::uuid,p_operation,
    reservations_private.intent(p_operation,(p_context->>'scopePartitionId')::uuid,p_args-'p_operation_id'),p_result
  );
  return p_result;
end $$;


--
-- Name: complete_standalone_create("uuid", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."complete_standalone_create"("p_operation_id" "uuid", "p_context" "jsonb", "p_args" "jsonb", "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 perform set_config('reservations.scope_partition_id',(p_context->>'scopePartitionId'),true);
 insert into reservations.operations(operation_id,scope_partition_id,actor_user_id,device_id,operation_name,intent_hash,result)
 values(p_operation_id,(p_context->>'scopePartitionId')::uuid,(p_context->>'actorUserId')::uuid,(p_context->>'actorDeviceId')::uuid,'create_event',reservations_private.standalone_create_intent(p_args),p_result);
 return p_result;
end $$;


--
-- Name: conference_context("uuid", "uuid", "text"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."conference_context"("p_device_id" "uuid", "p_conference_id" "uuid", "p_permission" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_context jsonb;
begin
 v_context:=public.require_effective_module_permission(p_device_id,'reservations',p_permission,null,null);
 if not exists(select 1 from public.conferences c where c.id=p_conference_id and c.deleted_at is null) then
  raise exception 'RESERVATIONS_CONFERENCE_ACCESS_REQUIRED' using errcode='42501';
 end if;
 return v_context||jsonb_build_object('conferenceId',p_conference_id,'scopeType','conference','scopePartitionId',p_conference_id);
end $$;


--
-- Name: create_event_authorized("uuid", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."create_event_authorized"("p_device_id" "uuid", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_context jsonb; v_replay jsonb; v_result jsonb; v_actor uuid; v_partition uuid;
        v_event_id uuid; v_revision bigint; v_operation_id uuid:=(p_args->>'p_operation_id')::uuid;
begin
  if p_args->>'p_scope_type'='standalone' then
    perform reservations_private.standalone_create_business_args(p_args-'p_scope_type');
    v_context:=public.require_effective_module_permission(
      p_device_id,'reservations','reservations.event.create',null,null
    )||jsonb_build_object('scopeType','standalone');
    v_replay:=reservations_private.begin_standalone_create(v_operation_id,v_context,p_args-'p_scope_type');
    if v_replay is not null then return v_replay; end if;
    v_partition:=extensions.gen_random_uuid();
    v_context:=v_context||jsonb_build_object('scopePartitionId',v_partition);
  elsif p_args->>'p_scope_type'='conference' and nullif(p_args->>'p_conference_id','')::uuid is not null then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_scope_type','p_conference_id','p_name','p_start_date','p_end_date','p_location','p_capacity','p_status','p_notes']);
    v_context:=reservations_private.conference_context(
      p_device_id,(p_args->>'p_conference_id')::uuid,'reservations.event.create'
    );
    v_replay:=reservations_private.begin_operation(v_operation_id,v_context,'create_event',p_args);
    if v_replay is not null then return v_replay; end if;
    v_partition:=(v_context->>'scopePartitionId')::uuid;
  else raise exception 'RESERVATIONS_CREATE_EVENT_SCOPE_INVALID' using errcode='22023'; end if;
  v_actor:=(v_context->>'actorUserId')::uuid;
  insert into reservations.events(
    scope_type,scope_partition_id,conference_id,name,start_date,end_date,
    location,capacity,status,notes,created_by,updated_by
  ) values(
    p_args->>'p_scope_type',v_partition,nullif(p_args->>'p_conference_id','')::uuid,btrim(p_args->>'p_name'),
    (p_args->>'p_start_date')::date,(p_args->>'p_end_date')::date,
    coalesce(p_args->>'p_location',''),(p_args->>'p_capacity')::integer,
    p_args->>'p_status',coalesce(p_args->>'p_notes',''),v_actor,v_actor
  ) returning id,revision into v_event_id,v_revision;
  perform platform_private.grant_deterministic_resource_permission(
    v_context,v_operation_id,v_event_id
  );
  v_result:=jsonb_build_object('eventId',v_event_id,'revision',v_revision,
    'scopeType',p_args->>'p_scope_type','scopePartitionId',v_partition,
    'event',(select to_jsonb(e) from reservations.events e where e.id=v_event_id));
  perform reservations_private.audit(v_context,'event.created','event',v_event_id,v_operation_id,null,v_result);
  if p_args->>'p_scope_type'='standalone' then
    return reservations_private.complete_standalone_create(v_operation_id,v_context,p_args-'p_scope_type',v_result);
  end if;
  return reservations_private.complete_operation(v_operation_id,v_context,'create_event',p_args,v_result);
end $$;


--
-- Name: create_standalone_event("uuid", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."create_standalone_event"("p_device_id" "uuid", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select reservations_private.create_standalone_event_scoped(p_device_id,p_args)
$$;


--
-- Name: create_standalone_event_scoped("uuid", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."create_standalone_event_scoped"("p_device_id" "uuid", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_context jsonb; v_partition uuid; v_actor uuid; v_replay jsonb; v_id uuid; v_revision bigint; v_result jsonb; v_operation_id uuid:=(p_args->>'p_operation_id')::uuid;
begin
 perform reservations_private.standalone_create_business_args(p_args);
 v_context:=public.require_effective_module_permission(p_device_id,'reservations','reservations.event.manage',null,null)||jsonb_build_object('scopeType','standalone');
 v_actor:=(v_context->>'actorUserId')::uuid;
 v_replay:=reservations_private.begin_standalone_create(v_operation_id,v_context,p_args);
 if v_replay is not null then return v_replay; end if;
 v_partition:=extensions.gen_random_uuid();
 v_context:=v_context||jsonb_build_object('scopePartitionId',v_partition);
 insert into reservations.events(scope_type,scope_partition_id,conference_id,name,start_date,end_date,location,capacity,status,notes,created_by,updated_by)
 values('standalone',v_partition,null,btrim(p_args->>'p_name'),(p_args->>'p_start_date')::date,(p_args->>'p_end_date')::date,coalesce(p_args->>'p_location',''),(p_args->>'p_capacity')::integer,p_args->>'p_status',coalesce(p_args->>'p_notes',''),v_actor,v_actor)
 returning id,revision into v_id,v_revision;
 v_result:=jsonb_build_object('eventId',v_id,'revision',v_revision,'scopeType','standalone','scopePartitionId',v_partition);
 perform reservations_private.audit(v_context,'event.created','event',v_id,v_operation_id,null,v_result);
 return reservations_private.complete_standalone_create(v_operation_id,v_context,p_args,v_result);
end $$;


--
-- Name: derive_child_scope_partition(); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."derive_child_scope_partition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_partition uuid; v_setting text;
begin
  if tg_table_name in ('event_periods','booking_types','bookings') then
    select scope_partition_id into v_partition from reservations.events where id=new.event_id;
  elsif tg_table_name in ('payments','attendance_records','operational_reviews') then
    select scope_partition_id into v_partition from reservations.bookings where id=new.booking_id;
  elsif tg_table_name='participants' then
    v_setting:=current_setting('reservations.scope_partition_id',true);
    v_partition:=nullif(v_setting,'')::uuid;
  elsif tg_table_name='operations' then
    v_setting:=current_setting('reservations.scope_partition_id',true);
    v_partition:=nullif(v_setting,'')::uuid;
  end if;
  if v_partition is null then raise exception 'RESERVATIONS_SCOPE_PARTITION_CONTEXT_REQUIRED' using errcode='22023'; end if;
  if new.scope_partition_id is not null and new.scope_partition_id<>v_partition then raise exception 'RESERVATIONS_SCOPE_PARTITION_OVERRIDE_DENIED' using errcode='42501'; end if;
  new.scope_partition_id:=v_partition;
  return new;
end $$;


--
-- Name: derive_event_scope_partition(); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."derive_event_scope_partition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if new.scope_type is null then
  if new.conference_id is null then
   new.scope_type:='standalone';
   new.scope_partition_id:=coalesce(new.scope_partition_id,extensions.gen_random_uuid());
  else new.scope_type:='conference';new.scope_partition_id:=new.conference_id;end if;
 elsif new.scope_type='standalone' then
  new.conference_id:=null;
  new.scope_partition_id:=coalesce(new.scope_partition_id,extensions.gen_random_uuid());
 elsif new.scope_type='conference' then
  if new.conference_id is null then raise exception 'RESERVATIONS_CONFERENCE_REQUIRED' using errcode='22023';end if;
  new.scope_partition_id:=new.conference_id;
 else raise exception 'RESERVATIONS_SCOPE_TYPE_INVALID' using errcode='22023';end if;
 return new;
end $$;


--
-- Name: disburse_refund_scoped("uuid", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."disburse_refund_scoped"("p_device_id" "uuid", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 ctx jsonb; replay jsonb; result jsonb; booking reservations.bookings%rowtype;
 settlement reservations.booking_cancellation_settlements%rowtype;
 op_id uuid:=(p_args->>'p_operation_id')::uuid;
 amount numeric(18,2); actor uuid; refund_id uuid;
begin
 perform platform_private.require_exact_jsonb_keys(p_args,array[
 'p_operation_id','p_booking_id','p_amount','p_disbursed_on','p_payment_method',
 'p_payment_method_other','p_reference','p_reason']);
 ctx:=reservations_private.resolve_booking_scope(p_device_id,(p_args->>'p_booking_id')::uuid,'reservations.payment.settle');
 replay:=reservations_private.begin_operation(op_id,ctx,'disburse_refund',p_args);
 if replay is not null then return replay; end if;
 select * into booking from reservations.bookings where id=(ctx->>'bookingId')::uuid
 and event_id=(ctx->>'eventId')::uuid and scope_partition_id=(ctx->>'scopePartitionId')::uuid for update;
 if not found or booking.lifecycle_status not in ('apologized','deleted') then
 raise exception 'RESERVATIONS_REFUND_BOOKING_NOT_APOLOGIZED' using errcode='55000'; end if;
 select * into settlement from reservations.booking_cancellation_settlements
 where booking_id=booking.id and scope_partition_id=booking.scope_partition_id for update;
 if not found then raise exception 'RESERVATIONS_REFUND_SETTLEMENT_MISSING' using errcode='P0002'; end if;
 amount:=(p_args->>'p_amount')::numeric(18,2);
 if amount is null or amount<=0 or amount>(settlement.pending_refund_amount+settlement.non_refundable_amount) then
 raise exception 'RESERVATIONS_REFUND_AMOUNT_EXCEEDS_DUE' using errcode='23514'; end if;
 if (p_args->>'p_disbursed_on')::date is null
 or (p_args->>'p_disbursed_on')::date>current_date then
 raise exception 'RESERVATIONS_REFUND_DATE_INVALID' using errcode='22023'; end if;
 actor:=(ctx->>'actorUserId')::uuid;
 insert into reservations.refund_disbursements(
 scope_partition_id,event_id,booking_id,settlement_id,amount,disbursed_on,
 payment_method,payment_method_other,reference,reason,operation_id,created_by,created_by_device_id)
 values(booking.scope_partition_id,booking.event_id,booking.id,settlement.id,amount,
 (p_args->>'p_disbursed_on')::date,p_args->>'p_payment_method',
 nullif(btrim(p_args->>'p_payment_method_other'),''),nullif(btrim(p_args->>'p_reference'),''),
 btrim(p_args->>'p_reason'),op_id,actor,p_device_id) returning id into refund_id;
 update reservations.booking_cancellation_settlements set
 refunded_amount=refunded_amount+amount,
 pending_refund_amount=greatest(pending_refund_amount-amount,0),
 non_refundable_amount=non_refundable_amount-greatest(amount-pending_refund_amount,0)
 where id=settlement.id;
 result:=jsonb_build_object('refundId',refund_id,'bookingId',booking.id,'eventId',booking.event_id,
 'amount',amount,'disbursedOn',(p_args->>'p_disbursed_on')::date);
 perform reservations_private.audit(ctx,'booking.refund.disbursed','booking',booking.id,op_id,to_jsonb(settlement),result);
 return reservations_private.complete_operation(op_id,ctx,'disburse_refund',p_args,result);
end $$;


--
-- Name: effective_capabilities("uuid", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."effective_capabilities"("p_device_id" "uuid", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid; v_conference_id uuid; v_is_owner boolean;
begin
  if p_args is null or jsonb_typeof(p_args)<>'object' then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
  v_actor:=public.require_current_approved_device(p_device_id);
  v_is_owner:=platform_private.is_canonical_platform_owner(v_actor);
  if p_args ? 'p_conference_id' and not p_args ? 'p_scope_type' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id']);
    v_conference_id:=nullif(p_args->>'p_conference_id','')::uuid;
    if v_conference_id is null or not exists(select 1 from public.conferences c where c.id=v_conference_id and c.deleted_at is null) then
      raise exception 'RESERVATIONS_CONFERENCE_ACCESS_REQUIRED' using errcode='42501';
    end if;
    perform public.require_effective_module_permission(p_device_id,'conference','conference.access.view','conference',v_conference_id::text);
  elsif p_args ? 'p_scope_type' and not p_args ? 'p_conference_id' then
    perform platform_private.require_exact_jsonb_keys(p_args,array['p_scope_type']);
    if p_args->>'p_scope_type'<>'standalone' then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
  else raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
  return jsonb_build_object('permissions',coalesce((select jsonb_agg(x.permission_key order by x.permission_key)
    from (select permission.code permission_key from platform.permissions permission
      where v_is_owner and permission.domain='reservations' and permission.status='active'
      union select permission.code from platform.permission_grants grant_row
      join platform.permissions permission on permission.id=grant_row.permission_id
      where grant_row.user_id=v_actor and permission.domain='reservations'
        and permission.status='active' and grant_row.revoked_at is null
        and (grant_row.scope_type='module' or (grant_row.scope_type='resource'
          and grant_row.resource_type='event' and exists(select 1 from reservations.events e
            where e.id::text=grant_row.resource_id and ((v_conference_id is null and e.scope_type='standalone'
              and e.conference_id is null) or (v_conference_id is not null and e.scope_type='conference'
              and e.conference_id=v_conference_id and e.scope_partition_id=v_conference_id)))))
    ) x),'[]'::jsonb));
end $$;


--
-- Name: enforce_event_scope_partition_immutable(); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."enforce_event_scope_partition_immutable"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_guard text;
begin
  if tg_op='UPDATE' and (new.scope_type,new.scope_partition_id,new.conference_id)
       is distinct from (old.scope_type,old.scope_partition_id,old.conference_id) then
    v_guard:=current_setting('reservations.scope_relink_guard',true);
    if not (
      old.scope_type='standalone'
      and new.scope_type='conference'
      and old.conference_id is null
      and new.conference_id is not null
      and new.scope_partition_id=new.conference_id
      and v_guard=(old.id::text||':'||old.scope_partition_id::text||':'||new.scope_partition_id::text)
    ) then
      raise exception 'RESERVATIONS_EVENT_SCOPE_IMMUTABLE' using errcode='55000';
    end if;
  end if;
  return new;
end $$;


--
-- Name: event_scope_context("uuid", "uuid", "text"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."event_scope_context"("p_device_id" "uuid", "p_event_id" "uuid", "p_permission" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_event reservations.events%rowtype;v_context jsonb;
begin
 v_context:=public.require_effective_module_permission(p_device_id,'reservations',p_permission,null,null);
 select * into v_event from reservations.events where id=p_event_id;
 if not found then raise exception 'RESERVATIONS_EVENT_NOT_FOUND' using errcode='P0002';end if;
 if v_event.scope_type='conference' then
  v_context:=reservations_private.conference_context(p_device_id,v_event.conference_id,p_permission);
 end if;
 return v_context||jsonb_build_object('scopeType',v_event.scope_type,'scopePartitionId',v_event.scope_partition_id,'eventId',v_event.id);
end $$;


--
-- Name: has_event_permission("uuid", "text", "uuid"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."has_event_permission"("p_actor" "uuid", "p_permission" "text", "p_event_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select platform_private.is_canonical_platform_owner(p_actor) or exists(
    select 1
    from platform.permission_grants grant_row
    join platform.permissions permission on permission.id=grant_row.permission_id
    where grant_row.user_id=p_actor and permission.domain='reservations'
      and permission.code=p_permission and permission.status='active'
      and grant_row.revoked_at is null
      and (
        grant_row.scope_type='module'
        or (grant_row.scope_type='resource' and grant_row.resource_type='event'
            and grant_row.resource_id=p_event_id::text)
      )
  )
$$;


--
-- Name: intent("text", "uuid", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."intent"("p_operation" "text", "p_scope_partition_id" "uuid", "p_args" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select encode(extensions.digest(convert_to(jsonb_build_object(
    'operation',p_operation,'scopePartitionId',p_scope_partition_id,'args',p_args
  )::text,'UTF8'),'sha256'),'hex')
$$;


--
-- Name: link_booking_to_canonical_participation("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."link_booking_to_canonical_participation"("p_booking_id" "uuid", "p_operation_id" "uuid", "p_context" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_booking reservations.bookings%rowtype;
  v_person_id uuid;
  v_conference_id uuid;
  v_device_id uuid;
  v_participation_id uuid;
  v_result jsonb;
begin
  if p_booking_id is null or p_operation_id is null or p_context is null then
    raise exception 'RESERVATIONS_CANONICAL_LINK_ARGUMENT_INVALID' using errcode='22023';
  end if;
  v_conference_id := nullif(p_context->>'conferenceId','')::uuid;
  v_device_id := nullif(p_context->>'actorDeviceId','')::uuid;
  if v_conference_id is null or v_device_id is null then
    raise exception 'RESERVATIONS_CANONICAL_LINK_CONTEXT_REQUIRED' using errcode='22023';
  end if;
  perform platform_private.require_conference_participation_context(
    v_device_id,v_conference_id,'conference.people.manage',true
  );
  select b.* into v_booking
  from reservations.bookings b
  join reservations.events e on e.id=b.event_id
    and e.scope_partition_id=b.scope_partition_id
  where b.id=p_booking_id and e.conference_id=v_conference_id
    and e.scope_type='conference'
  for key share of b;
  if not found then
    raise exception 'RESERVATIONS_CANONICAL_LINK_BOOKING_SCOPE_INVALID' using errcode='22023';
  end if;
  select p.person_id into v_person_id from reservations.participants p
  where p.id=v_booking.participant_id and p.scope_partition_id=v_booking.scope_partition_id
  for key share;
  if v_person_id is null then
    raise exception 'RESERVATIONS_BOOKING_PERSON_SELECTION_REQUIRED' using errcode='22023';
  end if;
  select cp.id into v_participation_id from public.conference_participations cp
  where cp.conference_id=v_conference_id and cp.person_id=v_person_id;
  if v_participation_id is not null then
    return jsonb_build_object('conferenceId',v_conference_id,'personId',v_person_id,
      'participationId',v_participation_id,'existing',true);
  end if;
  v_result := public.create_conference_participation(
    v_device_id,p_operation_id,v_conference_id,v_person_id
  );
  return v_result||jsonb_build_object('existing',false);
end
$$;


--
-- Name: link_standalone_event_to_conference("uuid", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."link_standalone_event_to_conference"("p_device_id" "uuid", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operation_id uuid:=nullif(p_args->>'p_operation_id','')::uuid;
  v_event_id uuid:=nullif(p_args->>'p_event_id','')::uuid;
  v_conference_id uuid:=nullif(p_args->>'p_conference_id','')::uuid;
  v_expected_revision bigint:=(p_args->>'p_expected_revision')::bigint;
  v_context jsonb; v_replay jsonb; v_event reservations.events%rowtype;
  v_new_event reservations.events%rowtype; v_old_partition uuid; v_new_partition uuid;
  v_actor uuid; v_result jsonb; v_booking_id uuid;
begin
  if p_args is null or jsonb_typeof(p_args)<>'object'
     or p_args ?| array['scope_partition_id','p_scope_partition_id',
       'device_id','p_device_id','actor_user_id','p_actor_user_id','actor_device_id','p_actor_device_id'] then
    raise exception 'RESERVATIONS_SCOPE_OVERRIDE_DENIED' using errcode='42501';
  end if;
  perform platform_private.require_exact_jsonb_keys(
    p_args,array['p_operation_id','p_event_id','p_expected_revision','p_conference_id']
  );
  if v_operation_id is null or v_event_id is null or v_conference_id is null then
    raise exception 'RESERVATIONS_LINK_ARGUMENTS_REQUIRED' using errcode='22023';
  end if;
  v_context:=reservations_private.conference_context(
    p_device_id,v_conference_id,'reservations.event.manage'
  );
  v_new_partition:=v_conference_id;
  v_actor:=(v_context->>'actorUserId')::uuid;
  v_context:=v_context||jsonb_build_object(
    'scopeType','conference','scopePartitionId',v_new_partition,'conferenceId',v_conference_id,
    'eventId',v_event_id
  );
  v_replay:=reservations_private.begin_operation(
    v_operation_id,v_context,'link_standalone_event_to_conference',p_args
  );
  if v_replay is not null then return v_replay; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('reservations-link-event:'||v_event_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('reservations-link-conference:'||v_conference_id::text,0)
  );
  select * into v_event from reservations.events where id=v_event_id for update;
  if not found then raise exception 'RESERVATIONS_EVENT_NOT_FOUND' using errcode='P0002'; end if;
  if v_event.scope_type<>'standalone' or v_event.conference_id is not null then
    raise exception 'RESERVATIONS_EVENT_NOT_STANDALONE' using errcode='22023';
  end if;
  if v_event.revision<>v_expected_revision then
    raise exception 'RESERVATIONS_REVISION_CONFLICT' using errcode='40001';
  end if;
  if exists(select 1 from reservations.events where conference_id=v_conference_id and id<>v_event_id) then
    raise exception 'RESERVATIONS_TARGET_CONFERENCE_ALREADY_HAS_EVENT' using errcode='40001';
  end if;
  v_old_partition:=v_event.scope_partition_id;
  if v_old_partition is null or v_old_partition=v_new_partition then
    raise exception 'RESERVATIONS_SCOPE_PARTITION_INVALID' using errcode='22023';
  end if;
  if exists(select 1 from reservations.scope_partition_links
    where old_scope_partition_id=v_old_partition or event_id=v_event_id or conference_id=v_conference_id) then
    raise exception 'RESERVATIONS_SCOPE_LINK_CONFLICT' using errcode='40001';
  end if;
  if exists(select 1 from reservations.booking_number_counters where scope_partition_id=v_new_partition)
     and exists(select 1 from reservations.booking_number_counters where scope_partition_id=v_old_partition) then
    raise exception 'RESERVATIONS_TARGET_PARTITION_COUNTER_CONFLICT' using errcode='40001';
  end if;
  set constraints all deferred;
  perform set_config('reservations.scope_relink_guard',
    v_event_id::text||':'||v_old_partition::text||':'||v_new_partition::text,true);
  update reservations.events set scope_type='conference',scope_partition_id=v_new_partition,
    conference_id=v_conference_id,revision=revision+1,
    updated_at=statement_timestamp(),updated_by=v_actor where id=v_event_id;
  update reservations.event_periods set scope_partition_id=v_new_partition where scope_partition_id=v_old_partition;
  update reservations.booking_types set scope_partition_id=v_new_partition where scope_partition_id=v_old_partition;
  update reservations.participants set scope_partition_id=v_new_partition where scope_partition_id=v_old_partition;
  update reservations.bookings set scope_partition_id=v_new_partition where scope_partition_id=v_old_partition;
  update reservations.payments set scope_partition_id=v_new_partition where scope_partition_id=v_old_partition;
  update reservations.attendance_records set scope_partition_id=v_new_partition where scope_partition_id=v_old_partition;
  update reservations.operational_reviews set scope_partition_id=v_new_partition where scope_partition_id=v_old_partition;
  update reservations.booking_number_counters set scope_partition_id=v_new_partition where scope_partition_id=v_old_partition;
  insert into reservations.scope_partition_links(
    old_scope_partition_id,new_scope_partition_id,event_id,conference_id,operation_id,linked_by
  ) values(v_old_partition,v_new_partition,v_event_id,v_conference_id,v_operation_id,v_actor);
  -- Link all existing bookings in the same transaction, after scope re-keying.
  -- A failed participation creation rolls back the event and every scope update.
  for v_booking_id in
    select b.id from reservations.bookings b
    where b.event_id=v_event_id order by b.id
  loop
    perform reservations_private.link_booking_to_canonical_participation(
      v_booking_id, extensions.uuid_generate_v5(v_operation_id,v_booking_id::text), v_context
    );
  end loop;
  select * into v_new_event from reservations.events where id=v_event_id;
  v_result:=jsonb_build_object('eventId',v_event_id,'conferenceId',v_conference_id,
    'scopeType','conference','oldScopePartitionId',v_old_partition,
    'scopePartitionId',v_new_partition,'revision',v_new_event.revision);
  perform reservations_private.audit(v_context,'event.linked_to_conference','event',v_event_id,
    v_operation_id,to_jsonb(v_event),to_jsonb(v_new_event));
  return reservations_private.complete_operation(
    v_operation_id,v_context,'link_standalone_event_to_conference',p_args,v_result
  );
end $$;


--
-- Name: mutate_scoped("uuid", "text", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."mutate_scoped"("p_device_id" "uuid", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_context jsonb; v_replay jsonb; v_result jsonb; v_event reservations.events%rowtype; v_period reservations.event_periods%rowtype; v_type reservations.booking_types%rowtype; v_booking reservations.bookings%rowtype; v_payment reservations.payments%rowtype; v_operation reservations.operations%rowtype; v_id uuid; v_revision bigint; v_actor uuid; v_partition uuid; v_number text; v_operation_id uuid:=(p_args->>'p_operation_id')::uuid; v_count integer; v_identity_profile jsonb; v_identity_candidates jsonb; v_identity_challenge reservations_private.manual_person_identity_challenges%rowtype; v_person_id uuid;
begin
 if p_args is null or jsonb_typeof(p_args)<>'object' or p_args ?| array['scope_partition_id','p_scope_partition_id','device_id','p_device_id','actor_user_id','p_actor_user_id','actor_device_id','p_actor_device_id'] then raise exception 'RESERVATIONS_SCOPE_OVERRIDE_DENIED' using errcode='42501'; end if;
 if p_operation='delete_event' and v_operation_id is not null then
  select * into v_operation from reservations.operations where operation_id=v_operation_id;
  if found then
   v_context:=public.require_effective_module_permission(p_device_id,'reservations','reservations.event.manage',null,null)||jsonb_build_object('scopePartitionId',v_operation.scope_partition_id);
   return reservations_private.begin_operation(v_operation_id,v_context,p_operation,p_args);
  end if;
 end if;
 if p_operation='delete_event_period' and v_operation_id is not null then
  select * into v_operation from reservations.operations where operation_id=v_operation_id;
  if found then
   v_context:=public.require_effective_module_permission(p_device_id,'reservations','reservations.event.manage',null,null)||jsonb_build_object('scopePartitionId',v_operation.scope_partition_id);
   return reservations_private.begin_operation(v_operation_id,v_context,p_operation,p_args);
  end if;
 end if;
 if p_operation='delete_booking' and v_operation_id is not null then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_booking_id','p_expected_revision']);
  select * into v_operation from reservations.operations where operation_id=v_operation_id;
  if found then
   v_context:=public.require_effective_module_permission(p_device_id,'reservations','reservations.booking.delete',null,null)||jsonb_build_object('scopePartitionId',v_operation.scope_partition_id);
   return reservations_private.begin_operation(v_operation_id,v_context,p_operation,p_args);
  end if;
 end if;
 if p_operation='create_event' then
  if p_args->>'p_scope_type'='standalone' then
   return reservations_private.create_standalone_event_scoped(p_device_id,p_args-'p_scope_type');
  elsif p_args->>'p_scope_type'<>'conference' or (p_args->>'p_conference_id')::uuid is null then raise exception 'RESERVATIONS_CREATE_EVENT_SCOPE_INVALID' using errcode='22023'; end if;
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_scope_type','p_conference_id','p_name','p_start_date','p_end_date','p_location','p_capacity','p_status','p_notes']);
  v_context:=reservations_private.conference_context(p_device_id,(p_args->>'p_conference_id')::uuid,'reservations.event.manage'); v_actor:=(v_context->>'actorUserId')::uuid; v_partition:=(v_context->>'scopePartitionId')::uuid;
  v_replay:=reservations_private.begin_operation(v_operation_id,v_context,'create_event',p_args); if v_replay is not null then return v_replay; end if;
  insert into reservations.events(scope_type,scope_partition_id,conference_id,name,start_date,end_date,location,capacity,status,notes,created_by,updated_by) values('conference',v_partition,(p_args->>'p_conference_id')::uuid,btrim(p_args->>'p_name'),(p_args->>'p_start_date')::date,(p_args->>'p_end_date')::date,coalesce(p_args->>'p_location',''),(p_args->>'p_capacity')::integer,p_args->>'p_status',coalesce(p_args->>'p_notes',''),v_actor,v_actor) returning id,revision into v_id,v_revision;
  v_result:=jsonb_build_object('eventId',v_id,'revision',v_revision,'scopeType','conference','scopePartitionId',v_partition); perform reservations_private.audit(v_context||jsonb_build_object('scopeType','conference','scopePartitionId',v_partition),'event.created','event',v_id,v_operation_id,null,v_result); return reservations_private.complete_operation(v_operation_id,v_context,'create_event',p_args,v_result);
 end if;
 if p_operation='update_event' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_expected_revision','p_name','p_start_date','p_end_date','p_location','p_capacity','p_status','p_notes']); v_context:=reservations_private.resolve_event_scope(p_device_id,(p_args->>'p_event_id')::uuid,'reservations.event.manage');
