    select 1 from reservations.events e
    join reservations.participants p
      on p.id=v_booking.participant_id and p.scope_partition_id=v_booking.scope_partition_id
    join public.conference_participations cp
      on cp.conference_id=e.conference_id and cp.person_id=p.person_id
    where e.id=v_booking.event_id and e.scope_partition_id=v_booking.scope_partition_id
      and e.scope_type='conference'
  ) then
    raise exception 'RESERVATIONS_CONFERENCE_PERSON_MANUAL_ACTION_REQUIRED' using errcode='55000';
  end if;

  if v_booking.lifecycle_status='active'
     and not exists(select 1 from reservations.booking_cancellation_settlements s
                    where s.booking_id=v_booking.id and s.scope_partition_id=v_booking.scope_partition_id) then
    insert into reservations.booking_cancellation_settlements(
      scope_partition_id,booking_id,person_id,collected_amount,
      non_refundable_amount,refunded_amount,credit_amount,pending_refund_amount,
      reason,created_by,created_by_device_id,operation_id
    )
    select v_booking.scope_partition_id,v_booking.id,p.person_id,
      coalesce(pay.collected,0),0,0,0,coalesce(pay.collected,0),
      'حذف من الفعالية',v_actor,p_device_id,v_operation_id
    from reservations.participants p
    left join lateral(
      select sum(z.amount) collected
      from reservations.payments z
      where z.booking_id=v_booking.id
        and z.scope_partition_id=v_booking.scope_partition_id
        and z.status='active'
    ) pay on true
    where p.id=v_booking.participant_id
      and p.scope_partition_id=v_booking.scope_partition_id;
  end if;

  update reservations.bookings set
    lifecycle_status='deleted',
    deleted_at=statement_timestamp(),
    deleted_by=v_actor,
    deleted_by_device_id=p_device_id,
    revision=revision+1,
    updated_at=statement_timestamp(),
    updated_by=v_actor
  where id=v_booking.id
    and event_id=v_booking.event_id
    and scope_partition_id=v_booking.scope_partition_id
  returning revision into v_revision;

  v_result:=jsonb_build_object(
    'bookingId',v_booking.id,'deleted',true,'status','deleted','revision',v_revision
  );
  perform reservations_private.audit(
    v_context,'booking.deleted','booking',v_booking.id,v_operation_id,to_jsonb(v_booking),v_result
  );
  return reservations_private.complete_operation(v_operation_id,v_context,p_operation,p_args,v_result);
 end if;
 if p_operation='record_payment' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_booking_id','p_amount','p_payment_date','p_payment_method','p_payment_method_other','p_reference','p_notes']); v_context:=reservations_private.resolve_booking_scope(p_device_id,(p_args->>'p_booking_id')::uuid,'reservations.payment.record'); v_actor:=(v_context->>'actorUserId')::uuid;
  v_replay:=reservations_private.begin_operation(v_operation_id,v_context,p_operation,p_args); if v_replay is not null then return v_replay; end if; select * into v_booking from reservations.bookings where id=(v_context->>'bookingId')::uuid and event_id=(v_context->>'eventId')::uuid and scope_partition_id=(v_context->>'scopePartitionId')::uuid for update; if not found then raise exception 'RESERVATIONS_BOOKING_NOT_FOUND' using errcode='P0002'; end if; if v_booking.lifecycle_status<>'active' then raise exception 'RESERVATIONS_BOOKING_APOLOGIZED_IMMUTABLE' using errcode='55000'; end if;
  insert into reservations.payments(scope_partition_id,booking_id,amount,payment_date,payment_method,payment_method_other,reference,notes,created_by,created_by_device_id) values(v_booking.scope_partition_id,v_booking.id,(p_args->>'p_amount')::numeric,(p_args->>'p_payment_date')::date,p_args->>'p_payment_method',nullif(btrim(p_args->>'p_payment_method_other'),''),nullif(p_args->>'p_reference',''),nullif(p_args->>'p_notes',''),v_actor,p_device_id) returning id into v_id; v_result:=jsonb_build_object('paymentId',v_id,'status','active'); perform reservations_private.audit(v_context,'payment.recorded','payment',v_id,v_operation_id,null,v_result); return reservations_private.complete_operation(v_operation_id,v_context,p_operation,p_args,v_result);
 end if;
 if p_operation='void_payment' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_payment_id','p_void_reason']); v_context:=reservations_private.resolve_payment_scope(p_device_id,(p_args->>'p_payment_id')::uuid,'reservations.payment.void'); v_actor:=(v_context->>'actorUserId')::uuid;
  v_replay:=reservations_private.begin_operation(v_operation_id,v_context,p_operation,p_args); if v_replay is not null then return v_replay; end if; select * into v_booking from reservations.bookings where id=(v_context->>'bookingId')::uuid and scope_partition_id=(v_context->>'scopePartitionId')::uuid for update; if not found then raise exception 'RESERVATIONS_BOOKING_NOT_FOUND' using errcode='P0002'; end if; if v_booking.lifecycle_status<>'active' then raise exception 'RESERVATIONS_BOOKING_APOLOGIZED_IMMUTABLE' using errcode='55000'; end if; select * into v_payment from reservations.payments where id=(v_context->>'paymentId')::uuid and booking_id=(v_context->>'bookingId')::uuid and scope_partition_id=(v_context->>'scopePartitionId')::uuid for update; if not found then raise exception 'RESERVATIONS_PAYMENT_NOT_FOUND' using errcode='P0002'; end if; if v_payment.status<>'active' or nullif(btrim(p_args->>'p_void_reason'),'') is null then raise exception 'RESERVATIONS_PAYMENT_VOID_INVALID' using errcode='22023'; end if;
  update reservations.payments set status='voided',voided_at=statement_timestamp(),void_reason=btrim(p_args->>'p_void_reason'),voided_by=v_actor,voided_by_device_id=p_device_id where id=v_payment.id and booking_id=v_payment.booking_id and scope_partition_id=v_payment.scope_partition_id; v_result:=jsonb_build_object('paymentId',v_payment.id,'status','voided'); perform reservations_private.audit(v_context,'payment.voided','payment',v_payment.id,v_operation_id,to_jsonb(v_payment),v_result); return reservations_private.complete_operation(v_operation_id,v_context,p_operation,p_args,v_result);
 end if;
 if p_operation='update_attendance' then if exists(select 1 from reservations.bookings where id=(p_args->>'p_booking_id')::uuid and lifecycle_status<>'active') then raise exception 'RESERVATIONS_BOOKING_APOLOGIZED_IMMUTABLE' using errcode='55000'; end if;
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_booking_id','p_segment','p_attended','p_attendance_date','p_notes']); v_context:=reservations_private.resolve_booking_scope(p_device_id,(p_args->>'p_booking_id')::uuid,'reservations.attendance.manage'); v_actor:=(v_context->>'actorUserId')::uuid;
  select * into v_booking from reservations.bookings where id=(v_context->>'bookingId')::uuid and event_id=(v_context->>'eventId')::uuid and scope_partition_id=(v_context->>'scopePartitionId')::uuid for update; if not found then raise exception 'RESERVATIONS_BOOKING_NOT_FOUND' using errcode='P0002'; end if; if v_booking.lifecycle_status<>'active' then raise exception 'RESERVATIONS_BOOKING_APOLOGIZED_IMMUTABLE' using errcode='55000'; end if; if cardinality(v_booking.attendance_segments_snapshot)=0 then raise exception 'RESERVATIONS_ATTENDANCE_NOT_APPLICABLE' using errcode='22023'; end if; if not (p_args->>'p_segment'=any(v_booking.attendance_segments_snapshot)) then raise exception 'RESERVATIONS_ATTENDANCE_SEGMENT_INELIGIBLE' using errcode='22023'; end if;
  v_replay:=reservations_private.begin_operation(v_operation_id,v_context,p_operation,p_args); if v_replay is not null then return v_replay; end if; insert into reservations.attendance_records(scope_partition_id,booking_id,segment,attended,attendance_date,notes,created_by,updated_by) values(v_booking.scope_partition_id,v_booking.id,p_args->>'p_segment',(p_args->>'p_attended')::boolean,case when (p_args->>'p_attended')::boolean then coalesce((p_args->>'p_attendance_date')::date,current_date) end,nullif(p_args->>'p_notes',''),v_actor,v_actor) on conflict(booking_id,segment) do update set attended=excluded.attended,attendance_date=excluded.attendance_date,notes=excluded.notes,revision=reservations.attendance_records.revision+1,updated_at=statement_timestamp(),updated_by=v_actor returning id,revision into v_id,v_revision; v_result:=jsonb_build_object('attendanceId',v_id,'revision',v_revision,'attended',(p_args->>'p_attended')::boolean); perform reservations_private.audit(v_context,'attendance.corrected','attendance',v_id,v_operation_id,null,v_result); return reservations_private.complete_operation(v_operation_id,v_context,p_operation,p_args,v_result);
 end if;
 if p_operation='update_operational_review' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_booking_id','p_expected_revision','p_review_status']); v_context:=reservations_private.resolve_booking_scope(p_device_id,(p_args->>'p_booking_id')::uuid,'reservations.operations.manage'); v_actor:=(v_context->>'actorUserId')::uuid;
  select o.id,o.revision into v_id,v_revision from reservations.operational_reviews o where o.booking_id=(v_context->>'bookingId')::uuid and o.scope_partition_id=(v_context->>'scopePartitionId')::uuid for update; if not found then raise exception 'RESERVATIONS_REVISION_CONFLICT' using errcode='40001'; end if; v_replay:=reservations_private.begin_operation(v_operation_id,v_context,p_operation,p_args); if v_replay is not null then return v_replay; end if;
  update reservations.operational_reviews o set review_status=p_args->>'p_review_status',reviewed_at=case when p_args->>'p_review_status'='completed' then statement_timestamp() end,reviewed_by=case when p_args->>'p_review_status'='completed' then v_actor end,reviewed_by_device_id=case when p_args->>'p_review_status'='completed' then p_device_id end,revision=o.revision+1,updated_at=statement_timestamp(),updated_by=v_actor where o.id=v_id and o.booking_id=(v_context->>'bookingId')::uuid and o.scope_partition_id=(v_context->>'scopePartitionId')::uuid and o.revision=(p_args->>'p_expected_revision')::bigint returning o.id,o.revision into v_id,v_revision; if not found then raise exception 'RESERVATIONS_REVISION_CONFLICT' using errcode='40001'; end if; v_result:=jsonb_build_object('operationalReviewId',v_id,'revision',v_revision,'status',p_args->>'p_review_status'); perform reservations_private.audit(v_context,'operational_review.updated','operational_review',v_id,v_operation_id,null,v_result); return reservations_private.complete_operation(v_operation_id,v_context,p_operation,p_args,v_result);
 end if;
 if p_operation='reorder_event_periods' then
  perform platform_private.require_exact_jsonb_keys(p_args,array['p_operation_id','p_event_id','p_period_ids']); v_context:=reservations_private.resolve_event_scope(p_device_id,(p_args->>'p_event_id')::uuid,'reservations.event.manage'); v_replay:=reservations_private.begin_operation(v_operation_id,v_context,p_operation,p_args); if v_replay is not null then return v_replay; end if; if jsonb_typeof(p_args->'p_period_ids')<>'array' or (select count(*) from jsonb_array_elements_text(p_args->'p_period_ids'))<>(select count(*) from reservations.event_periods where event_id=(v_context->>'eventId')::uuid and scope_partition_id=(v_context->>'scopePartitionId')::uuid) or (select count(distinct value) from jsonb_array_elements_text(p_args->'p_period_ids') s(value))<>(select count(*) from jsonb_array_elements_text(p_args->'p_period_ids')) or exists(select 1 from jsonb_array_elements_text(p_args->'p_period_ids') x left join reservations.event_periods p on p.id=x::uuid and p.event_id=(v_context->>'eventId')::uuid and p.scope_partition_id=(v_context->>'scopePartitionId')::uuid where p.id is null) then raise exception 'RESERVATIONS_PERIOD_ORDER_INVALID' using errcode='22023'; end if; update reservations.event_periods p set display_order=x.ordinality-1,revision=p.revision+1,updated_at=statement_timestamp(),updated_by=(v_context->>'actorUserId')::uuid from jsonb_array_elements_text(p_args->'p_period_ids') with ordinality x(id,ordinality) where p.id=x.id::uuid and p.event_id=(v_context->>'eventId')::uuid and p.scope_partition_id=(v_context->>'scopePartitionId')::uuid; v_result:=jsonb_build_object('eventId',(v_context->>'eventId')::uuid,'reordered',true); perform reservations_private.audit(v_context,'event_periods.reordered','event',(v_context->>'eventId')::uuid,v_operation_id,null,v_result); return reservations_private.complete_operation(v_operation_id,v_context,p_operation,p_args,v_result);
 end if;
 raise exception 'RESERVATIONS_SCOPED_OPERATION_NOT_IMPLEMENTED' using errcode='0A000';
end $_$;


--
-- Name: platform_dashboard_summary("uuid"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."platform_dashboard_summary"("p_device_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid;
begin
  v_actor:=public.require_current_approved_device(p_device_id);
  return (
    with authorized_events as (
      select e.id,e.name,e.start_date,e.end_date,e.status,e.scope_type,e.conference_id,
        platform_private.user_has_module_permission_for(v_actor,'reservations.event.view',null,null)
          or platform_private.user_has_module_permission_for(v_actor,'reservations.event.view','event',e.id::text)
          or platform_private.user_has_module_permission_for(v_actor,'reservations.booking.view',null,null)
          or platform_private.user_has_module_permission_for(v_actor,'reservations.booking.view','event',e.id::text)
          or platform_private.user_has_module_permission_for(v_actor,'reservations.reports.view',null,null) as can_view_event,
        platform_private.user_has_module_permission_for(v_actor,'reservations.booking.view',null,null)
          or platform_private.user_has_module_permission_for(v_actor,'reservations.booking.view','event',e.id::text)
          or platform_private.user_has_module_permission_for(v_actor,'reservations.reports.view',null,null) as can_view_bookings
      from reservations.events e
      where e.scope_type in('standalone','conference')
    ), visible_events as (
      select event_row.*,
        case when event_row.can_view_bookings then (
          select count(*)::bigint from reservations.bookings booking
          where booking.event_id=event_row.id
        ) end as booking_count
      from authorized_events event_row
      where event_row.can_view_event
    )
    select jsonb_build_object(
      'scope','platform',
      'events',count(*)::bigint,
      'standaloneEvents',count(*) filter(where scope_type='standalone'),
      'conferenceEvents',count(*) filter(where scope_type='conference'),
      'bookings',coalesce(sum(booking_count) filter(where can_view_bookings),0)::bigint,
      'bookingMetricsAvailable',coalesce(bool_or(can_view_bookings),false),
      'bookingMetricsComplete',coalesce(bool_and(can_view_bookings),false),
      'activities',coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'eventId',id,'name',name,'startDate',start_date,'endDate',end_date,
        'status',status,'scopeType',scope_type,'conferenceId',conference_id,
        'bookings',booking_count
      )) order by start_date desc,id),'[]'::jsonb)
    )
    from visible_events
  );
end;
$$;


--
-- Name: protect_dynamic_attendance_period(); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."protect_dynamic_attendance_period"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists(
    select 1 from reservations.booking_types booking_type
    where booking_type.event_id=old.event_id and old.kind=any(booking_type.eligible_attendance_segments)
  ) then raise exception 'RESERVATIONS_EVENT_PERIOD_IN_USE' using errcode='23503';end if;
  return old;
end $$;


--
-- Name: protect_payment_history(); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."protect_payment_history"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_guard text;
  v_booking_event_id uuid;
  v_booking_partition uuid;
begin
  if tg_op='DELETE' then
    raise exception 'RESERVATIONS_PAYMENT_DELETE_DENIED' using errcode='55000';
  end if;

  if old.scope_partition_id is distinct from new.scope_partition_id
     and old.booking_id=new.booking_id
     and old.amount=new.amount
     and old.payment_date=new.payment_date
     and old.payment_method=new.payment_method
     and old.payment_method_other is not distinct from new.payment_method_other
     and old.reference is not distinct from new.reference
     and old.notes is not distinct from new.notes
     and old.created_at=new.created_at
     and old.created_by=new.created_by
     and old.created_by_device_id=new.created_by_device_id
     and old.status=new.status then
    v_guard:=current_setting('reservations.scope_relink_guard',true);
    select b.event_id,b.scope_partition_id
      into v_booking_event_id,v_booking_partition
    from reservations.bookings b
    where b.id=new.booking_id;

    if v_booking_event_id is not null
       and v_booking_partition=new.scope_partition_id
       and v_guard=(v_booking_event_id::text||':'||old.scope_partition_id::text||':'||new.scope_partition_id::text) then
      return new;
    end if;
  end if;
  if old.booking_id<>new.booking_id
     or old.amount<>new.amount
     or old.payment_date<>new.payment_date
     or old.payment_method<>new.payment_method
     or old.payment_method_other is distinct from new.payment_method_other
     or old.reference is distinct from new.reference
     or old.notes is distinct from new.notes
     or old.created_at<>new.created_at
     or old.created_by<>new.created_by
     or old.created_by_device_id<>new.created_by_device_id
     or old.status<>'active'
     or new.status<>'voided' then
    raise exception 'RESERVATIONS_PAYMENT_IMMUTABLE' using errcode='55000';
  end if;

  return new;
end $$;


--
-- Name: read_scoped("uuid", "text", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."read_scoped"("p_device_id" "uuid", "p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 v_permission text; v_context jsonb; v_event_id uuid; v_booking_id uuid; v_conference_id uuid;
 v_partition uuid; v_limit integer:=coalesce((p_args->>'p_limit')::integer,100);
 v_result jsonb; v_after_created_at timestamptz; v_after_booking_id uuid; v_rows jsonb;
 v_has_more boolean; v_last_created_at timestamptz; v_last_booking_id uuid;
 v_snapshot jsonb; v_room jsonb; v_house jsonb; v_floor jsonb;
begin
 if p_args is null or jsonb_typeof(p_args)<>'object' then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
 if p_args ?| array['scope_partition_id','p_scope_partition_id','device_id','p_device_id','actor_user_id','p_actor_user_id','actor_device_id','p_actor_device_id'] then raise exception 'RESERVATIONS_SCOPE_OVERRIDE_DENIED' using errcode='42501'; end if;
 v_permission:=case when p_operation in('list_conference_options','list_events','get_event','list_event_periods','list_booking_types') then 'reservations.event.view' when p_operation in('list_bookings','get_booking_detail','search_participants_bookings','get_booking_accommodation') then 'reservations.booking.view' when p_operation='get_booking_settlement' then 'reservations.payment.view' when p_operation='get_cancellation_financial_summary' then 'reservations.reports.view' when p_operation='list_booking_payments' then 'reservations.payment.view' when p_operation='list_attendance' then 'reservations.attendance.view' when p_operation='get_operational_state' then 'reservations.operations.view' when p_operation in('get_dashboard_summary','get_report_source_data','get_report_booking_page') then 'reservations.reports.view' end;
 if v_permission is null then raise exception 'RESERVATIONS_OPERATION_NOT_ALLOWED' using errcode='42501'; end if;
 if p_operation='list_conference_options' then perform platform_private.require_exact_jsonb_keys(p_args,array[]::text[]); v_context:=public.require_effective_module_permission(p_device_id,'reservations',v_permission,null,null); return coalesce(public.list_accessible_conferences(p_device_id)->'conferences','[]'::jsonb); end if;
 if p_operation='list_events' then
  if p_args ? 'p_conference_id' and not p_args ? 'p_scope_type' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_conference_id','p_status','p_limit']); v_conference_id:=nullif(p_args->>'p_conference_id','')::uuid; if v_conference_id is null then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; v_context:=reservations_private.conference_context(p_device_id,v_conference_id,v_permission);
  elsif p_args ? 'p_scope_type' and not p_args ? 'p_conference_id' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_scope_type','p_status','p_limit']); if p_args->>'p_scope_type'<>'standalone' then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; v_context:=public.require_effective_module_permission(p_device_id,'reservations',v_permission,null,null);
  else raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
  if v_limit<1 or v_limit>5000 then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.start_date desc,x.id),'[]'::jsonb) into v_result from (select e.* from reservations.events e where ((v_conference_id is not null and e.scope_type='conference' and e.conference_id=v_conference_id) or (v_conference_id is null and e.scope_type='standalone' and e.conference_id is null)) and ((p_args->>'p_status') is null or e.status=p_args->>'p_status') order by e.start_date desc,e.id limit v_limit) x; return v_result;
 end if;
 if p_operation in('list_bookings','search_participants_bookings','list_attendance','get_report_source_data') and p_args ? 'p_conference_id' and p_args ? 'p_event_id' and p_args->'p_event_id'='null'::jsonb then v_conference_id:=nullif(p_args->>'p_conference_id','')::uuid; if v_conference_id is null then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; v_context:=reservations_private.conference_context(p_device_id,v_conference_id,v_permission);
 elsif p_operation in('get_event','list_event_periods','list_booking_types','list_bookings','search_participants_bookings','list_attendance','get_report_source_data','get_report_booking_page') or (p_operation in('get_dashboard_summary','get_cancellation_financial_summary') and p_args ? 'p_event_id') then v_event_id:=nullif(p_args->>'p_event_id','')::uuid; if v_event_id is null then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; v_context:=reservations_private.resolve_event_scope(p_device_id,v_event_id,v_permission);
 elsif p_operation in('get_booking_detail','list_booking_payments','get_operational_state','get_booking_accommodation','get_booking_settlement') then v_booking_id:=nullif(p_args->>'p_booking_id','')::uuid; if v_booking_id is null then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; v_context:=reservations_private.resolve_booking_scope(p_device_id,v_booking_id,v_permission);
 elsif p_operation in('get_dashboard_summary','get_cancellation_financial_summary') then v_conference_id:=nullif(p_args->>'p_conference_id','')::uuid; if v_conference_id is null then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; v_context:=reservations_private.conference_context(p_device_id,v_conference_id,v_permission); end if;
 v_partition:=nullif(v_context->>'scopePartitionId','')::uuid;
 if p_operation='get_event' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_event_id']); select to_jsonb(e)||jsonb_build_object('periods',(select coalesce(jsonb_agg(to_jsonb(p) order by p.display_order),'[]') from reservations.event_periods p where p.event_id=e.id and p.scope_partition_id=e.scope_partition_id),'bookingTypes',(select coalesce(jsonb_agg(to_jsonb(t) order by t.display_order),'[]') from reservations.booking_types t where t.event_id=e.id and t.scope_partition_id=e.scope_partition_id)) into v_result from reservations.events e where e.id=v_event_id and e.scope_partition_id=v_partition;
 elsif p_operation='list_event_periods' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_event_id']); select coalesce(jsonb_agg(to_jsonb(p) order by p.display_order),'[]') into v_result from reservations.event_periods p where p.event_id=v_event_id and p.scope_partition_id=v_partition;
 elsif p_operation='list_booking_types' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_event_id']); select coalesce(jsonb_agg(to_jsonb(t) order by t.display_order),'[]') into v_result from reservations.booking_types t where t.event_id=v_event_id and t.scope_partition_id=v_partition;
 elsif p_operation in('list_bookings','search_participants_bookings') then perform platform_private.require_exact_jsonb_keys(p_args,case when p_operation='list_bookings' and v_conference_id is not null then array['p_conference_id','p_event_id','p_limit'] when p_operation='list_bookings' then array['p_event_id','p_limit'] when v_conference_id is not null then array['p_conference_id','p_query','p_event_id','p_limit'] else array['p_event_id','p_query','p_limit'] end); if v_limit<1 or v_limit>5000 then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc,x.id),'[]') into v_result from (select b.*,to_jsonb(p) participant,to_jsonb(e) event,coalesce(pay.total_paid,0) total_paid,greatest(b.price_snapshot-coalesce(pay.total_paid,0),0) remaining_balance,greatest(coalesce(pay.total_paid,0)-b.price_snapshot,0) overpaid_amount,case when coalesce(pay.total_paid,0)=0 then 'unpaid' when pay.total_paid>=b.price_snapshot then 'paid' else 'partial' end payment_status from reservations.bookings_operational b join reservations.participants_canonical p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id left join lateral(select sum(z.amount) total_paid from reservations.payments z where z.booking_id=b.id and z.scope_partition_id=b.scope_partition_id and z.status='active') pay on true where ((v_event_id is not null and b.event_id=v_event_id and b.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id)) and (p_operation='list_bookings' or lower(p.full_name||' '||p.phone||' '||b.booking_number) like '%'||lower(btrim(p_args->>'p_query'))||'%') order by b.created_at desc,b.id limit v_limit) x;
 elsif p_operation='get_booking_detail' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_booking_id']); select to_jsonb(b)||jsonb_build_object('participant',to_jsonb(p),'event',to_jsonb(e),'payments',(select coalesce(jsonb_agg(to_jsonb(z) order by z.payment_date desc,z.id),'[]') from reservations.payments z where z.booking_id=b.id and z.scope_partition_id=b.scope_partition_id),'attendance',(select coalesce(jsonb_agg(to_jsonb(a) order by a.segment),'[]') from reservations.attendance_records a where a.booking_id=b.id and a.scope_partition_id=b.scope_partition_id),'operationalReview',(select to_jsonb(o) from reservations.operational_reviews o where o.booking_id=b.id and o.scope_partition_id=b.scope_partition_id)) into v_result from reservations.bookings_operational b join reservations.participants_canonical p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where b.id=v_booking_id and b.scope_partition_id=v_partition;
 elsif p_operation='list_booking_payments' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_booking_id']); select coalesce(jsonb_agg(to_jsonb(z) order by z.payment_date desc,z.id),'[]') into v_result from reservations.payments z where z.booking_id=v_booking_id and z.scope_partition_id=v_partition;
 elsif p_operation='list_attendance' then perform platform_private.require_exact_jsonb_keys(p_args,case when v_conference_id is not null then array['p_conference_id','p_event_id','p_limit'] else array['p_event_id','p_limit'] end); if v_limit<1 or v_limit>5000 then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; select coalesce(jsonb_agg(to_jsonb(x) order by x.full_name,x.booking_id,x.segment),'[]') into v_result from (select a.*,p.full_name,b.booking_number from reservations.attendance_records a join reservations.bookings_operational b on b.id=a.booking_id and b.scope_partition_id=a.scope_partition_id join reservations.participants_canonical p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where (v_event_id is not null and b.event_id=v_event_id and b.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) limit v_limit) x;
 elsif p_operation='get_operational_state' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_booking_id']); select to_jsonb(o)||jsonb_build_object('booking',to_jsonb(b),'participant',to_jsonb(p),'totalPaid',coalesce((select sum(z.amount) from reservations.payments z where z.booking_id=b.id and z.scope_partition_id=b.scope_partition_id and z.status='active'),0)) into v_result from reservations.operational_reviews o join reservations.bookings_operational b on b.id=o.booking_id and b.scope_partition_id=o.scope_partition_id join reservations.participants_canonical p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id where o.booking_id=v_booking_id and o.scope_partition_id=v_partition;
 elsif p_operation='get_booking_accommodation' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_booking_id']); if v_context->>'scopeType'='standalone' then return reservations_private.standalone_accommodation_not_applicable(v_booking_id); end if; return (select jsonb_strip_nulls(jsonb_build_object('bookingId',b.id,'conferenceId',e.conference_id,'conferencePersonId',p.person_id,'conferenceParticipationId',cp.id,'linked',cp.id is not null,'readyForAccommodation',cp.id is not null,'accommodated',o.id is not null,'roomId',r.id,'roomNumber',r.room_number,'houseLabel',h.name,'floorLabel',f.name)) from reservations.bookings_operational b join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id join reservations.participants_canonical p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id left join public.conference_participations cp on cp.conference_id=e.conference_id and cp.person_id=p.person_id left join lateral(select x.id,x.room_id from public.conference_accommodation_occupancies x where x.conference_id=e.conference_id and x.participation_id=cp.id order by x.arrival_day desc,x.id limit 1)o on true left join public.conference_accommodation_rooms r on r.id=o.room_id left join public.conference_accommodation_floors f on f.id=r.floor_id left join public.conference_accommodation_houses h on h.id=f.house_id where b.id=v_booking_id);
 elsif p_operation='get_dashboard_summary' then perform platform_private.require_exact_jsonb_keys(p_args,case when p_args ? 'p_event_id' and not p_args ? 'p_conference_id' then array['p_event_id'] when p_args ? 'p_conference_id' and not p_args ? 'p_event_id' then array['p_conference_id'] else array['__invalid__'] end); return jsonb_build_object('events',(select count(*) from reservations.events e where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id)),'bookings',(select count(*) from reservations.bookings_operational b join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where b.lifecycle_status='active' and ((v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id))),'bookingValue',(select coalesce(sum(b.price_snapshot),0) from reservations.bookings_operational b join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where b.lifecycle_status='active' and ((v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id))),'collected',(select coalesce(sum(z.amount),0) from reservations.payments z join reservations.bookings_operational b on b.id=z.booking_id and b.scope_partition_id=z.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where z.status='active' and b.lifecycle_status='active' and ((v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id))));
 elsif p_operation='get_report_source_data' then perform platform_private.require_exact_jsonb_keys(p_args,case when v_conference_id is not null then array['p_conference_id','p_event_id','p_limit'] else array['p_event_id','p_limit'] end); if v_limit<1 or v_limit>5000 then raise exception 'RESERVATIONS_READ_ARGUMENTS_INVALID' using errcode='22023'; end if; return jsonb_build_object('events',(select coalesce(jsonb_agg(to_jsonb(x) order by x.start_date,x.id),'[]') from (select e.* from reservations.events e where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by e.start_date,e.id limit v_limit)x),'periods',(select coalesce(jsonb_agg(to_jsonb(x) order by x.display_order,x.id),'[]') from (select p.* from reservations.event_periods p join reservations.events e on e.id=p.event_id and e.scope_partition_id=p.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by p.display_order,p.id limit v_limit)x),'bookingTypes',(select coalesce(jsonb_agg(to_jsonb(x) order by x.display_order,x.id),'[]') from (select t.* from reservations.booking_types t join reservations.events e on e.id=t.event_id and e.scope_partition_id=t.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by t.display_order,t.id limit v_limit)x),'participants',(select coalesce(jsonb_agg(to_jsonb(x) order by x.full_name,x.id),'[]') from (select distinct p.* from reservations.participants_canonical p join reservations.bookings_operational b on b.participant_id=p.id and b.scope_partition_id=p.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by p.full_name,p.id limit v_limit)x),'bookings',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at,x.id),'[]') from (select b.* from reservations.bookings_operational b join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by b.created_at,b.id limit v_limit)x),'payments',(select coalesce(jsonb_agg(to_jsonb(x) order by x.payment_date,x.id),'[]') from (select z.* from reservations.payments z join reservations.bookings_operational b on b.id=z.booking_id and b.scope_partition_id=z.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by z.payment_date,z.id limit v_limit)x),'attendance',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at,x.id),'[]') from (select a.* from reservations.attendance_records a join reservations.bookings_operational b on b.id=a.booking_id and b.scope_partition_id=a.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by a.created_at,a.id limit v_limit)x),'operationalReviews',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at,x.id),'[]') from (select o.* from reservations.operational_reviews o join reservations.bookings_operational b on b.id=o.booking_id and b.scope_partition_id=o.scope_partition_id join reservations.events e on e.id=b.event_id and e.scope_partition_id=b.scope_partition_id where (v_event_id is not null and e.id=v_event_id and e.scope_partition_id=v_partition) or (v_event_id is null and e.scope_type='conference' and e.conference_id=v_conference_id) order by o.created_at,o.id limit v_limit)x));
 elsif p_operation='get_report_booking_page' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_event_id','p_limit','p_after_created_at','p_after_booking_id']); v_after_created_at:=nullif(p_args->>'p_after_created_at','')::timestamptz; v_after_booking_id:=nullif(p_args->>'p_after_booking_id','')::uuid; if not (p_args ? 'p_limit') or v_limit<1 or v_limit>500 or ((v_after_created_at is null)<>(v_after_booking_id is null)) then raise exception 'RESERVATIONS_REPORT_PAGE_ARGUMENTS_INVALID' using errcode='22023'; end if; with candidates as materialized(select b.* from reservations.bookings_operational b where b.event_id=v_event_id and b.scope_partition_id=v_partition and (v_after_created_at is null or b.created_at>v_after_created_at or (b.created_at=v_after_created_at and b.id>v_after_booking_id)) order by b.created_at,b.id limit v_limit+1),page as materialized(select * from candidates order by created_at,id limit v_limit) select coalesce(jsonb_agg(jsonb_build_object('booking',to_jsonb(b),'participant',to_jsonb(p),'payments',coalesce((select jsonb_agg(to_jsonb(z) order by z.payment_date,z.id) from reservations.payments z where z.booking_id=b.id and z.scope_partition_id=b.scope_partition_id),'[]'),'attendance',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at,a.id) from reservations.attendance_records a where a.booking_id=b.id and a.scope_partition_id=b.scope_partition_id),'[]'),'operationalReview',(select to_jsonb(o) from reservations.operational_reviews o where o.booking_id=b.id and o.scope_partition_id=b.scope_partition_id)) order by b.created_at,b.id),'[]'),(select count(*)>v_limit from candidates),(array_agg(b.created_at order by b.created_at desc,b.id desc))[1],(array_agg(b.id order by b.created_at desc,b.id desc))[1] into v_rows,v_has_more,v_last_created_at,v_last_booking_id from page b join reservations.participants_canonical p on p.id=b.participant_id and p.scope_partition_id=b.scope_partition_id; return jsonb_build_object('rows',v_rows,'hasMore',coalesce(v_has_more,false),'nextCursor',case when coalesce(v_has_more,false) then jsonb_build_object('createdAt',v_last_created_at,'bookingId',v_last_booking_id) else null end);
 end if;
 if p_operation='get_booking_settlement' then perform platform_private.require_exact_jsonb_keys(p_args,array['p_booking_id']); return coalesce((select to_jsonb(s)||jsonb_build_object('creditBalance',coalesce(a.balance,0),'creditRevision',coalesce(a.revision,0),'refundDisbursements',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'amount',d.amount,'date',d.disbursed_on,'method',d.payment_method,'methodOther',d.payment_method_other,'reference',d.reference,'reason',d.reason) order by d.disbursed_on,d.created_at,d.id) from reservations.refund_disbursements d where d.scope_partition_id=s.scope_partition_id and d.event_id=credit_booking.event_id and d.booking_id=s.booking_id and d.settlement_id=s.id),'[]'::jsonb)) from reservations.booking_cancellation_settlements s left join reservations.bookings credit_booking on credit_booking.id=s.booking_id and credit_booking.scope_partition_id=s.scope_partition_id left join reservations.person_credit_accounts a on a.scope_partition_id=s.scope_partition_id and a.event_id=credit_booking.event_id and a.person_id=s.person_id where s.booking_id=v_booking_id and s.scope_partition_id=v_partition),'null'::jsonb);
 elsif p_operation='get_cancellation_financial_summary' then return (select jsonb_build_object('grossCollected',coalesce(sum(p.amount) filter(where p.status='active'),0),'actualRefunds',coalesce((select sum(d.amount) from reservations.refund_disbursements d where d.scope_partition_id=v_partition and (v_event_id is null or d.event_id=v_event_id)),0),'netCash',coalesce(sum(p.amount) filter(where p.status='active'),0)-coalesce((select sum(d.amount) from reservations.refund_disbursements d where d.scope_partition_id=v_partition and (v_event_id is null or d.event_id=v_event_id)),0),'activeCollection',coalesce(sum(p.amount) filter(where p.status='active' and b.lifecycle_status='active'),0),'nonRefundableApologyRevenue',coalesce((select sum(s.non_refundable_amount) from reservations.booking_cancellation_settlements s join reservations.bookings b2 on b2.id=s.booking_id where s.scope_partition_id=v_partition and (v_event_id is null or b2.event_id=v_event_id)),0),'outstandingCredits',coalesce((select sum(s.credit_amount-coalesce(redeemed.amount,0)) from reservations.booking_cancellation_settlements s join reservations.bookings credit_booking on credit_booking.id=s.booking_id left join lateral(select sum(entry.amount) amount from reservations.person_credit_entries entry where entry.settlement_id=s.id and entry.entry_kind='redeem') redeemed on true where s.scope_partition_id=v_partition and (v_event_id is null or credit_booking.event_id=v_event_id)),0),'refundDisbursements',coalesce((select jsonb_agg(jsonb_build_object('bookingId',d.booking_id,'amount',d.amount,'date',d.disbursed_on,'method',d.payment_method,'methodOther',d.payment_method_other,'reference',d.reference,'reason',d.reason) order by d.disbursed_on,d.created_at,d.id) from reservations.refund_disbursements d where d.scope_partition_id=v_partition and (v_event_id is null or d.event_id=v_event_id)),'[]'::jsonb),'pendingRefunds',coalesce((select sum(s.pending_refund_amount) from reservations.booking_cancellation_settlements s join reservations.bookings b3 on b3.id=s.booking_id where s.scope_partition_id=v_partition and (v_event_id is null or b3.event_id=v_event_id)),0),'retainedApologyFunds',coalesce((select sum(s.non_refundable_amount) from reservations.booking_cancellation_settlements s join reservations.bookings b4 on b4.id=s.booking_id where s.scope_partition_id=v_partition and (v_event_id is null or b4.event_id=v_event_id)),0),'settlements',coalesce((select jsonb_agg(jsonb_build_object('bookingId',b5.id,'bookingNumber',b5.booking_number,'lifecycleStatus',b5.lifecycle_status,'fullName',pc.full_name,'collected',s.collected_amount,'refunded',s.refunded_amount,'pending',s.pending_refund_amount,'retained',s.non_refundable_amount,'refundableAvailable',s.pending_refund_amount+s.non_refundable_amount,'reason',s.reason) order by b5.updated_at desc,b5.id) from reservations.booking_cancellation_settlements s join reservations.bookings b5 on b5.id=s.booking_id and b5.scope_partition_id=s.scope_partition_id join reservations.participants_canonical pc on pc.id=b5.participant_id and pc.scope_partition_id=b5.scope_partition_id where s.scope_partition_id=v_partition and (v_event_id is null or b5.event_id=v_event_id)),'[]'::jsonb)) from reservations.bookings b left join reservations.payments p on p.booking_id=b.id and p.scope_partition_id=b.scope_partition_id where b.scope_partition_id=v_partition and (v_event_id is null or b.event_id=v_event_id));
 end if;
 if v_result is null then raise exception 'RESERVATIONS_RECORD_NOT_FOUND' using errcode='P0002'; end if; return v_result;
end $$;


--
-- Name: redeem_person_credit_scoped("uuid", "jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."redeem_person_credit_scoped"("p_device_id" "uuid", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 context jsonb; replay jsonb; result jsonb; account reservations.person_credit_accounts%rowtype;
 settlement reservations.booking_cancellation_settlements%rowtype; actor uuid;
 operation_id uuid:=(p_args->>'p_operation_id')::uuid; amount numeric(18,2); source_balance numeric(18,2);
begin
  perform platform_private.require_exact_jsonb_keys(p_args,array[
    'p_operation_id','p_event_id','p_person_id','p_settlement_id','p_expected_revision','p_amount','p_reason'
  ]);
  raise exception 'RESERVATIONS_CREDIT_DESTINATION_REQUIRED' using errcode='55000'; context:=reservations_private.resolve_event_scope(
    p_device_id,(p_args->>'p_event_id')::uuid,'reservations.credit.redeem'
  );
  replay:=reservations_private.begin_operation(operation_id,context,'redeem_person_credit',p_args);
  if replay is not null then return replay; end if;
  amount:=(p_args->>'p_amount')::numeric;
  if amount<=0 or nullif(btrim(p_args->>'p_reason'),'') is null then
    raise exception 'RESERVATIONS_CREDIT_REDEMPTION_INVALID' using errcode='22023'; end if;
  select * into account from reservations.person_credit_accounts
   where scope_partition_id=(context->>'scopePartitionId')::uuid
     and person_id=(p_args->>'p_person_id')::uuid for update;
  if not found or account.revision<>(p_args->>'p_expected_revision')::bigint then
    raise exception 'RESERVATIONS_REVISION_CONFLICT' using errcode='40001'; end if;
  if account.balance<amount then raise exception 'RESERVATIONS_CREDIT_BALANCE_EXCEEDED' using errcode='23514'; end if;
  select settlement_row.* into settlement from reservations.booking_cancellation_settlements settlement_row
   join reservations.bookings booking on booking.id=settlement_row.booking_id
   where settlement_row.id=(p_args->>'p_settlement_id')::uuid
     and settlement_row.person_id=account.person_id
     and settlement_row.scope_partition_id=account.scope_partition_id
     and booking.event_id=(context->>'eventId')::uuid for update of settlement_row;
  if not found then raise exception 'RESERVATIONS_CREDIT_SOURCE_NOT_FOUND' using errcode='P0002'; end if;
  select settlement.credit_amount-coalesce(sum(entry.amount) filter(where entry.entry_kind='redeem'),0)
    into source_balance from reservations.person_credit_entries entry
   where entry.settlement_id=settlement.id;
  if source_balance<amount then raise exception 'RESERVATIONS_CREDIT_SOURCE_EXCEEDED' using errcode='23514'; end if;
  actor:=(context->>'actorUserId')::uuid;
  update reservations.person_credit_accounts set balance=balance-amount,
    revision=revision+1,updated_at=statement_timestamp()
   where scope_partition_id=account.scope_partition_id and person_id=account.person_id
   returning * into account;
  insert into reservations.person_credit_entries(
    scope_partition_id,person_id,settlement_id,entry_kind,amount,balance_after,reason,
    operation_id,created_by,created_by_device_id
  ) values(account.scope_partition_id,account.person_id,settlement.id,'redeem',amount,account.balance,
    btrim(p_args->>'p_reason'),operation_id,actor,p_device_id);
  result:=jsonb_build_object('personId',account.person_id,'settlementId',settlement.id,
    'balance',account.balance,'revision',account.revision,'redeemedAmount',amount);
  perform reservations_private.audit(context,'person_credit.redeemed','person_credit',account.person_id,
    operation_id,to_jsonb(account),result);
  return reservations_private.complete_operation(operation_id,context,'redeem_person_credit',p_args,result);
end $$;


--
-- Name: resolve_booking_scope("uuid", "uuid", "text"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."resolve_booking_scope"("p_device_id" "uuid", "p_booking_id" "uuid", "p_permission" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_event_id uuid; begin select event_id into v_event_id from reservations.bookings where id=p_booking_id; if not found then raise exception 'RESERVATIONS_BOOKING_NOT_FOUND' using errcode='P0002'; end if; return reservations_private.resolve_event_scope(p_device_id,v_event_id,p_permission)||jsonb_build_object('bookingId',p_booking_id); end $$;


--
-- Name: resolve_booking_type_scope("uuid", "uuid", "text"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."resolve_booking_type_scope"("p_device_id" "uuid", "p_booking_type_id" "uuid", "p_permission" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_event_id uuid; begin select event_id into v_event_id from reservations.booking_types where id=p_booking_type_id; if not found then raise exception 'RESERVATIONS_BOOKING_TYPE_NOT_FOUND' using errcode='P0002'; end if; return reservations_private.resolve_event_scope(p_device_id,v_event_id,p_permission)||jsonb_build_object('bookingTypeId',p_booking_type_id); end $$;


--
-- Name: resolve_event_period_scope("uuid", "uuid", "text"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."resolve_event_period_scope"("p_device_id" "uuid", "p_period_id" "uuid", "p_permission" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_event_id uuid; begin select event_id into v_event_id from reservations.event_periods where id=p_period_id; if not found then raise exception 'RESERVATIONS_EVENT_PERIOD_NOT_FOUND' using errcode='P0002'; end if; return reservations_private.resolve_event_scope(p_device_id,v_event_id,p_permission)||jsonb_build_object('periodId',p_period_id); end $$;


--
-- Name: resolve_event_scope("uuid", "uuid", "text"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."resolve_event_scope"("p_device_id" "uuid", "p_event_id" "uuid", "p_permission" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_event reservations.events%rowtype;v_context jsonb;
begin
 select * into v_event from reservations.events where id=p_event_id;
 if not found then raise exception 'RESERVATIONS_EVENT_NOT_FOUND' using errcode='P0002';end if;
 if p_permission='reservations.reports.view' then
  v_context:=public.require_effective_module_permission(p_device_id,'reservations',p_permission,null,null);
 else
  v_context:=public.require_effective_module_permission(p_device_id,'reservations',p_permission,'event',p_event_id::text);
 end if;
 if v_event.scope_type='conference' then
  if not exists(select 1 from public.conferences c where c.id=v_event.conference_id and c.deleted_at is null) then
   raise exception 'RESERVATIONS_CONFERENCE_ACCESS_REQUIRED' using errcode='42501';
  end if;
 elsif v_event.scope_type<>'standalone' then raise exception 'RESERVATIONS_SCOPE_TYPE_INVALID' using errcode='22023';end if;
 return v_context||jsonb_build_object('scopeType',v_event.scope_type,'scopePartitionId',v_event.scope_partition_id,'eventId',v_event.id,'conferenceId',v_event.conference_id);
end $$;


--
-- Name: resolve_payment_scope("uuid", "uuid", "text"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."resolve_payment_scope"("p_device_id" "uuid", "p_payment_id" "uuid", "p_permission" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_booking_id uuid; begin select booking_id into v_booking_id from reservations.payments where id=p_payment_id; if not found then raise exception 'RESERVATIONS_PAYMENT_NOT_FOUND' using errcode='P0002'; end if; return reservations_private.resolve_booking_scope(p_device_id,v_booking_id,p_permission)||jsonb_build_object('paymentId',p_payment_id); end $$;


--
-- Name: standalone_accommodation_not_applicable("uuid"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."standalone_accommodation_not_applicable"("p_booking_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select jsonb_build_object('bookingId',p_booking_id,'applicable',false,'reason','RESERVATIONS_ACCOMMODATION_NOT_APPLICABLE');
$$;


--
-- Name: standalone_create_business_args("jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."standalone_create_business_args"("p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
 if p_args is null or jsonb_typeof(p_args)<>'object'
    or p_args ?| array['scope_partition_id','p_scope_partition_id','device_id','p_device_id','actor_user_id','p_actor_user_id','actor_device_id','p_actor_device_id'] then
   raise exception 'RESERVATIONS_SCOPE_OVERRIDE_DENIED' using errcode='42501';
 end if;
 if not p_args ?& array['p_operation_id','p_name','p_start_date','p_end_date','p_location','p_capacity','p_status','p_notes']
    or p_args - array['p_operation_id','p_name','p_start_date','p_end_date','p_location','p_capacity','p_status','p_notes'] <> '{}'::jsonb then
   raise exception 'RESERVATIONS_STANDALONE_CREATE_ARGUMENTS_INVALID' using errcode='22023';
 end if;
 return jsonb_build_object(
   'name',btrim(p_args->>'p_name'),
   'startDate',((p_args->>'p_start_date')::date)::text,
   'endDate',((p_args->>'p_end_date')::date)::text,
   'location',coalesce(p_args->>'p_location',''),
   'capacity',(p_args->>'p_capacity')::integer,
   'status',p_args->>'p_status',
   'notes',coalesce(p_args->>'p_notes','')
 );
end $$;


--
-- Name: standalone_create_intent("jsonb"); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."standalone_create_intent"("p_args" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select encode(extensions.digest(convert_to(jsonb_build_object('operation','create_event','scopeType','standalone','args',reservations_private.standalone_create_business_args(p_args))::text,'UTF8'),'sha256'),'hex');
$$;


--
-- Name: validate_dynamic_attendance_segments(); Type: FUNCTION; Schema: reservations_private; Owner: -
--

CREATE FUNCTION "reservations_private"."validate_dynamic_attendance_segments"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_event_id uuid; v_segments text[];
begin
  if tg_table_name='booking_types' then
    v_event_id:=new.event_id; v_segments:=new.eligible_attendance_segments;
  elsif tg_table_name='bookings' then
    v_event_id:=new.event_id; v_segments:=new.attendance_segments_snapshot;
  else
    select booking.event_id,booking.attendance_segments_snapshot into v_event_id,v_segments
    from reservations.bookings booking
    where booking.id=new.booking_id and booking.scope_partition_id=new.scope_partition_id;
    if not found or not(new.segment=any(v_segments)) then raise exception 'RESERVATIONS_ATTENDANCE_SEGMENT_INELIGIBLE' using errcode='22023';end if;
    v_segments:=array[new.segment];
  end if;
  if v_segments is null then raise exception 'RESERVATIONS_EVENT_PERIOD_REQUIRED' using errcode='23514';end if;
  if cardinality(v_segments)=0 and tg_table_name<>'attendance_records' then return new;end if;
  if cardinality(v_segments)=0
     or cardinality(v_segments)<>(select count(distinct segment) from unnest(v_segments) requested(segment))
     or exists(
    select 1 from unnest(v_segments) requested(segment)
    where not exists(select 1 from reservations.event_periods period where period.event_id=v_event_id and period.kind=requested.segment)
  ) then
    raise exception 'RESERVATIONS_EVENT_PERIOD_REQUIRED' using errcode='23514';
  end if;
  return new;
end $$;


--
-- Name: audit_events; Type: TABLE; Schema: platform; Owner: -
--

CREATE TABLE "platform"."audit_events" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "actor_user_id" "uuid",
    "actor_device_authorization_id" "uuid",
    "subject_user_id" "uuid",
    "domain" "text" NOT NULL,
    "module" "text" NOT NULL,
    "action" "text" NOT NULL,
    "entity_type" "text" NOT NULL,
    "entity_id" "uuid",
    "scope_type" "text",
    "scope_id" "uuid",
    "old_values" "jsonb",
    "new_values" "jsonb",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "request_id" "uuid",
    "operation_id" "uuid",
    "source" "text" DEFAULT 'rpc'::"text" NOT NULL,
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "audit_events_action_check" CHECK (("action" ~ '^[a-z][a-z0-9_.-]{1,119}$'::"text")),
    CONSTRAINT "audit_events_domain_check" CHECK (("domain" = ANY (ARRAY['platform'::"text", 'inventory'::"text"]))),
    CONSTRAINT "audit_events_entity_type_check" CHECK (("entity_type" ~ '^[a-z][a-z0-9_.-]{1,119}$'::"text")),
    CONSTRAINT "audit_events_metadata_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "audit_events_module_check" CHECK (("module" ~ '^[a-z][a-z0-9_-]{1,39}$'::"text")),
    CONSTRAINT "audit_events_new_values_check" CHECK ((("new_values" IS NULL) OR ("jsonb_typeof"("new_values") = 'object'::"text"))),
    CONSTRAINT "audit_events_old_values_check" CHECK ((("old_values" IS NULL) OR ("jsonb_typeof"("old_values") = 'object'::"text"))),
    CONSTRAINT "audit_events_source_check" CHECK (("source" = ANY (ARRAY['rpc'::"text", 'bootstrap'::"text", 'migration'::"text", 'system'::"text"]))),
    CONSTRAINT "platform_audit_events_scope_invariant_check" CHECK (((("scope_type" IS NULL) AND ("scope_id" IS NULL)) OR (("scope_type" = ANY (ARRAY['platform'::"text", 'inventory'::"text"])) AND ("scope_id" IS NULL)) OR (("scope_type" = ANY (ARRAY['reservations'::"text", 'conference'::"text"])) AND ("scope_id" IS NOT NULL))))
);


--
-- Name: device_key_bindings; Type: TABLE; Schema: platform; Owner: -
--

CREATE TABLE "platform"."device_key_bindings" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "device_id" "uuid" NOT NULL,
    "device_authorization_id" "uuid" NOT NULL,
    "public_key_jwk" "jsonb" NOT NULL,
    "public_key_thumbprint" "text" NOT NULL,
    "algorithm" "text" NOT NULL,
    "lifecycle_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "migration_source" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "activated_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "replaced_by_binding_id" "uuid",
    "rotated_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    "retired_at" timestamp with time zone,
    "audit_event_id" "uuid",
    CONSTRAINT "device_key_bindings_algorithm_check" CHECK (("algorithm" = 'ECDSA_P256_SHA256'::"text")),
    CONSTRAINT "device_key_bindings_check" CHECK (((("lifecycle_status" = 'active'::"text") AND ("rotated_at" IS NULL) AND ("revoked_at" IS NULL) AND ("retired_at" IS NULL)) OR (("lifecycle_status" = 'rotated'::"text") AND ("rotated_at" IS NOT NULL)) OR (("lifecycle_status" = 'revoked'::"text") AND ("revoked_at" IS NOT NULL)) OR (("lifecycle_status" = 'retired'::"text") AND ("retired_at" IS NOT NULL)))),
    CONSTRAINT "device_key_bindings_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['active'::"text", 'rotated'::"text", 'revoked'::"text", 'retired'::"text"]))),
    CONSTRAINT "device_key_bindings_migration_source_check" CHECK (("migration_source" = ANY (ARRAY['current_http_only_device_secret'::"text", 'bound_key_rotation'::"text", 'privileged_recovery'::"text", 'native_device_enrollment'::"text"]))),
    CONSTRAINT "device_key_bindings_public_key_jwk_check" CHECK (((("public_key_jwk" ->> 'kty'::"text") = 'EC'::"text") AND (("public_key_jwk" ->> 'crv'::"text") = 'P-256'::"text") AND ("public_key_jwk" ? 'x'::"text") AND ("public_key_jwk" ? 'y'::"text") AND (NOT ("public_key_jwk" ? 'd'::"text")))),
    CONSTRAINT "device_key_bindings_public_key_thumbprint_check" CHECK (("public_key_thumbprint" ~ '^[0-9a-f]{64}$'::"text"))
);

ALTER TABLE ONLY "platform"."device_key_bindings" FORCE ROW LEVEL SECURITY;


--
-- Name: devices; Type: TABLE; Schema: platform; Owner: -
--

CREATE TABLE "platform"."devices" (
    "id" "uuid" NOT NULL,
    "secret_hash" "text" NOT NULL,
    "display_name" "text",
    "platform" "text",
    "browser" "text",
    "lifecycle_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "first_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "secret_rotated_at" timestamp with time zone,
    "retired_at" timestamp with time zone,
    "compromised_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "devices_browser_check" CHECK ((("browser" IS NULL) OR ("length"("browser") <= 120))),
    CONSTRAINT "devices_check" CHECK ((("lifecycle_status" <> 'retired'::"text") OR ("retired_at" IS NOT NULL))),
    CONSTRAINT "devices_check1" CHECK ((("lifecycle_status" <> 'compromised'::"text") OR ("compromised_at" IS NOT NULL))),
    CONSTRAINT "devices_display_name_check" CHECK ((("display_name" IS NULL) OR (("length"("btrim"("display_name")) >= 1) AND ("length"("btrim"("display_name")) <= 120)))),
    CONSTRAINT "devices_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['active'::"text", 'retired'::"text", 'compromised'::"text"]))),
    CONSTRAINT "devices_platform_check" CHECK ((("platform" IS NULL) OR ("length"("platform") <= 120))),
    CONSTRAINT "devices_secret_hash_check" CHECK (("secret_hash" ~ '^[0-9a-f]{64}$'::"text"))
);


--
-- Name: permission_grant_operations; Type: TABLE; Schema: platform; Owner: -
--

CREATE TABLE "platform"."permission_grant_operations" (
    "operation_id" "uuid" NOT NULL,
