--

CREATE TABLE "platform"."permission_grants" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "permission_id" "uuid" NOT NULL,
    "scope_type" "text" NOT NULL,
    "resource_type" "text",
    "resource_id" "text",
    "granted_by" "uuid",
    "granted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "revoked_at" timestamp with time zone,
    "revoked_by" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "permission_grants_check" CHECK (((("scope_type" = 'module'::"text") AND ("resource_type" IS NULL) AND ("resource_id" IS NULL)) OR (("scope_type" = 'resource'::"text") AND ("resource_type" IS NOT NULL) AND ("resource_id" IS NOT NULL)))),
    CONSTRAINT "permission_grants_metadata_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "permission_grants_resource_id_check" CHECK ((("resource_id" IS NULL) OR ((("length"("resource_id") >= 1) AND ("length"("resource_id") <= 255)) AND ("resource_id" = "btrim"("resource_id"))))),
    CONSTRAINT "permission_grants_resource_type_check" CHECK ((("resource_type" IS NULL) OR ("resource_type" ~ '^[a-z][a-z0-9_]{0,62}$'::"text"))),
    CONSTRAINT "permission_grants_scope_type_check" CHECK (("scope_type" = ANY (ARRAY['module'::"text", 'resource'::"text"])))
);


--
-- Name: permissions; Type: TABLE; Schema: platform; Owner: -
--

CREATE TABLE "platform"."permissions" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "code" "text" NOT NULL,
    "domain" "text" NOT NULL,
    "description" "text",
    "is_system" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "allowed_scope_mode" "text" DEFAULT 'module'::"text" NOT NULL,
    "allowed_resource_type" "text",
    "sensitive_mutation" boolean DEFAULT false NOT NULL,
    CONSTRAINT "permissions_allowed_resource_type_check" CHECK ((("allowed_resource_type" IS NULL) OR ("allowed_resource_type" ~ '^[a-z][a-z0-9_]{0,62}$'::"text"))),
    CONSTRAINT "permissions_allowed_scope_mode_check" CHECK (("allowed_scope_mode" = ANY (ARRAY['module'::"text", 'resource'::"text", 'both'::"text"]))),
    CONSTRAINT "permissions_check" CHECK (("split_part"("code", '.'::"text", 1) = "domain")),
    CONSTRAINT "permissions_code_check" CHECK (("code" ~ '^(platform|conference|warehouse|reservations)\.[a-z][a-z0-9_.-]{1,110}$'::"text")),
    CONSTRAINT "permissions_description_check" CHECK ((("description" IS NULL) OR ("length"("description") <= 500))),
    CONSTRAINT "permissions_domain_check" CHECK (("domain" = ANY (ARRAY['platform'::"text", 'conference'::"text", 'warehouse'::"text", 'reservations'::"text"]))),
    CONSTRAINT "permissions_scope_contract_check" CHECK (((("allowed_scope_mode" = 'module'::"text") AND ("allowed_resource_type" IS NULL)) OR (("allowed_scope_mode" = ANY (ARRAY['resource'::"text", 'both'::"text"])) AND ("allowed_resource_type" IS NOT NULL)))),
    CONSTRAINT "permissions_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'retired'::"text"])))
);


--
-- Name: profiles; Type: TABLE; Schema: platform; Owner: -
--

CREATE TABLE "platform"."profiles" (
