    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "profiles_account_status_check" CHECK (("account_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'blocked'::"text"]))),
    CONSTRAINT "profiles_avatar_url_check" CHECK ((("avatar_url" IS NULL) OR ("length"("avatar_url") <= 2048))),
    CONSTRAINT "profiles_check" CHECK ((("account_status" <> 'approved'::"text") OR ("approved_at" IS NOT NULL))),
    CONSTRAINT "profiles_check1" CHECK ((("account_status" <> 'blocked'::"text") OR ("blocked_at" IS NOT NULL))),
    CONSTRAINT "profiles_display_name_check" CHECK ((("display_name" IS NULL) OR (("length"("btrim"("display_name")) >= 1) AND ("length"("btrim"("display_name")) <= 120)))),
    CONSTRAINT "profiles_locale_check" CHECK ((("locale" IS NULL) OR ("locale" ~ '^[A-Za-z]{2,3}([_-][A-Za-z0-9]{2,8})*$'::"text"))),
    CONSTRAINT "profiles_phone_check" CHECK ((("phone" IS NULL) OR (("length"("btrim"("phone")) >= 3) AND ("length"("btrim"("phone")) <= 32)))),
    CONSTRAINT "profiles_status_reason_check" CHECK ((("status_reason" IS NULL) OR ("length"("status_reason") <= 1000))),
    CONSTRAINT "profiles_timezone_check" CHECK ((("timezone" IS NULL) OR (("length"("btrim"("timezone")) >= 1) AND ("length"("btrim"("timezone")) <= 120))))
);


