    CONSTRAINT "device_possession_challenges_purpose_check" CHECK (("purpose" = ANY (ARRAY['SYSTEM_OWNER_PENDING_DEVICE_LIST'::"text", 'SYSTEM_OWNER_PENDING_DEVICE_APPROVE'::"text", 'SYSTEM_OWNER_PENDING_DEVICE_REJECT'::"text", 'SYSTEM_OWNER_DEVICE_REVOKE'::"text", 'SYSTEM_OWNER_DEVICE_REPLACEMENT'::"text", 'SYSTEM_OWNER_CREDENTIAL_ENROLLMENT'::"text", 'SYSTEM_OWNER_CREDENTIAL_ROTATION'::"text", 'SYSTEM_OWNER_CREDENTIAL_RECOVERY'::"text"]))),
