    CONSTRAINT "privileged_device_audit_action_purpose" CHECK ((("action" = ANY (ARRAY['credential_bootstrap_authorization_issued'::"text", 'credential_recovery_authorization_issued'::"text"])) OR (("action" = 'pending_device_listed'::"text") AND ("challenge_purpose" = 'SYSTEM_OWNER_PENDING_DEVICE_LIST'::"text") AND ("operation_id" IS NULL) AND ("target_user_id_snapshot" IS NULL) AND ("target_device_id" IS NULL) AND ("challenge_target_user_id" IS NULL) AND ("challenge_target_device_id" IS NULL)) OR (("action" = 'pending_device_approved'::"text") AND ("challenge_purpose" = 'SYSTEM_OWNER_PENDING_DEVICE_APPROVE'::"text") AND ("operation_id" IS NOT NULL) AND ("challenge_target_user_id" IS NOT NULL) AND ("challenge_target_device_id" IS NOT NULL) AND ("challenge_target_user_id" = "target_user_id_snapshot") AND ("challenge_target_device_id" = "target_device_id")) OR (("action" = 'pending_device_rejected'::"text") AND ("challenge_purpose" = 'SYSTEM_OWNER_PENDING_DEVICE_REJECT'::"text") AND ("operation_id" IS NOT NULL) AND ("challenge_target_user_id" IS NOT NULL) AND ("challenge_target_device_id" IS NOT NULL) AND ("challenge_target_user_id" = "target_user_id_snapshot") AND ("challenge_target_device_id" = "target_device_id")) OR (("action" = 'device_revoked'::"text") AND ("challenge_purpose" = 'SYSTEM_OWNER_DEVICE_REVOKE'::"text") AND ("operation_id" IS NOT NULL) AND ("challenge_target_user_id" IS NOT NULL) AND ("challenge_target_device_id" IS NOT NULL) AND ("challenge_target_user_id" = "target_user_id_snapshot") AND ("challenge_target_device_id" = "target_device_id")) OR (("action" = 'device_replaced'::"text") AND ("challenge_purpose" = 'SYSTEM_OWNER_DEVICE_REPLACEMENT'::"text") AND ("operation_id" IS NOT NULL) AND ("challenge_target_user_id" IS NULL) AND ("challenge_target_device_id" IS NULL)) OR (("action" = 'credential_enrolled'::"text") AND ("challenge_purpose" = 'SYSTEM_OWNER_CREDENTIAL_ENROLLMENT'::"text") AND ("operation_id" IS NOT NULL) AND ("challenge_target_user_id" IS NULL) AND ("challenge_target_device_id" IS NULL) AND ("target_user_id_snapshot" = "actor_user_id_snapshot") AND ("target_device_id" = "actor_device_id")) OR (("action" = 'credential_activated'::"text") AND ("challenge_purpose" = ANY (ARRAY['SYSTEM_OWNER_CREDENTIAL_ROTATION'::"text", 'SYSTEM_OWNER_CREDENTIAL_RECOVERY'::"text"])) AND ("operation_id" IS NOT NULL) AND ("challenge_target_user_id" IS NOT NULL) AND ("challenge_target_device_id" IS NOT NULL) AND ("challenge_target_user_id" = "target_user_id_snapshot") AND ("challenge_target_device_id" = "target_device_id")) OR (("action" = 'credential_revoked'::"text") AND ("challenge_purpose" = ANY (ARRAY['SYSTEM_OWNER_CREDENTIAL_ROTATION'::"text", 'SYSTEM_OWNER_CREDENTIAL_RECOVERY'::"text"])) AND ("operation_id" IS NOT NULL) AND ("challenge_target_user_id" IS NOT NULL) AND ("challenge_target_device_id" IS NOT NULL) AND ("challenge_target_user_id" = "target_user_id_snapshot") AND ("challenge_target_device_id" = "target_device_id")))),
    CONSTRAINT "privileged_device_audit_live_snapshot_consistency" CHECK (((("actor_user_id" IS NULL) OR ("actor_user_id" = "actor_user_id_snapshot")) AND (("target_user_id" IS NULL) OR ("target_user_id" = "target_user_id_snapshot")))),
    CONSTRAINT "privileged_device_audit_target_shape" CHECK (((("action" = 'device_replaced'::"text") AND ("target_device_id" IS NULL) AND ("target_user_id_snapshot" IS NOT NULL) AND ("replaced_device_id" IS NOT NULL) AND ("replacement_device_id" IS NOT NULL) AND ("replaced_device_id" <> "replacement_device_id")) OR (("action" = 'pending_device_listed'::"text") AND ("target_user_id_snapshot" IS NULL) AND ("target_device_id" IS NULL) AND ("replaced_device_id" IS NULL) AND ("replacement_device_id" IS NULL)) OR (("action" <> ALL (ARRAY['device_replaced'::"text", 'pending_device_listed'::"text"])) AND ("target_user_id_snapshot" IS NOT NULL) AND ("target_device_id" IS NOT NULL) AND ("replaced_device_id" IS NULL) AND ("replacement_device_id" IS NULL)))),
    CONSTRAINT "privileged_device_audit_webauthn_policy" CHECK (((("action" = ANY (ARRAY['credential_bootstrap_authorization_issued'::"text", 'credential_recovery_authorization_issued'::"text"])) AND ("actor_credential_id" IS NULL) AND ("challenge_id" IS NULL) AND ("session_id" IS NULL) AND ("challenge_purpose" IS NULL) AND ("operation_id" IS NULL) AND ("challenge_target_user_id" IS NULL) AND ("challenge_target_device_id" IS NULL)) OR (("action" <> ALL (ARRAY['credential_bootstrap_authorization_issued'::"text", 'credential_recovery_authorization_issued'::"text"])) AND ("challenge_id" IS NOT NULL) AND ("session_id" IS NOT NULL) AND ("challenge_purpose" IS NOT NULL) AND (("actor_credential_id" IS NOT NULL) OR (("action" = 'credential_enrolled'::"text") AND ("challenge_purpose" = 'SYSTEM_OWNER_CREDENTIAL_ENROLLMENT'::"text"))) AND ("user_verified" = true) AND ((NOT "backup_state") OR "backup_eligible")))),
    CONSTRAINT "privileged_device_authorization_audit_lo_security_context_check" CHECK (("jsonb_typeof"("security_context") = 'object'::"text")),
    CONSTRAINT "privileged_device_authorization_audit_log_action_check" CHECK (("action" = ANY (ARRAY['credential_bootstrap_authorization_issued'::"text", 'credential_recovery_authorization_issued'::"text", 'credential_enrolled'::"text", 'credential_activated'::"text", 'credential_revoked'::"text", 'pending_device_listed'::"text", 'pending_device_approved'::"text", 'pending_device_rejected'::"text", 'device_revoked'::"text", 'device_replaced'::"text"]))),
    CONSTRAINT "privileged_device_authorization_audit_log_environment_check" CHECK (("environment" = ANY (ARRAY['local'::"text", 'development_preview'::"text", 'production'::"text"]))),
