    CONSTRAINT "system_owner_credential_recovery_authorizations_status_check" CHECK (("status" = ANY (ARRAY['pending_wait'::"text", 'ready'::"text", 'consumed'::"text", 'revoked'::"text", 'expired'::"text"]))),
    CONSTRAINT "system_owner_credential_recovery_consumption" CHECK (((("status" = 'consumed'::"text") AND ("consumed_at" IS NOT NULL) AND ("consumed_at" >= "not_before") AND ("consumed_at" <= "expires_at")) OR (("status" <> 'consumed'::"text") AND ("consumed_at" IS NULL)))),
    CONSTRAINT "system_owner_credential_recovery_timing" CHECK ((("not_before" >= "issued_at") AND ("expires_at" > "not_before")))
);


--
-- Name: system_owner_device_authorization_operations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."system_owner_device_authorization_operations" (
    "operation_id" "uuid" NOT NULL,
    "actor_user_id" "uuid",
    "actor_user_id_snapshot" "uuid" NOT NULL,
    "actor_device_id" "uuid" NOT NULL,
    "actor_credential_id" "uuid" NOT NULL,
    "challenge_id" "uuid" NOT NULL,
    "session_id" "uuid" NOT NULL,
    "challenge_purpose" "text" NOT NULL,
    "environment" "text" NOT NULL,
    "consumer_kind" "text" DEFAULT 'device_authorization_operation'::"text" NOT NULL,
    "target_user_id" "uuid",
    "target_user_id_snapshot" "uuid" NOT NULL,
    "target_device_id" "uuid",
    "replaced_device_id" "uuid",
    "replacement_device_id" "uuid",
    "action" "text" NOT NULL,
    "outcome" "text" NOT NULL,
    "stored_result" "jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "system_owner_device_authorization_operation_consumer_kind_check" CHECK (("consumer_kind" = 'device_authorization_operation'::"text")),
    CONSTRAINT "system_owner_device_authorization_operation_stored_result_check" CHECK (("jsonb_typeof"("stored_result") = 'object'::"text")),
    CONSTRAINT "system_owner_device_authorization_operations_action_check" CHECK (("action" = ANY (ARRAY['approve_system_owner_pending_device'::"text", 'reject_system_owner_pending_device'::"text", 'revoke_system_owner_device'::"text", 'replace_system_owner_device'::"text"]))),
    CONSTRAINT "system_owner_device_authorization_operations_environment_check" CHECK (("environment" = ANY (ARRAY['local'::"text", 'development_preview'::"text", 'production'::"text"]))),
    CONSTRAINT "system_owner_device_authorization_operations_outcome_check" CHECK (("outcome" = ANY (ARRAY['applied'::"text", 'unchanged'::"text", 'rejected'::"text"]))),
    CONSTRAINT "system_owner_device_operations_action_purpose" CHECK (((("action" = 'approve_system_owner_pending_device'::"text") AND ("challenge_purpose" = 'SYSTEM_OWNER_PENDING_DEVICE_APPROVE'::"text") AND ("target_device_id" IS NOT NULL) AND ("replaced_device_id" IS NULL) AND ("replacement_device_id" IS NULL)) OR (("action" = 'reject_system_owner_pending_device'::"text") AND ("challenge_purpose" = 'SYSTEM_OWNER_PENDING_DEVICE_REJECT'::"text") AND ("target_device_id" IS NOT NULL) AND ("replaced_device_id" IS NULL) AND ("replacement_device_id" IS NULL)) OR (("action" = 'revoke_system_owner_device'::"text") AND ("challenge_purpose" = 'SYSTEM_OWNER_DEVICE_REVOKE'::"text") AND ("target_device_id" IS NOT NULL) AND ("replaced_device_id" IS NULL) AND ("replacement_device_id" IS NULL)) OR (("action" = 'replace_system_owner_device'::"text") AND ("challenge_purpose" = 'SYSTEM_OWNER_DEVICE_REPLACEMENT'::"text") AND ("target_device_id" IS NULL) AND ("replaced_device_id" IS NOT NULL) AND ("replacement_device_id" IS NOT NULL) AND ("replaced_device_id" <> "replacement_device_id")))),
    CONSTRAINT "system_owner_device_operations_live_snapshot_consistency" CHECK (((("actor_user_id" IS NULL) OR ("actor_user_id" = "actor_user_id_snapshot")) AND (("target_user_id" IS NULL) OR ("target_user_id" = "target_user_id_snapshot"))))
);


