    CONSTRAINT "bookings_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['active'::"text", 'apologized'::"text", 'deleted'::"text"]))),
    CONSTRAINT "bookings_notes_check" CHECK ((("notes" IS NULL) OR ("char_length"("notes") <= 4000))),
