    CONSTRAINT "reservations_booking_apology_lifecycle_check" CHECK (((("lifecycle_status" = 'active'::"text") AND ("apologized_at" IS NULL) AND ("apology_reason" IS NULL) AND ("apologized_by" IS NULL) AND ("apologized_by_device_id" IS NULL) AND ("deleted_at" IS NULL) AND ("deleted_by" IS NULL) AND ("deleted_by_device_id" IS NULL)) OR (("lifecycle_status" = 'apologized'::"text") AND ("apologized_at" IS NOT NULL) AND (NULLIF("btrim"("apology_reason"), ''::"text") IS NOT NULL) AND ("apologized_by" IS NOT NULL) AND ("apologized_by_device_id" IS NOT NULL) AND ("deleted_at" IS NULL) AND ("deleted_by" IS NULL) AND ("deleted_by_device_id" IS NULL)) OR (("lifecycle_status" = 'deleted'::"text") AND ("deleted_at" IS NOT NULL) AND ("deleted_by" IS NOT NULL) AND ("deleted_by_device_id" IS NOT NULL) AND ((("apologized_at" IS NULL) AND ("apology_reason" IS NULL) AND ("apologized_by" IS NULL) AND ("apologized_by_device_id" IS NULL)) OR (("apologized_at" IS NOT NULL) AND (NULLIF("btrim"("apology_reason"), ''::"text") IS NOT NULL) AND ("apologized_by" IS NOT NULL) AND ("apologized_by_device_id" IS NOT NULL))))))
);

