--
-- Name: bookings_operational; Type: VIEW; Schema: reservations; Owner: -
--

CREATE VIEW "reservations"."bookings_operational" WITH ("security_invoker"='true') AS
 SELECT "booking"."id",
    "booking"."booking_number",
    "booking"."participant_id",
    "booking"."event_id",
    "booking"."booking_type_id",
    "booking"."booking_type_name_snapshot",
    "booking_type"."price" AS "price_snapshot",
    "booking"."attendance_segments_snapshot",
    "booking"."notes",
    "booking"."revision",
    "booking"."created_at",
    "booking"."updated_at",
    "booking"."created_by",
    "booking"."updated_by",
    "booking"."scope_partition_id",
    "booking"."lifecycle_status",
    "booking"."apologized_at",
    "booking"."apology_reason",
    "booking"."apologized_by",
    "booking"."apologized_by_device_id",
    "booking"."deleted_at",
    "booking"."deleted_by",
    "booking"."deleted_by_device_id"
   FROM ("reservations"."bookings" "booking"
     JOIN "reservations"."booking_types" "booking_type" ON ((("booking_type"."id" = "booking"."booking_type_id") AND ("booking_type"."event_id" = "booking"."event_id") AND ("booking_type"."scope_partition_id" = "booking"."scope_partition_id"))));


