--
-- Name: participants_canonical; Type: VIEW; Schema: reservations; Owner: -
--

CREATE VIEW "reservations"."participants_canonical" WITH ("security_invoker"='true') AS
 SELECT "participant"."id",
    "participant"."full_name",
    "participant"."phone",
    "participant"."age",
    "participant"."church",
    "participant"."governorate",
    "participant"."city_or_village",
    "participant"."service_sector",
    "participant"."service_sector_other",
    "participant"."notes",
    "participant"."revision",
    "participant"."created_at",
    "participant"."updated_at",
    "participant"."created_by",
    "participant"."updated_by",
    "participant"."scope_partition_id",
    "participant"."person_id",
    "participant"."gender_snapshot",
    "participant"."date_of_birth_snapshot",
    "participant"."gender_snapshot" AS "gender",
    "participant"."date_of_birth_snapshot" AS "date_of_birth",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM ("public"."conference_participations" "participation"
                 JOIN "reservations"."events" "event" ON ((("event"."conference_id" = "participation"."conference_id") AND ("event"."scope_partition_id" = "participant"."scope_partition_id"))))
              WHERE (("participation"."person_id" = "participant"."person_id") AND ("participation"."guardian_participation_id" IS NOT NULL)))) THEN 'child'::"text"
            ELSE 'adult'::"text"
        END AS "operational_category",
    "person"."revision" AS "person_revision",
    "person"."id" AS "canonical_person_id",
    "person"."full_name" AS "canonical_full_name",
    "person"."phone" AS "canonical_phone",
    "person"."gender" AS "canonical_gender",
    "person"."date_of_birth" AS "canonical_date_of_birth",
    "person"."church" AS "canonical_church",
    "person"."governorate" AS "canonical_governorate",
    "person"."city_or_village" AS "canonical_city_or_village",
    "person"."service_sector" AS "canonical_service_sector",
    "person"."service_sector_other" AS "canonical_service_sector_other"
   FROM ("reservations"."participants" "participant"
     LEFT JOIN "platform"."people" "person" ON (("person"."id" = "participant"."person_id")));


--
-- Name: payments; Type: TABLE; Schema: reservations; Owner: -
--

CREATE TABLE "reservations"."payments" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "booking_id" "uuid" NOT NULL,
    "amount" numeric(18,2) NOT NULL,
    "payment_date" "date" NOT NULL,
    "payment_method" "text" NOT NULL,
    "payment_method_other" "text",
    "reference" "text",
    "notes" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "voided_at" timestamp with time zone,
    "void_reason" "text",
    "voided_by" "uuid",
    "voided_by_device_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_by_device_id" "uuid" NOT NULL,
    "scope_partition_id" "uuid" NOT NULL,
    CONSTRAINT "payments_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "payments_check" CHECK (((("payment_method" = 'other'::"text") AND (NULLIF("btrim"("payment_method_other"), ''::"text") IS NOT NULL)) OR (("payment_method" <> 'other'::"text") AND ("payment_method_other" IS NULL)))),
    CONSTRAINT "payments_check1" CHECK (((("status" = 'active'::"text") AND ("voided_at" IS NULL) AND ("void_reason" IS NULL) AND ("voided_by" IS NULL) AND ("voided_by_device_id" IS NULL)) OR (("status" = 'voided'::"text") AND ("voided_at" IS NOT NULL) AND (NULLIF("btrim"("void_reason"), ''::"text") IS NOT NULL) AND ("voided_by" IS NOT NULL) AND ("voided_by_device_id" IS NOT NULL)))),
    CONSTRAINT "payments_notes_check" CHECK ((("notes" IS NULL) OR ("char_length"("notes") <= 4000))),
    CONSTRAINT "payments_payment_method_check" CHECK (("payment_method" = ANY (ARRAY['cash'::"text", 'instapay'::"text", 'e_wallet'::"text", 'bank_transfer'::"text", 'other'::"text"]))),
    CONSTRAINT "payments_reference_check" CHECK ((("reference" IS NULL) OR ("char_length"("reference") <= 200))),
    CONSTRAINT "payments_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'voided'::"text"])))
);

ALTER TABLE ONLY "reservations"."payments" FORCE ROW LEVEL SECURITY;


--
-- Name: person_credit_accounts; Type: TABLE; Schema: reservations; Owner: -
--

CREATE TABLE "reservations"."person_credit_accounts" (
    "scope_partition_id" "uuid" NOT NULL,
    "person_id" "uuid" NOT NULL,
    "balance" numeric(18,2) DEFAULT 0 NOT NULL,
    "revision" bigint DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "event_id" "uuid" NOT NULL,
    CONSTRAINT "person_credit_accounts_balance_check" CHECK (("balance" >= (0)::numeric)),
    CONSTRAINT "person_credit_accounts_revision_check" CHECK (("revision" > 0))
);

ALTER TABLE ONLY "reservations"."person_credit_accounts" FORCE ROW LEVEL SECURITY;


--
-- Name: person_credit_entries; Type: TABLE; Schema: reservations; Owner: -
--

CREATE TABLE "reservations"."person_credit_entries" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "scope_partition_id" "uuid" NOT NULL,
    "person_id" "uuid" NOT NULL,
    "settlement_id" "uuid",
    "entry_kind" "text" NOT NULL,
    "amount" numeric(18,2) NOT NULL,
    "balance_after" numeric(18,2) NOT NULL,
    "reason" "text" NOT NULL,
    "operation_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_by_device_id" "uuid" NOT NULL,
    "event_id" "uuid" NOT NULL,
    CONSTRAINT "person_credit_entries_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "person_credit_entries_balance_after_check" CHECK (("balance_after" >= (0)::numeric)),
    CONSTRAINT "person_credit_entries_entry_kind_check" CHECK (("entry_kind" = ANY (ARRAY['issue'::"text", 'redeem'::"text"]))),
    CONSTRAINT "person_credit_entries_reason_check" CHECK (((NULLIF("btrim"("reason"), ''::"text") IS NOT NULL) AND ("char_length"("reason") <= 1000))),
    CONSTRAINT "person_credit_entries_source_check" CHECK (("settlement_id" IS NOT NULL))
);

ALTER TABLE ONLY "reservations"."person_credit_entries" FORCE ROW LEVEL SECURITY;


