    "created_at" timestamp with time zone DEFAULT "statement_timestamp"() NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_by_device_id" "uuid" NOT NULL,
    CONSTRAINT "refund_disbursements_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "refund_disbursements_method_other_check" CHECK (((("payment_method" = 'other'::"text") AND (NULLIF("btrim"("payment_method_other"), ''::"text") IS NOT NULL)) OR (("payment_method" <> 'other'::"text") AND ("payment_method_other" IS NULL)))),
    CONSTRAINT "refund_disbursements_payment_method_check" CHECK (("payment_method" = ANY (ARRAY['cash'::"text", 'instapay'::"text", 'e_wallet'::"text", 'bank_transfer'::"text", 'other'::"text"]))),
    CONSTRAINT "refund_disbursements_reason_check" CHECK ((NULLIF("btrim"("reason"), ''::"text") IS NOT NULL))
);


